window.CHAI_DATA=window.CHAI_DATA||{};CHAI_DATA["26424544"]={"book":{"id":26424544,"title":"重塑心灵（升级版）","author":"李中莹","translator":"","publisher":"北京联合出版公司","pubdate":"2015-6","isbn":"9787550251465","tags":["NLP","心理学","个人成长","李中莹","心灵","心灵/感悟","自我完善","好书","值得一读"],"memCount":19},"np":1,"pb":[40],"idx":[{"i":19200,"t":"意义换框法","l":"TF1-2","c":"钟婧","g":1,"p":1},{"i":18290,"t":"意义换框法","l":"TF2-1","c":"鲲kun","g":1,"p":1},{"i":18208,"t":"南昌火炬分舵第133期活动—《向阳而生》","l":"TF2-4","c":"周姣姣0918","g":1,"p":1},{"i":18101,"t":"意义换框法","l":"TF2-3","c":"周姣姣0918","g":1,"p":1},{"i":15810,"t":"《重塑心灵》","l":"TF1-1","c":"梅子518","g":1,"p":1},{"i":15524,"t":"意义换框法","l":"TF2-1","c":"佑佑","g":1,"p":1},{"i":15284,"t":"意义换框法","l":"TF3-2","c":"emilyxiao","g":1,"p":1},{"i":15196,"t":"如何建立自信","l":"TF3-3","c":"yangzhuanfu","g":1,"p":1},{"i":15172,"t":"意义换框法，让我们从此告别负面。","l":"TF1-2","c":"孟旭","g":1,"p":1},{"i":15159,"t":"如何让我们做事更积极","l":"TF3-2","c":"缘起","g":1,"p":1},{"i":14956,"t":"用意义换框法摆脱当下负面情绪","l":"TF2-3","c":"石研","g":1,"p":1},{"i":14420,"t":"松动信念的方法","l":"TF2-1","c":"照照","g":1,"p":1},{"i":12841,"t":"意义换框法","l":"TF3-2","c":"紫珺","g":1,"p":1},{"i":12753,"t":"意义换框三步法","l":"TF3-2","c":"紫珺","g":1,"p":1},{"i":12737,"t":"意义换框法（第一次）","l":"TF3-2","c":"紫珺","g":1,"p":1},{"i":11442,"t":"改变信念系统的技巧-价值定位法","l":"TF2-1","c":"宋佳嶶","g":1,"p":1},{"i":10912,"t":"改变信念系统的技巧-价值定位法","l":"TF2-1","c":"宋佳嶶","g":1,"p":1},{"i":9897,"t":"《重塑心灵》意义换框法","l":"TF1-2","c":"乘风","g":1,"p":1},{"i":9456,"t":"《重塑心灵》先跟后带沟通技巧","l":"TF2-4","c":"乘风","g":1,"p":1},{"i":8085,"t":"意义换框法来处理负面经验","l":"TF1-2","c":"乘风","g":1,"p":1},{"i":7902,"t":"如何提升沟通力","l":"TF3-3","c":"CoCo陶可可","g":1,"p":1},{"i":7493,"t":"做有心的沟通者","l":"TF3-3","c":"CoCo陶可可","g":1,"p":1},{"i":6934,"t":"松动信念的方法","l":"TF2-2","c":"玲珍","g":1,"p":1},{"i":6090,"t":"EQ型处理他人情绪","l":"TF3-2","c":"邓燕珊|珍妮","g":1,"p":1},{"i":4944,"t":"意义换框法浅析","l":"TF3-1","c":"瑩雪","g":1,"p":1},{"i":4901,"t":"倾听是良好沟通的前提 恰当使用正面词语","l":"TF2-4","c":"瑩雪","g":1,"p":1},{"i":4786,"t":"意义换框法的妙用","l":"TF1-2","c":"林俏宏","g":1,"p":1},{"i":4542,"t":"心理学","l":"TF2-3","c":"田华*善美","g":1,"p":1},{"i":4487,"t":"如何选择实现目标的方法","l":"TF1-1","c":"林俏宏","g":1,"p":1},{"i":4423,"t":"如何看到事情的积极意义","l":"TF3-2","c":"黎娟","g":1,"p":1},{"i":4415,"t":"事情在脑里的位置——时间线","l":"TF2-1","c":"瑩雪","g":1,"p":1},{"i":4222,"t":"自我情绪管理","l":"TF3-2","c":"guoguo","g":1,"p":1},{"i":3360,"t":"重复旧的做法，只会得到旧的结果","l":"TF1-1","c":"玲Lynn","g":1,"p":1},{"i":3114,"t":"重塑心灵-换框法","l":"TF2-4","c":"房明","g":1,"p":1},{"i":3113,"t":"重塑心灵——意义换框法","l":"TF2-3","c":"房明","g":1,"p":1},{"i":2462,"t":"沟通方式决定沟通效果","l":"TF3-1","c":"简·单","g":1,"p":1},{"i":1641,"t":"如何管理情绪","l":"TF3-3","c":"guoguo","g":1,"p":1},{"i":1640,"t":"如何正确处理他人情绪的方式","l":"TF3-2","c":"guoguo","g":1,"p":1},{"i":733,"t":"情绪教导我们在事情中该有所学习，有所收获。","l":"TF3-2","c":"简·单","g":1,"p":1},{"i":318,"t":"什么决定了沟通效果","l":"TF3-1","c":"简·单","g":1,"p":1}],"ms":[{"id":19200,"topic":"意义换框法","learn_goal":"","remark":"《重塑心灵》：情绪不崩、关系不僵","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"钟婧","city":"南京市"},"club":{"name":"南京玄武分舵","city":"南京"},"prologue":"\u003cp>各位伙伴大家好，欢迎来到我的第二次拆书，希望我的分享对大家有帮助。\u003c/p>\u003cp>今天的拆页来自于《重塑心灵》，这是一本基于神经语言程序学（NLP）理论，探讨个人心理成长与自我提升的实践方法的书。旨在帮助读者建立积极信念系统，解锁内在潜能，让每个人都拥有让自己成功快乐的能力。作者：李中莹，华人世界的国际级NLP大师。\u003c/p>\u003cp>拆页【主题】意义换框法，是NLP技巧“换框法”中最常用和最好用的技巧。它完全只凭言语和思想模式而产生效果，是改变信念技巧中最快速最容易的一个，因此选这个主题跟大家分享。\u003c/p>","ratings_count":1,"texts":[{"id":23552,"quote":"\u003cp> 【主题】意义换框法 《重塑心灵》作者：李中莹 P52～53\u003c/p>\u003cp>“意义换框法”是NLP技巧“换框法”中最常用和最好用的技巧。它完全只凭言语和思想模式而产生效果，是NLP的改变信念技巧中最快速最容易的一个。\u003c/p>\u003cp>“意义换框法”是找出一个负面经验中的正面意义。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都只是人加诸的。\u003c/p>\u003cp>既然是人加上去的意义，则一件事情——\u003c/p>\u003cp>◇可以有其他的意义，也可以有更多的意义；\u003c/p>\u003cp>◇可以有不好的意义，也可以有好的意义。\u003c/p>\u003cp>试想一下，当你用一块石头去锤打一颗钉子，或者赶走一只老鼠，你赋予这块石头的意义是什么？它本来有这些意义吗？再想一想，一块石头可以有多少用途？把上面问题引出的意念放在别人的一句话、一个行为，甚至环境出现的一些情况上，会给你什么启示？\u003c/p>\u003cp>下次坐车没有事情做的时候，可以试想一想一只曲别针可以有多少用途。也许这样你会明白一件事情的意义只是取决于我们的主观思想。\u003c/p>\u003cp>同一件事情里面总有不止一个意义包含其中。\u003cstrong>找出最能帮助自己的意义，便可以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>意义换框法对一些因果式的信念最为有效。\u003c/strong>例如：“因为上级挑剔，所以我工作不开心。”\u003c/p>\u003cp>方法是把句中的“果”（工作不开心）改为它的反义词，再把句首的“因为”二字放到最后，成为：“上级挑剔，所以我工作积极，因为……”然后反复地思考如何能把句子写完，要求至少有六个不同的版本，再找出其中最能够接受的一句。以下是一些学员的杰作：“上级挑剔……”\u003c/p>\u003cp>◇使他无从挑剔\u003c/p>\u003cp>◇使我提升得更快\u003c/p>\u003cp>◇使我超越他的标准\u003c/p>\u003cp>◇使我更快升级，脱离他的管治 \u003c/p>\u003cp>◇使我更有能力去另找新工作\u003c/p>\u003cp>◇使我能清静愉快地工作\u003c/p>\u003cp>◇证明在最难相处的上级的领导下我仍能胜任\u003c/p>\u003cp>◇证明我能超越任何压力\u003c/p>\u003cp>◇使其他老板注意我，因而创造出换工作的机会\u003c/p>\u003cp>◇使我有更优良的表现\u003c/p>\u003cp>试试挑选一条你觉得最好的，然后把整句反复地念数遍。现在，你再念念本来的一句：“因为上司挑剔，所以我工作不开心。”你内心的感觉有怎样的不同？本来的一句和后来的一句，你觉得哪句更舒服一点？\u003c/p>","explains":"\u003cp>对同一件事情总有很多含义，如何解读取决于我们每个人自己的价值观和认知。找出对我们来说最有帮助和价值的意义，把事情由绊脚石变为踏脚石，这便是意义换框法的价值。\u003c/p>\u003cp>意义换框法，是一个非常好用的快速改变信念的技巧方法。帮助我们从一个负面经验中找出正面意义，从过去消极的体验走出来，面向未来，看到希望。因为我们人本来就是被未来召唤的。同时，促使我们主动的去思考清晰、具体化的行动计划，如何来改变现状，而不是只局限在模糊的“灾难化思维”，自怨自艾，无谓内耗。\u003c/p>\u003cp>意义换框法对一些因果式的信念最为有效。具体的做如下：\u003c/p>\u003cp>1、找因果句，比方说因为...，所以...。也就是一个负面信念；\u003c/p>\u003cp>2、改反义词，将果替换为积极的反义词；\u003c/p>\u003cp>3、调结构。注意：重点是调整后所以后面的部分，意义和价值所在。\u003c/p>\u003cp>例如：“因为上级挑剔，所以我工作不开心。”\u003c/p>\u003cp>把句中的“果”（工作不开心）改为它的反义词，再把句首的“因为”二字放到最后，成为：上级挑剔，所以我工作积极，因为使我变得更能干，或者使我更快升级，脱离他的管治。\u003c/p>\u003cp>通过这样的换框，我们的心理能量和情绪感知会得到极大地改善，对解决问题充满了信心。\u003c/p>","interaction":"\u003cp>A1：\u003c/p>\u003cp>我们已经一起学习了意义换框法的概念和方法，从一个负面经验中找出对我们来说最有价值的正面意义。为了更好地理解这个知识点，我们先一起回想下在过往的经历中：以前碰到消极信念的时候我们都是怎么处理的，如果用类似的意义换框方法会怎么样？\u003c/p>\u003cp> 讨论格式： 因为....，所以....。 改为 ......., 所以...., 因为....\u003c/p>\u003cp>比如： 因为孩子考试成绩不好，所以我很烦。改为 孩子考试成绩不好，所以我更加心平气和，因为我需要帮孩子一起分析原因，鼓励他进步\u003c/p>\u003cp>小组内讨论4分钟。请1位同学分享。\u003c/p>\u003cp>学习者案例记录：因为通勤路时间比较长，所以觉得浪费时间；通勤路比较长，所以有很多自己的时间了，可以听听书\u003c/p>\u003cp>A2：\u003c/p>\u003cp>学习了意义换框法，我们知道了如何去找到对我们来说最有价值的意义。那就请大家把应用规划写下来吧，具体模版：在（ 计划 ）时间内，（ 计划 ）场景下，我将用意义换框法，把因为（ 原因 ），所以（原果 ），改为（ 原因 ），所以（新果 ），因为（新因 ），来取得/得到（ 可衡量或可观测的结果、我怎么知道已经做到了 ）结果/目的。\u003c/p>\u003cp>目标尽量清晰明确，符合smart原则。\u003c/p>\u003cp>举例：在（ 接下来一周 ）时间内，（ 如果公众号文章阅读率2天内不到50次）场景下，我将用意义换框法，把因为（ 公众号文章阅读率不高 ），所以（ 我心情有点沮丧 ），改为（公众号文章阅读率不高 ），所以（我更要积极），因为（我要去研究怎么写文章可以让读者更加愿意看），来取得/得到（ 公众号文章阅读量有所上升）结果/目的（可衡量或可观测的结果、我怎么知道已经做到了）\u003c/p>\u003cp>每位同学2分钟时间撰写，请1位同学给我们做分享。\u003c/p>\u003cp>学习者案例记录：下一周，如果我遇到困难，决定使用意义换框法，思考事情的积极一面。例如准备拆页时，虽然难度较大，但可以倒逼我输入更多内容，有更多思考，提升自己的思维。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1754623726000,"updated_at":1755167478000,"ria":true},{"id":18290,"topic":"意义换框法","learn_goal":"","remark":"面对负面体验或事件，意义换框法的三步走是：倒结果、列好意、定新框","level":"TF2-1","duration":30,"status":30,"type":0,"chaishujia":{"username":"鲲kun","city":"深圳市"},"club":{"name":"深圳桃李分舵","city":"深圳"},"prologue":"\u003cp>\u003cstrong>【开场】3分钟\u003c/strong>\u003c/p>\u003cp>大家好，今天我分享的主题是\u003cstrong>意义换框法，语言的魅力！\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>我是\u003cstrong>鲲kun\u003c/strong>，一条大鱼。我是\u003cstrong>\u003cu>喜欢脑筋运动的啃书人\u003c/u>\u003c/strong>，\u003c/p>\u003cp>最近在刻意练习拆书帮的RIA拆书法，后边会重点和大家分享。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>【技能点：学习目标】学习目标包含了学习者可被观察到／被测量到的行为或动作。\u003c/em>\u003c/strong>\u003c/p>\u003cp>完成今天的学习后，学习者能基本了解意义换框法的三步走，能回顾出一次负面体验或事件，利用“倒结果，列新意，定新框”将这次体验转念到正面意义。\u003c/p>\u003cp>\u003cstrong>【图书介绍】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cem>【技能点：FAB图书介绍法】能够清晰辨别出F、A、B\u003c/em>\u003c/strong>\u003c/p>\u003cp>今天给大家介绍的这本书是李中莹老师写的《重塑心灵》，我这里想用FAB的方式介绍这本书。\u003c/p>\u003cp>【F】F\u003cstrong>eatu\u003c/strong>re-指特征/特点/特色：\u003c/p>\u003cp>\u003cstrong>李中莹\u003c/strong>老师的《重塑心灵》是一本关于NLP（神经语言程序学）的经典著作，全面介绍了神经语言程序学的历史、理论框架、基本概念等理论，并通过场景和案例分析展示实用有效的技巧。\u003c/p>\u003cp>【A】Advantage-优势：\u003c/p>\u003cp>本书在豆瓣评分8.4，微信读书APP的推荐值84.8%，是被广泛认可和推荐的。作者是国际级NLP大师，具有权威性和专业性。与同类书籍相比，李中莹提出了许多独到见解，观点具有前瞻性；提供了与时代同步发展的新观点和新案例。\u003c/p>\u003cp>【B1】Benefit-价值：（本书对学习者的价值）\u003c/p>\u003cp>一般人可能一听“NLP”感觉好高大上的东西，躲着走，其实它只是一个理论基础，作者就是在理论基础上提出很实用的技巧，比如\u003cstrong>意义换框法\u003c/strong>、抽离法等。读者可以感受到从理论到实践过程中，知其然知其所以然的独特价值。\u003c/p>\u003cp>【B2】Benefit-价值：（这次拆书对学习者的价值）\u003c/p>\u003cp>今天这个片段主要是讲\u003cstrong>\u003cu>意义换框法的三步走\u003c/u>\u003c/strong>，当大家遇到负面体验或事件时，能够利用“\u003cstrong>\u003cu>意义换框法\u003c/u>\u003c/strong>”将其转变为正面意义，将绊脚石转变为垫脚石。\u003c/p>","ratings_count":1,"texts":[{"id":22572,"quote":"\u003cp>\u003cstrong>【原文R】2分钟\u003c/strong>\u003c/p>\u003cp>接下来请大家一起阅读原文片段，会前，我已经将已经发给大家，接下来大家可以用2分钟再熟悉一下……\u003c/p>\u003cp>大家看完的话可以在腾讯聊天框里，回复“1”。\u003c/p>\u003cp>好的，时间差不多了，还没看完也不要紧，大家和我一起解读和实践就可以。\u003c/p>","explains":"\u003cp>\u003cstrong>【I便签】6分钟\u003c/strong>--诠释、准确、清晰、致用\u003c/p>\u003cp>\u003cstrong>\u003cem>目标：提到不这么做的坏处，找出人们的通常做法，举出反面例子，而且使用片段包含的技能把反面例子加工成正面例子。\u003c/em>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>意义换框法是什么（What）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>意义换框法\u003c/strong>是一种改变信念的技巧，是找出一个负面经验中的正面意义。\u003c/p>\u003cp>它的理论基础是\u003cstrong>“世界上所有的事情本身是没有意义的，所有的意义都只是人加的。”\u003c/strong>\u003c/p>\u003cp>既然是人加上去的意义，则每件事情——既可以有不好的意义，也可以好的意义。\u003c/p>\u003cp>在面对负面经验，即不好的意义（原框），\u003c/p>\u003cp>通过列举好意，选出适合自己好的意义（新框）。\u003c/p>\u003cp>\u003cstrong>换框\u003c/strong>是指将原框（不好的意义）换成新框（好的意义）。\u003c/p>\u003cp>\u003cstrong>意义换框法有什么益处（Why）\u003c/strong>\u003c/p>\u003cp>\u003cu>改变消极思维，改变限制性信念，提升动力和积极性。\u003c/u>\u003c/p>\u003cp>\u003cu>1）排除消极情绪，重树积极乐观心态；\u003c/u>\u003c/p>\u003cp>\u003cu>2）发现新的学习和成长机会；\u003c/u>\u003c/p>\u003cp>\u003cu>3）找到更有效的解决方案。\u003c/u>\u003c/p>\u003cp>【不这样做的坏处】----\u003cem>常用方法及坏处：\u003c/em>\u003c/p>\u003cp>处理负面情绪常用方法是逃避或者硬刚。\u003c/p>\u003cp>逃避可能使焦虑延长，生活质量下降，导致抑郁等心理健康或胜利健康问题；\u003c/p>\u003cp>逃避可能导致否认现实，无法解最终成为永远不敢提及的伤痛。\u003c/p>\u003cp>硬刚（激烈冲突）可能不利于问题的解决引发新的问题，可能伤害别人，甚至导致终身遗憾。\u003c/p>\u003cp>原框：因为\u003cu>上级挑剔\u003c/u>，所以\u003cu>我工作不开心！\u003c/u>\u003c/p>\u003cp>\u003cstrong>面对负面体验或事件，我提炼了意义换框法的三步走（How）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1）倒结果\u003c/strong>：将原来的结果颠倒换为反义词，如\u003cstrong>\u003cu>“我不开心”倒换为“我积极工作”\u003c/u>\u003c/strong>。“我不开兴”的反义是“我要开心”，就是“我要开心工作”，就是“我积极工作”。\u003c/p>\u003cp>同时，将原来的原因当作“事实”保留，把“因为”放后边用于新目标（好的意义）。\u003c/p>\u003cp>倒结果，这个环节大家可能会觉得比较复杂，不过大家可以看上图的红色的“因为”和“所以”就可以比较清晰。\u003c/p>\u003cp>2）\u003cstrong>列好意\u003c/strong>：事物都有两面意义，我们可以多列几种好的意义，建议找2个以上，如\u003cstrong>\u003cu>使我超越他的标准\u003c/u>；\u003cu>使我更快升级，脱离他的管治\u003c/u>；\u003cu>使其他老板注意我，因而创造出换工作的机会\u003c/u>。\u003c/strong>与其深陷到“老板挑剔”导致的不开心当作，“老板的挑剔”还是可以带来很多很多好的意义，像原文一样多列几个好意。\u003c/p>\u003cp>3）\u003cstrong>定新框\u003c/strong>：就是把好意清单里，感觉对自己很有帮助或者很适合自己的，选出来，和前文组合成整句，即新“框”，建议重复多念2遍以上。\u003c/p>\u003cp>我选择的新框是：上级挑剔，\u003cstrong>所以\u003cu>我积极工作\u003c/u>\u003c/strong>，\u003cstrong>因为\u003cu>这使我超越他的标准。\u003c/u>\u003c/strong>\u003c/p>\u003cp>\u003cu>备注：原来列好意写“建议找3个以上”，实录中修改为“建议找2个以上”。\u003c/u>\u003c/p>\u003cp>\u003cem>【举个反例】\u003c/em>\u003c/p>\u003cp>前单位工作时，我比较忙，工作经常加班。\u003c/p>\u003cp>我总是说：因为工作忙，所以没时间看书。\u003c/p>\u003cp>原框：\u003cstrong>因为我工作很忙\u003c/strong>，\u003cstrong>所以我没有时间看书！\u003c/strong>\u003c/p>\u003cp>\u003cem>反例变正例：\u003c/em>\u003c/p>\u003cp>倒结果：\u003cstrong>我工作很忙，所以\u003cu>我要多挤出时间看书\u003c/u>，因为……\u003c/strong>\u003c/p>\u003cp>列好意：（读书的好处）\u003c/p>\u003cp>1)读书可以增加专业知识，有助于设计更完善的方案，减少不必要的工作\u003c/p>\u003cp>2)读书可以学习到新技术，有利于突破困境，从根本上提高效率\u003c/p>\u003cp>3)读书可以提高专注力，以便完成复杂任务，减少失败后重复的时间\u003c/p>\u003cp>定新框：\u003c/p>\u003cp>\u003cstrong>我工作很忙\u003c/strong>，\u003cstrong>所以\u003cu>我要多挤出时间看书\u003c/u>，因为\u003c/strong>\u003cu>读书可以增加专业知识，有助于设计更完善的方案，减少不必要的工作\u003cstrong>！\u003c/strong>\u003c/u>\u003c/p>\u003cp>\u003cstrong>\u003cu>备注：原方法有一个比较隐晦的地方，最后出来的“新意”和原来的困果链仍然是有关联的，不能完全发散。\u003c/u>\u003c/strong>\u003c/p>\u003cp>意义换框法适用边界（Where）\u003c/p>\u003cp>这个方法适用于改变我们对特定时间或情景的观点或认知水平，特别适用于困果式的信念，也适用于调节负面情绪，适用于价值观和信念的重塑。\u003c/p>\u003cp>紧急情况或危机干预的事，不适用；\u003c/p>\u003cp>新的意义若与现实情况严重不符可能造成扭曲认知，不适用；\u003c/p>\u003cp>复杂或根深蒂固的问题，可能需要结合其他技术联合使用（不适用）。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1便签】6分钟\u003c/strong>----鲜活、故事、对应\u003c/p>\u003cp>\u003cstrong>\u003cem>【技能点：显像提问】显像提问清晰，其中包含了具体的情景。刚才的学习者分享了自己根据这个场景联系出过往情景或具体经验。\u003c/em>\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>\u003cstrong>【A1显像提问】\u003c/strong>\u003c/p>\u003cp>请大家回顾一下最近自己有没有因为某个事件让自己感到很“沮丧”、“怒火中烧”、“后悔”，比如学习场景中的失败；亲密关系中的争吵；亲子关系中，对小孩的责骂等。请大家用“因为……所以……”的形式表达情绪一下。\u003c/p>\u003cp>【分组指令】\u003c/p>\u003cp>我看今天我们会议室，人比较少，大家就分在一组，一会讨论时间，大家可以开麦克风自由发言和讨论。\u003c/p>\u003cp>大家在小组内自由讨论2分钟。分组讨论后，请大家写一下自己的“因为……所以……”可以发到腾讯会议的聊天框里，我会邀请1-2位伙伴给大家分享。\u003c/p>\u003cp>【小组讨论】（2分钟）\u003c/p>\u003cp>分组讨论。\u003c/p>\u003cp>\u003cstrong>【学习者案例记录】（4分钟）\u003c/strong>----随机应变（找反例或失败的例子）\u003c/p>\u003cp>学习者1（棋子落）\u003c/p>\u003cp>我是做计划运营，需要和各部门打交道。最近工作中，我发现有一个部门的负责人非常强势，每次都需要花很多精力和他沟通。借用这个场景，用“因为……，所以……”的表达如下：\u003c/p>\u003cp>\u003cstrong>因为\u003c/strong>\u003cu>某部门负责人很强势\u003c/u>，沟通很费力，\u003cstrong>所以\u003c/strong>\u003cu>我感到很沮丧。\u003c/u>\u003c/p>\u003cp>\u003cu>（鲲：好的谢谢分享者）\u003c/u>\u003c/p>\u003cp>备注：这里漏了感谢学习者1的分享。\u003c/p>\u003cp>学习者2（陆大哥）\u003c/p>\u003cp>我讲一个关于我孩子的（故事）。\u003c/p>\u003cp>因为\u003cu>我家宝宝晚上12点了还在蹦迪\u003c/u>，所以\u003cu>我很烦躁，我第2天需要早起\u003c/u>。\u003c/p>\u003cp>鲲回应，我们家小孩也是很晚睡；棋子落也回应，应该每家的娃都是晚睡，我本来也想分享小孩晚睡的。\u003c/p>\u003cp>\u003cu>（鲲：好的谢谢分享者）\u003c/u>\u003c/p>\u003cp>备注：这里漏了感谢学习者2的分享。\u003c/p>\u003cp>学习者3（红姐）\u003c/p>\u003cp>我刚进家门，刚刚我儿子和我说，他明天要去参加比赛(希望我能陪他)，但是我明天下午有事（参加不了）。\u003c/p>\u003cp>因为\u003cu>我儿子明天参加比赛，我不能陪他\u003c/u>，所以\u003cu>我感到很沮丧\u003c/u>。\u003c/p>\u003cp> 非常感谢小伙伴们的分享，让我们把掌声送给他们。\u003cbr> \u003c/p>\u003cp>\u003cstrong>【A1+\u003c/strong>便签】--\u003cstrong>（7分钟\u003c/strong>）----反思和再加工\u003c/p>\u003cp>\u003cstrong>\u003cem>【技能点：A1+】A1+反思加工指令清晰，提醒学习者将前边的分享的反例，利用I便签中的How加工使原来的反例转变为正例。\u003c/em>\u003c/strong>\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>【A1+指令提示】\u003c/p>\u003cp>（假设有一个时光机带你回到过去，）请大家用2分钟的时间，请用“倒结果、列好意、定新框”的三步法，转变前边自己的“因为……所以……”（过往的负面经历）。大家可以多列一些，好的意义。\u003c/p>\u003cp>若有想好的，可以主动打开麦克风回答，或者我直接邀请2位小伙伴分享一下。\u003c/p>\u003cp>（其他书友也可以把“定好的新框”以文字形式发到腾讯的聊天框里。）\u003c/p>\u003cp>【学习者案例记录】\u003c/p>\u003cp>提醒大家把完整句子发到聊天框里。邀请1-2个书友，读出来.\u003c/p>\u003cp>学习者1（棋子落）\u003c/p>\u003cp>【新框】（采用“倒结果、列好意、定新框）\u003c/p>\u003cp>\u003cu>某部门负责人很强势\u003c/u>，沟通很费力，\u003cstrong>所以\u003c/strong>\u003cu>我很开心，\u003c/u>\u003cstrong>因为\u003c/strong>\u003cu>这会极大提高我的沟通表达能力。\u003c/u>\u003c/p>\u003cp>鲲提醒1，除了表达能力提高外还有什么其他好意方面的可能？\u003c/p>\u003cp>棋子落回应1，这个有点挑战呀，还有“每次辩驳他，感觉自己有成长的有进步，有心得感悟”，如果他这种“刁专”的人还是少数，能辩驳他，是对自己的一种突破。\u003c/p>\u003cp>（补充好意：\u003cu>这会使自己获得成长性突破\u003c/u>）\u003c/p>\u003cp>鲲提醒2，其实可能帮助你认识到原来方案的（不足），他挑的刺，提到的点，刚好踩到你的知识盲区，反而促成你的项目更完善。（补充好意：\u003cu>这会使项目方案更完善\u003c/u>）\u003c/p>\u003cp>棋子落回应1，这是有可能的，我发现我应该好好留意这个，好好锻炼自己的思辨，我练一练辩驳他就行。\u003c/p>\u003cp>好的非常感谢你的分享，多列几种可能，会发现每块原来以为的绊脚石都可能成为自己上升的台阶。\u003c/p>\u003cp>（学习者1分享汇编：）\u003c/p>\u003cp>【原框】\u003cstrong>因为\u003c/strong>\u003cu>某部门负责人很强势\u003c/u>，沟通很费力，\u003cstrong>所以\u003c/strong>\u003cu>我感到很沮丧。\u003c/u>\u003c/p>\u003cp>倒结果：\u003cu>某部门负责人很强势\u003c/u>，沟通很费力，\u003cstrong>所以\u003c/strong>\u003cu>我感到很开心\u003c/u>，\u003cstrong>因为\u003c/strong>\u003cu>……\u003c/u>。\u003c/p>\u003cp>列好意：\u003cstrong>因为\u003c/strong>\u003cu>这会极大提高我的沟通表达能力。\u003c/u>\u003c/p>\u003cp> \u003cstrong>因为\u003c/strong>\u003cu>这会使自己获得成长性突破。\u003c/u>\u003c/p>\u003cp>\u003cstrong> 因为\u003c/strong>\u003cu>这会使项目方案更完善。\u003c/u>\u003c/p>\u003cp>定新框：\u003cu>某部门负责人很强势\u003c/u>，沟通很费力，\u003cstrong>所以\u003c/strong>\u003cu>我很开心，\u003c/u>\u003cstrong>因为\u003c/strong>\u003cu>这会极大提高我的沟通表达能力。\u003c/u>\u003c/p>\u003cp>学习者2（陆大哥）\u003c/p>\u003cp>【新框】\u003cu>我家宝宝晚上12点了还在蹦迪\u003c/u>，所以\u003cu>我很高兴，\u003c/u>因为\u003cu>我也可以明目张胆的熬夜刷手机了。\u003c/u>\u003c/p>\u003cp> 鲲提醒1，这个可以呀，还可以这样思考，哈哈。不过，你是不是可以思考有其他好处的场景？\u003cbr> 陆大哥回应，有思考过，（补充好意：）因为\u003cu>这是好契机，有理由重新调整我们家的作息时间\u003c/u>。说明我们家长自己睡得晚。说明，这是一个好的契机调整作息到早睡早起。\u003cbr> \u003cbr> （学习者2分享汇编：）\u003cbr> 【原框】因为\u003cu>我家宝宝晚上12点了还在蹦迪\u003c/u>，所以\u003cu>我很烦躁，我第2天需要早起\u003c/u>\u003cbr> 倒结果：\u003cu>我家宝宝晚上12点了还在蹦迪\u003c/u>，所以\u003cu>我很高兴，\u003c/u>因为\u003cu>……\u003c/u>\u003cbr> 列好意：因为\u003cu>我家宝这是好契机，有理由调整我们家的作息为早睡早起。\u003c/u>\u003cbr> 因为\u003cu>我也可以明目张胆的熬夜刷手机了。（不算真的好意，哈哈）\u003c/u>\u003cbr> 定新框：\u003cu>我家宝宝晚上12点了还在蹦迪\u003c/u>，所以\u003cu>我很高兴，\u003c/u>因为\u003cu>我家宝这是好契机，有理由调整我们家的作息为早睡早起\u003c/u>\u003cbr> \u003cbr> \u003c/p>\u003cp>好的以上是，我的两个互动小分享。可能大家还有一些想试的场景，欢迎大家会后，好好实践这种方法。\u003c/p>\u003cp>总结—\u003cstrong>（1分钟）\u003c/strong>\u003c/p>\u003cp>我这里先做个总结，意义换框法是改变信念的技巧，能使深陷困境或思维盲区的自己转念。\u003c/p>\u003cp>如果以后遇到负面经历时，希望书友们能利用“意义换框法的三步走”快速地走出困境。\u003c/p>\u003cp>原来“山穷水复疑无路”，换框后也许就是“柳暗花明又一村”。\u003c/p>\u003cp>感谢大家聆听，星辰大海，未来可期！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1730767613000,"updated_at":1731839841000,"ria":true},{"id":18208,"topic":"南昌火炬分舵第133期活动—《向阳而生》","learn_goal":"","remark":"通过“清晰的身份定位”可以帮助我们理清楚沟通前的角色定位，提前构建有效的沟通氛围；运用“先跟后带”的方法给对方空间表达，让我们可以做出准确的回应，从而产生良好的双向沟通效果。","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"周姣姣0918","city":"南昌市"},"club":{"name":"南昌火炬分舵","city":"南昌"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，欢迎参加拆书帮南昌火炬分舵的拆书活动。我是拆书家周姣姣，本次练级级别是2-4，预计用时50-60分钟。首先用三个标签介绍自己：两个孩子的妈妈，心理咨询师，练级中的拆书家。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>在活动开始前，我们先分个组，后面有讨论环节，我们分为三组：左边两位一组，中间两位一组，右边两位一组。\u003c/p>\u003cp>【FAB图书介绍】\u003c/p>\u003cp>F\u003c/p>\u003cp>《重塑心灵》作者李中莹老师，被誉为华人世界的国际级NLP大师，他发展出大量独到而实用的思想和行为技巧，有效地帮助一个人培养出良好的心理素质。\u003c/p>\u003cp>A\u003c/p>\u003cp>与其他同类型书籍比较，本书强调自我价值、沟通技巧、情绪管理等，对个人成长和心理健康的重要性。通过具体的案例和讲解，帮助读者理解并运用相关知识，改善自身的心理转态和生活质量。\u003c/p>\u003cp>B1\u003c/p>\u003cp>本书是讲NLP的书，NLP是研究人的大脑如何运作，以及如何提升它的运作效率的学问。沟通效果的好坏之分，决定于对方的回应。良好的回应是对方不一定会接受我的意见，但是乐意进一步了解我的意思，或者提出他自己的意见进行讨论。\u003c/p>\u003cp>B2\u003c/p>\u003cp>“清晰的身份定位”帮助我们理清楚沟通前的角色定位，提前构建有效的沟通氛围；“先跟后带”给对方空间表达，让我们可以做出准确的回应，从而产生良好的双向沟通效果。\u003c/p>\u003cp>片段之间是承前启后的关系，清晰的身份定位为“先跟后带”提供准确的角色基础和行动方向。\u003c/p>","ratings_count":2,"texts":[{"id":22480,"quote":"\u003cp>【学习目标1】\u003c/p>\u003cp>在跟随我完成本片段学习后，学习者能够在与不同身份背景人员交流时，通过身份定位法给对方身份角色进行分类，提高沟通效率。\u003c/p>\u003cp>下面请小伙伴用2分钟时间阅读第一个拆页片段，请阅读好的小伙伴举手示意。\u003c/p>\u003cp>Part1（10-15分钟）\u003c/p>\u003cp>【清晰的身份定位】P192\u003c/p>\u003cp>身份定位对沟通效果有着重要的影响。在沟通的时候，你的内心认定对方的身份是什么，决定了你对他的态度和说话行为模式。所以，最快最简单同时又是最本质的改善沟通效果的技巧，就是改变对方在你心里的身份定位。例如，准备去接待一个投诉的顾客，你把他的身份定为“给我麻烦的人”还是“最能帮助我们有效提升的人”？准备去跟自己的配偶或孩子讨论一些不愉快事情的时候，你把他的身份定为“总不谅解我的人”还是“证明我是多么好的妻子/妈妈的人”？\u003c/p>\u003cp>有一类名词称为“虚泛词”（抽象名词）。一般名词像“毛笔”“水杯”“手表”等可以明确其意义；而“虚泛词”则不可以，例如“资格”“爱情”“公平”“照顾”“人权”等。生活在这个世界里不能没有这些虚泛词，其中很多在人生里占有很重要的地位，但是人类社会里出现的很多冲突、矛盾和误会，也都是与“虚泛词”有关的。原因是人人都以为自己清楚地懂得这些名词是什么意思，而只有被问到的时候，才发觉自己不是怎么清楚。在平时，没有人想到自己和别人都不大清楚，也不会向别人提问。于是，每个人都凭内心模糊的、人人都不同的概念去处理与这些虚泛词有关的事，效果当然不会好。\u003c/p>\u003cp>所有代表一个人的身份角色的名词，都是虚泛词。家庭里的父母亲、丈夫、妻子；工作里的上级、下属、同事、顾客；生活里的朋友等，都是一样。丈夫心里的“太太”是什么，和妻子心里的“太太”往往不一样，而在婚姻生活里没有好好地谈过，于是妻子努力地做好自以为是的“太太”角色，而丈夫则越来越不满意，两人的关系越来越糟。再加上老人家的评论、社会传统思想等的要求，两个当事人会越来越迷惘。\u003c/p>\u003cp>把对方的身份角色定得清楚，自己才可以更有效地配合。事实上，当对方有清晰的身份定位时，自己的思想、情绪感觉和行为意欲也会相对性地清晰和对位。同时，把自己的身份清楚地定好时，自己也会有效地影响对方的思想、情绪感觉和行为意欲。\u003c/p>","explains":"\u003cp>【原文拆解】\u003c/p>\u003cp>【What】\u003c/p>\u003cp>清晰的身份定位，通过自我认知、情景分析，认清对方在我们心里的身份定位，进而调整自己的思想、情绪感觉和行为方式，与对方进行有效互动。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>通过身份定位三步法，提高沟通的效果和质量，避免因身份不明确而导致误解和冲突。使用这个方法可以避免回应不当，不清楚自己以什么身份回应他人，给出不恰当的反馈。\u003c/p>\u003cp>【强调不这么做的坏处】\u003c/p>\u003cp>如果不根据对方的身份调整自己的语言和行为，可能会说出不恰当的话，伤害到对方的感情，使关系变得紧张，或者沟通时难以把握沟通的重点和方向，浪费时间和精力。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>身份定位法使用时并非一定有效，比如对职业的刻板印象，一个人可以拥有多种身份等，在特定情况下，这些身份可能会产生冲突，我们需要在了解对方的基础上灵活调整。\u003c/p>\u003cp>【Where】\u003c/p>\u003cp>适用于沟通前，梳理清楚自己的思想、情绪和行为。\u003c/p>\u003cp>【How（细化步骤）】\u003c/p>\u003cp>清晰的身份定位，可以通过以下三步法确定：\u003c/p>\u003cp>1.自我认知，对自己有清晰的认知，思考自己在当前沟通情景中的角色定位、希望达到的沟通目标。\u003c/p>\u003cp>2.情景分析。分析当下沟通的具体情景，包括沟通对象、沟通目的、场合等因素。\u003c/p>\u003cp>3.行为调整。根据自我认知和情景分析的结果，调整自己的语言、态度和行为，以符合身份定位。\u003c/p>\u003cp>【意译案例】\u003c/p>\u003cp> 下面我给出一个更贴近身份定位的案例。我前面就因为身份定位不明确，导致关系不好的问题。我有一个关系比较好的同事升职后，每次与她沟通时，我都会不知道怎么称呼她，该怎么和她交流，导致关系变得比较尴尬，一度还比较僵硬。后面我通过身份定位法，明确对方的身份角色，改变对方在我心里的身份定位。首先，她已经升职，是我的上级；其次区分场合，是其他部门人员的时候、汇报工作时，还是私下聊天、逛街时。最后，调整我的语言和行为。现在我在正式场合，就会称呼她“主任”，私下会叫她“姐”。经过调整，我们的关系缓和了好多，上周六我们还一起逛了铜锣湾和盒马生鲜。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>最近有没有遇到过这样的场景：岗位调整后，进入新的岗位，从一个部门调入新的部门，导致身份点位模糊；新参加的一个兴趣小组或者活动，不知道这个团体的规则，也不知道自己可以做些什么。请各位小伙伴拿出一张便签纸，回忆一下是否有类似身份定位不清的场景呢？给大家1分钟的时间写在便签纸上。\u003c/p>\u003cp>妍妍：我女儿上周在微信中发给我一张肯德基的图片，我马上以老师的态度和她说：“博士啊，你怎么能吃这种垃圾食品啊？对身体会有伤害的。”女儿一听我用这种语气，我再和她沟通，她就很生气，直接挂了电话。\u003c/p>\u003cp>小园：这是我的卡点，我经常会身份不清，特别是工作当中，搞不清我和别人的关系。因为我的工作变动较多，很快升职，在与人沟通时回有些身份混乱。\u003c/p>\u003cp>【A1+】\u003c/p>\u003cp>再设想一下，假如有回到过去的时光机，我们坐着时光机回到过去，运用身份定位法：自我认知、情景分析、行为调整，你在该情景下如何应对，现在可以和身边小伙伴讨论一下，再写在便签纸上，2分钟后，我会邀请一个小伙伴来分享。\u003c/p>\u003cp>妍妍：假如回到过去，看着刚刚学习的清晰身份定位，我在想女儿只是想告诉我，她当时所处的环境，她正在干什么，并不表示我再吃这个。学习后，先明确我是妈妈，而不是老师，现在我会这样和孩子沟通：你那边正好是用餐时间，你是选择餐厅的套餐吗，鸡块是套餐之一吗。\u003c/p>\u003cp>小园：在回到过去，第一步，我会先问自己是谁？我沟通的人现在身份是什么？我会先清楚自我认知，搞清楚自己到底是谁，弄清楚我的沟通目标是什么，弄清楚自己身份定位然后表达自己。\u003c/p>\u003cp>感谢小伙伴的分享。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":22481,"quote":"\u003cp>第二部分：35分钟以上\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>上面我们学习了清晰身份定位的方法，下面我们学习“先跟后带”，通过先跟随对方的观点和感受，再表达自己的看法或感受，改善人际关系。\u003c/p>\u003cp>下面请小伙伴用2分钟时间阅读第一个拆页片段，请阅读好的小伙伴举手示意。\u003c/p>\u003cp>【原文拆解】\u003c/p>\u003cp>Part2：P186\u003c/p>\u003cp>第四，要学会先跟后带，就是先附和对方的观点，然后再带领他去你想去的方向。附和对方说话的技巧既可以取同——把焦点放在对方话语中你与他一致的部分，又可以取异——把焦点放在对方语言中与你不同的部分，还可以先接受对方全部的话，然后再表达自己的看法、观点。\u003c/p>\u003cp>例如：\u003c/p>\u003cp>你说：“我认为吃早餐的习惯对健康很重要，所以我每天早上都吃两只鸡蛋。”\u003c/p>\u003cp>对方：“鸡蛋的胆固醇含量太高，我的早餐绝不会有鸡蛋。”\u003c/p>\u003cp>回应1（取同）：“噢，原来你也有吃早餐的习惯，你觉得吃早餐对一天的工作有重要的帮助吗？”\u003c/p>\u003cp>回应2（取异）：“你觉得鸡蛋的胆固醇对身体不好，当然你不会以它作早餐了，那么，你的早餐吃什么？”\u003c/p>\u003cp>回应3（全部）：“不单你这样说，我以前也是这样理解的，直至去年我看到一篇科学新知的文章，发现原来胆固醇之中也有好坏之分，而且鸡蛋给我们的胆固醇好多过坏，有一些营养更是其他食物中很少能提供的呢！你有兴趣看一看这篇文章吗？”\u003c/p>","explains":"\u003cp>【原文拆解】\u003c/p>\u003cp>【What】\u003c/p>\u003cp>“先跟后带”是一种非常实用的沟通技巧，在沟通过程中，还需要认真思考对方的观点和感受，尝试从对方的角度看问题，取得对方认同后，再适当表达自己的不同看法。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>它能够帮助我们建立良好的关系，促进有效沟通，解决问题和冲突。在使用过程中要确保你的理解和认同是真诚的，如果对方察觉到你的虚假，可能会抵触你的沟通。\u003c/p>\u003cp>与直接表达观点相比，“先跟后带”强调先理解和认同对方，建立良好的关系基础后再引导对方，避免一开始就因观念冲突产生抵触情绪，导致沟通不畅。不仅仅是被动地接收信息，还在适当的时候进行引导，从而达成更好地沟通效果。\u003c/p>\u003cp>【强调不这么做的坏处】\u003c/p>\u003cp>一般我们在职场、生活中与人沟通意见出现不同时，总是想证明自己的观点是正确的，该怎么说服对方呢？但是沟通过程中如果出现反对对方观点和想法，只顾表达个人意见时，容易引发对方的不满情绪，让沟通受阻。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>有没有一些情况，你发现你跟着对方的节奏进行沟通，也认真思考对方的观点和感受，还是无法进行对话的情况。当沟通双方意见差距较大，或者一方就是不愿意改变时，会让沟通进入僵持，我们可以想其他的思路或方法去处理这种情况。\u003c/p>\u003cp>【How】\u003c/p>\u003cp>先跟后带有以下四个步骤：\u003c/p>\u003cp>1.接纳情绪。当对方表达观点或感受时，首先要接纳对方的情绪，给予对方理解和认同。\u003c/p>\u003cp>2.理解观点。认真倾听对方的观点和想法，尝试从对方的角度去理解其立场，可以通过重复对方的话，来确认理解是否正确。\u003c/p>\u003cp>3.表达共鸣。分享自己类似的经历或感受，表达出你和对方的共鸣。\u003c/p>\u003cp>4.启发思考。在建立良好的沟通氛围后，引导对方从不同的角度思考问题，分享自己的看法和建议。\u003c/p>\u003cp>【Where】\u003c/p>\u003cp>适用于家庭关系、朋友关系、职场关系中人际交往和沟通场景时使用。\u003c/p>\u003cp>【案例】\u003c/p>\u003cp>下面分享一个我的使用案例。一般我的两个孩子在爷爷奶奶吃晚饭，晚饭后爷爷或者奶奶会送孩子回家。上周五的时候，还没有打开门，就听到我儿子安安在嚎啕大哭，等我打开门，哭的更凶了。我赶紧抱起他问：“你这是伤心的哭，孩子生气的哭呀？”姐姐点点马上回答我：“他在爷爷奶奶哪不好好吃饭，被爷爷奶奶凶了，我也骂他了，然后他就哭了。”搞清楚哭的原因，我抱着孩子，并和他说：“被他们三个人骂了，你是不是也生气啦？”安安表示认同，哭声也减轻了。接着我说：“前两天爸爸也指责妈妈了，你还记得不，妈妈当时也可生气了。”聊了一会，了解孩子是在幼儿园吃多了点心不饿，所以不想吃晚饭。等孩子彻底平静后，我和他说：“奶奶是因为担心你饿着，着急才这么说的。”\u003c/p>\u003cp>这是我运用“先跟后带”的方法，安抚孩子情绪的事情。\u003c/p>","interaction":"\u003cp>【A3】\u003c/p>\u003cp>请大家用5分钟的时间进行讨论，把对话写在纸张上。剧本是说两个人，\u003c/p>\u003cp>销售人员小刘是电动汽车销售人员，正在向客户推销车辆，客户提出了诸多质疑：这车的里程只有410公里，会不会要经常充电，充电不方便怎么办？\u003c/p>\u003cp>请根据分组在小组内讨论，，就上面的场景进行讨论。同时要用到今天学到的“先跟后带”四步骤，通过角色扮演，一个扮演小刘，一个扮演客户，加工出一个剧本的对话。5分钟后，我会邀请一组小伙伴来分享，下面请大家开始小组讨论。\u003c/p>\u003cp>角色扮演：\u003c/p>\u003cp>小刘：蒋小姐，上次您说想看下我们家的电车，根据您的需求，我推荐这款最新款，比较适合居家出行、短途旅行，是一辆性价比比较高的车。\u003c/p>\u003cp>客户：我担心会要经常充电有些麻烦。万一电不够用怎么办？我经常看到网上有拖车拖走的。而且我希望周末能开电车会上饶。\u003c/p>\u003cp>小刘：我理解您的顾虑。您希望开电车回上饶，怕电量不足，是吗？\u003c/p>\u003cp>客户：是的，我开电车会有里程焦虑。在高速上，车没有电了改怎么办？\u003c/p>\u003cp>小刘：嗯，我专门去了解过电车里程的问题，这里可以和您分享下。我现在也每天用这个电车上下班的。首先，我们考虑买电车是要看品牌的，对吗？\u003c/p>\u003cp>客户：嗯。\u003c/p>\u003cp>小刘：我们家的车是品牌车，质量是有保证的。这辆车里程有410公里，日常出行时完全不用担心的。而且市区开车时比较省电节能的。再有这款车是免费送充电桩，可以帮您免费安装的。像您回上饶的话，来回可能是要充一次电，您可以在您娘家周边用APP搜下周边充电站，或者到高速服务区进行充电都是很方便的。快充的话，半个小时到1个小时就可以充好的。\u003c/p>\u003cp>客户：那冬天续航会不会缩减呀？网上还看到电车起火呢。\u003c/p>\u003cp>小刘：续航的话，天气冷是会有些缩减，但是您和油车比较下，能耗还是比较低的，这也是您考虑买电车的原因吧。您看到的电车起火，大部分都不是品牌车。我们家是全国top级的品牌，在安全测试这边是非常注重。当然车辆有问题是概率性事件，我们家这方面是概率比较低的，当您发现有问题，可以马上联系我处理。而且我们家这款车这个月还有活动哦。\u003c/p>\u003cp>客户：好的，您在多介绍下，我还是考虑买这款车的。\u003c/p>\u003cp>【回应】\u003c/p>\u003cp>好的，谢谢两个小伙伴的分享。您从开始的时候就充分接纳对方的情绪，理解对方的观点和顾虑，还启发客户的思考，帮助她规划回家的路线，与对方共情，表达自己有相同的精力，真是非常棒。\u003c/p>\u003cp>A2\u003c/p>\u003cp>分步催化1：\u003c/p>\u003cp>非常感谢小伙伴们的分享，现在请小伙伴想一下，在未来的一个月，会不会有需要先了解对方想法或感受的时刻？比如同事对项目方案提出质疑、客户抱怨产品质量问题、孩子对作业量多表示不满。具体是什么人和事情呢？请大家用2分钟的时间在小组内讨论。\u003c/p>\u003cp>分享环节：\u003c/p>\u003cp>绘宇：我有一个需要和女儿沟通的事，我最近给女儿报了羽毛球课，她觉得累，不想去上课。作业多，又要写作业，又要上课，提了很多反对意见。\u003c/p>\u003cp>分步催化2\u003c/p>\u003cp>请大家根据今天学习的先跟后带四步骤，可以和对方怎样沟通呢？请大家与小组内的小伙伴交流讨论下，时间是3分钟。下面请哪位小伙伴来分享一下。\u003c/p>\u003cp>绘宇：回家我可以先理解她的情况，表达与她的共情，然后和她聊聊打羽毛球的好处，再有羽毛球列入了中考体育项目呀。\u003c/p>\u003cp>【回应】\u003c/p>\u003cp>是的，先表达对孩子的理解，在听听孩子抱怨，接纳她的情绪，多听听孩子怎么说，同时和孩子聊聊打羽毛球的好处，启发孩子多思考。\u003c/p>\u003cp> 【结语】\u003c/p>\u003cp>“沟”者渠也，“通”者连也，“沟通”本身的意思是借助某种渠道使双方能够通连。希望小伙伴在未来与人沟通遇到障碍时，可以运用今天学到的身份定位和先跟后带方法，理清沟通思路，让沟通变得顺畅。\u003c/p>\u003cp>感谢小伙伴的陪伴，我的2-4拆书练级到此结束。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1729431746000,"updated_at":1730780548000,"ria":true},{"id":18101,"topic":"意义换框法","learn_goal":"","remark":"当我们在情绪难受、消极时，运用意义换框法转变我们对事件的看法，从消极中发现积极，从而以更积极的心态面对生活和工作。","level":"TF2-3","duration":25,"status":30,"type":0,"chaishujia":{"username":"周姣姣0918","city":"南昌市"},"club":{"name":"南昌火炬分舵","city":"南昌"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp> 大家好，欢迎参加拆书帮南昌火炬分舵的拆书活动。我是拆书家周姣姣，本次练级级别是2-3。首先用三个标签介绍自己：OH卡带领师，心理咨询师，练级中的拆书家。\u003c/p>\u003cp> 【分组】\u003c/p>\u003cp>在活动开始前，我们先分个组，后面有讨论环节，左边两位一组，右边两位一组。\u003c/p>\u003cp>【学习目标】\u003c/p>\u003cp>现场小伙伴在跟随我完成本次学习后，当我们情绪难受、消极时，运用意义换框法帮，找到事件的积极意义。\u003c/p>\u003cp>【FAB图书介绍】\u003c/p>\u003cp>F\u003c/p>\u003cp>《重塑心灵》作者李中莹老师，被誉为华人世界的国际级NLP大师，他发展出大量独到而实用的思想和行为技巧，有效地帮助一个人培养出良好的心理素质。\u003c/p>\u003cp>A\u003c/p>\u003cp>与其他同类型书籍相比，本书强调自我价值、沟通技巧、情绪管理等，对个人成长和心理健康的重要性。通过具体的案例和讲解，帮助读者理解并运用相关知识，改善自身的心理状态和生活质量。\u003c/p>\u003cp>B\u003c/p>\u003cp>NLP研究人的大脑运作及提升效率，能够推动人快速地提升素质，享受成功快乐。\u003c/p>\u003cp>“意义换框法”可以从负面经验中找出正面意义。因为世界上所有的事情本身没有意义，所有的意义都只是人加注的。提醒我们在面对困难和挫折时，不要局限于负面感受，而是去挖掘其中可能蕴含的积极因素，从而更好地应对挑战，实现个人成长。\u003c/p>","ratings_count":1,"texts":[{"id":22354,"quote":"\u003cp>现在请大家用2分钟的时间阅读原文拆页，阅读好的小伙伴可以举手示意。\u003c/p>\u003cp>【原文片段】\u003c/p>\u003cp>意义换框法\u003c/p>\u003cp>意义换框法是 NLP 技巧“换框法”中最常用和最好用的技巧。它完全只凭言语 和思想模式而产生效果，是 NLP 的改变信念技巧中最快速最容易的一个。“意义换框法”是找出一个负面经验中的正面意义。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都只是人加诸的。既然是人加上去的意义，则一件事情——\u003c/p>\u003cp>可以有其他的意义，也可以有更多的意义\u003c/p>\u003cp>可以有不好的意义，也可以有好的意义。\u003c/p>\u003cp>试想一下，当你用一块石头去锤打一颗钉子，或者赶走一只老鼠，你赋予这块 石头的意义是什么？它本来有这些意义吗？再想一想，一块石头可以有多少用途？ 把上面问题引出的意念放在别人的一句话、一个行为，甚至环境出现的一些情 况上，会给你什么启示？\u003c/p>\u003cp>下次坐车没有事情做的时候，可以试想一想一只曲别针可以有多少用途。也许 这样你会明白一件事情的意义只是取决于我们的主观思想。\u003c/p>\u003cp>同一件事情里面总有不止一个意义包含其中。找出最能帮助自己的意义，便可 以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意 义换框法。\u003c/p>\u003cp>意义换框法对一些因果式的信念最为有效。例如： “因为上级挑剔，所以我工作不开心。\u003c/p>\u003cp>方法是把句中的“果”（工作不开心）改为它的反义词，再把句首的“因为”二字放到最后，成为：“上级挑剔，所以我工作积极，因为……”然后反复地思考如何能把句子写完，要求至少有六个不同的版本，再找出其中最能够接受的一句以下是一些学员的杰作：“上级挑剔.......&quot;\u003c/p>\u003cp>使他无从挑剔\u003c/p>\u003cp>使我提升得更快\u003c/p>\u003cp>使他改变对我的态度\u003c/p>\u003cp>使我超越他的标准\u003c/p>\u003cp>使我变得更能干使我更快升级，脱离他的管治\u003c/p>\u003cp>使我更有能力去另找新工作\u003c/p>\u003cp>使我在同事之中受到最少的挑剔，因而更有工作安全感\u003c/p>\u003cp>使我能更早创业\u003c/p>\u003cp>我要证明他不能控制我的情绪\u003c/p>\u003cp>我要证明我可以做到\u003c/p>\u003cp>使我能清静愉快地工作\u003c/p>\u003cp>证明在最难相处的上级的领导下我仍能胜任\u003c/p>\u003cp>证明我能超越任何压力\u003c/p>\u003cp>使其他老板注意我，因而创造出换工作的机会\u003c/p>\u003cp>使我有更优良的表现\u003c/p>\u003cp>试试挑选一条你觉得最好的，然后把整句反复地念数遍。现在，你再念念本来的句： “因为上司挑剔，所以我工作不开心。”你内心的感觉有怎样的不同？本来的一句和后来的一句，你觉得哪句更舒服一点？\u003c/p>","explains":"\u003cp>What\u003c/p>\u003cp>意义换框法是一种有效的心理调节工具，通过调整语句表达顺序，改变我们对特定事件、情景的观点或认知水平，帮助我们从消极的事件中找到积极的意义，从而改变我们的心态和行为。\u003c/p>\u003cp>Why\u003c/p>\u003cp>我们对事件的看法和感受，往往取决于赋予事件的意义。这种方法有助于转变思维，以积极的心态看待各种经历。\u003c/p>\u003cp>一般来说，当我们遭遇挫折或负面事件时，容易陷入消极情绪，难以从不同角度去看待事物，无法发现潜在的机会或积极意义，阻碍个人成长和发展。\u003c/p>\u003cp>不同的人对意义换框法的接受度和反映各不相同，由于性格、成长经历等原因，对改变认知存在较大抵触时，会影响使用效果，这时可以结合其他方法一起使用。\u003c/p>\u003cp>How\u003c/p>\u003cp>意义换框法，按照以下步骤：\u003c/p>\u003cp>1.识别消极事件。找出正在经历的哪些让人不开心、有压力或者带来负面感受的事情是什么，对这个具体时间有哪些不好的感受。\u003c/p>\u003cp>2.找出因果关系。运用“因为。。。所以。。。”的句式，找出消极事件和负面感受之间的因果关系。\u003c/p>\u003cp>3.寻找积极意义。从不同角度去思考消极事件，寻找其中的积极意义。可以问自己一些问题，比如“什么最重要？”“能够带给你些什么？”“凭它，你可以得到些什么？”“你最在乎的是什么？”。\u003c/p>\u003cp>4.替换负面信念。用找到的积极意义替换原来的负面信念，把结果改为积极感受和信念，重新表述。并反复念诵新的信念，让它深入自己的内心。\u003c/p>\u003cp>Where\u003c/p>\u003cp>当工作中遇到挫折、人际关系出现问题、生活上遇到困难等情况导致负面情绪时，可以运用意义换框法，找出事件中的积极意义。\u003c/p>\u003cp>个人案例\u003c/p>\u003cp>我前段时间因为直接回答领导“不知道”，被我的直属上司叫到办公室谈话，提醒让我多学业务，让我整天的心情都很烦躁。因为我已经承担了部门很多的工作，还要协调上级、同级和下级的工作，让我的工作量和压力都很大。再说领导问的又不是我工作范围内的事。从直属上司办公室出来后，我一天的心情都很沮丧。\u003c/p>\u003cp>后来我运用意义换框法，转换我的情绪。我意识到是上司批评我业务能力差，让我感到不满（识别消极事件）。因为我负责的业务、杂事工作比较多，让我感到不堪重负，所以我感到烦躁（找出因果关系）。因为负责的工作多，说明上司认可我的工作能力，信任我（寻找积极意义）。所以我对自己说：“因为工作任务多、工作量大，使我有机会提升工作能力”（替换负面信念）。\u003c/p>","interaction":"\u003cp>下面有一个场景，需要大家运用今天所学的意义换框法进行对话。\u003c/p>\u003cp>小周被领导安排写一篇宣传稿件，写好交给领导审核时，稿件被领导从头至尾批评一通，小周感到很挫败。作为小周的朋友，可以如何帮助小周呢？请大家应用意义换框法四步骤，通过角色扮演进行对话，一个扮演朋友，一个扮演小周，在小组内进行讨论。5分钟后，我会邀请一组小伙伴来分享，下面请大家开始小组讨论。\u003c/p>\u003cp>现场小伙伴的角色扮演对话\u003c/p>\u003cp>小周：最近好烦呐！\u003c/p>\u003cp>朋友：怎么了呀？\u003c/p>\u003cp>小周：上次加班写了一个宣传稿，被领导从头到尾批了一顿，感觉好失败呀。\u003c/p>\u003cp>朋友：就是那篇稿子吗？上次约你出来吃饭，你说你要写稿子的那篇吗？\u003c/p>\u003cp>小周：嗯\u003c/p>\u003cp>朋友：我看了下，觉得很好呀。你们领导要求很高呀。当我们努力做一件事情的时候，得不到认可，我们心情肯定会不好。但是我最近学到一个方法，意义换框法，四个步骤可以帮助你把心情调整下，你愿意试试吗？\u003c/p>\u003cp>小周：可以呀\u003c/p>\u003cp>朋友：第一步是识别消极事件，你觉得这件事情最大的负面事件是什么？\u003c/p>\u003cp>小周：被领导批评了呀，然后觉得现在心情也很不好。\u003c/p>\u003cp>朋友：如果用因果关系的句式去表达的话，你觉得是因为什么，所以什么。\u003c/p>\u003cp>小周：因为被领导批评了，然后自己也没有做好，所以感觉到自己很失败。\u003c/p>\u003cp>朋友：意义换框法最主要的一步就是说我们要寻找积极意义，这件事情中，肯定会有一些比较好的点，你觉得呢？那是什么呢？\u003c/p>\u003cp>小周：领导批评的时候也指出了一些问题，知道自己有可以成长的空间，知道自己的问题在哪里，可以下次做的更好一些。可能领导对我也有一些期待，但是没有达到他的期待值。\u003c/p>\u003cp>朋友：我们替换一个表达，被领导批评使你怎么样？\u003c/p>\u003cp>小周：因为被领导批评，使我认识到了自己成长点在哪里，以后我可以更好的完成工作。\u003c/p>\u003cp>朋友：现在你的心情有好些吗？\u003c/p>\u003cp>小周：好多了，非常帮！\u003c/p>\u003cp>好的，感谢小伙伴的分享，我的2-3拆书练级到此结束，谢谢大家的参与。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1726920423000,"updated_at":1727057378000,"ria":true},{"id":15810,"topic":"《重塑心灵》","learn_goal":"","remark":"改变信念系统的技巧\n一个人的思想、情绪和行为，都收他内心的信念系统支配。一些局限性的信念，可以使这个人每当卖你对某些人和事物的时候，不能做到三赢，并感受不到应有的成功快乐。过去积存的选择也就是他头脑里现有的神经元网络，这些选择既然无效，每次遇到同一件事，便只会重复那不理想的效果。欲想他有更好的表现，必须先让他建立一些更有效的信念，也就是建立新的神经元网络改进对待同类事情的想法和做法","level":"TF1-1","duration":15,"status":0,"type":0,"chaishujia":{"username":"梅子518","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp> 大家好，很高兴在拆书帮里面认识这么多正能量的爱学习的伙伴们，我先在这里介绍一下我自己，我叫郭琼梅，我是一个两个男孩的妈妈，也是一个工作十几年的牙医，在深圳也已经有十几年了\u003c/p>\u003cp>先给大家介绍一下何为拆书，拆书帮又是一个怎样的组织。\u003c/p>\u003cp>大部分人看书时，看书时热情澎湃，看后就丢脑后，能运用到自己的工作和生活中就更少了。而拆书就是一种学习方法，适用于提升能力和解决问题的成人学习。它分为个人学习的拆书帮便签读书法，还有应用组织学习的拆书帮现场学习法。个人学习便签学习法，包括RIA三个环节，R指阅读原文片段，I是学习者对于原文片段的理解，而A则是学习者拆违已用，包括对之前经验的反思，和对于未来计划的运用。而现场学习则是像我们今天的学习一样，在现场演练，在用中学，跟别人分享自己的体会，教会别人是最好的学习方法。\u003c/p>\u003cp>拆书帮则是一群运用拆书法的学习爱好者组成的社群，在这个学习社群中，一群志同道合者，秉着陪伴赋能、拆为己用、持续精进、共同成长的理念，在现场学习法中，释放自己的能量，助人达己。\u003c/p>","ratings_count":0,"texts":[{"id":19898,"quote":"\u003cp>改变信念系统的技巧\u003c/p>\u003cp>一个人的思想、情绪和行为，都受他内心的信念系统支配。一些局限性的信念，可以使这个人每当面对某些人事物的时候，不能做到三赢，并感受不到应有的成功快乐。过去积存的选择也就是他头脑里现有的神经元网络，这些选择既然无效，每次遇到同一件事，便只会重复那不理想的效果。欲想他有更好的表现，必须先让他建立一些更有效的信念，也就是建立新的神经元 网络改进对待同类事情的想法与做法。\u003c/p>\u003cp>松动信念的方法\u003c/p>\u003cp>以下方法所持的信念做出审视和界定，因而能够使之松动。所用的例子是一位家庭主妇应否每天等待丈夫回家一同吃饭。\u003c/p>\u003cp>1、改变标签。\u003c/p>\u003cp>例：“不等待他回来便吃东西是不尊重他”（标签）\u003c/p>\u003cp>”不等待他回来便吃东西是照顾自己“（新标签）\u003c/p>\u003cp>2、改变标签的意义\u003c/p>\u003cp>例：”自己因为太饿而没有力气。从而产生抱怨情绪，他回来后你不能给他好的照顾，这才是不尊重他呢！”\u003c/p>\u003cp>3、审视背后的动机，找出事情背后的正面动机，这往往需要找出更高的理解层次，即更大的意义、更广的覆盖面或范畴。可以问：“这样做会让你变得怎么样？会给你一些什么重要的东西？”这样有可能让这个主妇看到改变的好处。\u003c/p>\u003cp>例：“不等待他回来便吃东西，使我有气力做好家务，进而把东西收拾好，怀着轻松愉快的心情等待他回来。”\u003c/p>\u003cp>4、极度延伸。把维持旧信念的终极结果明显化。引导她自问，或者对她说：“你继续这样做，最终会有什么结果”\u003c/p>\u003cp>例：“继续这样做，偶然的胃痛会变成长期的胃病，身体坏了，什么事情都做不好，情绪发也会越来越坏，两人的关系会越来越紧张。”\u003c/p>\u003cp>以上的过程，最好是引导对方制造一些有视觉、听觉和感觉元素的未来镜像，这会产生支持改变信念的动力。上面的例子，其实真正的突破点可能是教导这个家庭主妇如何与丈夫共同讨论晚饭时间的安排，但是这位女士必须先让内心的旧信念动摇了，才会有动力去思考和开口。\u003c/p>","explains":"\u003cp>好的，大家已经都阅读完毕了吧。这个片段选自于李中莹老师的《重塑心灵》，一个人的固有观念，可能有所局限，所呈现的结果不一定能做到三赢，可能会让自己不开心，松动信念的方法能够改变固有的局限的观念，建立更有效的观念，从而能达到三赢的状态。具体怎么做呢？可以分四步：\u003c/p>\u003cp>1、改变标签\u003c/p>\u003cp>2、改变标签的意义\u003c/p>\u003cp>3、审视后面的动机\u003c/p>\u003cp>4、极度延伸\u003c/p>\u003cp>此方法适用于当自己面对一些事情，不能做到三赢，感到不开心和快乐时，想要有更好的表现时，改变自己固有的观念，从而改进同类事情的想法和做法，实现三赢。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>接下来我来分享一下我是如何运用松动信念法，让自己快乐起来，也让身边的人没有压力。我和我先生在前几年会经常因为一些琐事发生一些争论，当时的那种低气压，每个人心情都不好，两个人都认为自己是对的，都希望能让对方接受自己。具体的事情现在有很多都已经忘记了，但有一件非常小的事情目前还记忆犹新。\u003c/p>\u003cp>有一天傍晚，吃完饭后，我准备去散步，看到我先生坐在沙发上看书。当时我邀请他一起，先生拒绝了，我很生气。然后我说：“饭后一起散步多浪漫呀，我一直觉得我父母这样非常浪漫，为什么不可以一起？”我先生说“我认为饭后一起看书也很浪漫，你怎么不一起？”\u003c/p>\u003cp>很幸运遇到《重塑心灵》让我有所反思，让自己没有陷在自己的固有观念里面。\u003c/p>\u003cp>1、改变标签\u003c/p>\u003cp>先生和我一起饭后散步，这样很浪漫\u003c/p>\u003cp>饭后不一起散步，各自做自己喜欢的事情，大家都舒服\u003c/p>\u003cp>2、改变标签的意义\u003c/p>\u003cp>自己因为觉得夫妻一定要饭后散步才浪漫，这个其实是小时候看父母那样潜移默化的认为一定要那样，但是先生这个时候可能要休息，他很累，那么一起散步对他就是负担，他不开心的话，怎么来的浪漫呢。\u003c/p>\u003cp>3、审视背后的动机\u003c/p>\u003cp>饭后没有一起散步，我认为不浪漫，自己不开心。可能更深层次是我把快乐建立在对方身上。其实快乐可以自己创造，读一本好书，去旅游，去运动，这些能让自己更加完善，而不依附于其他人。接受饭后自己去散步，我多了独处的时间，在这个时间里面我可以随心所欲的让自己色思想放空，可以听自己喜欢的音乐和博客，可以自己锻炼身体，这些都能让自己心情更加愉悦，有了愉悦的心情，有了愉悦的心情，夫妻间沟通也会更顺畅。也许你的这些正向回馈也能让配偶看见，有一天他会主动加入到饭后一起散步中。\u003c/p>\u003cp>4、极度延伸\u003c/p>\u003cp>如果我一直按照自己固有的观念要求配偶，那么他不开心，而我也没得到我想要的，两个人情绪都不好，关系僵化，这个和三赢相违背了。\u003c/p>\u003cp>这些心理暗示，让我放下执念，拥抱每个人的不同，承认人和人不同，观念也不同，但是能找到三赢的方法，和谐相处。\u003c/p>\u003cp>A2\u003c/p>\u003cp>我计划在这周内，对于孩子阅读打卡这件事情，我和先生不同的处理方式，让自己不开心，按照下面的步骤，松动信念，改进达成三方都开心的状态：\u003c/p>\u003cp>1、改变标签\u003c/p>\u003cp> 按老师要求每日在打卡圈发布阅读打卡，把阅读当作任务\u003c/p>\u003cp> 按老师要求每日在打卡圈发布阅读打卡，可以让孩子看到自己的进步，让自己更有动力。\u003c/p>\u003cp>2、改变标签的意义\u003c/p>\u003cp> 阅读打卡，老师能看到孩子的阅读，及时做出正向的反馈，这样孩子可以不断被激发，更有动力去阅读。先生对不打卡带来的后果的担忧也没有了，这样家庭气氛会更和谐，大家都开心了，阅读环境会更好。、\u003c/p>\u003cp>3、审视背后的动机\u003c/p>\u003cp> 我希望阅读是无功利性的发，先生看到的是及时反馈有助于激发孩子的潜能，这两个观念都没有错。如果进行打卡，先生没有思想负担，老师乐于看到结果，孩子可以看到自己的阅读成果，也不影响阅读体验，只要不当成负担。\u003c/p>\u003cp>4、极度延伸\u003c/p>\u003cp> 可以在协商中解决问题，可以跟先生协商，我不喜欢当作任务式的打卡，那么这项任务可以让先生承担，而我只需要和孩子共同阅读，想搜阅读带来的快乐就行。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1684310380000,"updated_at":1684310380000,"ria":true},{"id":15524,"topic":"意义换框法","learn_goal":"","remark":"作者是李中莹，是华人世界的国际级NLP大师，(这里解释下NLP,它是研究人大脑如何工作的学问）。本书主要是教我们如何使用NLP技法提高为人处事能力，建立成功快乐的人生","level":"TF2-1","duration":27,"status":30,"type":0,"chaishujia":{"username":"佑佑","city":"襄阳市"},"club":{"name":"襄阳朗瑟分舵","city":"襄樊"},"prologue":"\u003cp>各位老师们好，欢迎大家来到拆书帮线上活动。首先自我介绍下，我叫左天江。老规矩三个标签分别是淘宝店主，带娃宝爸，一级拆书家。\u003c/p>\u003cp>今天一共10位老师，为了方便学习讨论，我们现场老师分成两组，前面5位为一组，后面5位为一组，谢谢。\u003c/p>","ratings_count":1,"texts":[{"id":19577,"quote":"\u003cp>\u003cstrong>意义换框法 \u003c/strong>\u003c/p>\u003cp>意义换框法是 NLP 技巧“换框法”中最常用和最好用的技巧。它完全只凭言语 和思想模式而产生效果，是 NLP 的改变信念技巧中最快速最容易的一个。“意义换 框法”是找出一个负面经验中的正面意义。它的概念基础是：世界上所有的事情本 身是没有意义的，所有的意义都只是人加诸的。既然是人加上去的意义，则一件事 情—— \u003c/p>\u003cp>可以有其他的意义，也可以有更多的意义 \u003c/p>\u003cp>可以有不好的意义，也可以有好的意义。 \u003c/p>\u003cp>试想一下，当你用一块石头去锤打一颗钉子，或者赶走一只老鼠，你赋予这块 石头的意义是什么？它本来有这些意义吗？再想一想，一块石头可以有多少用途？ 把上面问题引出的意念放在别人的一句话、一个行为，甚至环境出现的一些情 况上，会给你什么启示？ \u003c/p>\u003cp>下次坐车没有事情做的时候，可以试想一想一只曲别针可以有多少用途。也许 这样你会明白一件事情的意义只是取决于我们的主观思想。 \u003c/p>\u003cp>同一件事情里面总有不止一个意义包含其中。找出最能帮助自己的意义，便可 以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意 义换框法。 \u003c/p>\u003cp>意义换框法对一些因果式的信念最为有效。例如： “因为上级挑剔，所以我工 作不开心。 \u003c/p>\u003cp>方法是把句中的“果”（工作不开心）改为它的反义词，再把句首的“因为” 二字放到最后，成为： “上级挑剔，所以我工作积极，因为……”然后反复地思考 \u003c/p>\u003cp>如何能把句子写完，要求至少有六个不同的版本，再找出其中最能够接受的一句以下是一些学员的杰作： “上级挑剔.......&quot; \u003c/p>\u003cp>使他无从挑剔 \u003c/p>\u003cp>使我提升得更快 \u003c/p>\u003cp>使他改变对我的态度 \u003c/p>\u003cp>使我超越他的标准 \u003c/p>\u003cp>使我变得更能干使我更快升级，脱离他的管治 \u003c/p>\u003cp>使我更有能力去另找新工作 \u003c/p>\u003cp>使我在同事之中受到最少的挑剔，因而更有工作安全感 \u003c/p>\u003cp>使我能更早创业 \u003c/p>\u003cp>我要证明他不能控制我的情绪 \u003c/p>\u003cp>我要证明我可以做到 \u003c/p>\u003cp>使我能清静愉快地工作 \u003c/p>\u003cp>证明在最难相处的上级的领导下我仍能胜任 \u003c/p>\u003cp>证明我能超越任何压力 \u003c/p>\u003cp>使其他老板注意我，因而创造出换工作的机会 \u003c/p>\u003cp>使我有更优良的表现 \u003c/p>\u003cp>试试挑选一条你觉得最好的，然后把整句反复地念数遍。现在，你再念念本来 的句： “因为上司挑剔，所以我工作不开心。”你内心的感觉有怎样的不同？本来的 一句和后来的一句，你觉得哪句更舒服一点？\u003c/p>","explains":"\u003cp>我们今天的学习目标是，在本次RIA现场学习后，当我们意识到自己开始陷入负面情绪了，就停下来，通过【意义换框法】来摆脱当下的负面情绪，掌控自己的情绪，以一种积极的心态去看待和处理问题。\u003c/p>\u003cp> 接下来介绍下今天这本书——《重塑心灵》\u003c/p>\u003cp>【F特征】它作者是李中莹，是华人世界的国际级NLP大师，(这里解释下NLP,它是研究人大脑如何工作的学问）。本书主要是教我们如何使用NLP技法提高为人处事能力，建立成功快乐的人生。\u003c/p>\u003cp>【A优势】这本书优势是： 1、它是国内心理学入门普及书的经典之一，畅销21年；2、相比其它心理学书来说，它所讲的理论更加通俗易懂，所提供的方法简单实用，快速有效。\u003c/p>\u003cp>【B利益】\u003c/p>\u003cp>B1这本书能给你们带来什么好处呢？在生活中，我们经常会听到自己和别人发出类似的声音，如“为何我总是不开心？”“你怎么就是不听我的呢？”其实这是个人的信念系统、沟通方式和情绪管理出现了问题。阅读本书，你将学会改善自己的人际关系网络，拥有充满力量的健康心理！\u003c/p>\u003cp> B2今天带来P51-52的拆页分享，主要是可以帮助我们走出负面情绪。在遇到负面情绪的事情时，给我们提供正确的方法去处理它，摆脱负面情绪的影响，让自己能够以积极心态去面对和解决问题。\u003c/p>\u003cp>\u003cstrong>环节3：R阅读原书拆页。\u003c/strong>\u003c/p>\u003cp>现在屏幕上是今天的拆页，给大家2分钟的阅读时间，看完了的小伙伴可以在评论区扣个1 示意一下。\u003c/p>\u003cp>\u003cstrong>环节4：I讲解引导\u003c/strong>\u003c/p>\u003cp> 【what】意义换框法是一种快速高效处理负面情绪的方法。通过不同的角度，找到事情中最能帮助自己的意义和价值，跳出原本看待事情的“框架”，从而达到提升自己目的。\u003c/p>\u003cp>【why】采用意义换框法能帮助把事情的负面意义转化为正面意义，摆脱负面意义的干扰，以一种更积极的心态去做一件事，增加胜算的概率，从而使未来行动变得更好。 \u003c/p>\u003cp>它是怎么作用的呢？世界上所有的事情本身没有意义的，所有的意义是我们人为赋予上的，从这个角度来说，事情的意义取决于我们的主观意识，一件事情从不同的角度，可以找到很多的意义，我们需要从中找到对自己最有帮助的意义，从中获得成长提升自己。\u003c/p>\u003cp>相信大家多少都会遇到以下情况：工作上被经理批评了，往往情绪或低落，或愤怒，甚至对抗；在生活中，孩子不听话，自己很生气，发脾气；爱人应酬晚回家，自己对家庭很失望，冷战，冲突。如果这些负面情绪出现了，不应用这种方法有什么坏处呢，这些负面情绪会一直你脑中晃荡，影响你接下来一段时间甚至好几天的情绪和行动，同时也影响自己身边的人和事，甚至往失控的方向发展。\u003c/p>\u003cp>上个星期我就遇到一个客户投诉，客户收到了东西时就挑三捡四，提出各种要求，时不时还威胁几句，极力给他解释但最后还是被投诉了。但这件事影响了一下午心情就不好，接下来的工作就心不在焉。更坏的影响还在后面，晚上回家后，因为一点小事就对孩子发起脾气。\u003c/p>\u003cp>意义换框法可以应用在生活、工作、情感沟通等方面，适合帮助有情绪困扰的暂时走出情绪困境，当然使用前提是这个人自己想改变，且情绪没有严重的心理问题。\u003c/p>\u003cp>【why】具体如何做呢？很简单，只有四步：\u003c/p>\u003cp>\u003cstrong>1、整理因果。\u003c/strong>\u003c/p>\u003cp>首先运用“因为……所以……”的因果句式，把对事情的理解写出来。这个原因可以是事实，也可以是假设。\u003c/p>\u003cp>比如，因为今天主管狠狠批评了我，所以我很难过\u003c/p>\u003cp>\u003cstrong>2、转换因果。\u003c/strong>\u003c/p>\u003cp>把句中的结果改为它的反面，再把句首的“因为”二字放到最后。\u003c/p>\u003cp>比如，今天主管狠狠批评了我，所以我很开心，是因为..........。\u003c/p>\u003cp>\u003cstrong>3、寻找意义。\u003c/strong>\u003c/p>\u003cp>多角度地寻找事情的意义，最少得完成6个不同版本的，从而使新的因果关系和逻辑成立。\u003c/p>\u003cp>\u003cstrong>4、优选价值\u003c/strong>\u003c/p>\u003cp>从上面意义挑选自己最能接受的，反复默念，直到改变自己的信念。\u003c/p>\u003cp> 就拿我自己刚才的例子，应用意义换框法加工如下：\u003c/p>\u003cp>第一步，今天可以按因果式整理下这个事，\u003cstrong>因为客户很挑剔，所以我工作很不开心\u003c/strong>。\u003c/p>\u003cp>第二步，转换说法：\u003cstrong>客户很挑剔，所以我工作很开心\u003c/strong>，是因为…………\u003c/p>\u003cp>第三步，寻找意义\u003c/p>\u003cp>因为不管结果如何我挣到他的钱了，只是多少的问题，\u003c/p>\u003cp>因为客户让我看到了自己能力不足，\u003c/p>\u003cp>因为我有机会学习到更多处理售后的经验，\u003c/p>\u003cp>因为可以训练我强大的内心，\u003c/p>\u003cp>因为学习到了如何控制我的情绪，\u003c/p>\u003cp>因为这事将是我事业成功的垫脚石。\u003c/p>\u003cp>第四步，优选价值，挑选出最适合自己的，直到信念改变。\u003c/p>\u003cp>默念两遍，客户很挑剔，所以我工作很开心，因为我有机会学习到更多处理售后的经验。与这句话“因为客户很挑剔，所以我工作很不开心，”比较下这两句，我感觉舒服多了。接下来对待被投诉的事情转变了看法，就会积极去处理这事情。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1激活经验\u003c/strong>\u003c/p>\u003cp> 请大家回忆下，最近一次比较强烈的负面情绪，比如在与家人生活相处中，有没有生气、无助、愤怒等，再比如与同事/领导/客户之间有没有郁闷、挫败、顶撞等，可以感受下当时这种的情景（包括时间、经过、结果等）。 请大家想一想，在小组里分享，给大家3分钟时间。\u003c/p>\u003cp>栗子老师：拆书帮作主播带货视频，从网上找素材，录制，合成，编辑视频（包括字幕，音乐，动画），整整在电脑前弄了5个多小时，由于前几年眼部手术的原因，眼睛受不了，泪流满面，当时很抱怨这件事。\u003c/p>\u003cp>\u003cstrong>A1+反思加工\u003c/strong>\u003c/p>\u003cp> 根据今天拆页所学的方法，结合刚刚自己的案例，可以想像下回到过去，应用\u003cstrong>意义换框法\u003c/strong>的方法和步骤，反思下自己更好的做法和选择，先用因果式总结下，再尝试着转换因果，寻找意义，优选出对自己最有帮助价值的意义。给大家5-7分钟时间，呆会找位老师分享下。\u003c/p>\u003cp> 栗子老师：\u003c/p>\u003cp>\u003cstrong>整理因果：\u003c/strong>因为做主播拆书带货视频，让我眼疾发作，所以情绪上十分抱怨。\u003c/p>\u003cp>\u003cstrong>转换因果：\u003c/strong>做主播拆书带货视频，让我眼疾发作，所以我情绪上十分开心，是因为……\u003c/p>\u003cp>\u003cstrong>寻找意义：\u003c/strong>因为我锻炼到了作视频剪辑的技能，因为视频推广了给我点赞了，让更多的人看到我，因为突破了自己，因为视频爆了，会有金钱的回馈，因为有了这个，在圈里的名声更大了，因为我的眼睛熬不住5个小时，要多休息\u003c/p>\u003cp>\u003cstrong>优先价值：\u003c/strong>做主播拆书带货视频，让我眼疾发作，所以我情绪上十分开心，是因为视频推广了给我点赞了，让更多的人看到我。\u003c/p>\u003cp>结束语.\u003c/p>\u003cp>很高兴XX老师的分享，把意义换框法应用得十分到位。这里总结下今天学习的内容，意义换框法一共分四个步骤：整理因果，转换因果，寻找意义，优选价值。我们大家在日常工作、生活中，可以多加练习，熟练地掌握运用。\u003c/p>\u003cp>好了，今天我的T2-1分享到这里结束了，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1680613083000,"updated_at":1681278152000,"ria":true},{"id":15284,"topic":"意义换框法","learn_goal":"","remark":"李中莹先生很早就把NLP完整地介绍到国内，因而被誉为“华人世界的国际级NLP大师”，他发展出大量独到而实用的思想和行为技巧，可以有效地帮助一个人培养出良好的心理素质。今天介绍的意义换框法，是NLP技巧“换框法”中最常用和最好用的技巧，让我们找到负面经验中的正面意义，从积极的角度去看待事情，拥有乐观的心态。","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"emilyxiao","city":"深圳市"},"club":{"name":"深圳桃李分舵","city":"深圳"},"prologue":"\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，在学习者遇到负面经历的时候（行为场景），能通过“意义换框法”的三个步骤（澄清，如何做），找出（行为动词）负面经历当中的正面意义（界定，做到什么）”。\u003c/p>\u003cp>大家好，我是今天的拆书家Emily。因为今天的拆书我们有一个小组讨论的环节，我先给大家分一下小组，从这边开始，相邻的3个人为一个小组。\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>周六下班的时候，我和朋友一起吃饭，她跟我吐槽说：“哎呀，我们上班工作压力真的太大了！我才刚进公司没多久，老板就总是问我有没有给客户送样品，有没有在谈的订单，我感觉人都要被逼疯了。我看公司其他部门的人也没好到哪里去，研发部的人也是被催项目催到天天加班；最近要开代理商大会，听说市场部的天天改文案已经改到要吐了...天呐，我们公司上班真的太难了~”\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>不知道在座的小伙伴们有没有遇到类似的朋友的吐槽，或者自己向身边的朋友吐槽过呢？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>当我们遇到这种压力山大的情况的时候，我们第一反应就是自己太难了，公司太苛刻了，久而久之，就会越来越厌倦这样的环境，工作也越来越不积极。自己也会觉得越来越不开心，最后甚至会产生离职的想法。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>今天给大家带拆的图书叫《重塑心灵》，作者李中莹先生很早就把NLP完整地介绍到国内，因而被誉为“华人世界的国际级NLP大师”，他发展出大量独到而实用的思想和行为技巧，可以有效地帮助一个人培养出良好的心理素质。今天我们一起要学习的意义换框法，是NLP技巧“换框法”中最常用和最好用的技巧，让我们找到负面经验中的正面意义，从积极的角度去看待事情，拥有乐观的心态。\u003c/p>\u003cp>好，接下来请大家先用１分钟时间来做一下拆页上的自测题，针对下面5种情况，1代表完全不符合，6代表非常符合。测完后，请大家把分数加起来，看看得分是多少。\u003c/p>\u003cp>&lt;解释自测题&gt;\u003c/p>\u003cp>好，我看大家都已经测完了。调查一下，15分以下的伙伴请举一下手；16-24分的伙伴请举一下手；25以上的伙伴请举一下手。这个自测题主要是看下大家在遇到情绪，特别是负面的情绪体验的时候，是不是可以用更积极的角度去思考。\u003c/p>\u003cp>如果你的分数是15以下，说明你容易沉溺在对事件的负面想法当中；\u003c/p>\u003cp>如果你的分数是16-24分之间，说明你面对事情时，会有一些积极的思考，但是偶尔还是会被负面情绪困扰。\u003c/p>\u003cp>如果是25分以上，说明你面对事情时，总是可以用积极的思维去思考，恭喜你。\u003c/p>","ratings_count":1,"texts":[{"id":19322,"quote":"\u003cp>\u003cstrong>意义换框法\u003c/strong>\u003c/p>\u003cp>“意义换框法”是NLP技巧“换框法”中最常用和最好用的技巧。它完全只凭言语和思想模式而产生效果，是NLP的改变信念技巧中最快速最容易的一个。\u003cstrong>“意义换框法”是找出一个负面经验中的正面意义\u003c/strong>。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都只是人加诸的。既然是人加上去的意义，则一件事情——\u003c/p>\u003cp>◇ 可以有其他的意义，也可以有更多的意义；\u003c/p>\u003cp> ◇ 可以有不好的意义，也可以有好的意义。\u003c/p>\u003cp>试想一下，当你用一块石头去锤打一颗钉子，或者赶走一只老鼠，你赋予这块石头的意义是什么？它本来有这些意义吗？再想一想，一块石头可以有多少用途？把上面问题引出的意念放在别人的一句话、一个行为，甚至环境出现的一些情况上，会给你什么启示？下次坐车没有事情做的时候，可以试想一想一只曲别针可以有多少用途。也许这样你会明白一件事情的意义只是取决于我们的主观思想。\u003c/p>\u003cp>\u003cstrong> 同一件事情里面总有不止一个意义包含其中\u003c/strong>。\u003cstrong>找出最能帮助自己的意义，便可以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升\u003c/strong>。这便是意义换框法。\u003c/p>","explains":"\u003cp>好的，我看到大部分小伙伴已经阅读完了。\u003c/p>\u003cp>在讲“意义换框法”之前，我先给大家简短的介绍一下NLP。NLP是三个英文单词的缩写（Neuro Linguistic Programming）， 意思是神经语法程序，用直白一点的话说，就是研究我们的大脑如何运作。意义换框法属于NLP里面的一种技巧，它的底层逻辑是事件本身是没有意义的，是人为赋予的，我们可以通过思考事件的不同意义，找到负面经验当中正面的意义。具体怎么理解呢，我给大家做一个类比，我们现在都知道美颜相机对吧，美颜相机有很多滤镜，每一种滤镜对应不同的图像效果。当我们对图片不满意的时候，可以用不同的滤镜来处理，最后选择自己最喜欢的那个滤镜。回过头来看意义换框法，就是把自己的大脑当做美颜相机，事件就是图片，我们赋予的意义就是滤镜。我们可以像选择滤镜那样对事情赋予不同的意义，找出自己对自己最有帮助，最有价值的意义。\u003c/p>\u003cp>\u003cstrong>&lt;举例&gt;\u003c/strong>\u003c/p>\u003cp>比如我们刚才提到的朋友抱怨压力大，刚进公司就被各种催单需要出业绩。那我们就可以运用意义换框法，去思考除了让人压力大之外，老板催业绩这件事情还有没有其他的特别是积极的意义呢？比如可以让自己快速提升客户开发技能，比如可以让自己更快速的熟悉公司产品等等。\u003c/p>\u003cp>\u003cstrong>&lt;简短互动&gt;\u003c/strong>\u003c/p>\u003cp>我这样讲大家明白“意义换框法”的含义了吗？已经理解的伙伴请举一下手！我邀请一位伙伴用一句话想分享一下他的理解\u003c/p>\u003cp>&lt;学习者回答&gt; \u003c/p>\u003cp>\u003cstrong>爱华：\u003c/strong>意义换框法就是刚刚讲到的，能够找到负面经验中的正面意义。\u003c/p>\u003cp>我再给大家举一个例子：比如你辛辛苦苦加班熬夜赶出来的方案，老板就一句不满意就把你打发了，你第一反应觉得很委屈，自己的劳动成果没有得到认可。\u003c/p>\u003cp>\u003cstrong>&lt;简短互动&gt;\u003c/strong>\u003c/p>\u003cp>请问大家，这个负面经历当中的事件是什么？对事件赋予的意义又是什么？\u003c/p>\u003cp>&lt;学习者回答&gt;\u003c/p>\u003cp>\u003cstrong>婷婷：\u003c/strong>事件是老板不满意自己的方案。赋予的意义是自己的劳动成果没有得到认可。\u003c/p>\u003cp>当我们有一个负面经历的时候，很重要的一点就是要把事件和给事件赋予的负面意义分开。然后再去思考这件事情本身带来的正面意义，最后找到最有价值的意义。\u003c/p>\u003cp>结合我们前面所讲的，对于用意义换框法找出负面经历当中的正面意义，我总结出了以下的三个步骤：\u003c/p>\u003cp>第一步：分离出负面经历当中的发生的具体事件和负面意义；\u003c/p>\u003cp>第二步：思考具体事件的正面意义，尽量多写几条（3条或以上）；\u003c/p>\u003cp>第三步：找到自己最满意，最有价值的意义；\u003c/p>\u003cp>\u003cstrong>&lt;举例&gt;\u003c/strong>\u003c/p>\u003cp>上周的时候我去拜访一个客户，那个客户我自认为一直给的支持是非常多的 ，包括价格，售后，出货等方面支持都很到位，给他们的价格甚至比我最大的客户还低，可以说是我所有客户里面最好的。但是到了客户那里，他就一直说我们不重视他们，产品培训没有做到位，价格也比其他家的高，说了一大堆，让我感觉他们简直是得寸进尺，但是当着客户的面也不好发作，嘴上说着我们会改进，心里暗暗的觉得这客户太难伺候了。\u003c/p>\u003cp>事后回来复盘的时候，我想到了意义换框法的内容，于是我按照这三个步骤重新思考了整个经历。\u003c/p>\u003cp>\u003cstrong>首先，发生的具体事件是\u003c/strong>我去拜访客户，被客户说我工作做的不好，不重视他们。我赋予这件事情的\u003cstrong>负面意义是\u003c/strong>客户得寸进尺，很难伺候。\u003c/p>\u003cp>接下来我试着\u003cstrong>思考这件事情带来的正面意义\u003c/strong>，我写了三条\u003c/p>\u003cp>1. 客户觉得我们产品培训不到位，我可以更贴切的表述来完善产品培训PPT，有新产品第一时间更新给客户\u003c/p>\u003cp>2. 客户觉得我们价格比其他家的高，我可以多去了解竞争对手的价格和产品质量，帮助客户强化我们产品的优势和竞争力\u003c/p>\u003cp>3. 我可以服务好要求这么苛刻的客户，那么我服务客户的能力会提到提升，以后在遇到难缠的客户我也可以做的很好了\u003c/p>\u003cp>这样的思考之后，我对比\u003cstrong>发现第三点是对我最有启发的，让我感觉最有价值的\u003c/strong>，这时我内心的怨气也消失了不少。\u003c/p>","interaction":"\u003cp>接下来，是我们的学以致用环节，我请大家进行一个情景演练。具体的场景是这样的：\u003c/p>\u003cp>小花最近心情不太好，于是她去找好朋友小明倾诉。小花说她遇到了一位非常挑剔的领导，一句经典的台词就是“凡事最高要求是满意，最低要求也是满意”。小花有时候费尽心思写好的方案，领导就回复两个字“重写”。本来她觉得自己能力还不错的，但是面对这样的领导，她总是觉得自己哪里会做的不好，每天上班都感觉很紧张，像在走钢丝一样。\u003c/p>\u003cp>请根据上面给出的信息，结合我们今天所学的“意义换框法”的三个步骤，帮助小花走出心情不好的阴霾。\u003c/p>\u003cp>请大家在小组内进行讨论，时间5分钟。按照刚才的分组，一个人扮演小花，一个人扮演小明，讨论结束后，我邀请一个小组来分享。大家可以把步骤的关键词写在纸上。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者：JESSIE（小明）， 婷婷（小花）\u003c/strong>\u003c/p>\u003cp>小花：我方案又被毙了，还是得重写，我领导他怎么那么苛刻呀！\u003c/p>\u003cp>小明：那你就是因为方案又被毙了\u003cstrong>（事件\u003c/strong>），觉得领导苛刻对吧\u003cstrong>（负面意义）\u003c/strong>。\u003c/p>\u003cp>小花：我觉得自己挺不错的，领导觉得方案还有要提高的方面。\u003c/p>\u003cp>小明：那你觉得领导对你苛刻对你来说有什么好处呢？\u003c/p>\u003cp>小花：我觉得可以加强对他的沟通，说不定只是我对他的刻板印象。他说不定只是为了好意提醒我提升工作技能。\u003c/p>\u003cp>小明：还有吗？\u003c/p>\u003cp>小花：还有我本来觉得自己挺不错的，他指出来之后我觉得可以写的更专业一些，然后我重新写一版给他看一下，说不定就能过了，我写方案的能力也提升了。哎呀我心情好像好多了。\u003cstrong>（正面意义）\u003c/strong>\u003c/p>\u003cp>小明：所以从这件事情你也看到很多正面的意义。\u003c/p>\u003cp>小花：对\u003c/p>\u003cp>小明：这几个正面意义里面是哪个让你觉得心情好多了？\u003c/p>\u003cp>小花：我觉得提升写方案的能力吧\u003cstrong>（最有价值的意义）\u003c/strong>，因为开始觉得是领导苛刻的对我。反思了一下说不定我可以把方案写的更精彩一些。一方面领导认可了，另一方面我的写作能力也提升了，这多棒。\u003c/p>\u003cp>小明：所以就没那么焦虑了\u003c/p>\u003cp>小花：对\u003c/p>\u003cp>\u003cstrong>&lt;与人分享&gt;\u003c/strong>\u003c/p>\u003cp>现在请大家想想，自己的朋友或者家人会不会遇到有负面经历的时候呢？我们今天学习的“意义换框法”有没有可能帮到他呢？假如回去后，你要将意义换框法分享给一个人，那么\u003c/p>\u003cp>你最想分享的人是谁？请将名字写下来 \u003c/p>\u003cp>你会在什么时间分享呢？ \u003c/p>\u003cp>你会怎么分享“意义换框法”呢？\u003c/p>\u003cp>请大家在纸上写下来，稍后我会请一位小伙伴来分享。\u003c/p>\u003cp>\u003cstrong>&lt;学习者案例记录&gt;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>分享者：Doris\u003c/strong>\u003c/p>\u003cp>我最想分享的人是我男朋友\u003c/p>\u003cp>时间：今天回来之后\u003c/p>\u003cp>具体内容：\u003c/p>\u003cp>我男朋友他们公司经常换领导，他在公司七八年了，换了好多领导。他也经常跟我抱怨，我之前也开导过他。那他今天回来之后呢，当他跟我抱怨说他老板又是十一二点发微信让他继续工作，首先我就会分析一下发生了什么事，然后他是怎么感受这个事儿的。（\u003cstrong>具体事件和负面意义\u003c/strong>），他可能会说24小时让我待命，我觉得很烦。第二我会问他，你老板这样对你还有什么好的地方吗？他可能会说可以提升工作能力，再就是如果这个老板能搞定，那未来换更多的老板，他还是一样可以搞定。（正面意义）然后我就会跟他说你看在这个公司七八年，领导都换了那么多，你还一直都在，你的抗压能力还是很强的，是可以搞定领导的\u003cstrong>（最有价值的意义）\u003c/strong>。他很喜欢肯定的语言，我觉得这个转念的观念是非常好的。\u003c/p>\u003cp>在我们的工作和生活当中，难免会遇到一些负面的经历。当我们学习了意义换框法并加以运用的时候，就会慢慢的转变我们对事件的看法。久而久之，我们再遇到类似的事情，就会更多的想到它的正面意义，我们的思维也会变得越来越积极了。以上就是我今天拆书的全部内容了，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1677927966000,"updated_at":1679144767000,"ria":true},{"id":15196,"topic":"如何建立自信","learn_goal":"","remark":"了解肯定的价值，以及如何通过肯定建立自信，提升自我价值感，重塑心灵，成就快乐人生","level":"TF3-3","duration":80,"status":30,"type":0,"chaishujia":{"username":"yangzhuanfu","city":"重庆市"},"club":{"name":"重庆山城分舵","city":"重庆市"},"prologue":"\u003cp>【自我介绍】\u003c/p>\u003cp>大家好，我是杨转福，可以叫我卷福，一个转型推动者，致力于以教练技术推动个人转型，以数字化转型方法论推动企业转型，很高兴认识大家，我今天挑战的等级是TF3-3。\u003c/p>\u003cp>美国著名作家爱默生曾经说过：“自信是成功的第一秘诀”，我今天给大家带来的书籍和话题，是《重塑心灵》里边关于如何建立自信的话题。\u003c/p>\u003cp> \u003cstrong>【场景法介绍图书】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>事件场景：\u003c/strong>我想和大家分享一个我朋友因为不自信，工作中陷入低谷的故事。我有个很好的朋友，最近刚从自己工作了10年的报社辞职，去到一个民营企业做新媒体相关的岗位。因为以前她是在国企工作，条条框框和规范以及工作内容都很明确，但是在这个新的民营企业，公司各种规范制度都不明确，她担心自己不能胜任这个岗位的工作，也对自己能不能过试用期很没有信心，所以她特别怕犯错，这也导致她在跨部门沟通遇到了严重问题，很多需要她去主动推进协调的工作，她会选择回避，能拖就拖，这反而导致她被领导多次批评，她开始变得更加不自信和犹犹豫豫。在她看来，如果试用期工作丢了，失去收入不说，婚姻的稳定性可能也会受影响。她的工作生活陷入了一种深深的低谷，感觉到内心没有力量，整日惶恐。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>大家有没有像我朋友一样，因为不自信，自我价值感低，导致工作或者生活中陷入低谷的时刻？当陷入低谷的时候，你是不是也感觉到内心没有力量，整个天空都是灰暗的？当这种消极的情绪蔓延的时候，大家会怎么做呢？这会对我们的工作生活有些什么影响呢？\u003c/p>\u003cp>\u003cstrong>影响：\u003c/strong>其实，这种不自信带来的低谷或者消极的情绪，非常影响我们的工作生活。如果一个人长期不自信，他的自我价值感也会严重不足，他的情绪状态会变得消沉，会导致职场升迁受阻，生活质量下降，家庭幸福程度降低，最终会影响他的整个未来人生的幸福程度。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>那该怎么解决自信和自我价值的问题呢？这本《重塑心灵》给了我们答案：要想建立自信和自我价值，我们需要明确自信的价值，以及如何通过做事去建立自信。作者也给出了一个具体怎么建立自信的万能公式。\u003c/p>\u003cp>[引导互动]\u003c/p>\u003cp>拆书家提问：大家想不想知道这个万能公式是什么？想不想？\u003c/p>\u003cp>学习者反馈：想。\u003c/p>\u003cp>拆书家反馈：先不告诉大家，留个悬念，且听我慢慢道来。今天带来的两个片段，一个是讲的是自信的价值和重要性（心法），一个讲的是如何建立自信的具体操作步骤（手法）。\u003c/p>\u003cp>接下来，让我们先学习第一个片段的内容。首先让我们明确第一个片段的学习目标：\u003c/p>\u003cp>\u003cstrong>\u003cu>【片段一学习目标】\u003c/u>\u003c/strong>\u003c/p>\u003cp> 希望大家在跟随我完成本次RIA现场学习后，当身边的亲朋好友面临消极情绪、心灰意冷、内心没有力量、老是自责等不自信的场景时，能够使用“如何成为一个自信的人”四步法，现场编写出一个帮助他们提升自信程度的故事。\u003c/p>","ratings_count":2,"texts":[{"id":19224,"quote":"\u003cp>\u003cstrong>\u003cu>【片段一：自信与人生】\u003c/u>\u003c/strong>\u003c/p>\u003cp>自信带给人生的是一种\u003cstrong>积极的态度\u003c/strong>，以及由此带来的处理人生事务的能力。因为相信自己，便\u003cstrong>不会\u003c/strong>凡事都去\u003cstrong>指望别人\u003c/strong>，并且稍不如意便牢骚满腹。自信的人总是\u003cstrong>自己去努力\u003c/strong>，\u003cstrong>很平和很从容\u003c/strong>地朝着\u003cstrong>人生目标一步步迈进\u003c/strong>，在\u003cstrong>过程中\u003c/strong>体验充实与快乐，在\u003cstrong>结果中\u003c/strong>感受成功和满足，在\u003cstrong>一个个目标实现的同时\u003c/strong>积累更多的自信。\u003c/p>\u003cp>一个人有了充足的自信，并不意味着他什么烦恼都没有了，而是意味着他\u003cstrong>有足够的力量\u003c/strong>来处理人生中的烦恼。生老病死、苦辣酸甜，是每个人都必须面对的。自信的人，往往\u003cstrong>具备足够的能力\u003c/strong>，同时又在\u003cstrong>想方设法增添更多的能力\u003c/strong>。他\u003cstrong>不怨天尤人\u003c/strong>，也\u003cstrong>不畏惧逃避\u003c/strong>，在面对困难时会\u003cstrong>采取积极的态度\u003c/strong>，只要态度积极，办法总是会有的，NLP相信凡事至少有三个解决方法。即便最坏的情况出现，自信的人也会抱着“\u003cstrong>面对、接受、放下\u003c/strong>”的态度，\u003cstrong>从容\u003c/strong>应对林林总总的事情。自信的人，其人生必然是\u003cstrong>积极进取\u003c/strong>，同时又是\u003cstrong>知足常乐\u003c/strong>的。\u003c/p>\u003cp>注释1：NLP是神经语言程序学（Neuro-Linguistic Programming）的英文缩写，研究的是我们的\u003cstrong>语言对身心起作用的程序\u003c/strong>。它起源于研究卓越人士特别成功的原因，把结果化成一套一套的技巧程序，使其他人也可以成为卓越人士。\u003c/p>","explains":"\u003cp>\u003cu>\u003cstrong>【I：片段一重述知识】\u003c/strong>\u003c/u>\u003c/p>\u003cp>【与学习者互动】\u003c/p>\u003cp>拆书家：大家看完了吗？大家觉得这个片段最重要的一个关键词是什么呢？\u003c/p>\u003cp>学习者A互动：自信。\u003c/p>\u003cp>拆书家反馈：是的，关键词是“自信”。然我们把掌声送给这位学习者。\u003c/p>\u003cp>【与学习者互动】\u003c/p>\u003cp>拆书家：在这个拆页，我们可以看到作者想表达的是自信的重要性以及对人生的意义。那什么样的人才能称为“自信”呢？大家可以用一个关键词来描述。\u003c/p>\u003cp>学习者轮流互动发言：积极、乐观、幽默、有能力、有自我掌控感\u003c/p>\u003cp>拆书家反馈：非常好，大家说的太棒了（把大家的答案写在白板上）。通过大家的描述，看来大家身边都有很自信的人。让我们一起来看看这个片段是怎么说的。\u003c/p>\u003cp>【强化概念讲解】（概念与案例相互参照，引出知识点逻辑和步骤）\u003c/p>\u003cp>我们从原文片段中可以归纳总结，自信的人会呈现出来四个核心特点：有方向，有态度，有能力，有行动。\u003c/p>\u003cp>[场景一]\u003c/p>\u003cp>怎么理解呢？大家从小到大寒窗苦读十几年，可曾想过为什么而读书？试想在同一个教室里边，老师问：读书问是为了什么？一个不知道为什么而读书的学生，和一个说“为中华之崛起而读书”的学生，哪一个会让人感觉更自信？是后者对吧，为什么呢？因为他是有方向的，有方向的人，他们做事情会有自己的节奏感和目标感，会让我们产生信任，给人更自信的感觉\u003cu>[引出有方向的要点]\u003c/u>\u003c/p>\u003cp>[场景二]\u003c/p>\u003cp>大家从小都看过西游记，西天取经九九八十一难，每次取经遭遇大的挫折，猪八戒会说一些散伙的话，开始分行李，说“你回你的花果山，我回我的高老庄”，这其实是在消极回避问题。而孙悟空的做法是什么呢？他会很从容的应对，从不畏惧逃避，相信能够救出师傅，并积极主动与土地、观音和天庭的各种官员积极沟通，想着怎么解决问题\u003cu>[引出有态度的要点]\u003c/u>。\u003c/p>\u003cp>很多次唐僧落入妖怪之后，猪八戒的做法是什么？他会大喊：“大师兄，师傅又被妖怪抓走了”，这是在把解决问题的包袱甩给了孙悟空，可能因为他觉得自己打不过妖怪。而孙悟空的做法呢？他会主动去和妖怪喊话，对战，使出各种本领，最终把师傅救出来\u003cu>[引出有能力的要点]\u003c/u>。\u003c/p>\u003cp>猪八戒和孙悟空，谁让人感觉更自信呢？显然是孙悟空，因为他遇到挫折和问题时态度积极主动，并且有能力解决遇到的问题\u003cu>[引出有态度和有能力的要点]。\u003c/u>\u003c/p>\u003cp>[场景三]\u003c/p>\u003cp>最后再来看一个场景，我们拆书帮每周会进行拆书晋级活动，有的会员很喜欢参加活动，一直说要成为三级拆书家，但是从来不报名晋级拆书。有的会员没说什么，有机会有时间就报名拆书，在具体做的过程中收集大家的反馈，踏踏实实一步一步走。大家说哪种会员给人的感觉更自信呢？肯定是参加拆书的会员，会什么呢？因为他是在用行动说话\u003cu>[引出有行动的要点]。\u003c/u>\u003c/p>\u003cp>所以，我们从自信的人的呈现出来的要点，能够归纳出以下四个步骤，让我们变得更自信。\u003c/p>\u003cp>【如何成为一个自信的人】（“四动”模型）\u003c/p>\u003cp>第一，方向驱动。这个方向是你内心真心想要的，是明确的，是可能实现的。\u003c/p>\u003cp>第二，积极主动。核心是要有积极、从容、乐观的态度，如原文中说的相信“凡事必有三个解决方案”。\u003c/p>\u003cp>第三，能力推动。核心是要积累学习各种能力，如解决问题的能力，学习能力，沟通表达能力。\u003c/p>\u003cp>第四，踏实行动。朝着方向，一步步迈进，核心是“干”，要点是马上可以行动的第一步。\u003c/p>\u003cp>【举例】回到最开始我朋友在工作中陷入低估和消极情绪的例子，学了这个方法之后，我可以怎样帮助她变成一个更自信的人呢？详细和她交流了解情况后，我打算这样做：\u003c/p>\u003cp>1、方向驱动。向上级明确自己这个岗位的试用期通过标准。\u003c/p>\u003cp>2、积极主动。面对问题时，主动向同事请教沟通，不畏惧，不逃避。\u003c/p>\u003cp>3、能力推动。积累自己工作中解决问题和沟通表达的能力。\u003c/p>\u003cp>4、踏实行动。马上可以行动的第一步是和直接领导沟通。\u003c/p>\u003cp>【适用场景】\u003c/p>\u003cp>该方法适用于自己或者身边的亲朋好友，因为不自信自我价值感不强，陷入低谷或者消极情绪的场景，可以用这个方法提升自信程度。如工作上遭遇挫折心灰意冷，生活中没有激情提不起劲儿，经常觉得内心没有力量或者老是自责等。该方法不适用于遭遇重大挫折、变故或者心理问题的场景，这个时候您可能需要专业的心理支持。\u003c/p>\u003cp>不知道大家听了我分享的适用场景之后，有没有可以联想到自己的一些场景？\u003c/p>\u003cp>（停顿十来秒，给学习者思考时间，再进行接下来的A2应用）\u003c/p>","interaction":"\u003cp>\u003cstrong>【A2：催化学习者应用】\u003c/strong>（教学习者编剧本）\u003c/p>\u003cp>接下来，为了我们更好的掌握这个知识点，邀请大家每个人给自己编一个小故事。\u003c/p>\u003cp>【A2之确定场景】\u003cem>（分步催化降低学习者难度）\u003c/em>\u003c/p>\u003cp>大家可以设想一下未来几天或者一周，你可能会用到“如何成为一个自信的人”帮助到你的亲朋好友提升自信的场景，请花1分钟的时间，把这个场景的关键词写下来等。\u003c/p>\u003cp>【A2之编故事】\u003c/p>\u003cp>请大家根据这个场景，编一个小故事。故事需要包括哪些元素呢？这个故事要有基本的背景，发生了一些什么事，经过了什么，故事里边的人物有哪些对话等。最最重要的是，大家一定要用到今天学习的这个“如何成为一个自信的人”的知识点（方向驱动、积极主动、能力推动、踏实行动）。\u003c/p>\u003cp>每个人独立编故事，时间是4分钟。4分钟之后，我邀请一位小伙伴上台来分享，通过将故事的方式将你的未来应用讲出来。\u003c/p>\u003cp>（给大家发放辅助编故事的A4纸，并以我的案例在PPT上作引导）\u003c/p>\u003cp> 【学习者案例记录】\u003c/p>\u003cp>学习者静秋分享她和她女儿的故事。\u003c/p>\u003cp>\u003cstrong>【回应与反馈】\u003c/strong>\u003c/p>\u003cp>拆书家回应：谢谢静秋的分享。你刚刚编写的是如何帮助你女儿真真提升演讲比赛自信的故事，一共提了3个问题，你在询问她需要具备什么才可以拿奖的时候，如果回到我们今天学习的四步法知识点，有什么更好的提问方法呢？\u003c/p>\u003cp>学习者反馈：其实可以把能力和态度进行分开提问。比如你在态度方面可以做一些什么调整，更好的帮助你呢？你在能力方面还有哪些需要提高的，这样会更完整。\u003c/p>\u003cp>拆书家回应：特别好的一个补充，让我们再次把掌声送给静秋。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}},{"id":19320,"quote":"\u003cp>\u003cu>【片段二原文：怎样培养出自信】\u003c/u>\u003c/p>\u003cp>因为自信就是“信赖自己有足够的能力取得所追求的价值”，所以自信的基础是能力。能力的基础是经验，经验的基础是尝试，尝试的基础是感觉。感觉就是想去尝试的内心状态，也就是自信最基本的原动力。\u003c/p>\u003cp>没有“想去尝试”的感觉，不会去做第一次的尝试，因此不能有任何的经验累积，也因此不能发展出做事的能力。经验不一定是成功的，也有可能是失败的经验。成功的经验固然好，但是失败的经验也带给我们知识和能力。\u003c/p>\u003cp>我们从婴儿到成年，从走路到说话，从打球到看书，每一项能力都是凭着不断地失败、不断地累积经验而学会的。偏偏就有很多人成年后不允许自己失败，为了避免失败而不肯去面对和尝试新的东西。这是不让自己成长的做法，结果是天天活在因为没有体会到成长的快乐而带来的痛苦之中。\u003c/p>\u003cp>自信的基础是“能力”，但是能力本身不一定会产生自信。犯罪行为往往需要很大的力量，你我都不敢去做。罪犯表现出很大的力量，但同时也表现出严重缺乏自信。问题少年的打斗、自残等行为，不也是显出过人的力量吗？为何他们如此缺乏自信？原来能力必须经过肯定才能变成自信！例如，我对一个外国人说了两句英语，外国人听不懂，或者斥责我不应该这样说，我有说这两句的能力，但是，因为得不到肯定，这种能力没有变成自信。如果那个外国人按我那两句的意思给我恰当的回应，或者称赞我说得好，这样，我因为得到了肯定，这种能力就变成了自信。\u003c/p>\u003cp>每个人出生时都没有什么能力或自信。凭着在成长的过程中不断地接触新事物，学习如何面对、处理，凭事情结果和人们的肯定，能力和自信才会不断地累积起来。因此，自信是成长过程中经过不断的肯定而建立起来的。肯定有两种：来自本人和来自他人的，最好是两者都有。若只有一种，产生自信的效果会大打折扣，若长期只有一种，自信甚至会减少。\u003c/p>\u003cp>前面解释过怎样培养出自信。把整个过程编成一个方程式，就是这样：\u003c/p>\u003cp>感觉→尝试→经验→能力→（肯定）→自信→自爱→自尊。\u003c/p>","explains":"\u003cp>\u003cstrong>【片段一与片段二的关系】\u003c/strong>\u003c/p>\u003cp>再回顾一下片段一和片段二的关系，第一个片段“如何成为一个自信的人”，该片段给的是一个自信的人的标准是什么样的：有方向、有态度、有能力和有行动，是一种自信的结果，聚焦在人身上。\u003c/p>\u003cp>而具体自信和自我价值的建立具体过程是如何发生的，如何通过一件具体的事情或者想法去建立自信和自我价值，具体的有逻辑有顺序的操作步骤，则是接下来这个“培养自信三步法”片段要解决的问题，片段二聚焦在事情上。\u003c/p>\u003cp>\u003cstrong>【片段二学习目标】\u003c/strong>\u003c/p>\u003cp>学习者在使用“培养自信三步法”时，能够找出该方法落地的1个卡点难点，并针对该卡点难点现场加工出针对性的解决方案。\u003c/p>\u003cp>\u003cstrong>【A1量表自测】 通过量表测试自己是否自信\u003c/strong>\u003c/p>\u003cp>在正式阅读原书片段之前，先邀请各位伙伴完成这份自测表：以下5个题目，请按照1~6分的标准给自己打分，1分代表完全不符合，6分代表非常符合，请你花1分钟的时间，将每道题打分，并汇总分数，做好的小伙伴可以示意我一下。\u003c/p>\u003cp>\u003cstrong>【量表题解释】\u003c/strong>\u003c/p>\u003cp>好的，小伙伴都已经完成。这个自测表能帮助我们对自信心有个初步了解，也是为了引出我们片段二的学习内容。\u003c/p>\u003cp>根据打分得分，我们可以分为四个类型：自信重度失调者、自信轻度失调者、一般常态自信者、完美自信者。\u003c/p>\u003cp>请各位对照一下自己的得分，得分在25分以上的小伙伴请举手？好的，有1位小伙伴，恭喜你，说明你是个超级自信的人，希望今天的学习可以让你更精进；对于完美自信者（大于25分），他们会有一种毫无畏惧和“战无不胜”的感觉；但也要留意，可能部分人也会听不进意见，独断专行。\u003c/p>\u003cp>得分在15-25分的小伙伴请举手？在这个得分范围，说明你的自信心还是很不错的，可以通过今天学习有更大的提升；对于一般常态自信者（15-25分）：对自己的行为和结果颇有自信心，明白自己的优点，同时也清楚自己的缺点。\u003c/p>\u003cp>得分在5-15分的小伙伴请举手，在这个得分范围，我们一般称为自信轻度失调者，对于自信轻度失调者（5-15分）：有一定程度的自信心，但往往看不到自己的优点、长处、才能和成就，相反，看自己的弱点和不足有余，对行为所能达到的结果缺乏自信的判断。希望今天的拆书能够给你启发和帮助。\u003c/p>\u003cp>有5分以下的小伙伴吗？没有哈，看来今天在场的小伙伴整体自信程度还是比较不错的。对于自信重度失调者（小于5分）：性格内向，很少跟别人交往，内心特别敏感，眼神躲闪；同时内心感情世界丰富。\u003c/p>\u003cp>当然，此量表结果涉及维度较少，仅供参考，帮助大家更好的理解自信心。\u003c/p>\u003cp>接下来，请大家花2分钟的时间阅读我给大家提前准备的原书拆页，看过的小伙伴可以跟我确认一下眼神。\u003c/p>\u003cp>\u003cu>【片段二：拆书家讲解引导】\u003c/u>\u003c/p>\u003cp>【不这么做的坏处】\u003c/p>\u003cp>结合刚刚的量表自测，我们常见的缺乏自信的表现有哪些呢？一般分为两种，一种是没有能力，感觉不自信，如刚毕业的学生，或者是刚接触一个陌生的领域对什么都不清楚。一种是有能力，但是没有得到足够的肯定，也无法获得自信，如工作上得不到上级领导或同事的肯定，家里边做的事情得不到父母的肯定等。\u003c/p>\u003cp>我们常见的提升自己自信的方法是什么？我们可能会去学习各种书籍，听各种课程，学各种方法论，积累了一堆的知识，可最后还是感觉没有自信，为什么呢？因为我们是在单点的突破和发力，学的东西并没有沉淀为经验或能力，或者我们的能力没有得到肯定，所以没有转化为自信。\u003c/p>\u003cp>\u003cstrong>【How】培养自信三步法\u003c/strong>\u003c/p>\u003cp>结合片段中给我们推荐的方法以及我自己的实践，为了方便大家记忆，我把万能公式总结成以下三个步骤，三步法培养自信：\u003c/p>\u003cp>\u003cstrong>1、将想法付诸行动。\u003c/strong>这个想法（感觉）需要和你想要提升的某项能力相关联，并且这个想法的落实，能够帮你建立自信。行动是建立自信最好的良药，如果想跑步（提升运动能力），你就迈开腿去跑，不需要太多的准备工作，也不需要必需要跑多久，Just do it。\u003c/p>\u003cp>\u003cstrong>2、积累经验和能力。\u003c/strong>关键词是多做，做好。生命中所有的事情都有助于我们成长，我们可以从我们做的事情当中进行总结，复盘，反思，形成经验和能力。\u003c/p>\u003cp>\u003cstrong>3、向内外获取肯定。\u003c/strong>分为两个层面：1）向内：自我肯定，如写成功日记。2）向外获取肯定，定期分享、输出，获得反馈，如写文章、做拆书和演讲等[细化行动步骤]。\u003c/p>\u003cp>\u003cstrong>【举例】想把字练好，提升板书的自信\u003c/strong>\u003c/p>\u003cp>举一个我自己去年四季度练字的例子。我的字不好看，一直都想把自己的字练好，一手好字会让我更自信。这个想法一直都有，但总是迟迟没有行动，给自己找没时间、没方法、没钢笔、没墨水等各种借口。后面看了重塑心灵的这个方法，我就用在了自己这个想法上。\u003c/p>\u003cp>首先，\u003cstrong>将想法付诸行动\u003c/strong>。我在知乎上了解到可以临摹吴玉生的字，在京东上买了五本吴玉生的字帖，把压箱底的钢笔翻出来，在晨光文具店买了瓶碳素墨水，然后就开始练起字来。\u003c/p>\u003cp>其次，\u003cstrong>积累经验和能力\u003c/strong>。如何积累经验呢？最重要的还是勤练习（多做），对照着老师写的字和自己的字，总结反思，针对性模仿和提高（做好）。\u003c/p>\u003cp>最后，\u003cstrong>向内外获取肯定\u003c/strong>。1）向内获取肯定方面，我会用语言肯定我自己，肯定我自己的坚持和付出，对于写的好的笔划，我会很开心。2）向外获取肯定方面，我会将自己写的字拍照发到我的家人和朋友群里边，他们会给予我点赞和反馈，我写的好的字，佳洁也会给我圈出来。\u003c/p>\u003cp>最终，三个月后，我写完了五本字帖，字迹有了很大的提高，自信心也更强了。\u003c/p>\u003cp>\u003cstrong>【适用场景】\u003c/strong>\u003c/p>\u003cp>该方法适用于你有某个想法想要提升某项能力，并且如果这项能力缺乏会导致你的自信受损，如写字能力、运动能力、演讲能力、沟通能力等，并且这项能力是需要经过较长周期（1-3个月）的行动才能有效果。不适用于一些随机的、需要及时满足的想法的行动，如想吃一顿火锅等。\u003c/p>","interaction":"\u003cp>\u003cu>\u003cstrong>【A3：微行动学习】\u003c/strong>\u003c/u>\u003c/p>\u003cp>为了我们更好的掌握这个方法，接下来我们通过微行动进行现场演练。\u003c/p>\u003cp>首先给大家介绍一下什么是微行动学习法。\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>为了让我们更好的进行演练，让我们先分个组，左边3个小伙伴一个组，右边4个小伙伴一个组，中间的小伙伴1个组。每个小组选出一个时间官。\u003c/p>\u003cp>【显性提问之确定场景】（为了引出微行动问题场景）\u003c/p>\u003cp>首先邀请大家思考，听了我给大家分享的“培养自信三步法”，大家觉得自己未来几天或几周，可以应用的场景是什么？比如说工作上自己在面对领导的时候不自信，一直有想法想提升自己的向上管理能力；或者在沟通表达方面感觉不自信，一直想有想法想提升自己的表达能力；或者生活上在掌控自己方面感觉不自信，一直有想法想提升自己的自律能力。\u003c/p>\u003cp>给大家一分钟，请写下自己可以应用这个方法的关键词，时间、地点、场景等。\u003c/p>\u003cp>【显性提问之抛出问题】大家觉得应用这个方法，落地执行最大的卡点或者难点是什么？接下来我们就在小组里边讨论，每个小组先在组内讨论自己觉得的卡点难点，最后小组推选出一个小组内最有代表性的卡点难点，由这个代表进行发言。\u003c/p>\u003cp>\u003cu>（一）明确问题\u003c/u>\u003c/p>\u003cp>【第一轮小组讨论】\u003c/p>\u003cp>时间5分钟，5分钟后我邀请每个小组派一个代表发言，分享你们组认为最大的卡点或难点，\u003c/p>\u003cp>【小组代表发言】\u003c/p>\u003cp>中凤组：最难的是将想法付诸行动，如想要尝试拆书，一直未行动。\u003c/p>\u003cp>秋香组：最难的也是尝试，想法很难启动，比如说想要做健康管理咨询。\u003c/p>\u003cp>涛涛组：我们组认为最大的卡点难点，是向外获取正向肯定很难。\u003c/p>\u003cp>【票选确定问题】\u003c/p>\u003cp>拆书家：针对刚刚每个小组提出的卡点难点问题，让我们所有人一起投票，每人一票，确认接下来我们大家一起要讨论的卡点难点问题。根据3个组的分享，中凤组合秋香组的问题可以合并成一个。\u003c/p>\u003cp>学习者：针对卡点难点问题进行投票。将想法付诸行动落地最难，5票；向外获取正向肯定落地最难，7票。\u003c/p>\u003cp>拆书家：好的，根据大家的投票情况，认为最大的卡点难点是将想法付诸行动的有5票，认为最大的卡点难点是向外获取肯定的有7票。那我们今天确认要讨论的卡点难点问题是：向外获取正向肯定很难。\u003c/p>\u003cp>\u003cu>（二）分组讨论问题本质\u003c/u>\u003c/p>\u003cp>【分组讨论问题本质】\u003c/p>\u003cp>拆书家：好的，接下来我们每个小组针对这个票选出的卡点难点问题，进行小组讨论，分析发生这个问题的本质原因。所谓的本质原因，就是当你解决了这个本质原因，这个问题就解决了。\u003c/p>\u003cp>\u003cstrong>【回应与反馈】\u003c/strong>\u003c/p>\u003cp>学习者秋香提问：在刚刚大家投票讨论得出的卡点难点问题，这个问题的背景感觉不是很清楚。\u003c/p>\u003cp>拆书家回应：谢谢这位学习者的反馈，你的意思是，针对提出这个问题的案主本人，他产生这个问题的具体背景不是很清楚，我的理解对吗？\u003c/p>\u003cp>学习者秋香：是的\u003c/p>\u003cp>拆书家回应：特别好的一个问题，那我们邀请学习者涛涛，针对这个问题的背景，再做一个补充描述，可以吗？\u003c/p>\u003cp>学习者涛涛：好的，我的本职工作是在公务员系统做综合管理相关的事情，平时会有很多公文写作的任务，领导要求很高，会修改5-6遍，这让我觉得效率很低，我也感觉在这一块缺少自信，所以第三步获取外部肯定是我觉得落地最大的卡点。\u003c/p>\u003cp>拆书家反馈：谢谢涛涛的补充，让我们把掌声送给他。\u003c/p>\u003cp>【学习者分组讨论】\u003c/p>\u003cp>好的，那我们开始分组讨论问题发生的本质原因，时间5分钟，5分钟后我邀请每个小组派一个代表发言。\u003c/p>\u003cp>【小组代表发言】\u003c/p>\u003cp>中凤组：我们组认为问题的本质原因是：如何让自己主动的获取向外和向内的正向反馈，以提升自己的自信心。\u003c/p>\u003cp>涛涛组：我们总结的本质原因是，如何寻找领导给予肯定的标准。\u003c/p>\u003cp>秋香组：我们组讨论的本质原因是，对于公文语言的学习，不熟悉。\u003c/p>\u003cp>\u003cu>（三）明确问题本质\u003c/u>\u003c/p>\u003cp>【票选确认本质原因】\u003c/p>\u003cp>拆书家：针对刚刚大家分析的本质原因，让我们所有人一起投票，确认这个卡点难点问题发生本质的原因是什么。大家分别对三个组总结出来的本质原因进行投票，票数最高的本质原因，我们将进行下一轮解决方案的讨论。每个人既可以投自己小组的票，也可以投其他组的，1人1票。\u003c/p>\u003cp>【学习者投票确认本质原因】\u003c/p>\u003cp>学习者投票：中凤组，5票。涛涛组，7票。秋香组，0票。\u003c/p>\u003cp>拆书家反馈：好的，那我们大家确认达成共识，向外获取正向肯定很难 这个卡点难点问题发生的本质是：如何寻找领导给予肯定的标准？\u003c/p>\u003cp>\u003cu>（四）分组讨论解决方案\u003c/u>\u003c/p>\u003cp>拆书家：接下来针对大家票选出的本质原因：如何寻找领导给予肯定的标准？进行小组讨论，每个小组讨论出你们的解决方案。\u003c/p>\u003cp>时间5分钟，5分钟后我会邀请每个小组派一个代表发言，讲解你们的成果。\u003c/p>\u003cp>\u003cu>（五）小组代表讲解成果\u003c/u>\u003c/p>\u003cp>【小组代表发言】\u003c/p>\u003cp>涛涛组：多写、梳理经验、向专家获取点评反馈、领导心情好的时候与其沟通\u003c/p>\u003cp>中凤组：询问领导、同事；调研前公司的经验；自己总结，参考以前的公文\u003c/p>\u003cp>秋香组：以前的资料分析总结，主动沟通\u003c/p>\u003cp>\u003cstrong>【拆书家总结反馈】\u003c/strong>\u003c/p>\u003cp>拆书家总结：针对刚刚大家每个小组提出的本质问题的解决方案，我一共列举出了9个解决方案建议，有些建议的内容是相似的，我们可以进行合并同类项，把大家的解决方案提炼成共性的解决方案，可以得到如下三个步骤：\u003c/p>\u003cp>1、主动和领导沟通肯定的标准。领导是第一当事人。\u003c/p>\u003cp>2、向第三方获取肯定的标准。如专家、同事等，他们有和领导打交道的经验。\u003c/p>\u003cp>3、自己总结肯定标准经验。根据自己以前写的好的材料，进行复盘反思和总结。\u003c/p>\u003cp>拆书家反馈：最后我想采访一下提出这个问题的案主涛涛，如果给到你大家总结的这三个步骤的方法建议，如果从1-10分打个分的话，你觉得有多大程度解决了你的问题？\u003c/p>\u003cp>学习者涛涛：我打8分。\u003c/p>\u003cp>拆书家反馈：好的，感谢涛涛，让我们再次把掌声送给涛涛。\u003c/p>\u003cp>\u003cstrong>\u003cu>【A2：催化应用之布置作业】\u003c/u>\u003c/strong>\u003c/p>\u003cp>【找人分享】\u003c/p>\u003cp>请在接下来的一两天内找人聊聊如何培养自信这个话题，跟他们聊聊他们在哪些方面会表现的不自信，目前带来了哪些困扰，发生的原因是什么，并给出如何培养自信的建议。如果你完成这个分享任务，可以事后将你们的聊天对话关键部分记录下来，并分享到我们的会员群里边。完成这个分享的小伙伴，可以找我领取精美小礼物一份喔。\u003c/p>\u003cp>【学习者作业跟踪记录】学习者王宇老师的作业跟踪记录\u003c/p>\u003cp>\u003cstrong>1．找人分享：请在未来1-2天内找人分享如何培养自信这个话题\u003c/strong>\u003c/p>\u003cp>今天和朋友小A电话，聊到了如何培养自信，小A说她现在的婚姻一团糟，没有自信经营好家庭带好孩子。\u003c/p>\u003cp>故事背景：大学毕业后，小A选择随男友去到县城工作，从市里到县城，交通不便、服务有限。在城市里生活惯了的小A很不习惯，可也不愿意回到家里听父母争吵，有懂自己、疼自己的男友就够了。很快结婚怀了孩子，农村的婆婆妈来照顾，月子里各种不适应争吵，骨子里瞧不上县城老公一家，连听到县城的口音都受不了，常常给老公报怨，开始老公向着她，听久了也听烦了，对她说：“我一回家，你就报怨，说过来说过去就这点事，有意思吗？”小A委屈出现了产后抑郁，更多报怨也更多对婚姻的恐惧和不安，对经营婚姻的不自信，各种问题接踵而来。\u003c/p>\u003cp>\u003cstrong>2．聊天内容：了解他们在哪些方面会表现的不自信，目前带来了哪些困扰，发生的原因是什么，并给出如何培养自信的建议\u003c/strong>\u003c/p>\u003cp>\u003cstrong> 不自信的方面：\u003c/strong>与老公、婆婆妈关系相处的不自信；带好孩子的不自信； \u003c/p>\u003cp>\u003cstrong> 困扰：\u003c/strong>老公不理解小A的感受，不愿意站在她的立场去想并解决问题；老公长期在外地工作，周末才回家，平时只能接受婆婆妈的照顾，婆婆妈做饭难吃，月子里每天做凉菜不会照顾人；小A情绪不稳定，看到孩子哭很厌烦，把气撒在孩子身上，不愿带孩子，更没自信能带好孩子。\u003c/p>\u003cp>\u003cstrong> 原因：\u003c/strong>原生家庭的阴影，成长后又逃避正面解决问题。\u003c/p>\u003cp>\u003cstrong> 建议：\u003c/strong>\u003c/p>\u003cp> 一是与老公一起建立家庭的愿景目标——和谐温馨的家庭氛围\u003c/p>\u003cp> 二是用积极的心态去面对和解决问题\u003c/p>\u003cp> 三是与原生家庭和解，学会课题分离；看到现在拥有的，不和同学比，去珍惜和感恩；学会与老公、婆婆妈运用非暴力沟通方式去表达感受和需求；\u003c/p>\u003cp>四是每天记录当天发生的美好，并和老公分享，得到老公的肯定；每天对婆婆妈说感恩的语言，并拥抱婆婆妈说：“辛苦了”，婆婆妈感动并主动和燕子一起参与学习育儿方法。\u003c/p>\u003cp>3． \u003cstrong>记录分享：如完成分享任务，可将你们的聊天地话关键部分记录下来，分享到我们的会员群里边。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cu>【强有力的总结】\u003c/u>\u003c/strong>\u003c/p>\u003cp>最后进行一个小结。今天给大家分享的是关于自信的两个片段，第一个片段是心法，聚焦于人，和大家分享了如何成为一个自信的人的四个步骤（方向驱动、积极主动、能力推动、踏实行动），这是一个是否自信的标准，可以用来自己行动提升自信，也可以用来评价其他人是否自信，并给出针对性的建议。为了方便大家加深印象，现场也让大家给自己编了一个应用的小故事。\u003c/p>\u003cp>第二个片段是手法，聚焦于事，给了一个建立自信的万能公式，培养自信的三个步骤（将想法付诸行动、积累经验和能力、向内外进行肯定）。为了让大家更好的应用，我们也进行了微行动的学习，通过大家达成的共识，针对第三步向外获取肯定很难这个落地卡点问题，进行了深入的本质原因探讨和解决方案讨论，最终提炼总结了具体的解决方案。\u003c/p>\u003cp>希望这两个片段能够帮助大家更好的建立自信，最后，感谢大家的时间，我的拆书到此结束，请观察家掐表。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1676782994000,"updated_at":1678802193000,"ria":true},{"id":15172,"topic":"意义换框法，让我们从此告别负面。","learn_goal":"","remark":"我们在日常生活和工作中，经常会遇到一些我们不顺心和不开心的事情，这些事情的发生，可能会让我们很长一段时间心情低落，也能导致我们怨天尤人，抱怨连连。长期的处于负面情绪中不仅会大大降低我们的工作激情和效率，也会让我们的生活越来越糟。意义换框法呢，可以让我 们快速从负面事件中找到正面价值，化阻碍为动力，从而快速成长和提升。","level":"TF1-2","duration":20,"status":30,"type":0,"chaishujia":{"username":"孟旭","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>自我介绍：\u003c/strong>大家晚上好，欢迎大家参加今晚我1-2的晋级活动，我是孟旭，首先用三个标签介绍我自己：\u003c/p>\u003cp>1.医药代表。\u003c/p>\u003cp>我目前的主业。\u003c/p>\u003cp>2. 心理咨询师\u003c/p>\u003cp>我热爱并且追求终生的使命。\u003c/p>\u003cp>3. 三级拆书家。\u003c/p>\u003cp>今年的目标。\u003c/p>\u003cp>\u003cstrong>分组\u003c/strong>：因为今晚有分享环节，首先我们做一下分组，因为今晚人数大于6人就分为两个组.。\u003c/p>\u003cp>\u003cstrong>图书介绍：\u003c/strong>今天我们的学习片断来自于《重塑心灵》，作者李中莹先生是华人世界研究NLP（身心语言程序学）的大师，NLP是一门研究我们的大脑如何工作的学问。书中全面地介绍了NLP的历史、理论框架和基本概念，提供了一些既安全又容易产生实效的NLP技巧。浅显易懂，我尤其喜欢书的封面这句话“\u003cstrong>每个人都拥有让自己成功快乐的能力\u003c/strong>”，也推荐给大家。\u003c/p>","ratings_count":2,"texts":[{"id":19195,"quote":"\u003cp>今天拆解【主题】“意义换框法”，让我们从此告别负面。\u003c/p>\u003cp>【片段来源】《重塑心灵》，作者：李中莹 P49-50\u003c/p>\u003cp>接下来，我给大家读一下原文。\u003c/p>\u003cp>【R-阅读原文】\u003c/p>\u003cp>意义换框法\u003c/p>\u003cp>“意义换框法”是找出一个负面经验中的正面意义。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都只是人加诸的。既然是人加上去的意义，则一件事情——\u003c/p>\u003cp>◇可以有其他的意义，也可以有更多的意义；\u003c/p>\u003cp>◇可以有不好的意义，也可以有好的意义。\u003c/p>\u003cp>同一件事情里面总有不止一个意义包含其中。找出最能帮助自己的意义，便可以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。\u003c/p>\u003cp>意义换框法对一些因果式的信念最为有效。\u003c/p>\u003cp>例如：“因为上级挑剔，所以我工作不开心。”方法是把句中的“果”（工作不开心）改为它的反义词，再把句首的“因为”二字放到最后，成为：“上级挑剔，所以我工作积极，因为……”然后反复地思考如何能把句子写完，要求至少有六个不同的版本，再找出其中最能够接受的一句。\u003c/p>\u003cp>以下是一些学员的杰作：\u003c/p>\u003cp>“上级挑剔……”\u003c/p>\u003cp>◇使他无从挑剔\u003c/p>\u003cp>◇使我提升得更快\u003c/p>\u003cp>◇使他改变对我的态度\u003c/p>\u003cp>◇使我超越他的标准\u003c/p>\u003cp>◇使我变得更能干\u003c/p>\u003cp>◇使我更快升级，脱离他的管治\u003c/p>\u003cp>◇使我更有能力去另找新工作……\u003c/p>\u003cp>试试挑选一条你觉得最好的，然后把整句反复地念数遍。\u003c/p>\u003cp>现在，你再念念本来的一句：“因为上司挑剔，所以我工作不开心。”你内心的感觉有怎样的不同？本来的一句和后来的一句，你觉得哪句更舒服一点？\u003c/p>","explains":"\u003cp>\u003cstrong>What:\u003c/strong>本片段讲了“意义换框法”，可以帮助我们快速从负面事件和经历中找到其正面意义。\u003c/p>\u003cp>\u003cstrong>Why\u003c/strong>:我们在日常生活和工作中，经常会遇到一些我们不顺心和不开心的事情，这些事情的发生，可能会让我们很长一段时间心情低落，也能导致我们怨天尤人，抱怨连连。长期的处于负面情绪中不仅会大大降低我们的工作激情和效率，也会让我们的生活越来越糟。意义换框法呢，可以让我们快速从负面事件中找到正面价值，化阻碍为动力，从而快速成长和提升。\u003c/p>\u003cp>\u003cstrong>Where\u003c/strong>:意义换框法适用于我们生活和工作中遇到的所有负面的事件和经历，还有我们前进遇到阻碍的情况，尤其适用于因果式的信念转变。\u003c/p>\u003cp>\u003cstrong>How\u003c/strong>:那接下来就用我自身的一个例子来说明一下意义换框法具体怎么来应用，\u003c/p>\u003cp>大体可以分为五步：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>找出“因”和“果”\u003c/strong>\u003c/p>\u003cp>例如：老公控制我花钱，我很气愤。\u003c/p>\u003cp>那么因：老公控制我花钱，果：我很气愤。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong> \u003cstrong>找“果”的反义。\u003c/strong> \u003c/p>\u003cp>找到结果的反义词，把负面意义的果转变为正面意义的果，\u003c/p>\u003cp>如：把“我很气愤”转变成“我很开心。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong> \u003cstrong>“因为”移句末\u003c/strong>。\u003c/p>\u003cp>把“因为老公控制我花钱，所以我很开心”。中的因为移到句末，\u003c/p>\u003cp>改为“老公控制我花钱，所以我很开心，因为.....”\u003c/p>\u003cp>\u003cstrong>4.\u003c/strong> \u003cstrong>句末补完整。\u003c/strong>\u003c/p>\u003cp>老公控制我花钱，所以我很开,因为可以使我可以攒下钱；因为可以使我不再买回一堆没用的东西；因为可以使我可以把钱花在更有意义的地方；因为可以使我不用担心没钱的日子......\u003c/p>\u003cp>\u003cstrong>5.\u003c/strong> \u003cstrong>选最佳意义。\u003c/strong>\u003c/p>\u003cp>从因为后面的理由中选出最有价值，最符合自己心意的。\u003c/p>\u003cp>说到这里呢？我给大家分享一个我的故事：\u003c/p>\u003cp>以前我对象每次回家，都会先巡视一下家里的卫生情况，一有不满意的地方，他就会唠叨个没完，每当这个时候我就会又气又烦，弄不好就会吵一架。那么\u003cstrong>反思\u003c/strong>我之所以跟我老公会吵架，没有处理好这件事情，没有变成积极的意愿，那是因为我有以下几个方面没有做好。\u003c/p>\u003cp>具体分析如下：\u003c/p>\u003cp>\u003cstrong>1. 找到因和果\u003c/strong>\u003c/p>\u003cp>因为老公挑剔家里的卫生，所以我很气愤。\u003c/p>\u003cp>\u003cstrong>2找果的反义\u003c/strong>\u003c/p>\u003cp>因为老公挑剔家里的卫生，所以我很欣慰。\u003c/p>\u003cp>\u003cstrong>3.因为移动句末\u003c/strong>\u003c/p>\u003cp>老公挑剔家里的卫生，所以我很欣慰，因为......\u003c/p>\u003cp>\u003cstrong>4.句末补完整\u003c/strong>\u003c/p>\u003cp>老公挑剔家里的卫生，所以我很欣慰，因为可以使我不再偷懒，也可以使我养成收拾家的好习惯，使家里的环境保持更加干净整洁，使一家人都有个好心情\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>5.\u003c/strong> \u003cstrong>选最佳意义\u003c/strong>\u003c/p>\u003cp>老公挑剔家里的卫生，所以我很欣慰,因为以使我养成收拾家的好习惯，使家里的环境保持更加干净整洁，使一家人都有个好心情\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>如果以上几点做到的话就有正面意义的结果了！\u003c/strong>\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）：我们刚才学了意义换框法，那么请大家回想一下，过去一段时间，自己遇到负面经历或者做事情遇到阻碍的经历。比如说因为自己的领导事特别多所以自己很烦恼呀!或者因为遇到一个难缠的客户所以自己很气愤呀!或者是因为某件事另一半特别不支持，所以我很委屈呀!，然后这个句式就是：因为.....所以我....。我给大家四分钟的时间，让大家在小组内进行分享，\u003c/p>\u003cp>时间到后我请每小组推荐一个代表来给大家进行分享\u003cstrong>。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1.伙伴：因为孩子上课步专心所以我很焦虑。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>2.伙伴：因为休息时间领导老找我处理各种事情，所以我很气愤。\u003c/strong>\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>刚才我们已经分享了自己过去遇到的这个负面儿的经历或者是阻碍，\u003c/p>\u003cp>我们之前，遇到这个事情做的并不好，\u003c/p>\u003cp>那我们今天学了这个方法之后，请大家思考一下，\u003c/p>\u003cp>在这里请大家想象一下在未来一个周或者一个月如果再出现日常生活中经常发生负面经历，那我们将如何利用今天的方法，来在负面经验里找正面意义？也就是说给自己制定一个小目标把原先的负面经历转变一个正面的意义！\u003c/p>\u003cp>那同时要提醒大家一定要有具体的做法,行动方案,有明确的时间限制,有可衡量和可观测的结果。通俗一点说就是什么时间，用什么方法，做什么事儿，做到什么程度，大家注意，一定是未来的一周或一个月内。时间两分钟，写到聊天区，时间有结余的话，我们会请一到两位小伙伴公开分享。\u003c/p>\u003cp>\u003cstrong>学习者案例记录：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>目标：下个周主动联系领导帮忙处理事情，化被动为主动。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>行动：下周每天下班后主动给领导打电话询问是否有需要帮忙处理的事情，确认没有后在回家。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>[结束语]\u003c/strong>\u003c/p>\u003cp>让我们回顾一下，今天我们一起学习了“意义换框法”\u003c/p>\u003cp>找出“因”和“果”\u003c/p>\u003cp>找“果”反义\u003c/p>\u003cp>“因为”移句末\u003c/p>\u003cp>句末补完整\u003c/p>\u003cp>选最佳意义\u003c/p>\u003cp>希望大家学习了“意义换框法”更积极地去面对人生，化阻力为动力，创造更美好的生活。\u003c/p>\u003cp>谢谢大家的聆听，今晚我的分享到此结束！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1676426324000,"updated_at":1677730353000,"ria":true},{"id":15159,"topic":"如何让我们做事更积极","learn_goal":"","remark":"你是否有过以下经历：你的老板很挑剔，你工作很不开心......。疫情之下公司业绩很差，让你压力很大.....考试没通过，导致情绪低落......。钱丢了，让你懊恼好几天......。你觉得自己沟通表达很差，不断自我否定......\n\n这样的事如果经常发生，容易让人在负面的体验中失衡，而事情的结果也容易出现问题，将面对人生的更多困境。\n\n碰到负面的事情和体验后该怎么办呢？","level":"TF3-2","duration":30,"status":30,"type":0,"chaishujia":{"username":"缘起","city":"青岛市"},"club":{"name":"青岛五月风分舵","city":"青岛"},"prologue":"\u003cp>\u003cstrong>【自我介绍】\u003c/strong>\u003c/p>\u003cp>大家好，我是韩新波，我有三个标签：1.心理学习者 2.教育培训者 3.终身学习者\u003c/p>\u003cp>\u003cstrong>【分组】\u003c/strong>\u003c/p>\u003cp>因为我们就六个人，只能分为一个大组来讨论，这样我们就分一个组。\u003c/p>\u003cp>\u003cstrong>【学习者场景法图书介绍】X分钟\u003c/strong>\u003c/p>\u003cp>接下来我从几个方向来介绍我拆的书籍和拆页\u003c/p>\u003cp>\u003cstrong>【场景】\u003c/strong>\u003c/p>\u003cp>你是否有过以下经历：你的老板很挑剔，你工作很不开心......。疫情之下公司业绩很差，让你压力很大.....考试没通过，导致情绪低落......。钱丢了，让你懊恼好几天......。甚至你觉得自己沟通表达很差，不断自我否定......\u003c/p>\u003cp>\u003cstrong>【提问】\u003c/strong>\u003c/p>\u003cp>以上这样的事经常发生，为什么有些事达不到你的心理预期时，会出现负面情绪，或者人生找不到意义，体现不出自我价值呢？是因为你没有了解自己的主观经验和大脑是如何运作的？\u003c/p>\u003cp>\u003cstrong>【影响】\u003c/strong>\u003c/p>\u003cp>当你不了解自己大脑运作的方式和主观经验/信念的时候，做事时用经验去决定未来，使结果和过去差别不大，同时限制了开拓性的思维和行为。容易有负面的想法去思考，事情的结果很易出问题。\u003c/p>\u003cp>\u003cstrong>【解决】\u003c/strong>\u003c/p>\u003cp>碰到这些事要如何解决呢？《重塑心灵》这本书是NLP理论实用类的书籍，作者是：李中莹老师，书中对人生各个层面的解析，结合方法和技巧处理工作、学习、生活等各个方面的问题，实际落地效果好，极大的提升你的学习/沟通/情绪等能力并获得更多的幸福感。\u003c/p>\u003cp>本拆页是把负面的事情通过意义换框法，转换负面事件的体验，找到事件当中的积极正向的意义。\u003c/p>\u003cp>\u003cstrong>【学习目标】X分钟\u003c/strong>\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者能够在负面体验时使用意义换框法，转换事情的正面意义，让心态变得积极主动。\u003c/p>\u003cp>\u003cstrong>【A1量表自测】设计量表自测\u003c/strong>\u003c/p>\u003cp>下面我给大家做一次量表测试，了解每个人在负面体验时的状态。\u003c/p>\u003cp>请大家花1分钟时间，对下面几种情况，以1—6分的标准给自己打分。1代表完全符合，6代表完全不符合。根据自己的实际情况给自己打分，完成后核算总分。\u003c/p>\u003cp>根据自己的感觉和实际情况，来给自己打分，给大家五分钟时间。\u003c/p>\u003cp>负面体验的行为表现\u003c/p>\u003cp>我被别人否定时情绪易低落，总是觉得自己不行。\u003c/p>\u003cp> 1　２　３　４　５　６\u003c/p>\u003cp>我努力做事但结果不好时，总是自我攻击。\u003c/p>\u003cp> 1　 ２　 ３ 　４　 ５　 ６\u003c/p>\u003cp>不是我想要的结果出现时，总是爆发负面情绪。\u003c/p>\u003cp>1　 ２　 ３ 　４　 ５　 ６\u003c/p>\u003cp>我发现事情超出自己能力时，总是逃避不敢面对。\u003c/p>\u003cp>1　 ２　 ３ 　４　 ５　 ６\u003c/p>\u003cp>我总是认为自己各方面都不如别人，感觉生活处处不如意。\u003c/p>\u003cp>1　 ２　 ３ 　４　 ５　 ６\u003c/p>\u003cp>\u003cstrong>【I解释量表自测意义】\u003c/strong>\u003c/p>\u003cp>如果大家提前打完分，可以结束打分的过程。\u003c/p>\u003cp>接下来，一起看看自测结果：\u003c/p>\u003cp>分数在25分以上的小伙伴请打出数字1，25分以上的小伙伴，说明你遇到负面情绪和体验时，处理方式需要提高。容易消极被动，情绪不稳定。适应能力需要加强。\u003c/p>\u003cp>11到24分之间的请举手，这个分数区间的小伙伴，说明平时遇到事情有时候会积极，有时候会消极，自我调整能力和提升空间还是很多的。\u003c/p>\u003cp>10分以下的说明你在碰到负面情绪和体验时，能够积极主动的面对，心态调整能力很强，抗压性很强。\u003c/p>\u003cp>大家不要被测量的分数所干扰，只是你过去的状态，今天大家将学会一个技巧来改变过去负面的状态。请小伙伴一起阅读原文片段：\u003c/p>\u003cp>阅读完的伙伴可以聊天区打个1，示意我已完成。\u003c/p>","ratings_count":2,"texts":[{"id":19178,"quote":"\u003cp>图书《重塑心灵》 P49页\u003c/p>\u003cp>&quot;意义换框法&quot;是找出一个负面经验中的正面意义。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都只是人加诸的。既然是人加上去的意义，则一件事情﹣-\u003c/p>\u003cp>◇可以有其他的意义，也可以有更多的意义；\u003c/p>\u003cp>◇可以有不好的意义，也可以有好的意义。\u003c/p>","explains":"\u003cp>\u003cstrong>【WHAT】\u003c/strong>\u003c/p>\u003cp>本拆页给我们讲的是意义换框法，它能让我们看到任何事情都有正面和负面的意义，而这个意义是人所赋予的。学完意义换框法可以帮我们从负面体验找到正面意义。\u003c/p>\u003cp>\u003cstrong>【和学习者简短互动】\u003c/strong>\u003c/p>\u003cp>互动1：小伙伴们，读完拆页后，谁能告诉我们这个片段关键词是什么？\u003c/p>\u003cp>\u003cstrong>互动反馈：\u003c/strong>\u003c/p>\u003cp>对的，是意义换框法，大家回答的非常正确\u003c/p>\u003cp>互动2：意义换框法&quot;是可以从负面事件或体验当中找到正面意义 ，是否可以从正面事情当中可以找到正面意义呢？也可以的。非常棒\u003c/p>\u003cp>太好了，小伙伴们已经抓住今天学习的重点了，你们太智慧了。\u003c/p>\u003cp>\u003cstrong>【WHY】\u003c/strong>\u003c/p>\u003cp>在工作/学习/生活种有很多例子：你的老板很挑剔，所以你工作很不开心。疫情之下让你压力倍增。考试没通过，让你心灰意冷。钱丢了让你懊恼好多天。或者觉得自己沟通表达很差，不断自我否定......\u003c/p>\u003cp>\u003cstrong>【坏处】\u003c/strong>当你处在这些事情的阴影之下呢，在生活中处处可见这样事情的经历，如果这样的情况越久，越来越多的负面困扰容易出现，人容易在负面的情绪中爆发，让生活变得不快乐，幸福指数会不断下降。\u003c/p>\u003cp>\u003cstrong>【好处】\u003c/strong>如果学会意义换框法。可以找到这些负面事情的正面的意义和价值，看到更多好的一面，积极向上的生活状态，也会感染更多的人，并被你吸引。\u003c/p>\u003cp>要如何找到负面事情的意义和价值呢？下面有三个步骤。\u003c/p>\u003cp>\u003cstrong>【HOW】\u003c/strong>\u003c/p>\u003cp>如何把主观负面情绪转换为正面意义呢？\u003c/p>\u003cp>1. 找因果句式：因为一件事导致另一件事发生。\u003c/p>\u003cp>例如：班级换老师了，所以我觉得学习\u003cu>没兴趣\u003c/u>。因为下雨，我\u003cu>没心情工作\u003c/u>等。因为班级换老师，导致我学习没兴趣，因为下雨导致我没心情工作，因为一件事导致另外一件事发生，这样就是因果句式。\u003c/p>\u003cp>2. 换正面价值：把\u003cu>负面词语换成正面词语\u003c/u>，找正面意义和价值，（多找几个正面价值，最少找3个）\u003c/p>\u003cp>例如：班级换老师了，所以我学习\u003cu>更有兴趣（原来负面词语是没兴趣现在改成正面词语，是更有兴趣），\u003c/u>\u003c/p>\u003cp>\u003cu>把“因为”放在后面\u003c/u>，为什么我有兴趣呢？ 因为我适应能力强\u003c/p>\u003cp> 因为·我喜欢他的教学风格。\u003c/p>\u003cp> 因为他年轻有活力\u003c/p>\u003cp> 因为·他更有耐心。\u003c/p>\u003cp>因为，就是把正面意义和价值找到了，这么多价值和意义，怎么找到合适的呢，找一个你最认同的价值。\u003c/p>\u003cp>3. 取最佳价值：找出你最认同的价值\u003c/p>\u003cp>例如：班级换老师了，所以我学习\u003cu>更有兴趣\u003c/u>，因为他年轻有活力。\u003c/p>\u003cp>这就是我找出的最认同的价值。\u003c/p>\u003cp>\u003cstrong>【WHERE】\u003c/strong>\u003c/p>\u003cp>意义换框法可以在工作/学习/生活/情感沟通等用于事件出现负面价值和有负面情绪困扰的场景中应用，是有效果的。\u003c/p>\u003cp>\u003cstrong>【举例】\u003c/strong>\u003c/p>\u003cp>在年前的时候，一朋友来找我吐槽，因为老婆把车借给小舅子回老家，他没有车开，就很生气没有心情工作。我说：这件事对你来说有负面情绪和体验，但里面有正面的的意义和价值，我们一起找一找。\u003c/p>\u003cp>\u003cu>因为老婆借车，让我没心情工作\u003c/u>。（找因果句式）我们如何找到正面的词语，把没心情工作转换为正面词语是“\u003cu>工作更积极\u003c/u>”。后面再加上“因为”找到价值和意义。（换正面价值）\u003c/p>\u003cp>选择的句式：\u003cu>老婆借车，让我工作更积极，因为可以让我工作更专注。\u003c/u>\u003c/p>\u003cp> 因为要赚钱，买自己喜欢的车。\u003c/p>\u003cp> 因为证明这件事影响不了我。\u003c/p>\u003cp>最后，朋友选择了：\u003cu>老婆借车，让我工作更积极，\u003c/u> \u003cu>因为要赚钱，买自己喜欢的车。（取最佳价值）\u003c/u>\u003c/p>\u003cp>这个例子听过以后，大家对步骤流程和场景也很清晰了。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3现场演练】场景设计、拆书家提问设计\u003c/strong>\u003c/p>\u003cp>下面我给大家一个场景，大家在这个场景之中做角色扮演，大家听好这个场景：\u003c/p>\u003cp>\u003cstrong>场景\u003c/strong>：小明在学校上课时说话，被老师批评了，小明认为老师不喜欢他。回到家里跟妈妈说他很难受。\u003c/p>\u003cp>现在请小伙伴们两人一组，分别扮演一个角色：一个扮演小明，一个扮演妈妈。妈妈用刚才的三个步骤，为小明找到该事件的正面的价值和意义，来解决小明的负面情绪困扰。\u003c/p>\u003cp>别忘记三个步骤：1.找因果句式。2.换正面价值。3.取最佳价值。\u003c/p>\u003cp>因为人数很少，现在我邀请张芳和清栎做角色扮演好吗？张芳做妈妈，清栎做小明。\u003c/p>\u003cp>因为有观察家，还有小伙伴不方便说话，所以现在只能你们两个人先角色扮演探讨一下，\u003c/p>\u003cp>五分钟后邀请你们两个人来做案例的角色扮演。\u003c/p>\u003cp>\u003cstrong>【A3现场演练】学习者案例\u003c/strong>\u003c/p>\u003cp>\u003cstrong>小明：\u003c/strong>妈妈，我今天非常不开心，老师批评我了，我觉得老师不喜欢我。\u003c/p>\u003cp>\u003cstrong>妈妈：\u003c/strong>因为老师批评你，就是不喜欢你，所以你不开心，那这件事有什么正面意义和价值呢？\u003c/p>\u003cp>老师批评你，说明老师很喜欢你，因为老师关注你。\u003c/p>\u003cp> 因为老师给予你更高的期望。\u003c/p>\u003cp> 因为可以证明自己更好的机会。\u003c/p>\u003cp>这三个正面的意义，小明你选哪个最佳价值呢？\u003c/p>\u003cp>\u003cstrong>小明：\u003c/strong>老师批评我，说明她很喜欢我，因为她比较关心我。\u003c/p>\u003cp>\u003cstrong>互动反馈：\u003c/strong>\u003c/p>\u003cp>哇，你们两个人演练的的非常好，把三个步骤完美的做到，找到因果句式，正面价值找的非常好，最佳价值也做到让孩子在心理上感受到正面的力量和能量，非常棒。我们大家给个掌声吧。\u003c/p>\u003cp>\u003cstrong>【A2】布置任务\u003c/strong>\u003c/p>\u003cp>生活中有负面情绪和困扰的情况很多，很多人在负面情绪和困扰中不知如何解决。接下来给大家布置一个小作业：\u003c/p>\u003cp>结束课程以后，在未来一周的时间里，给自己或身边的人做一次意义换框法，解决对方的负面情绪或困扰，就像刚才小明的例子一样，让对方看到负面事件后面的正面意义和价值。\u003c/p>\u003cp>等一周后，我会提醒大家把实践过程的反馈，发在微信小组群里，我们一起复盘，探讨学习。\u003c/p>\u003cp>\u003cstrong>【结束语】\u003c/strong>\u003c/p>\u003cp>今天学到的意义换框法，需要不断的练习和实践，才更好的应用生活/学习和工作中。在任何事情当中，你会看到任何事都有正面的意义和价值，我们学会了意义换框法，可以把负面事件看到正面意义和价值。我们会更加积极正面的面对生活。让你的生活状态越来越好。\u003c/p>\u003cp>而且可以把这个方法教会你身边的人让你身边的小朋友/家人/同事学会这个方法后，生活也越来越好。\u003c/p>\u003cp>今天的拆书课到此结束。谢谢大家。\u003c/p>\u003cp>\u003cstrong>【A2反馈案例】\u003c/strong>\u003c/p>\u003cp>学习完拆书课后，和老公聊天，正好听老公说因为项目规划被否定，打回来三次了，觉得老板对他不信任了，觉得很失落。\u003c/p>\u003cp>我正好用学习到的意义换框法，帮助他看到正面的价值了，我很开心。\u003c/p>\u003cp>老公：今天我的项目规划被打回来第三次了，我觉得老总他对我不信任，很失落。\u003c/p>\u003cp>我：你老板以前对你很信任吗？\u003c/p>\u003cp>老公，是的，我以前的项目计划都是一次就过。现在连着三次，感觉在不信任我呢。\u003c/p>\u003cp>我：我们一起来找正面价值吧。因为老板把计划打回三次，所以你认为老板对你不信任。\u003c/p>\u003cp>我认为老板把计划打回三次，对你很信任，因为他重视你，否则早就把项目计划给别人做了。\u003c/p>\u003cp>老公：对啊，是这样的。\u003c/p>\u003cp>我：多找几个正面价值。老板把计划打回三次，对你很信任，因为他重视我。\u003c/p>\u003cp>因为因为他相信我有这个能力。\u003c/p>\u003cp> 因为我做的计划客户认可度高。\u003c/p>\u003cp>老公：因为看到我越挫越勇，迎难而上。\u003c/p>\u003cp>我：你觉得这几个正面价值，有你最认可的吗？\u003c/p>\u003cp>老公：我觉得是：老板把计划打回三次，对我很信任，因为他相信我有这个能力。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1676216295000,"updated_at":1676557319000,"ria":true},{"id":14956,"topic":"用意义换框法摆脱当下负面情绪","learn_goal":"","remark":"我们经常会受到一些事情当下的负面情绪的影响，如何用一个句式巧妙的翻转情绪，看到事情的积极意义？\n“意义换框法”改变句式中的“因果关系”，从负面影响中看到积极意义！","level":"TF2-3","duration":35,"status":30,"type":0,"chaishujia":{"username":"石研","city":"石家庄市"},"club":{"name":"石家庄冀城分舵","city":"石家庄"},"prologue":"\u003cp>大家好，我是石研，一个专职在线课程运营官，也是一个终身学习不断精进中的个人成长教练！这是我的三个标签。\u003c/p>\u003cp>\u003cstrong>【Feature特征】（以书为核心来满足好奇心）\u003c/strong>\u003c/p>\u003cp>《重塑心灵》这本书豆瓣评分8.4，作者是国际NLP大师李中莹，本书一经出版就成为国内最权威的NLP入门书。NLP可译为“身心语法程序学”，是一门研究我们的大脑如何工作的学问。本书不仅提供了既安全又容易产生实效的NLP技巧，还提出了更多与时代同步发展的新观点与新案例。\u003c/p>\u003cp>\u003cstrong>【Advantage优势】（用比较建立安全感）\u003c/strong>\u003c/p>\u003cp>李中莹先生很早就把NLP完整地介绍到国内，因而被誉为“华人世界的国际级NLP大师”，他发展出大量独到而实用的思想和行为技巧，可以有效地帮助一个人培养出良好的心理素质。这本书与其他介绍NLP的书籍相比，非常通俗易懂、并且又系统性很强，没有过多艰涩的专业辞藻，而是站在一般大众角度，以尽量通俗的中文重新诠释英文原意，李中莹的NLP理论中，更强调信念系统给人生最重要的影响。\u003c/p>\u003cp>\u003cstrong>【Benefit利益、好处】\u003c/strong>（强调学习者能学到什么以引发兴趣）\u003c/p>\u003cp>\u003cstrong>【B1】（学完本书可得利益）\u003c/strong>\u003c/p>\u003cp>NLP是研究人的大脑如何运作，以及如何提升它的运作效率的学问，对于心理学，就是通过研究、改变我们神经反馈构造、思维等方式，并以此改变我们的行为模式。\u003c/p>\u003cp>这本书可以帮助我们拥有让自己成功快乐的能力，是一本值得反复阅读的书，李中莹在书里甚至把我们整个认识世界的方式进行了分解，细分到每一个步骤，每一个细节，用到了公式，用到了很多具体工具，帮助我们真正了解自己，了解我们认识世界的方式，改变认知，重塑我们的心灵。\u003c/p>\u003cp>\u003cstrong>【B2】（学完此片段可得利益）\u003c/strong>\u003c/p>\u003cp>今天我们就来学习改变我们信念系统的技巧中最快速最容易的一个——意义换框法，这个方法可以帮助我们找到负面体验中的正面意义。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>\u003c/p>\u003ch2>通过跟随我今天的RIA学习，能够利用意义换框法7步法，改变句中的因果关系，通过角色扮演演练从一件事情的负面经验中找到多个正面意义，安慰自己或朋友摆脱当下的负面情绪。\u003c/h2>","ratings_count":1,"texts":[{"id":18953,"quote":"\u003cp>选择书籍：《重塑心灵》第二章 信念系统\u003c/p>\u003cp>【R阅读原文拆页】\u003c/p>\u003cp>\u003cstrong>技能点：所选图书是实用类或理论类书籍。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【R】所选拆页，包括How的内容；且总内容未超过2页图书内页。\u003c/strong>\u003c/p>\u003cp>主题【页码】P50—51\u003c/p>\u003cp>\u003cstrong>换框法之一：意义换框法\u003c/strong> \u003c/p>\u003cp>所有的事本身是没有意义的，所有的意义都是人加上去的。既然是人加上去的意义，则一件事情：\u003c/p>\u003cp>第一，可以有其他的意义，也可以有更多的意义。 \u003c/p>\u003cp>第二，可以有不好的意义，也可以有好的意义。 \u003c/p>\u003cp>试想一下：当你用一块石头去锤打一颗钉子。或者赶走一只老鼠，你加到这块石头上的意义是什么？它本来有这些意义吗？再想一想，一块石头可以有多少用途？\u003c/p>\u003cp>把上面问题引出的意念放在别人所说的一句话、一个行为、甚至环境出现的一些情况上，你会得到什么启示？下次坐车没事做的时候，试想一想万字夹可以有多少用途。也许这样你会明白\u003cstrong>一件事情的意义，只是决定于我们的主观思想\u003c/strong>。 \u003c/p>\u003cp>同一件事情里面总有不只一个意义包含其中。找出其中\u003cstrong>最能给自己帮助的意义，便可以把事情的价值改变\u003c/strong>，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。 \u003c/p>\u003cp>\u003cstrong>意义换框法对一些因果式的信念最为有效\u003c/strong>。例如：\u003c/p>\u003cp>“因为上司挑剔，所以我工作不开心。”\u003c/p>\u003cp> 方法是把句中的&quot;果&quot;改为它的相反词，再把句首的&quot;因为&quot;二字放到最后，成为：\u003c/p>\u003cp>“上司挑剔，所以我工作积极，因为……” \u003c/p>\u003cp>然后反复地思考如何能把句子写完,要求至少有6个不同的版本,再找出其中最能够接受的句子。 \u003c/p>\u003cp>以下是课程里一些学员的杰作： \u003c/p>\u003cp>使我变得更能干 \u003c/p>\u003cp>使我更快升级，脱离他的管治 \u003c/p>\u003cp>使我更有能力去另找新工作 \u003c/p>\u003cp>使我在同事之中受到最少的挑剔，因而更有安全感 \u003c/p>\u003cp>使我能更早创业 \u003c/p>\u003cp>我要证明他不能控制我的情绪 \u003c/p>\u003cp>我要证明我可以做到 \u003c/p>\u003cp>使我能清静愉快地工作 \u003c/p>\u003cp>能证明在这种上司之下我仍能胜任 \u003c/p>\u003cp>能证明我能超越任何压力 \u003c/p>\u003cp>使其他老板注意我，因而创出转工的机会 \u003c/p>\u003cp>使我有更优良的表现 \u003c/p>\u003cp>试着挑选一条你觉得最好的，然后把整句话反复地念数遍。现在，你再念念本来的一句：“因为上司挑剔，所以我工作不开心。”你内心的感觉有怎样的不同？本来的一句和后来的一句，哪句你觉得更舒服一点？\u003c/p>\u003cp>假若我是你的一位多年好友，3个月前转了工作，今天走到你面前说，因为上司挑剔，所以我工作不开心。”你会觉得很自然地接受我的话，给我安慰、鼓励，你接受我的话的信念平常是：“上司挑剔，当然会不开心。” 现在，你把内容转了180度，刚好是相反的：“上司挑剔，所以我工作积极，因为……”而你的内心感觉比上一句更好。这是因为你内心的信念已经改变了。信念是在潜意识里，所以感觉是最好的测试标准。 \u003c/p>","explains":"\u003cp>what:\u003c/p>\u003cp>同一件事情里面总有不只一个意义包含其中。找出其中\u003cstrong>最能给自己帮助的意义，便可以把事情的价值改变\u003c/strong>，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。 \u003c/p>\u003cp>why:\u003c/p>\u003cp>正如上一个片段告诉我们：同一件事情，既可以有正面意义，也可以有负面意义。所以，才会有古人云“塞翁失马，焉知非福”。既然得失总在一念之间，那有没有什么方法能够帮助我们具备遇事学会转念一想，多想一点正面意义，少想一点负面意义的能力呢？\u003c/p>\u003cp>意义换框法，恰好可以帮助我们借助信念模式的改变，找到一件事情负面体验中的正面积极的意义。\u003c/p>\u003cp>how:\u003c/p>\u003cp>意义换框法有哪些步骤呢？\u003c/p>\u003cp>\u003cstrong>意义换框法对一些因果式的信念最为有效。\u003c/strong>\u003c/p>\u003cp>我来举一个自己的案例大家一起学习一下意义换框法的几个步骤。\u003c/p>\u003cp>近期工作还是比较多的，结果我感染了流感，身体不舒服，鼻塞睡不好，头疼很难受，只能暂停工作，孩子的事情我还得操心照顾，心情很低落，也很焦虑烦躁。后面我尝试用了意义换框法，心情真的会好很多。 \u003c/p>\u003cp>\u003cstrong>1.\u003c/strong> \u003cstrong>描述情绪，找到情绪中的因果关系\u003c/strong>\u003c/p>\u003cp>选择准确的情绪词汇，并用因果句式描述，比如：因为……（描述事件），所以我很……(描述情绪)，“因为我生病无法工作，还得操心照顾小孩，所以我感到低落、焦虑、烦躁。”。既说出了事件，又描述了自己的情绪。\u003c/p>\u003cp>\u003cstrong>2.“果”变反义词“非果”——把“果”转换成反义词\u003c/strong>。\u003c/p>\u003cp>我生病无法工作，还得操心照顾小孩，把“我感到低落、焦虑、烦躁”变成“我感到很开心”\u003c/p>\u003cp>\u003cstrong>3.把“因为”置后——\u003c/strong>腾出更多的可能性的积极的信念空间。\u003c/p>\u003cp>我生病无法工作，还得操心照顾小孩，我感到很开心，因为...\u003c/p>\u003cp>\u003cstrong>4.补全句子——尽可能多的补全句子\u003c/strong>，头脑风暴，尽可能多地把句子补全写完，不同的版本可供接下来的选择。\u003c/p>\u003cp>我生病无法工作，还得操心照顾小孩，我感到很开心，因为：\u003c/p>\u003cp>1）这几天我终于可以美美的心安理得的躺平睡懒觉了。\u003c/p>\u003cp>2）这几天我终于可以名正言顺的不工作了。\u003c/p>\u003cp>3）这几天我终于可以随时陪伴孩子，享受陪伴的乐趣了。\u003c/p>\u003cp>4）这几天我终于可以放心追剧，看娱乐节目了。\u003c/p>\u003cp>5）我终于可以放空自己几天，让身体得到一个充足的休息了。\u003c/p>\u003cp>6）我终于可以尽情享受几天闲适生活，无所事事也不会有任何压力。\u003c/p>\u003cp>\u003cstrong>5.选出一句念数遍——选出最好的一句，反复念数遍\u003c/strong>，挑选一条你觉得最能接受的最好的句子，反复念数遍，完成因果式信念置换，意义转换。\u003c/p>\u003cp> 我生病无法工作，还得操心照顾小孩，我感到很开心，因为这几天我终于可以尽情享受几天闲适生活，无所事事也不会有任何压力。\u003c/p>\u003cp>我反复默念这句话，越念越觉得确实是这样，心情放松很多。 \u003c/p>\u003cp>\u003cstrong>6.比较感受，测试心情——比较开始句子和现在句子\u003c/strong>，测试感受心情，感受心情变化，哪一句更舒服？\u003c/p>\u003cp>l 因为我生病无法工作，还得操心照顾小孩，所以我感到低落、焦虑、烦躁。\u003c/p>\u003cp>l 我生病无法工作，还得操心照顾小孩，我感到很开心，因为这几天我终于可以尽情享受几天闲适生活，无所事事也不会有任何压力。\u003c/p>\u003cp>比较一下这两句话，后面一句感觉更加舒服，放松，没有压力。\u003c/p>\u003cp>\u003cstrong>7.确认心情，完成信念改变\u003c/strong>。\u003c/p>\u003cp>我现在心情感觉是放飞的，变得开心、轻松，接纳当下，顺其自然。\u003c/p>\u003cp>可以用一个简单的公式表述为：\u003c/p>\u003cp>因为\u003cu>A\u003c/u>，所以\u003cu>\u003cstrong>B\u003c/strong>\u003c/u> \u003c/p>\u003cp>转换为：\u003c/p>\u003cp>\u003cu>A\u003c/u>，所以\u003cu>\u003cstrong>非B\u003c/strong>，因为...\u003c/u>\u003c/p>\u003cp>其中，A：负面体验；B：负面感受。\u003c/p>\u003cp>我来解释一下，这一组公式如何来用：\u003c/p>\u003cp>\u003cstrong>（1）因为\u003cu>A\u003c/u>，所以\u003cu>B\u003c/u>\u003c/strong>：公式中，A是负面体验，B是由A得到的负面感受。这一步的关键是觉察并记录负面感受。 \u003c/p>\u003cp>\u003cstrong>\u003cu>（2）A\u003c/u>，所以\u003cu>非B\u003c/u>\u003c/strong>：将B转换为非B，也就是将负面感受转换为正面感受和意义。从B的反面来重新看待A事件带给我不同视角的意义。\u003c/p>\u003cp>\u003cstrong>\u003cu>（3）A\u003c/u>，所以\u003cu>非B，因为...,\u003c/u>\u003c/strong>借助头脑风暴，反复思考将句子补全。这是最后形成一个开放式的句式，腾出更多的积极信念可能性的空间，能补全几个不同版本的句子，目的是从中选出感觉最好的那一句，并反复多念几遍，体会最开始的那句话与这句话带给你心情感受和能量的变化。\u003c/p>\u003cp>（以上是行动步骤建议）\u003c/p>\u003cp>where:\u003c/p>\u003cp>请大家注意，意义换框法特别适合改变因果式的负面想法和感受，可以应用在工作、生活、情感沟通、教育子女等多个方面。\u003c/p>\u003cp>（以上是与行动步骤相对应的案例）\u003c/p>","interaction":"\u003cp>\u003cstrong>【A3】\u003c/strong>(场景练习) 4分钟\u003c/p>\u003cp>\u003cstrong>技能点：【A3】环节，给出了一个非常具体、确定的场景，学习者可以此场景中演练或讨论或应用新学技能。（无需分组，在会议软件主界面演练）\u003c/strong>\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp> 小张在公司做人力资源已经6年了，最近原本计划好想要在单位举行的心理沙龙，现在因为一个基本功不怎么扎实的同事，先拿到了内训师名额，搞得自己很被动，今年内训师选拔由于工作时间冲突，没能参加，导致自己两年内可能都没有一个名正言顺的资格来做这件事，很影响规划。小张感到很沮丧，她把心中的不快向她的朋友小S倾诉，小S给予她安慰和鼓励。\u003c/p>\u003cp>\u003cstrong>技能点：使用【A3】技能点的环节指令清晰，学习者可以根据拆书家设定的案例场景，进行小组讨论、应用知识点并形成一个解决方案，或是应用知识点进行组内角色扮演。（无需分组，在主界面演练扮演）\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【A3】\u003c/strong>（角色扮演）\u003c/p>\u003cp>【角色扮演】\u003c/p>\u003cp>现在，邀请两人进行演练。一人扮演小张，一人扮演她的朋友小S。请两位伙伴用2分钟讨论一下小张的朋友小S如何安慰和鼓励小张，从而帮助她找到这件事情的正面意义，心情获得好转。双方可以3分钟演练一下对话，需要用上原文拆解中意义换框法的公式。\u003c/p>\u003cp>指令：\u003c/p>\u003cp>1、先请大家花3分钟思考一下，请参考我给大家的意义换框法的公式和模板边思考边进行记录。\u003c/p>\u003cp>2、再邀请两位伙伴，一人扮演小张，一人扮演小S。3分钟时间，小S需要利用意义换框法的公式帮助小张找到这个事情的正面意义，帮小张走出情绪困境。\u003c/p>\u003cp>给大家3分钟时间先讨论一下，稍后我会请两位小伙伴上来和大家分享。\u003c/p>\u003cp>请参考下面的模板，写下你们的思考过程。\u003c/p>\u003cp>意义换框法公式\u003c/p>\u003cp>因为A，所以B。\u003c/p>\u003cp>因为 ，\u003c/p>\u003cp>所以 。\u003c/p>\u003cp>A，所以非B，因为......\u003c/p>\u003cp> ，\u003c/p>\u003cp>所以 ，因为：\u003c/p>\u003cp>1.\u003c/p>\u003cp>2.\u003c/p>\u003cp>3.\u003c/p>\u003cp>小张感觉最好的句子是： （反复读）\u003c/p>\u003cp>此时，小张的心情：\u003c/p>\u003cp>【角色演练】\u003c/p>\u003cp>李跃（小张）：今年内训师选拔由于工作时间冲突，没能参加，导致我两年内可能都没有一个名正言顺的资格来做我想做的心理沙龙，很影响规划，我觉得很沮丧。\u003c/p>\u003cp>京京（小S）：事情不只是有一个意义，这件事确实当下给你的感受是负面的，那我们也可以换个角度想想，这件事情对你来说有没有一些积极的意义和思考？\u003c/p>\u003cp>李跃（小张）：如果这么说，我想想，可能这次没参加内训师，是为了让我更好的做好准备吧，先看看同事怎么做。\u003c/p>\u003cp>京京（小S）：还有吗？\u003c/p>\u003cp>李跃（小张）：还有就是让我继续在人力资源这个岗位上继续磨砺吧，我也可以给当上内训师的同事一些建议，先参与进来。\u003c/p>\u003cp>京京（小S）：我刚才听到你已经找到了这件事情的3个积极意义，那现在你的心情感觉怎么样？\u003c/p>\u003cp>李跃（小张）：我好像没有之前那么沮丧、郁闷了，现在觉得接纳当下吧，看看现在能做的事情是什么，感觉轻松很多了。\u003c/p>\u003cp>【结束语】\u003c/p>\u003cp>相信通过刚才的讲解和演练，大家对意义换框法有了一个更加清晰的认知和理解，我们在日常生活工作中遇到一些因果式负面事件带给我们当下产生负面的感受情绪时，用简单的换框公式，就可以快速发生信念置换。意义转换，看到事情的积极意义，转变心情，感谢大家今天的陪伴，我的TF2-3拆书过级到此结束，感谢大家！\u003c/p>\u003cp>\u003cstrong>技能点：总时长没有少于25分钟，没有超过30分钟。\u003c/strong>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1672371851000,"updated_at":1674273723000,"ria":true},{"id":14420,"topic":"松动信念的方法","learn_goal":"","remark":"思维类书","level":"TF2-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"照照","city":""},"club":{"name":"湖州吴越分舵","city":"湖州"},"prologue":"\u003cp>各位好！我是湖州阅亮分舵的新手拆书家照照，我今天挑战的级别是TF 2-1.\u003c/p>\u003cp>我先来自我介绍一下，我的三个标签\u003c/p>\u003cp>一是服装设计 多年从事男装品牌开发 ，二是个人成长教练，希望通过沟通的艺术和教练技术支持他人，第三我也是一名早起领读人，和一群伙伴早起晨读一起在生活中实践书中的理论。\u003c/p>\u003cp>！很开心今天和大家聚在一起学习。\u003c/p>\u003cp>F:今天我们拆页节选于《重塑心灵》。这是一本NLP心理学的书籍，01年首次出版就成为NLP领域最重要的中文著作，并且多次再版.\u003c/p>\u003cp>A:NLP指的是神经语言程序，是研究我们的大脑如何工作的学问，作者李中莹老师是最早将NLP完整地介绍到国内的人，被誉为“华人世界的国际级NLP大师”。这本书和其它类NLP书籍比较的话， 它保持李中莹惯有的务实和落地态度，特别通俗易懂，站在大众的视角传达NPL技巧的灵活多样 ，让我们简单上手容易操作。                \u003c/p>\u003cp>B:从这本书中能够从NLP的角度认识自己，认识他人，提高自我价值，运用更好的沟通方式改善人际关系，化解内心冲突，激发个人潜力，从而拥有成功快乐的人生。\u003c/p>\u003cp>今天我们学习书中的一个片段“松动信念的方法”，在书中的43页和44页，这个段落的学习，可以让我们对同一件事情有不一样的看法，从困境中解脱出来,从而有更好的选择，让我们更加轻松快乐。\u003c/p>","ratings_count":1,"texts":[{"id":18431,"quote":"\u003cp>一个人的思想、情绪和行为，都受他内心的信念系统所支配。一些局限性的信念，可以使这个人每当面对某些人事物的时候，不能做到三赢，并感受不到应有的成功快乐。过去积存的选择也就是他头脑里现有的神经元网络，这些选择既然无效，每次遇到同一件事，便都只会重复那不理想的效果。欲想他有更好的表现，必须先让他建立一些更有效的信念，也就是建立新的神经元网络去改进对待同类事情的想法与做法。\u003c/p>\u003cp>松动信念的方法\u003c/p>\u003cp>以下方法对所持的信念做出审视和界定，因而能够使之松动。所用的例子是一位家庭主妇应否每天都等待丈夫回家一同吃饭。\u003c/p>\u003cp>1．改变标签。\u003c/p>\u003cp>例：“不等待他回来便吃东西是不尊重他。”（标签）\u003c/p>\u003cp>“不等待他回来便吃东西是照顾自己。”（新标签）\u003c/p>\u003cp>2．改变标签的定义。\u003c/p>\u003cp>例：“自己因为太饿而没有气力，从而产生抱怨情绪，他回来后你不能给他好的照顾，这才是不尊重他呢！”\u003c/p>\u003cp>3．审视背后的动机。找出事情背后的正面动机，这往往需要找出更高的理解层次，即更大的意义、更广的覆盖面或范畴。可以问：“这样做会让你变得怎么样？会给你一些什么重要的东西？”这样有可能让这个主妇看到改变的好处。\u003c/p>\u003cp>例：“不等待他回来便吃东西，使我有气力做好家务，进而把东西收拾好，怀着轻松愉快的心情等待他回来。”\u003c/p>\u003cp>4．极度延伸。把维持旧信念的终极结果明显化。引导她自问，或者对她说：“你继续这样做，最终会有什么结果？\u003c/p>\u003cp>例：“继续这样做，偶然的胃痛会变成长期的胃病，身体坏了，什么事情都做不好，情绪也会越来越坏，两人的关系会越来越紧张。”\u003c/p>\u003cp>以上的过程，最好是引导对方制造一些有视觉、听觉和感觉元素的未来景象，这会产生支持改变信念的动力。上面的例子，其实真正的突破点可能是教导这个家庭主妇如何与丈夫共同讨论晚饭时间的安排，但是这位女士必须先让内心的旧信念动摇了，才会有动力去思考和开口。\u003c/p>","explains":"\u003cp>好，看到大家很认真的看完了，我们今天的学习目标\u003c/p>\u003cp>（\u003cstrong>学习目标：\u003c/strong>通过和我完成本次RIA现场学习后，我们学习者能够运用松动信念的四种方法，从一个很纠结的事情当中跳出来，内心挣脱原先的束缚，重新做出选择。）这就是今天的学习目标。\u003c/p>\u003cp>\u003cstrong>（WHY不这么做的坏处)\u003c/strong>\u003c/p>\u003cp>（what）今天的学习片段给了一个松动信念的四个方法，让我们在遇到一个很纠结的事情时，运用这里的方法有新的角度来转化信念，重新做出选择。\u003c/p>\u003cp>(why)我们思考一下，生活中我们是否经常固执地坚持一些不合适宜的信念呢？例如长期进行两点一线的工作，精神上很疲惫，很想出去旅游个四五天，但是觉得把手头工作扔到一边很不负责任。所以你就进入两难的境地，感觉到自己很矛盾，时间久了就越来越有情绪，甚至可能会有些焦虑，那通过文中的方法我们来看看怎么做我们能够迅速摆脱当前的焦虑有新的方向呢？（这样做的坏处是什么）\u003c/p>\u003cp>how:\u003c/p>\u003cp>第1步：改变标签。标签就是我们对事情或者人下的定义, 比如刚才的案例\u003c/p>\u003cp>把工作放到一边时出去旅游是不负责任的。”（标签），我们可以改成这样的想法\u003c/p>\u003cp>“把工作放到一边时出去旅游是关照自己的爱自己的表现。”（新标签）\u003c/p>\u003cp>第2步：改变原标签的定义。\u003c/p>\u003cp>原来我们内在的信念是“出去旅游不工作是不负责任”改成“带着情绪不认真工作才是不负责任呢”。\u003c/p>\u003cp>第3步：找到新行为背后的正面动机，也就是这样做有什么好处。\u003c/p>\u003cp>“出去旅游后，有一个全新的状态投入工作，就会特别的开心，也能把工作做好。”看，这好像又是一个新的角度\u003c/p>\u003cp>第4步：极度延伸。思考旧的做法继续做下去导致最终的结果是什么。\u003c/p>\u003cp>日复一日的工作上班，人变得越来越麻木，生活越来越没有激情，那就更糟糕了。\u003c/p>\u003cp>所以这时候出去旅游放松一下是一个很有必要的建设性的事情。\u003c/p>\u003cp>同时我们来感受和想象一些有视觉、听觉和感觉的未来景象和画面，这会产生支持改变信念的动力。\u003c/p>\u003cp>Where:当我们感觉自己在某件事上陷入困境，左右为难时，就可以尝试用上述的松动信念的方法改变自己的想法，也可以用这个方法帮助他人梳理，从困境中走出来。\u003c/p>\u003cp>这几个步骤属于心理学的范畴，好像不是特别容易落地，那我举一个自己的例子，相信大家会更容易理解。\u003c/p>\u003cp>\u003cstrong>（自己的反面案例）\u003c/strong>2分钟\u003c/p>\u003cp> 最近有一个工作机会摆在我前面，我很想去但是觉得上班后不能很好的陪伴孩子觉得自己不是个好妈妈。\u003c/p>\u003cp>反思：\u003c/p>\u003cp>①这个工作是一个好机会，能让我重新进入职场，有一份自己的收入。\u003c/p>\u003cp>②陪孩子的时间肯定就减少了，一天大概只有两三个小时陪孩子玩和学习，而且有时候可能需要加班出差，就更不能陪孩子了。\u003c/p>\u003cp>所以我陷入了纠结，矛盾，不知道怎么选择。\u003c/p>\u003cp>\u003cstrong>（把反面加工成正面）\u003c/strong>\u003c/p>\u003cp>我学习了用松动信念的方法，我就这样做了 （不够圆滑）\u003c/p>\u003cp>第一步改变旧标签，\u003c/p>\u003cp>选择工作不能陪伴孩子不是好妈妈。（老标签）\u003c/p>\u003cp>选择工作不能陪伴孩子是因为我要成为孩子的榜样（新标签）\u003c/p>\u003cp>第二步改变原标签的定义，\u003c/p>\u003cp>“如果一直在家，不工作，没有成长和进步不能给予孩子更好的资源，这才不是一个好妈妈呢！”。\u003c/p>\u003cp>第三步找到事情背后的正面动机，“我有自己的工作，有自己的收入，在工作当中不断成长学习，工作做好了，对于家庭和孩子才是最最负责任的。\u003c/p>\u003cp>第四步极度延伸，“如果我为了照顾孩子，我把所有的心思都放在孩子身上，孩子可能会变得越来越来越依赖我，就算我天天陪在孩子身边，孩子也不会很自主很独立”。这个结果我就不能接受，经过上面的思考，我毅然决定去上班了。\u003c/p>","interaction":"\u003cp>\u003cstrong>（A1显像提问）\u003c/strong>3分钟\u003c/p>\u003cp>现在请伙伴们回忆一下，你在生活中有没有碰到这样的场景：\u003c/p>\u003cp>老的工作没有激情，想换工作但是又怕重新去适应一个新环境。\u003c/p>\u003cp>想专心养育孩子，又想有一份自己的工作，做一个经济独立的女性。\u003c/p>\u003cp>你遇到过类似的情况吗？\u003c/p>\u003cp>我们花两分钟时间讨论一下，我们请一个伙伴伟来给大家分享一下。\u003c/p>\u003cp>\u003cstrong>（A1+反思加工经验\u003c/strong>)\u003c/p>\u003cp>好，谢谢这位伙伴的分享，回到大家想到的那样的情景，你会怎么运用我们刚刚学习的松动信念的方法呢，一是改变标签，二是改变标签的定义，三是审视背后的动机四是极度延伸。让我们试着“柳暗花明又一村”，请大家写在我们的便签上，写完之后把你们的便签反馈给我，感谢!\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1666661940000,"updated_at":1666838760000,"ria":true},{"id":12841,"topic":"意义换框法","learn_goal":"","remark":"在我们遇到一些不顺心的事情时，我们如何给事情赋予积极正面的意义，让我们走出情绪困境","level":"TF3-2","duration":25,"status":29,"type":0,"chaishujia":{"username":"紫珺","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>各位伙伴，大家晚上好！我是拆书家周周，欢迎大家来到今天的拆书现场!\u003c/p>\u003cp>事件场景：\u003c/p>\u003cp>上周五下午，我的同事小兰报考了茶艺师，因为考试没有通过心情很是郁闷，觉得自己什么事都做不好，看到我就一副愁眉哭脸的样子。\u003c/p>\u003cp>提问：请问一下大家，考试没有通过这件事，是正面的还是负面的呢？\u003c/p>\u003cp>正面或者负面？\u003c/p>\u003cp>学习者A回答：我觉得是负面的，会影响到我们的情绪\u003c/p>\u003cp>学习者B回答：我认为是正面的，可以多一些时间准备，多复习一下。\u003c/p>\u003cp>好，很不错，是的，很多人理解的不一样。\u003c/p>\u003cp>同一件事情，有的人理解为可以接受，是正面的，有的人理解为不好接受，是负面的。所以，给事情赋予不同的意义，我们的情绪状态和处理方式也会不一样。\u003c/p>\u003cp>影响：\u003c/p>\u003cp>如果一个人经常把各种事情，习惯性的就想到他不好的一面，他会怎么样呢？会带来什么样的影响呢？\u003c/p>\u003cp>学习者回答：会变得很消极了，变成一个负面的人\u003c/p>\u003cp>嗯嗯，是的\u003c/p>\u003cp>如果长久这样下去，我们就会一直处于负面或者低落的情绪里面，导致工作越来越恶化，最终很难走出困境。\u003c/p>\u003cp>解决：但我们判断一件事情的价值或意义，大多是过去习惯性的认知。那该如何让我们能脱离认知习惯，从负面感受的事件中，看到他的正面意义或发现他的价值所在呢？\u003c/p>\u003cp>今天我介绍的李中莹老师的《重塑心灵》就可以帮到大家，这是一本关于研究大脑如何工作的书籍，它通过一些语言模式、思维模式的转变来改变我们的信念、价值系统，让我们能够多看到事情积极的一面。\u003c/p>\u003cp>【学习目标】：\u003c/p>\u003cp>通过今天的分享，学习者在面对负面感受的事件时，能够使用“意义换框法”的三个步骤，看到事件的正面意义或发现价值，避免负面感受带来的主观判断。\u003c/p>\u003cp>我们今天的学习过程中有分组练习，所以我们先进行一下分组，这边两位为第一组，这边为第二组。\u003c/p>","ratings_count":1,"texts":[{"id":16802,"quote":"\u003cp>技能点：【把知识改编为量表自测题】\u003c/p>\u003cp>在此之前，我们先做一个小测试，看看我们目前处理负面感受的现状如何。\u003c/p>\u003cp>请大家花1分钟时间，对下面四种情况，以1—6分的标准给自己打分。1代表完全不符合，6代表完全符合。仔细阅读每一句话，根据自己的实际情况给自己打分，并在完成后核算一下总分。\u003c/p>\u003cp>题目 评分\u003c/p>\u003cp> 1完全不符合 6完全符合\u003c/p>\u003cp>1当我情绪低落时，我总能找到影响情绪的具体事件 123456\u003c/p>\u003cp>2当事情的结果不尽人意时，我总会去尝试寻找这件事情对我的价值 123456\u003c/p>\u003cp>3当不如意的结果困扰我时，我总会将想到的这件事情的价值写下来 123456\u003c/p>\u003cp>4写下的这些好处与价值，我总会选出最佳的大声念出来 123456\u003c/p>\u003cp>总分\u003c/p>\u003cp>【解释一下刚才量表自测题的意义】\u003c/p>\u003cp>好的，咱们一起来看看自测结果：\u003c/p>\u003cp>结果在20分以上的小伙伴请举手，20分以上的，说明你比较积极乐观，遇事总能很快想到积极的方法解决，自我调整能力非常强；\u003c/p>\u003cp>12到20分之间的请举手，这个分数阶段的小伙伴说明平时遇到事情有时候会积极，有时候会消极，自我调整能力较强，但是还可以继续提高一下；\u003c/p>\u003cp>有没有和我一样分数的，12分以下的小伙伴？\u003c/p>\u003cp>说明平时被负面情绪困扰时，不能很快的通过合适的技巧来进行处理。\u003c/p>\u003cp>不管大家的分数是怎样的，都只代表你现在的一个状态，我今天将教会一个技巧给大家。请大家花1分钟时间阅读一下原文片段：阅读完的伙伴可以抬头示意一下。谢谢！\u003c/p>\u003cp>技能点：【原书拆页R为Why或者What的内容,或原书的一个完整的案例】\u003c/p>\u003cp>原文拆页： 意义换框法\u003c/p>\u003cp>“意义换框法”是NLP技巧“换框法”中最常用和最好用的技巧。它完全只凭言语和思想模式而产生效果，是NLP的改变信念技巧中最快速最容易的一个。“意义换框法”是找出一个负面经验中的正面意义。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都只是人加诸的。既然是人加上去的意义，则一件事情——\u003c/p>\u003cp>可以有其他的意义，也可以有更多的意义；\u003c/p>\u003cp>可以有不好的意义，也可以有好的意义。\u003c/p>\u003cp>试想一下，当你用一块石头去锤打一颗钉子，或者赶走一只老鼠，你赋予这块石头的意义是什么？它本来有这些意义吗？再想一想，一块石头可以有多少用途？\u003c/p>\u003cp>把上面问题引出的意念放在别人的一句话、一个行为，甚至环境出现的一些情况上，会给你什么启示？\u003c/p>\u003cp>下次坐车没有事情做的时候，可以试想一想一只曲别针可以有多少用途。也许这样你会明白一件事情的意义只是取决于我们的主观思想。\u003c/p>\u003cp>同一件事情里面总有不止一个意义包含其中。找出最能帮助自己的意义，便可以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。（拆页结束~）\u003c/p>","explains":"\u003cp>I拆书家讲解引导：\u003c/p>\u003cp>技能点：【I讲解引导时，拆书家有进行简短互动，精准控场，还要举例子】\u003c/p>\u003cp>好的，大家都看完了拆页。\u003c/p>\u003cp>请问一下大家，这个片段主要讲了什么？（意义换框法）\u003c/p>\u003cp>对，是意义换框法。\u003c/p>\u003cp>原文中解释意义换框法的是哪句话呢？（找出负面经验中的正面意义）\u003c/p>\u003cp>对，找出负面经验中的正面意义。\u003c/p>\u003cp>负面经验也就是不如意的事情，任何事情都有好的意义和不好的意义。意义换框法就是，对于本来有不好意义的事情换成可以帮助自己的正面意义，把这件事情的价值改变一下，我们的情绪和处理问题的方式也就跟着变得正面了。\u003c/p>\u003cp>【How步骤】：\u003c/p>\u003cp>那我们如何使用意义换框法呢？结合我们的拆页内容得出步骤：找出一个负面经验中的正面意义：所以我们的\u003c/p>\u003cp>第一步：找负面情绪的具体事件\u003c/p>\u003cp>将所面临的问题用“因为某某事情，所以我感觉怎么样”的句式表达出来。\u003c/p>\u003cp>感觉出来负面情绪其实就是给事情赋予了负面意义。\u003c/p>\u003cp>举例：\u003c/p>\u003cp>比如上个月我拆书过2-4的时候，拆了4次都没有通过，当时的心情非常的沮丧，情绪也比较低落。\u003c/p>\u003cp>我想请问下大家，这个情景我们用因果句式可以怎么表示呢？（学习者回答。。。）\u003c/p>\u003cp>对，我们可以表示成：\u003c/p>\u003cp>因为拆书过级4次都没有通过，所以我感觉很沮丧。\u003c/p>\u003cp>然后刚才拆页里讲到，同一个事情总有不止一个意义包含其中，那我们就把多个意义找出来。\u003c/p>\u003cp>第二步：思考这件事情的正面价值，写下来\u003c/p>\u003cp>接着第一步里面提到的负面情绪的事件，我们来反复思考“如果这件事情对我来说是有正面价值的，会是什么呢？”可以换成：某某事情也是有积极的一面，因为。。。。。注意：这些价值一定要是积极乐观、接近现实的，要起到立马鼓舞士气的作用。\u003c/p>\u003cp>积极的价值观是我们做事保持好状态的最大动力，如果找到了一件事情越多的正面价值，即使这是一件不顺心的事情，我们也会因为心中有目标和方向而克服万难。写下来（建议写2-3个，或者更多）\u003c/p>\u003cp>举例：\u003c/p>\u003cp>还是刚才我的那个例子，我可以这样来想：\u003c/p>\u003cp>我多次过级没有通过，这件事情也有积极的一面，因为.....\u003c/p>\u003cp>1、让我获得了多一次上台，锻炼自己、提升自己的机会。\u003c/p>\u003cp>2、使我清楚的意识到我的技能点还没有完全掌握。\u003c/p>\u003cp>3、可以有多一次被观察家点评的机会，让我加深对技能点的了解。\u003c/p>\u003cp>其实还有很多点，当我朝着积极的方面去想的时候，我发现自己情绪好了很多。\u003c/p>\u003cp>接着，拆页里讲到，找出最能帮助自己的意义，便可以把事情的价值改变。那我们的第三步：\u003c/p>\u003cp>第三步：找出最佳意义表达出来\u003c/p>\u003cp>找出最能接受的一句并将这一句反复念几遍并记住。这一句最好是让你读完心情非常舒服，精神振奋的，心中充满力量的。\u003c/p>\u003cp>有种“恩，对了，就是这样”的感觉。这个话术就是：某某事情，它也有积极的一面，因为......\u003c/p>\u003cp>举例：\u003c/p>\u003cp>刚才列出来的意义，我觉得让我情绪马上好转的积极点是：\u003c/p>\u003cp>让我获得了多一次上台，锻炼自己、提升自己的机会。\u003c/p>\u003cp>所以我可以这样来换框：我拆书过级没有通过，这件事情也有积极的一面，让我获得了多一次上台，锻炼自己、提升自己的机会。这样一换框，我的情绪很快就有了一个转变。\u003c/p>\u003cp>这个步骤和刚才的第二步是比较难的，但是却很关键，需要大家练习的时候静下心来，最好写下来分析。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>意义换框法可以应用在工作、生活、情感沟通等多个方面，这个方法适用于帮助有情绪困扰的个人暂时走出情绪困境，不能作为解决问题的最终方法。还有就是使用这个方法的前提是：这个人自己想改变，且情绪没有构成严重的心理问题。如果对方情绪问题严重，需要及时找专业人员进行沟通疏导。\u003c/p>","interaction":"\u003cp>A学习者拆为己用：学习者拆为己用：\u003c/p>\u003cp>技能点：【A3给出一个非常具体，确定的场景，学习者可在此场景中演练或讨论或应用新学技能】\u003c/p>\u003cp>为了能更好地理解和掌握“意义换框法”，我设计了一个场景，请小伙伴们根据我的场景编写一个剧本或是给出一个解决方案。\u003c/p>\u003cp>【场景】\u003c/p>\u003cp>最近，小丽找到好朋友小林倾诉，因为上司对小丽的工作非常挑剔、不满意，让她在工作的时候心惊胆战的，总是觉得自己哪里没有做好，也总觉得做不好事情，非常沮丧。\u003c/p>\u003cp>指令：1、先请大家在小组内花3分钟讨论一下，请大家参考我刚刚的步骤和话术来进行讨论，可以边讨论边写出事情的正面意义。\u003c/p>\u003cp>2、再根据我们刚才的分组，一人做小丽，一人做小林。小林需要利用意义换框法的三个步骤帮助小丽找到这个事情的正面意义，帮小丽走出情绪困境。然后花2分钟时间一人扮演小丽一人扮演小林来进行角色扮演。\u003c/p>\u003cp>这里要请大家注意我们训练的目的不是来解决场景中的问题，而是借用这个场景来练习意义换框法的三个步骤。\u003c/p>\u003cp>给大家5分钟，稍后我会请一组小伙伴上来和大家分享。\u003c/p>\u003cp>（5分钟过去后。。。中间要给学员做一些引导和互动）\u003c/p>\u003cp>好的，哪组小伙伴愿意来进行分享呢？邀请我们第一组伙伴。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>学习者森夏与Rick的分享：\u003c/p>\u003cp>运用意义换框三步法进行\u003c/p>\u003cp>森夏：小林，我最近心情很差，总觉得自己什么事都做不好，我的上司对我的工作很挑剔，我做这个也不满意，那个也不满意，搞的我上班心惊胆颤的，感觉连呼吸都是错的。\u003c/p>\u003cp>Rick：小丽，刚好我最近学习到一个方法，意义换框法，可以和你沟通分享一下。\u003c/p>\u003cp>森夏：好的好的。\u003c/p>\u003cp>Rick：想想让你非常不爽，非常沮丧的事情是什么？是因为什么事情导致你现在的情绪？\u003c/p>\u003cp>森夏：因为上司对我特别挑剔，所以我特别沮丧。\u003c/p>\u003cp>Rick：好的，那我们从另外一个角度来说，你的上司对你挑剔这个事情，有没有让你觉的好的一面的呢？比较正面的一面吗?把他记录写下来，写2-3个。\u003c/p>\u003cp>森夏：我觉得他挑剔我，如果说要有正面积极的一面，那是他对我要求很高了。\u003c/p>\u003cp>Rick:是的，思考一下这个事情背后，他存在的正面意义，上司挑剔你，是不是可以思考为：他对你要求比较高，挑剔你的地方刚好是你工作上确实没有做好的地方，你刚好可以有个提升，还有就是，他老挑剔你，是不是要找上司进行一个沟通了。\u003c/p>\u003cp>森夏：我也想了一下，确实他讲的很多地方也很有道理，可以改善一下自己的做事方式和思考的方式，还是非常有帮助的。\u003c/p>\u003cp>Rick：那很好啊，你自己好好梳理一下，哪一个是你觉得最好的正面意义\u003c/p>\u003cp>森夏：我觉得让自己的工做有很大的改善和提升\u003c/p>\u003cp>Rick：嗯嗯，是的，我们就可以将意义换框：上司挑剔我的工作，其实他也有正面积极的一面，可以让我的工作有一个改善和提升。\u003c/p>\u003cp>既然意识到了这一点，我们就可以去调整自己，然后马上行动起来。\u003c/p>\u003cp>森夏：嗯嗯， 是的，谢谢分享！\u003c/p>\u003cp>好的，谢谢两位精彩的分享，他们很好的运用了意愿换框法的三个步骤，去引导对方走出负面的情绪困境，帮助其提升，得到了一次与上司沟通交流，提升自己的机会。他们在分享的时候，有去找到这个事情的正面价值，上司挑剔我，可以让我提升的空间，改善思考方式，沟通方法的机会，非常好，谢谢!\u003c/p>\u003cp>技能点：【A2学习者可以根据指令，写出自己未来的一个具体的要做的应用，比如：某个特定任务、和人分享、事后复盘或找人陪练】\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>找人分享：\u003c/p>\u003cp>现在我来布置一个作业。\u003c/p>\u003cp>虽然我们刚才进行了演练，但是生活中类似的场景经常发生，需要我们不断的练习才能掌握这个方法。\u003c/p>\u003cp>现在请大家想想，在自己或朋友或家人碰到不顺心的事情时，利用意义换框法三步骤来引导，找到负面经验的正面意义，帮助自己或他人走出情绪困境。\u003c/p>\u003cp>假如回去后，你要将意义换框法分享给一个人\u003c/p>\u003cp>你最想分享给谁？请将姓名写下来\u003c/p>\u003cp>什么时间分享呢？\u003c/p>\u003cp>你会怎样去做意义换框呢？\u003c/p>\u003cp>请把你的答案写在问题空白处，我会请伙伴来分享，谢谢！写关键字就好。\u003c/p>\u003cp>学习者Rick分享：\u003c/p>\u003cp>下周一，在公司与同事小杨分享意义换框法，我会这样和他分享：\u003c/p>\u003cp>同事小杨最近情绪不是很好，与同事因为工作上的意见不合闹矛盾，关系比较差\u003c/p>\u003cp>首先，我会和他沟通，分享意义换框法：\u003c/p>\u003cp>第一步：让他确定使他情绪不好的具体事件是什么？因为和同事意见不合闹矛盾，所以他情绪非常郁闷\u003c/p>\u003cp>第二步：引导他思考，这个事情如果有正面积极的一面，他是什么呢？让他思考写下来2-3个。与同事意见不合，可以思考的是，同事的意见和想法也许也不错，可以多一个解决方案，同时也有一个反思自己沟通方式的机会，意见不合就有情绪，是否可以反思自己的情绪管理 也需要有一个调整。。。\u003c/p>\u003cp>第三步：根据分享和引导的内容，让他选出最佳的一句表达出来，最能让他缓解情绪的。让他进行意义换框\u003c/p>\u003cp>好的，谢谢Rick的分享！\u003c/p>\u003cp>结束语：\u003c/p>\u003cp>今天我分享的拆页就讲解到这里，我们学习了意义换框法，碰到负面经验时，想想如果这件事情对我来说是有正面价值的，会是什么呢？多想想这件事情的正面意义，负面情绪自然就减少了。\u003c/p>\u003cp>学习了这个方法后，我们要去练习和实践，在遇到负面经验的时候，真的可以帮助大家走出困境！\u003c/p>\u003cp>我是爱学习、爱分享的拆书家周周，再次感谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1640400453000,"updated_at":1640604589000,"ria":true},{"id":12753,"topic":"意义换框三步法","learn_goal":"","remark":"利用意义换框法走出情绪困境","level":"TF3-2","duration":25,"status":29,"type":0,"chaishujia":{"username":"紫珺","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>各位伙伴，大家下午好！我是拆书家周周，欢迎大家来到今天的拆书现场!\u003c/p>\u003cp>事件场景：\u003c/p>\u003cp>上周五下午，我的同事小兰报考了茶艺师，因为考试没有通过心情很是郁闷，觉得自己什么事都做不好，看到我就一副愁眉哭脸的样子。\u003c/p>\u003cp>提问：请问一下大家，考试没有通过这件事，是正面的还是负面的呢？\u003c/p>\u003cp>正面或者负面？\u003c/p>\u003cp>学习者A回答：我觉得是负面的，会影响到我们的情绪\u003c/p>\u003cp>学习者B回答：我认为是正面的，可以多一些时间准备，多复习一下。\u003c/p>\u003cp>好，很不错，是的，很多人理解的不一样。\u003c/p>\u003cp>同一件事情，有的人理解为可以接受，是正面的，有的人理解为不好接受，是负面的。所以，给事情赋予不同的意义，我们的情绪状态和处理方式也会不一样。\u003c/p>\u003cp>影响：\u003c/p>\u003cp>如果一个人经常把各种事情，习惯性的就想到他不好的一面，他会怎么样呢？\u003c/p>\u003cp>，会带来什么样的影响呢？\u003c/p>\u003cp>学习者回答：会变得很消极了，变成一个负面的人\u003c/p>\u003cp>嗯嗯，是的\u003c/p>\u003cp>如果长久这样下去，我们就会一直处于负面或者低落的情绪里面，导致工作越来越恶化，最终很难走出困境。\u003c/p>\u003cp>解决：但我们判断一件事情的价值或意义，大多是过去习惯性的认知。那该如何让我们能脱离认知习惯，从负面感受的事件中，看到他的正面意义或发现他的价值所在呢？\u003c/p>\u003cp>今天我介绍的李中莹老师的《重塑心灵》就可以帮到大家，这是一本关于研究大脑如何工作的书籍，它通过一些语言模式、思维模式的转变来改变我们的信念、价值系统，让我们能够多看到事情积极的一面。\u003c/p>\u003cp>【学习目标】：\u003c/p>\u003cp>通过今天的分享，学习者在面对负面感受的事件时，能够使用“意义换框法”的三个步骤，看到事件的正面意义或发现价值，避免负面感受带来的主观判断。\u003c/p>\u003cp>我们今天的学习过程中有分组练习，所以我们先进行一下分组，这边两位为第一组，这边为第二组，后面两位为第三组.\u003c/p>","ratings_count":1,"texts":[{"id":16694,"quote":"\u003cp>技能点：【把知识改编为量表自测题】\u003c/p>\u003cp>在此之前，我们先做一个小测试，看看我们目前处理负面感受的现状如何。\u003c/p>\u003cp>请大家花1分钟时间，对下面四种情况，以1—6分的标准给自己打分。1代表完全不符合，6代表完全符合。仔细阅读每一句话，根据自己的实际情况给自己打分，并在完成后核算一下总分。\u003c/p>\u003cp>题目评分\u003c/p>\u003cp>1完全不符合 6完全符合\u003c/p>\u003cp>1当我情绪低落时，我总能找到影响情绪的具体事件 123456\u003c/p>\u003cp>2当事情的结果不尽人意时，我总会去尝试寻找这件事情对我的价值 123456\u003c/p>\u003cp>3当不如意的结果困扰我时，我一般会将想到的这件事情的价值写下来 123456\u003c/p>\u003cp>4写下的这些好处与价值，我经常会选出最佳的大声念出来 123456\u003c/p>\u003cp>总分\u003c/p>\u003cp>【解释一下刚才量表自测题的意义】\u003c/p>\u003cp>好的，咱们一起来看看自测结果：\u003c/p>\u003cp>结果在20分以上的小伙伴请举手，20分以上的，说明你比较积极乐观，遇事总能很快想到积极的方法解决，自我调整能力非常强；\u003c/p>\u003cp>12到20分之间的请举手，这个分数阶段的小伙伴说明平时遇到事情有时候会积极，有时候会消极，自我调整能力较强，但是还可以继续提高一下；\u003c/p>\u003cp>有没有和我一样分数的，12分以下的小伙伴？\u003c/p>\u003cp>说明平时被负面情绪困扰时，不能很快的通过合适的技巧来进行处理。\u003c/p>\u003cp>不管大家的分数是怎样的，都只代表你现在的一个状态，我今天将教会一个技巧给大家。请大家花1分钟时间阅读一下原文片段：阅读完的伙伴可以抬头示意一下。谢谢！\u003c/p>\u003cp>技能点：【原书拆页R为Why或者What的内容,或原书的一个完整的案例】\u003c/p>\u003cp>原文拆页： 意义换框法\u003c/p>\u003cp>“意义换框法”是NLP技巧“换框法”中最常用和最好用的技巧。它完全只凭言语和思想模式而产生效果，是NLP的改变信念技巧中最快速最容易的一个。“意义换框法”是找出一个负面经验中的正面意义。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都只是人加诸的。既然是人加上去的意义，则一件事情——\u003c/p>\u003cp>可以有其他的意义，也可以有更多的意义；\u003c/p>\u003cp>可以有不好的意义，也可以有好的意义。\u003c/p>\u003cp>试想一下，当你用一块石头去锤打一颗钉子，或者赶走一只老鼠，你赋予这块石头的意义是什么？它本来有这些意义吗？再想一想，一块石头可以有多少用途？\u003c/p>\u003cp>把上面问题引出的意念放在别人的一句话、一个行为，甚至环境出现的一些情况上，会给你什么启示？\u003c/p>\u003cp>下次坐车没有事情做的时候，可以试想一想一只曲别针可以有多少用途。也许这样你会明白一件事情的意义只是取决于我们的主观思想。\u003c/p>\u003cp>同一件事情里面总有不止一个意义包含其中。找出最能帮助自己的意义，便可以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。（拆页结束~)\u003c/p>","explains":"\u003cp>技能点：【I讲解引导时，拆书家有进行简短互动，精准控场，还要举例子】\u003c/p>\u003cp>好的，大家都看完了拆页。\u003c/p>\u003cp>（简短互动）\u003c/p>\u003cp>请问一下大家，这个片段主要讲了什么？（意义换框法）\u003c/p>\u003cp>对，是意义换框法。\u003c/p>\u003cp>原文中解释意义换框法的是哪句话呢？（找出负面经验中的正面意义）\u003c/p>\u003cp>对，找出负面经验中的正面意义。\u003c/p>\u003cp>负面经验也就是不如意的事情，任何事情都有好的意义和不好的意义。意义换框法就是，对于本来有不好意义的事情换成可以帮助自己的正面意义，把这件事情的价值改变一下，我们的情绪和处理问题的方式也就跟着变得正面了。\u003c/p>\u003cp>【How步骤】：\u003c/p>\u003cp>那我们如何使用意义换框法呢？结合我们的拆页内容得出步骤：找出一个负面经验中的正面意义：所以我们的\u003c/p>\u003cp>第一步：找负面情绪的具体事件\u003c/p>\u003cp>将所面临的问题用“因为某某事情，所以我感觉怎么样”的句式表达出来。\u003c/p>\u003cp>感觉出来负面情绪其实就是给事情赋予了负面意义。\u003c/p>\u003cp>举例：\u003c/p>\u003cp>比如上个月我拆书过2-4的时候，拆了4次都没有通过，当时的心情非常的沮丧，情绪也比较低落。\u003c/p>\u003cp>我想请问下大家，这个情景我们用因果句式可以怎么表示呢？（学习者回答。。。）\u003c/p>\u003cp>对，我们可以表示成：\u003c/p>\u003cp>因为拆书过级4次都没有通过，所以我感觉很沮丧。\u003c/p>\u003cp>然后刚才拆页里讲到，同一个事情总有不止一个意义包含其中，那我们就把多个意义找出来。\u003c/p>\u003cp>第二步：思考这件事情的正面价值，写下来\u003c/p>\u003cp>接着第一步里面提到的负面情绪的事件，我们来反复思考“如果这件事情对我来说是有正面价值的，会是什么呢？”可以换成：某某事情也是有积极的一面，因为。。。。。注意：这些价值一定要是积极乐观、接近现实的，要起到立马鼓舞士气的作用。\u003c/p>\u003cp>积极的价值观是我们做事保持好状态的最大动力，如果找到了一件事情越多的正面价值，即使这是一件不顺心的事情，我们也会因为心中有目标和方向而克服万难。写下来（建议写2-3个，或者更多）\u003c/p>\u003cp>举例：\u003c/p>\u003cp>还是刚才我的那个例子，我可以这样来想：\u003c/p>\u003cp>我多次过级没有通过，这件事情也有积极的一面，因为.....\u003c/p>\u003cp>1、让我获得了多一次上台，锻炼自己、提升自己的机会。\u003c/p>\u003cp>2、使我清楚的意识到我的技能点还没有完全掌握。\u003c/p>\u003cp>3、可以有多一次被观察家点评的机会，让我加深对技能点的了解。\u003c/p>\u003cp>其实还有很多点，当我朝着积极的方面去想的时候，我发现自己情绪好了很多。\u003c/p>\u003cp>接着，拆页里讲到，找出最能帮助自己的意义，便可以把事情的价值改变。那我们的第三步：\u003c/p>\u003cp>第三步：找出最佳意义表达出来\u003c/p>\u003cp>找出最能接受的一句并将这一句反复念几遍并记住。这一句最好是让你读完心情非常舒服，精神振奋的，心中充满力量的。\u003c/p>\u003cp>有种“恩，对了，就是这样”的感觉。这个话术就是：某某事情，它也有积极的一面，因为......\u003c/p>\u003cp>举例：\u003c/p>\u003cp>刚才列出来的意义，我觉得让我情绪马上好转的积极点是：\u003c/p>\u003cp>让我获得了多一次上台，锻炼自己、提升自己的机会。\u003c/p>\u003cp>所以我可以这样来换框：我拆书过级没有通过，这件事情也有积极的一面，让我获得了多一次上台，锻炼自己、提升自己的机会。这样一换框，我的情绪很快就有了一个转变。\u003c/p>\u003cp>这个步骤和刚才的第二步是比较难的，但是却很关键，需要大家练习的时候静下心来，最好写下来分析。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>意义换框法可以应用在工作、生活、情感沟通等多个方面，这个方法适用于帮助有情绪困扰的个人暂时走出情绪困境，不能作为解决问题的最终方法。还有就是使用这个方法的前提是：这个人自己想改变，且情绪没有构成严重的心理问题。如果对方情绪问题严重，需要及时找专业人员进行沟通疏导。\u003c/p>","interaction":"\u003cp>技能点：【A3给出一个非常具体，确定的场景，学习者可在此场景中演练或讨论或应用新学技能】\u003c/p>\u003cp>为了能更好地理解和掌握“意义换框法”，我设计了一个场景，请小伙伴们根据我的场景编写一个剧本或是给出一个解决方案。\u003c/p>\u003cp>【场景】\u003c/p>\u003cp>最近，小丽找到好朋友小林倾诉，因为上司对小丽的工作非常挑剔、不满意，让她在工作的时候心惊胆战的，总是觉得自己哪里没有做好，也总觉得做不好事情，非常沮丧。\u003c/p>\u003cp>指令：1、先请大家在小组内花3分钟讨论一下，请大家参考我刚刚的步骤和话术来进行讨论，可以边讨论边写出事情的正面意义。\u003c/p>\u003cp>2、再根据我们刚才的分组，一人做小丽，一人做小林。小林需要利用意义换框法的三个步骤帮助小丽找到这个事情的正面意义，帮小丽走出情绪困境。然后花2分钟时间一人扮演小丽一人扮演小林来进行角色扮演。\u003c/p>\u003cp>这里要请大家注意我们训练的目的不是来解决场景中的问题，而是借用这个场景来练习意义换框法的三个步骤。\u003c/p>\u003cp>给大家5分钟，稍后我会请一组小伙伴上来和大家分享。\u003c/p>\u003cp>（5分钟过去后。。。中间要给学员做一些引导和互动）\u003c/p>\u003cp>好的，哪组小伙伴愿意来进行分享呢？邀请我们第三组伙伴。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>学习者化蝶与品玲分享：\u003c/p>\u003cp>运用意义换框三步法进行\u003c/p>\u003cp>化蝶：最近心情不好，很不开心，工作上遇到了一些问题，昨天没有及时提醒我们的咨询师，来访者没有提前预约，让他工作衔接出现了一些问题，我心里很自责难受，觉得自己什么都做不好。\u003c/p>\u003cp>品玲：哦，这个事情发生后让你非常自责和愧疚，那我们来想想这个事情会给我们带来一些什么正面的影响呢？会有什么积极的一面呢？\u003c/p>\u003cp>化蝶：嗯嗯，是的，这个事情发生了，其实，他也有正面积极的一面。1、他让我明白，即使没有来访者，也让我明白咨询不是一次就能完成的，还有对于我以后成为一名咨询师也是很有帮助的。2、我当时的情绪不好，这也是一个让我看见自己情绪的一个办法，如何让自己走出这个情绪。这让我有了一次经历情绪处理情绪的机会。\u003c/p>\u003cp>品玲：我能看到你接纳自己，理解自己，在自己负面情绪的背后知道了自己哪里提升做的更好，让自己以后成为一个专业的心理咨询师，了解了以后如果去和来访者沟通，如何去处理情绪等相关内容，是吗？\u003c/p>\u003cp>化蝶：是的，让自己知道了很多。\u003c/p>\u003cp>品玲：好的，在这些积极的一些内容里面，哪一个最能让你缓解此刻的情绪，能最佳的表达出来的，是哪一点呢?\u003c/p>\u003cp>化蝶：嗯，让我有机会看见情绪走出情绪，因为没有处理好工作上的事情，导致心情沮丧，其实他也有正面积极的一面，让我有机会看见自己的情绪，走出情绪。\u003c/p>\u003cp>品玲：嗯嗯，很好。以后再遇到这样的情况，我们也能很好的处理解决\u003c/p>\u003cp>化蝶：是的，以后即使我犯错了，我也能积极的走出情绪。\u003c/p>\u003cp>品玲：好的，非常不错！\u003c/p>\u003cp>好的，谢谢两位精彩的分享，她们很好的运用了意愿换框法的三个步骤，去引导对方走出负面的情绪困境，帮助其提升，得到了一次处理情绪提升自己的机会。非常好，谢谢!\u003c/p>\u003cp>技能点：【A2学习者可以根据指令，写出自己未来的一个具体的要做的应用，比如：某个特定任务、和人分享、事后复盘或找人陪练】\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>找人分享：\u003c/p>\u003cp>现在我来布置一个作业。\u003c/p>\u003cp>虽然我们刚才进行了演练，但是生活中类似的场景经常发生，需要我们不断的练习才能掌握这个方法。\u003c/p>\u003cp>现在请大家想想，在自己或朋友或家人碰到不顺心的事情时，利用意义换框法三步骤来引导，找到负面经验的正面意义，帮助自己\u003c/p>\u003cp>他人走出情绪困境。\u003c/p>\u003cp>假如回去后，你要将意义换框法分享给一个人\u003c/p>\u003cp>你最想分享给谁？请将姓名写下来\u003c/p>\u003cp>什么时间分享呢？\u003c/p>\u003cp>你会怎样去做意义换框呢？\u003c/p>\u003cp>请把你的答案写在问题空白处，我会请伙伴来分享，谢谢！写关键字就好。\u003c/p>\u003cp>学习者王静雯分享：\u003c/p>\u003cp>我回去之后就会和我的好朋友小林分享，明天分享给他，因为最近小林和我反馈，家里人对他管束太多了，导致他们的关系不太好，也经常影响他的情绪。我计划用意义换框法去引导他与他沟通，帮他分析一下这个事情的正面价值。找出最积极的意义去进行表达，帮助他走出情绪困境。\u003c/p>\u003cp>对话补充：\u003c/p>\u003cp>静雯：我会和好朋友小林进行分享：小林，你最近因为家人对你的管束太多，导致你的情绪情绪不好，我学习到一个方法分享给你，可以帮助你走出情绪困境。\u003c/p>\u003cp>小林：好的，快和我分享一下，是什么方法！\u003c/p>\u003cp>静雯：给你介绍的方法是意义换框法，你情绪不好是什么原因呢？\u003c/p>\u003cp>第一步：找出负面情绪的具体事情，因为家里人对你的管束太多了，所以你感觉很不开心。\u003c/p>\u003cp>第二步：思考这件事情的正面价值，写下来，你想想，父母管束你太多，其实这件事情也有他积极的一面。那这件事情有什么正面价值呢？\u003c/p>\u003cp>小林思考：\u003c/p>\u003cp>1、可以让父母知道自己的情况，减少他们的担心，\u003c/p>\u003cp>2、如果自己觉得反感，可以反思自己以后做了父母，要适当的管束自己的孩子。\u003c/p>\u003cp>3、父母管束我，我就情绪不好，反映出平时家庭关系与沟通还有很大的提升空间。\u003c/p>\u003cp>第三步：找出最佳意义表达出来，小林你看看你刚才思考的正面价值，哪一句是你认为最重要的，多念几遍大声读出来。\u003c/p>\u003cp>小林：嗯嗯，可以让父母知道自己的近况，减少他们的担心。父母对我管束较多，其实这件事情也有他积极的一面。可以让父母了解自己的情况，减少他们的担心。\u003c/p>\u003cp>静雯：对啊，其实有家人的关心和管束，是一件很幸福的事情呢。\u003c/p>\u003cp>好的，谢谢静雯的分享，很好的使用了我们意义换框法的三步骤！\u003c/p>\u003cp>结束语：\u003c/p>\u003cp>今天我分享的拆页就讲解到这里，我们学习了意义换框法，碰到负面经验时，想想如果这件事情对我来说是有正面价值的，会是什么呢？多想想这件事情的正面意义，负面情绪自然就减少了。\u003c/p>\u003cp>学习了这个方法后，我们要去练习和实践，在遇到负面经验的时候，真的可以帮助大家走出困境！\u003c/p>\u003cp>我是爱学习、爱分享的拆书家周周，再次感谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1638702031000,"updated_at":1639544744000,"ria":true},{"id":12737,"topic":"意义换框法（第一次）","learn_goal":"","remark":"通过意义换框法，让学习者在面对负面感受的事情时，能看到事件的正面意义或价值。","level":"TF3-2","duration":25,"status":29,"type":0,"chaishujia":{"username":"紫珺","city":"深圳市"},"club":{"name":"深圳智荟分舵","city":"深圳"},"prologue":"\u003cp>各位伙伴，大家下午好！我是拆书家周周，欢迎大家来到今天的拆书现场!\u003c/p>\u003cp>\u003cstrong>事件场景\u003c/strong>：\u003c/p>\u003cp>上周五下午，我的同事小兰报考了茶艺师，因为考试没有通过心情很是郁闷，觉得自己什么事都做不好，看到我就一副愁眉哭脸的样子。\u003c/p>\u003cp>\u003cstrong>提问：\u003c/strong>请问一下大家，考试没有通过这件事，是正面的还是负面的呢？\u003c/p>\u003cp>正面或者负面？\u003c/p>\u003cp>学习者A回答：我觉得是负面的，会影响到我们的情绪\u003c/p>\u003cp>学习者B回答：我认为是正面的，可以多一些时间准备，多复习一下。\u003c/p>\u003cp>好，很不错，是的，很多人理解的不一样。\u003c/p>\u003cp>同一件事情，有的人理解为可以接受，是正面的，有的人理解为不好接受，是负面的。所以，给事情赋予不同的意义，我们的情绪状态和处理方式也会不一样。\u003c/p>\u003cp>\u003cstrong>影响\u003c/strong>：\u003c/p>\u003cp>如果一个人经常把各种事情，习惯性的就想到他不好的一面，他会怎么样呢？\u003c/p>\u003cp>，会带来什么样的影响呢？\u003c/p>\u003cp>学习者回答：会变得很消极了，变成一个负面的人\u003c/p>\u003cp>嗯嗯，是的\u003c/p>\u003cp>如果长久这样下去，我们就会一直处于负面或者低落的情绪里面，导致工作越来越恶化，最终很难走出困境。\u003c/p>\u003cp>\u003cstrong>解决：\u003c/strong>但我们判断一件事情的价值或意义，大多是过去习惯性的认知。那该如何让我们能脱离认知习惯，从负面感受的事件中，看到他的正面意义或发现他的价值所在呢？\u003c/p>\u003cp>今天我介绍的李中莹老师的《重塑心灵》就可以帮到大家，这是一本关于研究大脑如何工作的书籍，它通过一些语言模式、思维模式的转变来改变我们的信念、价值系统，让我们能够多看到事情积极的一面。\u003c/p>\u003cp>\u003cstrong>【学习目标】\u003c/strong>：\u003c/p>\u003cp>通过今天的分享，学习者在面对负面感受的事件时，能够使用“意义换框法”的三个步骤，看到事件的正面意义或发现价值，避免负面感受带来的主观判断。\u003c/p>\u003cp>我们今天的学习过程中有分组练习，所以我们先进行一下分组，这边两位为第一组，这边为第二组，后面两位为第三组.\u003c/p>","ratings_count":1,"texts":[{"id":16676,"quote":"\u003cp>\u003cstrong>技能点：【把知识改编为量表自测题】\u003c/strong>\u003c/p>\u003cp>在此之前，我们先做一个小测试，看看我们目前处理负面感受的现状如何。\u003c/p>\u003cp>请大家花1分钟时间，对下面四种情况，以1—6分的标准给自己打分。1代表完全不符合，6代表完全符合。仔细阅读每一句话，根据自己的实际情况给自己打分，并在完成后核算一下总分。\u003c/p>\u003cp>\u003cstrong>题目\u003c/strong>\u003c/p>\u003cp>\u003cstrong>评分\u003c/strong>\u003c/p>\u003cp>\u003cstrong>1完全不符合\u003c/strong> 6\u003cstrong>完全符合\u003c/strong>\u003c/p>\u003cp>1当我情绪低落时，我总能找到影响情绪的具体事件 123456\u003c/p>\u003cp>2当事情的结果不尽人意时，我总会去尝试寻找这件事情对我的价值 123456\u003c/p>\u003cp>3当不如意的结果困扰我时，我一般会将想到的这件事情的价值写下来 123456\u003c/p>\u003cp>4写下的这些好处与价值，我经常会选出最佳的大声念出来 123456\u003c/p>\u003cp>\u003cstrong>总分\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【解释一下刚才量表自测题的意义】\u003c/strong>\u003c/p>\u003cp>好的，咱们一起来看看自测结果：\u003c/p>\u003cp>结果在20分以上的小伙伴请举手，20分以上的，说明你比较积极乐观，遇事总能很快想到积极的方法解决，自我调整能力非常强；\u003c/p>\u003cp>12到20分之间的请举手，这个分数阶段的小伙伴说明平时遇到事情有时候会积极，有时候会消极，自我调整能力较强，但是还可以继续提高一下；\u003c/p>\u003cp>有没有和我一样分数的，12分以下的小伙伴？\u003c/p>\u003cp>说明平时被负面情绪困扰时，不能很快的通过合适的技巧来进行处理。\u003c/p>\u003cp>不管大家的分数是怎样的，都只代表你现在的一个状态，我今天将教会一个技巧给大家。请大家花1分钟时间阅读一下原文片段：阅读完的伙伴可以抬头示意一下。谢谢！\u003c/p>\u003cp>\u003cstrong>技能点：【原书拆页R为Why或者What的内容,或原书的一个完整的案例】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>原文拆页：\u003c/strong> \u003cstrong>意义换框法\u003c/strong>\u003c/p>\u003cp>“意义换框法”是NLP技巧“换框法”中最常用和最好用的技巧。它完全只凭言语和思想模式而产生效果，是NLP的改变信念技巧中最快速最容易的一个。\u003cstrong>“意义换框法”是找出一个负面经验中的正面意义\u003c/strong>。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都只是人加诸的。既然是人加上去的意义，则一件事情——\u003c/p>\u003cp>可以有其他的意义，也可以有更多的意义；\u003c/p>\u003cp>可以有不好的意义，也可以有好的意义。\u003c/p>\u003cp>试想一下，当你用一块石头去锤打一颗钉子，或者赶走一只老鼠，你赋予这块石头的意义是什么？它本来有这些意义吗？再想一想，一块石头可以有多少用途？ \u003c/p>\u003cp>把上面问题引出的意念放在别人的一句话、一个行为，甚至环境出现的一些情况上，会给你什么启示？\u003c/p>\u003cp>下次坐车没有事情做的时候，可以试想一想一只曲别针可以有多少用途。也许这样你会明白一件事情的意义只是取决于我们的主观思想。\u003c/p>\u003cp>同一件事情里面总有不止一个意义包含其中。找出最能帮助自己的意义，便可以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。（拆页结束~）\u003c/p>","explains":"\u003cp>\u003cstrong>技能点：【I讲解引导时，拆书家有进行简短互动，精准控场，还要举例子】\u003c/strong>\u003c/p>\u003cp>好的，大家都看完了拆页。\u003c/p>\u003cp>（简短互动）\u003c/p>\u003cp>\u003cstrong>请问一下大家，这个片段主要讲了什么？\u003c/strong>（意义换框法）\u003c/p>\u003cp>对，是意义换框法。\u003c/p>\u003cp>\u003cstrong>原文中解释意义换框法的是哪句话呢？\u003c/strong>（找出负面经验中的正面意义）\u003c/p>\u003cp>对，找出负面经验中的正面意义。\u003c/p>\u003cp>负面经验也就是不如意的事情，任何事情都有好的意义和不好的意义。意义换框法就是，对于本来有不好意义的事情换成可以帮助自己的正面意义，把这件事情的价值改变一下，我们的情绪和处理问题的方式也就跟着变得正面了。\u003c/p>\u003cp>【How步骤】：\u003c/p>\u003cp>那我们如何使用意义换框法呢？结合我们的拆页内容得出步骤：找出一个负面经验中的正面意义：所以我们的\u003c/p>\u003cp>\u003cstrong>第一步：找负面情绪的具体事件\u003c/strong>\u003c/p>\u003cp>将所面临的问题用“因为某某事情，所以我感觉怎么样”的句式表达出来。\u003c/p>\u003cp>感觉出来负面情绪其实就是给事情赋予了负面意义。\u003c/p>\u003cp>\u003cstrong>举例：\u003c/strong>\u003c/p>\u003cp>比如上个月我拆书过2-4的时候，拆了4次都没有通过，当时的心情非常的沮丧，情绪也比较低落。\u003c/p>\u003cp>我想请问下大家，这个情景我们用因果句式可以怎么表示呢？（学习者回答。。。）\u003c/p>\u003cp>对，我们可以表示成：\u003c/p>\u003cp>因为拆书过级4次都没有通过，所以我感觉很沮丧。\u003c/p>\u003cp>然后刚才拆页里讲到，同一个事情总有不止一个意义包含其中，那我们就把多个意义找出来。\u003c/p>\u003cp>\u003cstrong>第二步：思考这件事情的正面价值，写下来\u003c/strong>\u003c/p>\u003cp>接着第一步里面提到的负面情绪的事件，我们来反复思考“如果这件事情对我来说是有正面价值的，会是什么呢？”可以换成：某某事情也是有积极的一面，因为。。。。。注意：这些价值一定要是积极乐观、接近现实的，要起到立马鼓舞士气的作用。\u003c/p>\u003cp>积极的价值观是我们做事保持好状态的最大动力，如果找到了一件事情越多的正面价值，即使这是一件不顺心的事情，我们也会因为心中有目标和方向而克服万难。写下来（建议写2-3个，或者更多）\u003c/p>\u003cp>\u003cstrong>举例：\u003c/strong>\u003c/p>\u003cp>还是刚才我的那个例子，我可以这样来想：\u003c/p>\u003cp>我多次过级没有通过，这件事情也有积极的一面，因为.....\u003c/p>\u003cp>1、让我获得了多一次上台，锻炼自己、提升自己的机会。\u003c/p>\u003cp>2、使我清楚的意识到我的技能点还没有完全掌握。\u003c/p>\u003cp>3、可以有多一次被观察家点评的机会，让我加深对技能点的了解。\u003c/p>\u003cp>其实还有很多点，当我朝着积极的方面去想的时候，我发现自己情绪好了很多。\u003c/p>\u003cp>接着，拆页里讲到，找出最能帮助自己的意义，便可以把事情的价值改变。那我们的第三步：\u003c/p>\u003cp>\u003cstrong>第三步：找出最佳意义表达出来\u003c/strong>\u003c/p>\u003cp>找出最能接受的一句并将这一句反复念几遍并记住。这一句最好是让你读完心情非常舒服，精神振奋的，心中充满力量的。\u003c/p>\u003cp>有种“恩，对了，就是这样”的感觉。这个话术就是：某某事情，它也有积极的一面，因为......\u003c/p>\u003cp>\u003cstrong>举例：\u003c/strong>\u003c/p>\u003cp>刚才列出来的意义，我觉得让我情绪马上好转的积极点是：\u003c/p>\u003cp>让我获得了多一次上台，锻炼自己、提升自己的机会。\u003c/p>\u003cp>所以我可以这样来换框：我拆书过级没有通过，这件事情也有积极的一面，让我获得了多一次上台，锻炼自己、提升自己的机会。这样一换框，我的情绪很快就有了一个转变。\u003c/p>\u003cp>这个步骤和刚才的第二步是比较难的，但是却很关键，需要大家练习的时候静下心来，最好写下来分析。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>\u003c/p>\u003cp>意义换框法可以应用在工作、生活、情感沟通等多个方面，这个方法适用于帮助有情绪困扰的个人暂时走出情绪困境，不能作为解决问题的最终方法。还有就是使用这个方法的前提是：这个人自己想改变，且情绪没有构成严重的心理问题。如果对方情绪问题严重，需要及时找专业人员进行沟通疏导。\u003c/p>","interaction":"\u003cp>\u003cstrong>技能点：【A3给出一个非常具体，确定的场景，学习者可在此场景中演练或讨论或应用新学技能】\u003c/strong>\u003c/p>\u003cp>为了能更好地理解和掌握“意义换框法”，我设计了一个场景，请小伙伴们根据我的场景编写一个剧本或是给出一个解决方案。\u003c/p>\u003cp>【场景】\u003c/p>\u003cp>最近，小丽找到好朋友小林倾诉，因为上司对小丽的工作非常挑剔、不满意，让她在工作的时候心惊胆战的，总是觉得自己哪里没有做好，也总觉得做不好事情，非常沮丧。\u003c/p>\u003cp>\u003cstrong>指令\u003c/strong>：1、先请大家在小组内花3分钟讨论一下，请大家参考我刚刚的步骤和话术来进行讨论，可以边讨论边写出事情的正面意义。\u003c/p>\u003cp>2、再根据我们刚才的分组，一人做小丽，一人做小林。小林需要利用意义换框法的三个步骤帮助小丽找到这个事情的正面意义，帮小丽走出情绪困境。然后花2分钟时间一人扮演小丽一人扮演小林来进行角色扮演。\u003c/p>\u003cp>这里要请大家注意我们训练的目的不是来解决场景中的问题，而是借用这个场景来练习意义换框法的三个步骤。\u003c/p>\u003cp>给大家5分钟，稍后我会请一组小伙伴上来和大家分享。\u003c/p>\u003cp>（5分钟过去后。。。中间要给学员做一些引导和互动）\u003c/p>\u003cp>好的，哪组小伙伴愿意来进行分享呢？邀请我们第三组伙伴。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>学习者化蝶与品玲分享：\u003c/p>\u003cp>运用意义换框三步法进行\u003c/p>\u003cp>\u003cstrong>化蝶\u003c/strong>：最近心情不好，很不开心，工作上遇到了一些问题，昨天没有及时提醒我们的咨询师，来访者没有提前预约，让他工作衔接出现了一些问题，我心里很自责难受，觉得自己什么都做不好。\u003c/p>\u003cp>\u003cstrong>品玲\u003c/strong>：哦，这个事情发生后让你非常自责和愧疚，那我们来想想这个事情会给我们带来一些什么正面的影响呢？会有什么积极的一面呢？\u003c/p>\u003cp>\u003cstrong>化蝶\u003c/strong>：嗯嗯，是的，这个事情发生了，其实，他也有正面积极的一面。1、他让我明白，即使没有来访者，也让我明白咨询不是一次就能完成的，还有对于我以后成为一名咨询师也是很有帮助的。2、我当时的情绪不好，这也是一个让我看见自己情绪的一个办法，如何让自己走出这个情绪。这让我有了一次经历情绪处理情绪的机会。\u003c/p>\u003cp>\u003cstrong>品玲\u003c/strong>：我能看到你接纳自己，理解自己，在自己负面情绪的背后知道了自己哪里提升做的更好，让自己以后成为一个专业的心理咨询师，了解了以后如果去和来访者沟通，如何去处理情绪等相关内容，是吗？\u003c/p>\u003cp>\u003cstrong>化蝶\u003c/strong>：是的，让自己知道了很多。\u003c/p>\u003cp>\u003cstrong>品玲\u003c/strong>：好的，在这些积极的一些内容里面，哪一个最能让你缓解此刻的情绪，能最佳的表达出来的，是哪一点呢?\u003c/p>\u003cp>\u003cstrong>化蝶\u003c/strong>：嗯，让我有机会看见情绪走出情绪，因为没有处理好工作上的事情，导致心情沮丧，其实他也有正面积极的一面，让我有机会看见自己的情绪，走出情绪。\u003c/p>\u003cp>\u003cstrong>品玲\u003c/strong>：嗯嗯，很好。以后再遇到这样的情况，我们也能很好的处理解决\u003c/p>\u003cp>\u003cstrong>化蝶：\u003c/strong>是的，以后即使我犯错了，我也能积极的走出情绪。\u003c/p>\u003cp>\u003cstrong>品玲\u003c/strong>：好的，非常不错！\u003c/p>\u003cp>好的，谢谢两位精彩的分享，她们很好的运用了意愿换框法的三个步骤，去引导对方走出负面的情绪困境，帮助其提升，得到了一次处理情绪提升自己的机会。非常好，谢谢!\u003c/p>\u003cp>\u003cstrong>技能点：【A2学习者可以根据指令，写出自己未来的一个具体的要做的应用，比如：某个特定任务、和人分享、事后复盘或找人陪练】\u003c/strong>\u003c/p>\u003cp>【A2催化应用】\u003c/p>\u003cp>\u003cstrong>找人分享\u003c/strong>：\u003c/p>\u003cp>现在我来布置一个作业。\u003c/p>\u003cp>虽然我们刚才进行了演练，但是生活中类似的场景经常发生，需要我们不断的练习才能掌握这个方法。\u003c/p>\u003cp>现在请大家想想，在自己或朋友或家人碰到不顺心的事情时，利用意义换框法三步骤来引导，找到负面经验的正面意义，帮助自己或他人走出情绪困境。\u003c/p>\u003cp>假如回去后，你要将意义换框法分享给一个人\u003c/p>\u003cp>你最想分享给谁？请将姓名写下来\u003c/p>\u003cp>什么时间分享呢？ \u003c/p>\u003cp>你会怎样去做意义换框呢？\u003c/p>\u003cp>请把你的答案写在问题空白处，我会请伙伴来分享，谢谢！写关键字就好。\u003c/p>\u003cp>学习者\u003cstrong>王静雯\u003c/strong>分享：\u003c/p>\u003cp>我回去之后就会和我的好朋友分享，明天分享给他，因为家里人对他管束太多了，导致他们的关系不太好，也经常影响他的情绪，我计划用意义换框法去引导他与他沟通，帮他分析一下这个事情的正面价值。找出最积极的意义去进行表达，帮助他走出情绪困境。\u003c/p>\u003cp>好的，谢谢静雯的分享！\u003c/p>\u003cp>（邀请学习者进行分享，并回馈）\u003c/p>\u003cp>\u003cstrong>结束语：\u003c/strong>\u003c/p>\u003cp>今天我分享的拆页就讲解到这里，我们学习了意义换框法，碰到负面经验时，想想如果这件事情对我来说是有正面价值的，会是什么呢？多想想这件事情的正面意义，负面情绪自然就减少了。\u003c/p>\u003cp>学习了这个方法后，我们要去练习和实践，在遇到负面经验的时候，真的可以帮助大家走出困境！\u003c/p>\u003cp>我是爱学习、爱分享的拆书家周周，再次感谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1638407907000,"updated_at":1638588091000,"ria":true},{"id":11442,"topic":"改变信念系统的技巧-价值定位法","learn_goal":"","remark":"希望大家在跟我现场学习和互动后： 能够帮助你在意识和潜意识两个层面去客观分析，根据内心真实需求，做出有效选择 。\n内容简要：一个人做或者不做任何事，都是由他的价值观决定的，而价值观也是被意识和潜意识共同影响的，但人们决定做事前，大多只是从意识层面去思考要不要去做，而忽略了潜意识层面的思考，所以到最后事情的执行力就会不如人意。通过这个片段就可以帮找出意识和潜意识层面的真实需求。\n","level":"TF2-1","duration":20,"status":19,"type":0,"chaishujia":{"username":"宋佳嶶","city":"哈尔滨市"},"club":{"name":"哈尔滨索菲亚分舵","city":"哈尔滨"},"prologue":"\u003cp>拆书成长，悦享人生！大家好，我是宋佳嶶。首先三个标签介绍一下我自己，第一个标签拆书帮哈尔滨索菲亚分舵的一级拆书家，第二个标签向阳花爱心公益团队财务负责人，第三个标签NLP内容学习者。\u003c/p>\u003cp>\u003cstrong>F特征： （Feature），核心是“书”，用于满足好奇心\u003c/strong>\u003c/p>\u003cp>我今天带来的这本书是李中莹老师的《重塑心灵》，他也是最早把NLP完整地介绍到国内，被誉为“华人世界的国际级NLP大师”，书中从信念系统、沟通方式、情绪管理等多个方面讲述了主动获得成功快乐的人生方法。\u003c/p>\u003cp> \u003cstrong>A优势：（Advantage）,重点是“比较”，用于建立安全感\u003c/strong>\u003c/p>\u003cp> 这本书也可以作为，每一位想学习NLP知识的入门书籍，这本书的优势在于，他比其他NLP心理学书籍，更加注重灵活性和实用性。对于书中的不同技巧都有清晰的步骤，可以帮组我们直接用在生活和学习中。 \u003c/p>\u003cp> \u003cstrong>B利益：\u003c/strong> \u003cstrong>（Benefit）强调的是“你（学习者）”，用于引发兴趣\u003c/strong>\u003c/p>\u003cp>你是否在生活中，总会听到自己或是别人这样的声音“我肯定不行。”“别人为什么就不理解我那？” 其实这是个人的信念系统、沟通方式等出现了问题。阅读过后可以让你从多个角度去看问题，不在纠结和自我否定。 今天我给大家分享的片段就是《价值定位法》。\u003c/p>\u003cp>在跟随我完成本次RIA现场学习后，学习者在遇到意识层面和潜意思层面之间产生矛盾时，能够通过自我潜意识层面反思，找到内心的真实想法，可以根据内心真实的需求，做出行之有效的选择\u003c/p>\u003cp>今天我们只有4个人，就先不分组了。 下面请大家花2分钟时间阅读下拆页，阅读完后，大家举手示意下。 \u003c/p>","ratings_count":1,"texts":[{"id":15365,"quote":"\u003cp>\u003cstrong>技能：请学习者阅读拆页\u003c/strong>\u003c/p>\u003cp>主题：改变信念系统的技巧-价值定位法\u003c/p>\u003cp>第二章 《信念系统之改变信念系统的技巧》  P55-56 《价值定位法》\u003c/p>\u003cp>一个人对某一件事情的价值观，即是希望该件事给他的各项价值，需要按大小轻重做出排列。但是他的意识和潜意识，常常有不一样的排列。意识的价值观，可以因为环境因素受到其他人的影响，或者通过自我思考而修正；而潜意识的价值观，受到内心深层的一些因素的操控（包括系统层次。身份层次和一些重大的信念），往往会与意识的排列不同。意识与潜意识的价值排列差异越大，这个人的内心矛盾和无力感会越大。“价值定位法”能帮助一个人找出潜意识里的价值排列。\u003c/p>\u003cp>首先我们要学会如何凭询问找出受导者对某一件事的价值观，以“找工作”为例，\u003c/p>\u003cp>首先，用这样的文字询问每个问题， 一份理想的工作…… 因为询问的目的是找出受导者的主观价值，符合他的主观价值的，就是他认为理想的。\u003c/p>\u003cp>第二，询问四个问题“什么最重要？” “能够带给你些什么”“凭他，你可以得到什么？”\u003c/p>\u003cp>“你最在乎的是什么？”将四个问题补充完整就是：\u003c/p>\u003cp>“在一份理想的工作中，什么最重要”\u003c/p>\u003cp>“一份理想的工作能够带给你些什么？”“凭着一份理想的工作，你可以得到些什么？”“在一份理想的工作里，你最在乎的是什么？”\u003c/p>\u003cp>这四个问题就像是一间木屋的四扇窗子，每一扇窗子都能让人看到里面的东西，但不是全部，且从四扇窗子里分别看到的东西会有不同的。如果一个人对某一问题不太清楚，回答有困难，可以 改变下一个问题，也可以在这个问题以后回答他：“还有呢？”使得受导者说出更多的价值。\u003c/p>\u003cp>第三，如果这个人的回答是一些感觉的词，例如快乐、开心、成功感、满足感等，辅导者必须问他：“有什么情况出现，你便会有这份……（感觉的字）？”\u003c/p>\u003cp>最后要注意的是，这个人最先说出来的，并不一定就是对他最重要的价值。\u003c/p>\u003cp>应该用上述的询问方式，找出四五个价值写下，让这个人看着他们，然后说出哪个最重要，并排列出次序。\u003c/p>\u003cp>一个人做或者不做任何事，都是由他的价值观所看控制。一个人很容易认识到自己意识层面对某件事的价值排位，较难的是了解本人潜意识层面的价值排位，所以，找出潜意识的价值排位，他便能认识到内心的推动力，再加上对某些价值做创造、增大、转移的工作，他便可以使本人的意识和潜意识更为和谐合拍了。\u003c/p>","explains":"\u003cp>\u003cstrong>技能点：当众表达自己的便签\u003c/strong>\u003c/p>\u003cp>好。我看到大家都已经读完了，下面我们进行拆页讲解。\u003c/p>\u003cp>\u003cstrong>［what］是什么\u003c/strong>\u003c/p>\u003cp>这个片段讲的是，在生活中我们做的每一件事的顺序，都是由我们的价值观所决定的，而价值观是受意识和潜意识决定的。如果一个人在对待某件事情上，意识和潜意思的价值观的排列不一样，两者间发生矛盾，就会影响事情的进行，因此我们要寻找出，潜意识的价值排位。\u003c/p>\u003cp>\u003cstrong>［why］为什么可以帮助我们解决\u003c/strong>\u003c/p>\u003cp>为什么要用价值定位法那？例如：当我们想每天早起30分钟进行运动，但是闹表响了就是起不来，为什么想做又不想动那，这时我们就可以用这个方法来看看运动是不是我们的真实需求\u003c/p>\u003cp>\u003cstrong>［how］具体的思考方法分为以下三步\u003c/strong>\u003c/p>\u003cp>在工作生活中，当内心出现矛盾，陷入做与不做的纠结中，可以参照以下步骤：\u003c/p>\u003cp>1、确定内心矛盾问题\u003c/p>\u003cp>2、询问四个问题\u003c/p>\u003cp>“什么最重要？”\u003c/p>\u003cp>“能够带给你些什么？”\u003c/p>\u003cp>“凭它，你可以得到些什么？”\u003c/p>\u003cp>“你最在乎的是什么？”找出事情的更多价值\u003c/p>\u003cp>3、列出价值，按重要程度进行排序，根据这些价值顺序我们就会知道我们要不要去做这件事，这件事是否是我们内心的真实想法\u003c/p>\u003cp>\u003cstrong>【where】适用边界\u003c/strong>\u003c/p>\u003cp>这个方法适合一次解决一个矛盾，挖掘潜意识的真实价值排序，根据内心真实想法，去看这件事是不是我们想要做的。不适合同时处理多个矛盾\u003c/p>\u003cp>\u003cstrong>【如果不这样做的坏处】\u003c/strong>\u003c/p>\u003cp>我说一个去年自己的内心矛盾，19年年底，我听了一个姐姐的建议，想参加社工\u003c/p>\u003cp>考试，然后在我什么都不了解的情况下，就决定要考，又花了好几百买了教材和视频结果我，翻了翻就不在看了，这件事就放那不在进行了。这时候我的内心就出现了矛盾，不知道参加这个考试到底是不是我的真实需求。\u003c/p>\u003cp>后来，我就用这个拆页的这个方法行了化解：\u003c/p>\u003cp>第一步，确定内心矛盾问题：我报考社工师考试有没有必要？还是不要参加这个考试，不要让自己那么辛苦，因为我有时候觉得学习是反人类的\u003c/p>\u003cp>第二步，询问四个问题，\u003c/p>\u003cp>（1）社工师证，对我那面方更重要？\u003c/p>\u003cp>（2）社工师证，可以给我带来什么？\u003c/p>\u003cp>（3）凭社工师证，我能得到什么？\u003c/p>\u003cp>（4）有了这个社工师证，我最在乎的价值是什么？\u003c/p>\u003cp>第三步，写出价值\u003c/p>\u003cp>（1）对以后做家庭教育、做临终关怀志愿者有帮组。\u003c/p>\u003cp>（2）是一个从业资格证，可以多了一个从业机会，\u003c/p>\u003cp>（3）我学会了专业的社工思维\u003c/p>\u003cp>（4）她是国家承认的从业资格证，可以在一定情况下产生和心理咨询师同等的效果，增加一个有价值的备书。看到这些写出的价值，我决定认真的去复习考\u003c/p>","interaction":"\u003cp>\u003cstrong>技能点：当众表达自己的便签\u003c/strong>\u003c/p>\u003cp>好。我看到大家都已经读完了，下面我们进行拆页讲解。\u003c/p>\u003cp>\u003cstrong>［what］是什么\u003c/strong>\u003c/p>\u003cp>这个片段讲的是，在生活中我们做的每一件事的顺序，都是由我们的价值观所决定的，而价值观是受意识和潜意识决定的。如果一个人在对待某件事情上，意识和潜意思的价值观的排列不一样，两者间发生矛盾，就会影响事情的进行，因此我们要寻找出，潜意识的价值排位。\u003c/p>\u003cp>\u003cstrong>［why］为什么可以帮助我们解决\u003c/strong>\u003c/p>\u003cp>为什么要用价值定位法那？例如：当我们想每天早起30分钟进行运动，但是闹表响了就是起不来，为什么想做又不想动那，到底只是不是我们的真实需求那，这时候就可以用这个方法来看看，我们的潜意识价值排位是怎么排的了\u003c/p>\u003cp>\u003cstrong>［how］具体的思考方法分为以下三步\u003c/strong>\u003c/p>\u003cp>在工作生活中，当内心出现矛盾，陷入做与不做的纠结中，可以参照以下步骤：\u003c/p>\u003cp>1、确定内心矛盾问题\u003c/p>\u003cp>2、询问四个问题\u003c/p>\u003cp>“什么最重要？”\u003c/p>\u003cp>“能够带给你些什么？”\u003c/p>\u003cp>“凭它，你可以得到些什么？”\u003c/p>\u003cp>“你最在乎的是什么？”找出事情的更多价值\u003c/p>\u003cp>3、列出价值，按重要程度进行排序，根据这些价值顺序我们就会知道我们要不要去做这件事，这件事是否是我们内心的真实想法\u003c/p>\u003cp>\u003cstrong>【where】适用边界\u003c/strong>\u003c/p>\u003cp>这个方法适合一次解决一个矛盾，挖掘潜意识的真实价值排序，根据内心真实想法，去看这件事是不是我们想要做的。不适合同时处理多个矛盾\u003c/p>\u003cp>\u003cstrong>【如果不这样做的坏处】\u003c/strong>\u003c/p>\u003cp>我说一个去年自己的内心矛盾，19年年底，我听了一个姐姐的建议，想参加社工\u003c/p>\u003cp>考试，然后在我什么都不了解的情况下，就决定要考，又花了好几百买了教材和视频结果我，翻了翻就不在看了，这件事就放那不在进行了。这时候我的内心就出现了矛盾，不知道参加这个考试到底是不是我的真实需求。\u003c/p>\u003cp>后来，我就用这个拆页的这个方法行了化解：\u003c/p>\u003cp>第一步，确定内心矛盾问题：我报考社工师考试有没有必要？还是不要参加这个考试，不要让自己那么辛苦，因为我有时候觉得学习是反人类的\u003c/p>\u003cp>第二步，询问四个问题，\u003c/p>\u003cp>（1）社工师证，对我那面方更重要？\u003c/p>\u003cp>（2）社工师证，可以给我带来什么？\u003c/p>\u003cp>（3）凭社工师证，我能得到什么？\u003c/p>\u003cp>（4）有了这个社工师证，我最在乎的价值是什么？\u003c/p>\u003cp>第三步，写出价值\u003c/p>\u003cp>（1）对以后做家庭教育、做临终关怀志愿者有帮组。\u003c/p>\u003cp>（2）是一个从业资格证，可以多了一个从业机会，\u003c/p>\u003cp>（3）我学会了专业的社工思维\u003c/p>\u003cp>（4）她是国家承认的从业资格证，可以在一定情况下产生和心理咨询师同等的效果，增加一个有价值的备书。看到这些写出的价值，我决定认真的去复习考试\u003c/p>\u003cp>\u003cstrong>接下来我们进入A1环节\u003c/strong>\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>刚才我分享了自己如何用今天这个拆页的方法，化解了自己内心的矛盾，大家有没这样的经历：比方说你想减肥，制定详细运动计划，调整饮食结构。在执行过程中，就会发现，遇到美食，我们想吃又不能吃，运动想动又不想动，这个时候我们内心就会想，我是不是真的需要减肥那，内心十分矛盾，减肥计划就不一定会进行，这种内心产生矛盾的事情，在生活中大家一定遇到过，现在我们分一下组，桌子左面2个人一组，右面2个人一组，在讨论的过程中，大家可以分享一个具体的事，在什么时间，地点，以及起因经过和结果。讨论过程中，只要讲出过去的经历就可以，如何解决我们会在下一个环节讲解。\u003c/p>\u003cp>学习者案例实录：\u003c/p>\u003cp>拆书家：我看大家刚才都讨论的挺积极的，哪位小伙伴来分享下？好，这位小伙伴。\u003c/p>\u003cp>小伙伴：时间：现在\u003c/p>\u003cp>        地点：何所有书店\u003c/p>\u003cp>        人物：何所有书店的王辉，和拆书帮的小伙伴\u003c/p>\u003cp>        起因：上班没啥意思，没啥挑战\u003c/p>\u003cp>        经过：觉得上班没什么意思，都是重复，自己在权衡利弊，到底是创业还是换新的工作，迟迟没有进行\u003c/p>\u003cp>        结果：还在纠结中\u003c/p>\u003cp>拆书家：感谢这位小伙伴分享\u003c/p>\u003cp>【A1+】反思加工 \u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>如果现在我们在回到当时的情景，那我们可不可以试一下，用今天的方法来解决，当时的内心矛盾\u003c/p>\u003cp>化解内在矛盾，找出真实需求排位的三步骤：\u003c/p>\u003cp>一、确认矛盾，\u003c/p>\u003cp>二、询问四个问题，\u003c/p>\u003cp>三、列出价值在纸上，\u003c/p>\u003cp>现在请两个小组的伙伴在小组内分享，每个人都尽量表达一下，1-2分钟，我再请小组代表分享\u003c/p>\u003cp>学习者案例实录：\u003c/p>\u003cp>拆书家：我看大家都在小组内分享的很热闹，哪位小伙伴愿意给大家一起分享？\u003c/p>\u003cp>小伙伴：\u003c/p>\u003cp>使用今天的三步重新解决\u003c/p>\u003cp>（一）确认矛盾，是什么事情？要创业还是要打工\u003c/p>\u003cp>（二）询问四个问题：\u003c/p>\u003cp>“什么最重要？”最重要的是适当的收入和家人的陪伴\u003c/p>\u003cp>“能够带给你些什么？”够给女儿不错的生活加陪伴\u003c/p>\u003cp>“凭它，你可以得到些什么？”让女儿有快乐的童年，并且有良好的成长经历\u003c/p>\u003cp>“你最在乎的是什么？”可能最在乎的是个人的传承\u003c/p>\u003cp>（三）列出价值观在纸上：亲子关系、工作与爱好统一、赚钱\u003c/p>\u003cp>拆书家：感谢这位小伙伴分享，希望你再次遇到这件事的时候自己把今天的A1+直接用出来\u003c/p>\u003cp>好，希望我分享的内容能被大家拆为己用，对大家有所帮助，今天的拆书就到这里，感谢大家的聆听，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1619360651000,"updated_at":1620359798000,"ria":true},{"id":10912,"topic":"改变信念系统的技巧-价值定位法","learn_goal":"","remark":"学习目标：\n   希望大家在跟我现场学习和互动后： 能够帮助你在意识和潜意识两个层面去客观分析，根据内心真实需求，做出有效选择 。\n内容简要（不少于20字）\n一个人做或者不做任何事，都是由他的价值观决定的，而价值观也是被意识和潜意识共同影响的，但人们决定做事前，大多只是从意识层面去思考要不要去做，而忽略了潜意识层面的思考，所以到最后事情的执行力就会不如人意。通过这个片段就可以帮找出意识和潜意识层面的真实需求。\n","level":"TF2-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"宋佳嶶","city":"哈尔滨市"},"club":{"name":"哈尔滨索菲亚分舵","city":"哈尔滨"},"prologue":"\u003cp>拆书成长，悦享人生！大家好，我是宋佳嶶。首先三个标签介绍一下我自己，第一个标签拆书帮哈尔滨索菲亚分舵的一级拆书家，第二个标签向阳花爱心公益团队财务负责人，第三个标签NLP内容学习者。\u003cbr>在跟随我完成本次RIA现场学习后，学习者在遇到意识层面和潜意思层面之间产生矛盾时，能够通过自我潜意识层面反思，找到内心的真实想法，可以根据内心真实的需求，做出行之有效的选择\u003c/p>\u003cp>\u003cstrong>F特征： （Feature），核心是“书”，用于满足好奇心\u003c/strong>\u003c/p>\u003cp>这本书《重塑心灵》作者李中莹，他是最早把NLP完整地介绍到国内，因而被誉为“华人世界的国际级NLP大师”，书中从信念系统、沟通方式、情绪管理等方面讲述了主动获得成功快乐的人生方法。\u003c/p>\u003cp> \u003cstrong>A优势：（Advantage）,重点是“比较”，用于建立安全感\u003c/strong>\u003c/p>\u003cp> 这本书是每一位学NLP会拜读的一本书，与其他NLP心理学书籍相比，这本书更加注重灵活性和实用性。对于书中的不同技巧都有清晰的步骤，可以指导我们运用在生活和学习中。 \u003c/p>\u003cp> \u003cstrong>B利益：\u003c/strong> \u003cstrong>（Benefit）强调的是“你（学习者）”，用于引发兴趣\u003c/strong>\u003c/p>\u003cp>你是否在生活中，总会听到自己或是别人这样的声音“我肯定不行。”“别人为什么就不理解我那？” 其实这是个人的信念系统、沟通方式等出现了问题。阅读过后可以让你从多个角度去看问题，不在纠结和自我否定。 今天我给大家分享的片段就是《价值定位法》。\u003c/p>\u003cp>在阅读前我们分下组，两人一组，便于之后的组内讨论。 现在请大家花2分钟时间阅读下拆页，阅读完后，大家举手示意下。 \u003c/p>","ratings_count":1,"texts":[{"id":14809,"quote":"\u003cp>\u003cstrong>技能：请学习者阅读拆页\u003c/strong>\u003c/p>\u003cp>主题：改变信念系统的技巧-价值定位法\u003c/p>\u003cp>第二章 《信念系统之改变信念系统的技巧》  P55-56 《价值定位法》\u003c/p>\u003cp>一个人对某一件事情的价值观，即是希望该件事给他的各项价值，需要按大小轻重做出排列。但是他的意识和潜意识，常常有不一样的排列。意识的价值观，可以因为环境因素受到其他人的影响，或者通过自我思考而修正；而潜意识的价值观，受到内心深层的一些因素的操控（包括系统层次。身份层次和一些重大的信念），往往会与意识的排列不同。意识与潜意识的价值排列差异越大，这个人的内心矛盾和无力感会越大。“价值定位法”能帮助一个人找出潜意识里的价值排列。\u003c/p>\u003cp>首先我们要学会如何凭询问找出受导者对某一件事的价值观，以“找工作”为例，\u003c/p>\u003cp>首先，用这样的文字询问每个问题， 一份理想的工作…… 因为询问的目的是找出受导者的主观价值，符合他的主观价值的，就是他认为理想的。\u003c/p>\u003cp>第二，询问四个问题“什么最重要？” “能够带给你些什么”“凭他，你可以得到什么？”\u003c/p>\u003cp>“你最在乎的是什么？”将四个问题补充完整就是：\u003c/p>\u003cp>“在一份理想的工作中，什么最重要”\u003c/p>\u003cp>“一份理想的工作能够带给你些什么？”“凭着一份理想的工作，你可以得到些什么？”“在一份理想的工作里，你最在乎的是什么？”\u003c/p>\u003cp>这四个问题就像是一间木屋的四扇窗子，每一扇窗子都能让人看到里面的东西，但不是全部，且从四扇窗子里分别看到的东西会有不同的。如果一个人对某一问题不太清楚，回答有困难，可以 改变下一个问题，也可以在这个问题以后回答他：“还有呢？”使得受导者说出更多的价值。\u003c/p>\u003cp>第三，如果这个人的回答是一些感觉的词，例如快乐、开心、成功感、满足感等，辅导者必须问他：“有什么情况出现，你便会有这份……（感觉的字）？”\u003c/p>\u003cp>最后要注意的是，这个人最先说出来的，并不一定就是对他最重要的价值。\u003c/p>\u003cp>应该用上述的询问方式，找出四五个价值写下，让这个人看着他们，然后说出哪个最重要，并排列出次序。\u003cbr> 一个人做或者不做任何事，都是由他的价值观所看控制。一个人很容易认识到自己意识层面对某件事的价值排位，较难的是了解本人潜意识层面的价值排位，所以，找出潜意识的价值排位，他便能认识到内心的推动力，再加上对某些价值做创造、增大、转移的工作，他便可以使本人的意识和潜意识更为和谐合拍了。\u003cbr>\u003c/p>","explains":"\u003cp>\u003cstrong>技能点：当众表达自己的便签\u003c/strong>\u003c/p>\u003cp>好。我看到大家都已经读完了，下面我们进行拆页讲解。\u003c/p>\u003cp>\u003cstrong>［what］是什么\u003c/strong>\u003c/p>\u003cp>在生活中我们做的每一件事，都是由我们的价值观所决定的，并按照我们认为的重要性，去先做什么后做什么。价值观是受意识和潜意识决定的。如果他们两者间发生矛盾，就会影响事情的进行，因此我们要寻找出，潜意识的原动力。\u003c/p>\u003cp>\u003cstrong>［why］为什么可以帮助我们解决\u003c/strong>\u003c/p>\u003cp>在意识与潜意识产生矛盾时，了解潜意识对事情的看法，然后理性地调节行为去满足意识和潜意思两方面的需要\u003c/p>\u003cp>\u003cstrong>［how］具体的思考方法分为以下三步\u003c/strong>\u003c/p>\u003cp>在工作生活中，当内心出现矛盾，陷入做与不做的纠结中，可以参照以下步骤：\u003c/p>\u003cp>1、确定内心矛盾问题\u003c/p>\u003cp>2、询问四个问题\u003c/p>\u003cp>“什么最重要？”\u003c/p>\u003cp>“能够带给你些什么？”\u003c/p>\u003cp>“凭它，你可以得到些什么？”\u003c/p>\u003cp>“你最在乎的是什么？”找出事情的更多价值\u003c/p>\u003cp>3、列出价值观，按重要程度进行排序，根据这些价值顺序我们就会知道我们要不要去做这件事，这件事是否是我们内心的真实想法\u003c/p>\u003cp>\u003cstrong>【where】适用边界\u003c/strong>\u003c/p>\u003cp>任何一种方法，都不可能解决所有问题的，比如不能同时处理多个矛盾，那是意识和理性负责的工作。当我们就一件事情执行不下去的时候，可以用这个方法去挖掘潜意识的真实价值排序，根据内心真实想法，去看这件事是不是我们想要做的\u003c/p>\u003cp>\u003cstrong>【如果不这样做的坏处】\u003c/strong>\u003c/p>\u003cp>首先，当你没有了解自己最重要的内心需求时，就盲目的设定目标。\u003c/p>\u003cp>然后，你就会发现，这件事就一直拖着不想去做。举一个例子，去年我听别人说社工证好，我就也想考，可后来我买了教材买了书，翻了翻就不在看了，这件事就放那了。\u003cbr>最后，我用这个拆也得方法这三步骤进行了化解：\u003c/p>\u003cp>第一步，确定事项，内心矛盾：我报考社工师考试有没有必要？还是不要参加这个考试，不要让自己那么辛苦\u003c/p>\u003cp>第二步，询问四个问题，（1）社工师证，对我那面方更重要？对以后做家庭教育有帮助，所以很重要。\u003c/p>\u003cp>（2）社工师证可以给我带来什么？多了一个从业资格证，可以用来找工作\u003c/p>\u003cp>（3）凭社工师证，我能得到什么？在学习课程的过程中，我学会了专业的社工思维\u003c/p>\u003cp>（4）有了这个社工师证，我最在乎的价值是什么？她一个国家承认的从业资格证，可以在一定情况下产生和心理咨询师同等的效果，成为一个有价值的备书。\u003c/p>\u003cp>第三步，写出价值观（1）对我做兼职有帮组，（2）多了一个从业机会，（3）学会了一套新的思维体系，（4）增加一个有价值的备书。看到这些写出的价值观，我决定认真的去复习考试\u003cbr>\u003c/p>","interaction":"\u003cp>\u003cstrong>接下来我们进入A1环节\u003c/strong>\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>刚才我分享了自己如何用今天这个拆页的方法，化解了自己内心的矛盾，大家有没这样的经历：比方说你想减肥，制定详细运动计划，调整饮食结构。可是当让你拒绝心爱的奶油蛋糕，并且要每天的5公里慢跑，你对减肥这件事又犹豫了，我真的需要减肥吗，我减肥到底是为了什么那，减肥能给我带来什么好处那，我的潜意识也真的认为自己胖吗？与美食相比，减肥真的可以让我觉得更有意义吗？\u003c/p>\u003cp>这种内心产生矛盾的事情，在生活中大家一定遇到过，现在我们就在小组内讨论一下，在讨论的过程中，大家可以分享一个具体的事，在什么时间，什么地点，以及起因经过和结果。大家在讨论过程中，大家只要讲出过去的经历就可以，如何解决我们会在下一个环节讲解。组内分享结束之后，每组各请一位小伙伴来做一下分享。\u003cbr>学习者案例实录：\u003c/p>\u003cp>拆书家：我看大家刚才都讨论的挺积极的，哪位小伙伴来分享下？好，这位小伙伴。\u003c/p>\u003cp>小伙伴：时间：周四下午\u003c/p>\u003cp>地点：公司\u003c/p>\u003cp>人物：深圳HR\u003c/p>\u003cp>起因：1月份请我帮忙制作3门微课\u003c/p>\u003cp>经过：1、问我时间，2、犹豫了一下\u003c/p>\u003cp>结果：答应2门\u003c/p>\u003cp>拆书家：感谢这位小伙伴分享\u003cbr>【A1+】反思加工\u003c/p>\u003cp>拆书家提问设计：\u003c/p>\u003cp>如果现在我们在回到当时，事情再来一遍，那我们可不可以试一下，用今天的方法来解决，然后让自己能获得一个更好的结果那，\u003c/p>\u003cp>化解内在矛盾，找出真实需求排位的三步骤：一、确认矛盾，二、询问四个问题，三、列出价值观在纸上，大家花几分钟时间对之前的A1场景进行优化，可将重要内容写下来，然后我们请一位小伙伴来分享。\u003cbr>学习者案例实录：\u003c/p>\u003cp>拆书家：我看大家都有在纸上修改刚刚的A1了，哪位小伙伴写完愿意来分享一下？\u003c/p>\u003cp>小伙伴：\u003c/p>\u003cp>使用今天的三步重新解决\u003c/p>\u003cp>（一）确认矛盾，是什么事情？领导可能不同意，占用我的时间\u003c/p>\u003cp>（二）询问四个问题：\u003c/p>\u003cp>“什么最重要？”学习提升锻炼最重要\u003c/p>\u003cp>“能够带给你些什么？”1制作流程，2经验积累\u003c/p>\u003cp>“凭它，你可以得到些什么？”总部支持\u003c/p>\u003cp>“你最在乎的是什么？”能力实践提升，人际支持\u003c/p>\u003cp>（三）列出价值观在纸上：学习能力，人际帮助\u003c/p>\u003cp>拆书家：感谢这位小伙伴分享，希望你再次遇到这件事的时候自己把今天的A1+直接用出来\u003cbr>好，看到大家都写好了自己的行动计划，希望我分享的内容能被大家拆为己用，对大家有所帮助，今天的拆书就到这里，感谢大家的聆听，谢谢！\u003c/p>\u003cp>添加片段\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}}],"created_at":1609944051000,"updated_at":1610862737000,"ria":true},{"id":9897,"topic":"《重塑心灵》意义换框法","learn_goal":"","remark":"本次分享的“意义换框法”是一个实用工具，可以帮助我们从更多角度发现事件背后的意义和价值。","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"乘风","city":"广州市"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp> (现场分组)大家好，我是老程，首先我们做一下分组，从这边开始，临近2人为一组，谢谢。那我用三个标签介绍一下自己：1）2020年的三级拆书家，这是我今年的个人目标；2）职业发展精进探索者，这是近期的阅读和学习方向；3）价值链接者，这是今年重点实践的一个理念。\u003c/p>\u003cp> 今天我们的学习片断来自于《重塑心灵》，作者李中莹先生是华人世界研究NLP（身心语言程序学）的大师，这本书浅显易懂，我尤其喜欢书的封面这句话“每个人都拥有让自己成功快乐的能力”，也推荐给大家。\u003c/p>\u003cp> 本次分享的“意义换框法”是一个实用工具，可以帮助我们从更多角度发现事件背后的意义和价值。\u003c/p>","ratings_count":2,"texts":[{"id":13726,"quote":"\u003cp>《重塑心灵》李中莹 P49-50\u003c/p>\u003cp>意义换框法\u003c/p>\u003cp>“意义换框法”是NLP技巧“换框法”中最常用和最好用的技巧。它完全只凭言语和思想模式而产生效果，是NLP的改变信念技巧中最快速最容易的一个。“意义换框法”是找出一个负面经验中的正面意义。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都只是人加诸的。既然是人加上去的意义，则一件事情——\u003c/p>\u003cp>◇可以有其他的意义，也可以有更多的意义；\u003c/p>\u003cp>◇可以有不好的意义，也可以有好的意义。\u003c/p>\u003cp>……\u003c/p>\u003cp>同一件事情里面总有不止一个意义包含其中。找出最能帮助自己的意义，便可以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。\u003c/p>\u003cp>意义换框法对一些因果式的信念最为有效。例如：“因为上级挑剔，所以我工作不开心。”\u003c/p>\u003cp>方法是把句中的“果”（工作不开心）改为它的反义词，再把句首的“因为”二字放到最后，成为：“上级挑剔，所以我工作积极，因为……”然后反复地思考如何能把句子写完，要求至少有六个不同的版本，再找出其中最能够接受的一句。以下是一些学员的杰作：“上级挑剔……”\u003c/p>\u003cp>◇使他无从挑剔\u003c/p>\u003cp>◇使我提升得更快\u003c/p>\u003cp>◇使他改变对我的态度\u003c/p>\u003cp>◇使我超越他的标准\u003c/p>\u003cp>◇使我变得更能干\u003c/p>\u003cp>◇使我更快升级，脱离他的管治\u003c/p>\u003cp>◇使我更有能力去另找新工作\u003c/p>","explains":"\u003cp>\u003cstrong>[why]\u003c/strong>有时候我们难免遇到一些负面事件，怎么想都不开心，这就会产生困扰，然后带来一系列坏的影响。所以我们需要自己掌握一个快速高效的工具来帮助我们处理这些负面经验。\u003c/p>\u003cp>\u003cstrong>[what]\u003c/strong>这段拆页介绍的“意义换框法”就通过4个步骤，让我们从不同角度去看待那些负面事件，找到其中最能帮助自己的意义和价值，从而跳出原本看待事情的“框”，提升自己。\u003c/p>\u003cp>\u003cstrong>[适用边界]\u003c/strong> 如果我们对负面事件已经有了分析，表现为可以用“因为…所以…”这样的句式表达对事件的看法，那在此基础上再使用意义换框法是非常有效的。\u003c/p>\u003cp>\u003cstrong>[how]\u003c/strong>具体来讲分为四步\u003c/p>\u003cp>\u003cstrong>1)\u003c/strong> \u003cstrong>接受原因。\u003c/strong>首先“因为…所以…”这样的句式把我们原来对事件的理解写出来，直接把“因为”两字去掉，代表着把这个作为“假设”现实，接受它，不在这个地方纠结。\u003c/p>\u003cp>\u003cstrong>2)\u003c/strong> \u003cstrong>倒转结果。\u003c/strong>把原来的结果部分，用想要的正向积极结果来倒转。\u003c/p>\u003cp>\u003cstrong>3)\u003c/strong> \u003cstrong>添加新意。\u003c/strong>探索至少3个这个事件可以带来的不同意义的价值，从而使新的因果关系和逻辑成立。\u003c/p>\u003cp>\u003cstrong>4)\u003c/strong> \u003cstrong>优选价值\u003c/strong>。比较选择其中最能打动你的那个解读“框”。\u003c/p>\u003cp>[例子]这里分享一个我本人的例子。我原来很为孩子不听话苦恼，那当时我的看法就是“因为孩子不听话，所以经常反驳我”。但学会了“意义换框法”后，我分成4步来转变了看法：\u003c/p>\u003cp>1） \u003cstrong>接受原因\u003c/strong>。把“因为”去掉接受现实，变成“孩子不乖乖听话，所以经常反驳我。“\u003c/p>\u003cp>2） \u003cstrong>倒转结果\u003c/strong>。转换为我想要的正向积极结果“孩子不乖乖听话，所以经常会顺从我。”但到这里，这个句子还是有些奇怪。\u003c/p>\u003cp>3） \u003cstrong>添加新意\u003c/strong>。我要重新组织逻辑，探索了几个原因，让新的句子符合逻辑，比如：“孩子不乖乖听话，所以经常会顺从我，因为a）我学会了站在他的角度考虑问题 b）我表达的时候尝试用他能理解的语言 c）我表达的时候，不再让他感觉他一定要听我的”等等，这些都是逻辑上完整和成立的。\u003c/p>\u003cp>4） \u003cstrong>优选价值。\u003c/strong>综合比较后我的选择解读是：“孩子不乖乖听话，所以经常会顺从我，因为我学会了站在他的角度考虑问题。”\u003c/p>\u003cp>就这样，对同样一件负面经验，我探索了几种不同的意义和价值，扩大了思路，找到新的解读和办法，这就是意义换框法的解读和用处。\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】激活经验\u003c/strong>\u003c/p>\u003cp> 接下来我们进行小组讨论，先请大家联想自己过去经历的某个“不开心”的事情，并在便笺纸上用“因为…所以…”格式写下你对那件事的理解。建议花1分钟回想书写，然后1分钟分享和反馈。\u003c/p>\u003cp>学习者案例记录1：\u003c/p>\u003cp>\u003cstrong>事件（时间、人物、地点、过程）\u003c/strong>： \u003cu>最近经常在公司加班 \u003c/u>\u003c/p>\u003cp>\u003cstrong>原框\u003c/strong>：因为 \u003cu>加班\u003c/u> 所以 \u003cu>不开心\u003c/u> \u003c/p>\u003cp>学习者案例记录2：\u003c/p>\u003cp>\u003cstrong>事件（时间、人物、地点、过程）\u003c/strong>： \u003cu>最近刚从医院跳槽\u003c/u> \u003c/p>\u003cp>\u003cstrong>原框\u003c/strong>：因为\u003cu>经常要和陌生人的打交道\u003c/u>所以\u003cu>感觉压力很大\u003c/u>\u003c/p>\u003cp>\u003cstrong>【A2】催化应用\u003c/strong>\u003c/p>\u003cp>学习了今天的“意义换框法”后，我们在未来2周内怎样实践一下呢？请用便签写出行动计划，为了保证可执行性，请按照以下格式去写，写完后请示意，时间有结余的话，我们会请一位小伙伴公开分享。\u003c/p>\u003cp>学习者现场分享记录1（见网盘中作业图片）：\u003c/p>\u003cp>\u003cstrong>事件（时间、人物、地点、过程）\u003c/strong>： \u003cu>公司，将来两周还会有加班的情况\u003c/u> \u003c/p>\u003cp>\u003cstrong> 原框\u003c/strong>：因为 \u003cu>加班\u003c/u> 所以 \u003cu>不开心\u003c/u> \u003c/p>\u003cp>\u003cstrong>新框\u003c/strong>：\u003c/p>\u003cp>\u003cstrong> 接受原因：\u003c/strong> \u003cu>接受加班\u003c/u> \u003c/p>\u003cp>\u003cstrong> 倒转结果：\u003c/strong> 因为 \u003cu>加班\u003c/u> 所以 \u003cu>很开心 \u003c/u> \u003c/p>\u003cp>\u003cstrong> 添加新意：\u003c/strong> \u003cu>1） 少做家务\u003c/u> \u003cu>2）\u003c/u> \u003cu>省一顿饭 \u003c/u> \u003cu>3）\u003c/u> \u003cu>赚加班费\u003c/u> \u003c/p>\u003cp> \u003cstrong>优选价值： \u003c/strong> \u003cu>加班 所以 很开心 ，因为 又可以赚加班费了！\u003c/u> \u003c/p>\u003cp>学习者现场分享记录2（见网盘中作业图片）\u003c/p>\u003cp>\u003cstrong>事件（时间、人物、地点、过程）\u003c/strong>： \u003cu>如果将来两周面试再有失败\u003c/u> \u003c/p>\u003cp>\u003cstrong>原框\u003c/strong>：因为 \u003cu>面试失败\u003c/u> 所以 \u003cu>不开心\u003c/u> \u003c/p>\u003cp>\u003cstrong>新框\u003c/strong>：\u003c/p>\u003cp>\u003cstrong>接受原因：\u003c/strong> \u003cu>接受面试失败\u003c/u> \u003c/p>\u003cp>\u003cstrong>倒转结果：\u003c/strong> \u003cu>因为面试失败，所以很开心\u003c/u> \u003c/p>\u003cp>\u003cstrong>添加新意：\u003c/strong> \u003cu>1）\u003c/u> \u003cu>还有更好的工作\u003c/u> \u003cu>2）\u003c/u> \u003cu>面试技巧会进步\u003c/u> \u003cu>3）\u003c/u> \u003cu>又多了解一家公司\u003c/u> \u003c/p>\u003cp>\u003cstrong>优选价值： \u003c/strong> \u003cu>面试失败 所以 很开心 ，因为 面试技巧会进步 \u003c/u>\u003c/p>\u003cp>\u003cstrong>[结束语]\u003c/strong>\u003c/p>\u003cp>让我们回顾一下，今天我们一起学习了“意义换框法”，具体有\u003cstrong>接受原因\u003c/strong>-\u003cstrong>倒转结果\u003c/strong>-\u003cstrong>添加新意-优选价值\u003c/strong>四个步骤，这个方法能从更多角度解读负面经验，帮我们发现它让我们成长的新价值，正是“山重水复疑无路，柳暗花明又一村”，希望这个方法能让大家更加快乐！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1591175940000,"updated_at":1591413239000,"ria":true},{"id":9456,"topic":"《重塑心灵》先跟后带沟通技巧","learn_goal":"《重塑心灵》先跟后带沟通技巧","remark":"在生活和工作中，我们处处需要与别人沟通，通常我们希望：1）深化双方的关系；2）完成信息的充分交换；3）甚至有时候需要说服别人。\r\n但“直来直去的”沟通方法很容易造成几个坏结果:1)话不投机半句多，双方陷入尬聊，都觉得没法继续了； 2）双方情绪上来甚至起冲突了。\r\n本次我们学习的“先跟后带”方法通过三个步骤：1）跟--复述重点；2）转-上堆下切平推；3）带-询问确认 这三个步骤来帮助我们顺利达成沟通目的。","level":"TF2-4","duration":60,"status":30,"type":0,"chaishujia":{"username":"乘风","city":"广州市"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"【分组】大家好，我是老程，首先用三个标签法介绍一下自己：软件行业从业者、职场精进探索者、2020年的三级拆书家。首先我们做一下分组，方便等会讨论，请从我右手边开始两人分为一组，谢谢。\r\n接下来我和大家一起学习的这本书叫做《重塑心灵》。\r\n（F）这是一本讲NLP，即“身心语法程序学”的书。作者李中莹老师最早把 NLP 完整地介绍到国内，被誉为“华人世界的国际级 NLP大师”，这本书完整全面地介绍了NLP的各项基础知识，非常适合想全面学习NLP的小伙伴。\r\n（A）这本书相比其他NLP书籍的特点在于全面、实用和接地气，主要章节包括了信念系统、自我价值、理解层次、脑的运作、内感官和情绪等，都是读者普遍关心的内容，而且作者在每部分都提供了非常实用的技巧，举例也非常的接地气。\r\n（B1）就像这本书封面所说“每个人都拥有让自己成功快乐的能力”，这本书通过介绍NLP中的各个概念和技巧，能够让读者认识到自己的头脑和潜意识的运作原理，并且能够有意识地通过“语言”去“重新编程”，提升自己的认知，改善自己的情绪，追求更成功快乐的生活。\r\n（B2）今天我们学习的“先跟后带”是书中很重要的一个沟通技巧，它可以极大地改善沟通过程，帮我们顺利达成沟通目标。","ratings_count":1,"texts":[{"id":13266,"quote":"\u003cp>【学习目标1】在跟随我完成本次RIA现场学习后，大家能够学会“先跟后带”沟通法，当与别人沟通时，使用“1.跟随、2.迎合、3.带引”三个步骤来顺利达成沟通目标。\u003c/p>\u003cp>《重塑心灵》p182\u003c/p>\u003cp>第四，要学会先跟后带，就是先附和对方的观点，然后再带领他去你想去的方向。附和对方说话的技巧既可以取同——把焦点放在对方话语中你与他一致的部分，又可以取异——把焦点放在对方语言中与你不同的部分，还可以先接受对方全部的话，然后再表达自己的看法、观点。\u003c/p>\u003cp>例如：\u003c/p>\u003cp>你说：“我认为吃早餐的习惯对健康很重要，所以我每天早上都吃两只鸡蛋。”\u003c/p>\u003cp>对方：“鸡蛋的胆固醇含量太高，我的早餐绝不会有鸡蛋。”\u003c/p>\u003cp>回应1（取同）：“噢，原来你也有吃早餐的习惯，你觉得吃早餐对一天的工作有重要的帮助吗？”\u003c/p>\u003cp>回应2（取异）：“你觉得鸡蛋的胆固醇对身体不好，当然你不会以它作早餐了，那么，你的早餐吃什么？”\u003c/p>\u003cp>回应3（全部）：“不单你这样说，我以前也是这样理解的，直至去年我看到一篇科学新知的文章，发现原来胆固醇之中也有好坏之分，而且鸡蛋给我们的胆固醇好多过坏，有一些营养更是其他食物中很少能提供的呢！你有兴趣看一看这篇文章吗？”\u003c/p>","explains":"\u003cp>【what】我们今天学习“先跟后带”的沟通方法，是指我们与别人谈话时，先与别人同频，表达理解，然后再引领谈话，从而达成沟通目标的沟通技巧。\u003c/p>\u003cp>【Why】\u003c/p>\u003cp>〈一般做法〉\u003c/p>\u003cp>我们知道，沟通最常见的三个目的是：1）深化关系；2）交换信息；3）达成一致。但大部分人在和别人沟通时，只顾着自己的真实表达，却对沟通对象的同理和互动重视不足，这样沟通就容易出现问题。\u003c/p>\u003cp>〈一般做法案例〉\u003c/p>\u003cp>举个例子，上个星期我和同事小张的一次沟通是这样开场的。\u003c/p>\u003cp>我说：“小张，这一周你都迟到两次了，是怎么回事呢？”\u003c/p>\u003cp>“唉呀，闹钟响了，但我还是起不来。”小张说。\u003c/p>\u003cp>我一听有点激动：“那说明你根本没把准时上班当回事啊,这样怎么能行？！”\u003c/p>\u003cp>小张听了，很不高兴地说：“我怎么没把准时上班放心上了？你以为我想啊！”\u003c/p>\u003cp>话说到这里，气氛就有些僵了。\u003c/p>\u003cp>〈一般做法的坏处〉\u003c/p>\u003cp>回顾这个沟通过程，本来我是善意想问下原因然后找解决办法，但这样“直来直去”，完全不考虑对方的说话很容易尬聊甚至冲突。\u003c/p>\u003cp>【How】那我们今天介绍的“先跟后带”方法，可以帮助我们在轻松和尊重的氛围中轻松达成沟通目标，非常实用并且容易掌握。具体来说分三步：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>跟随-复述关键。\u003c/strong>我们首先复述对方言语中的关键词，这些关键词通常是表达事实、评价、情绪、需求等词语。复述可以让对方有被倾听和被尊重的感觉，同时对方也可以回顾他的表达是否准确和充分。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>迎合-选择同异。\u003c/strong>然后我们基于刚才的重点词去有意迎合。这种迎合可以取与对方相同，或者不同的信息路径。常见的方式有两种：同意对方的关键词并且给出细节补充；不同意对方的关键词并且给出细节补充。\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong>\u003cstrong>带引-引领确认。\u003c/strong>高质量的沟通谈话需要双方参与贡献信息，所以我们再用引领更多内容的问句来结尾，使得谈话逐步推进。这里的“引领”可以是邀请对方确认共识，或者激发对方继续谈话的兴趣和方向等。\u003c/p>\u003cp>〈正面案例〉\u003c/p>\u003cp>比如说，以前我如果会“先跟后带”沟通法，我和小张的谈话可能是这样的：\u003c/p>\u003cp>我：“小张，这周你都迟到两次了，是怎么回事呢？”\u003c/p>\u003cp>“唉呀，闹钟响了，但我还是起不来。”小张说。\u003c/p>\u003cp>我继续说：“定了闹钟还起不来啊（复述重点），那说明你其实也很注意了。早晨起床确实不容易（这是求同），那你有想过什么办法吗？（带引）”\u003c/p>\u003cp>小张说：“我已经把闹钟声音调大了，这两天我再试试，应该可以的。”\u003c/p>\u003cp>我虽然感觉这样会改善，但还不够稳妥。我继续说：“调大声音啊，这也是一个办法（跟随）。但因为之前没效果，你有没有可能再多个保障办法呢？（取异），否则大家都注意到你迟到，就会产生坏影响，你说呢？（带引）”\u003c/p>\u003cp>小张说：“嗯，那我另外也会11点准时上床睡觉，另外让我室友出门的时候也叫我起床，这样就万无一失了，你看行吗？”\u003c/p>\u003cp>我笑了：“小张加油！”\u003c/p>\u003cp>大家看，我不断复述小张说话中的关键词，让小张觉得我一直在倾听和理解他，而且我还注意与他谈话内容的迎合，带引谈话的方向，这样我们就很聚焦并且容易达成共识。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>&nbsp; “先跟后带”沟通法是一种让人非常舒服的沟通方法，即使是对于较易冲突的沟通场景也是适用的\u003c/p>","interaction":"\u003cp>【显像】现在那请大家回想一下过往经验，你有没有遇到过类似的“尬聊”情景，比如你和朋友正聊着香港最近发生的反修例事件，对方虽然和你观点一致，都不赞同“黑衣人”的暴力行为，但我非常激动，我就挥着手兴致勃勃地讲着我的观点，我的朋友就很想加入进来，但只要一接话，我就会很快打断，又把话头抢过来，而且看他脚尖都转了方向，看起来随时都想走了，这就感觉有一种很奇怪的气氛，就属于一种尬聊。\u003c/p>\u003cp>【提问】请大家按照开始的分组进行小组讨论，你经历过的“尬聊”的沟通场景吗？是什么样的？请花2分钟在小组内讨论，然后我邀请小伙伴来分享（我的指令清晰吗？）\u003c/p>\u003cp>【学习者案例记录1】\u003c/p>\u003cp>学习者1的过往经验分享:\u003c/p>\u003cp>有一次公司出外举办活动，当时中午用餐时才发现预订的午餐订少了，我当时是考虑到时间紧急，建议是想干脆到就近的餐厅直接用餐，但这样做总费用就会高一些。但是因为原来是预订，已经有预缴费，而且如果这样做法也违背了双方的承诺，所以我和预订负责人沟通过之后，没办法说服他，反正他去处理他的，但当时是有情绪在，不是很愉快，事件最后还是按原预订者的方法来处理了。\u003c/p>\u003cp>【拆书家提问设计】\u003c/p>\u003cp>好的，假如时光倒流，使用今天学习的“先跟后带”的方法，你或者对方会怎样沟通呢？请着重使用“先跟后带”的方法，而不必强求一定要沟通出双方共识的结果。\u003c/p>\u003cp>【学习者案例记录2】\u003c/p>\u003cp>学习者1和学习者2模拟使用“先跟后带”的沟通的方法来尝试进行说服沟通：\u003c/p>\u003cp>学习者1：我和你商量一件事情，你看我们今天的午餐该怎么办？\u003c/p>\u003cp>学习者2：我觉得就到附近吃就行了。\u003c/p>\u003cp>学习者1：那怎么行？肯定不行啊！那么贵，而且我觉得人家会有意见的。\u003c/p>\u003cp>学习者2：是的（跟随），我觉得你考虑的有道理，就近吃的话，可能会比较贵（迎合）…\u003c/p>\u003cp>学习者1：而且这是个承诺问题\u003c/p>\u003cp>学习者2：而且之前已经给过钱了，对他们经理也不是很好哦…\u003c/p>\u003cp>学习者1：关键是我们破坏了承诺，我们不可以破坏承诺。\u003c/p>\u003cp>学习者2：是（跟随），我觉得做人肯定是要有信用的。既然之前答应了他们这样子，那我们也应该这样子（迎合）。不过我考虑到另外一个问题，就是如果我们有另外的办法去做，你觉得什么样的方式可以呢？（尝试带引）\u003c/p>\u003cp>学习者1：我想不出来，我才问你的啊…\u003c/p>\u003cp>学习者2：嗯，这个确实不太好处理（迎合）。那如果想不出来，我们就到附近吃怎么样？\u003c/p>\u003cp>学习者1：问题是我不觉得这是最优的方案，我觉得还是在这里吃，再多定几个不就行了吗？如果时间不行，我们可以等等，给大家作个解释嘛…\u003c/p>\u003cp>学习者2：……\u003c/p>\u003cp>(点评：刚才学习者2的对话已经体现了“先跟后带”的方法，包括说“贵、承诺、满意”等都是在重复对方的关键词和迎合，然后又尝试去带引“你觉得什么样的方式可以呢？”只不过对方又回复了一句“我也不知道才问你的啊”，可以看到你又“跟”了一句“嗯，这个确实不太好处理”，所以从演练“先跟后带”的技巧上，已经很充分了！谢谢。\u003c/p>\u003cp>\u003cbr>（注意根据现场情况，对学习者的回答关联相关知识点，给出赞美）\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":13267,"quote":"\u003cp>&nbsp; &nbsp; 现在相信小伙伴已经感觉到“先跟后带”的沟通方法是很实用的，同时也可能隐约意识到第二步-“迎合”还不好掌握，似乎不够灵活。所以接下来更进一步，我们要学习另外一个拆页，让“先跟后带”方法如虎添翼，更具威力。\u003c/p>\u003cp>&nbsp; 在学习完第二个拆页后，我们将学会使用“上堆下切平行”配合上“先跟后带”，使用“1.跟随-复述关键词、2.迎合-上堆下切平行（这里换了）、3.带引-引领确认”三个步骤来完成一次复杂沟通。\u003c/p>\u003cp>《重塑心灵》p184\u003c/p>\u003cp>在语言沟通中，我们经常会把交谈的方向引向三个方面：\u003c/p>\u003cp>一是弄清楚对方话语的意思，或者在说过的内容里面把焦点调细，把其中的部分放大，就像用小钳把内容的一些资料拣出来，这样的技巧叫作“下切”（chunk-down），NLP的检定语言模式（the meta model of languages）就是一套这方面的技巧；\u003c/p>\u003cp>二是为了建立与对方一致的气氛，用含义更广的词语去暗示意义上的共通，因而建立接受对方和允许对方引导的感觉。因为“意义”存于一个人的潜意识，是很主观和不能尽言的，所以在语言层次取得意义上的一致感觉时，对方会被带到新的思考方向上，这样的技巧叫作“上堆”（chunk-up），NLP的提示语言模式（the Milton model of languages）就是一套这方面的技巧；\u003c/p>\u003cp>三是探索对方说话的意义，因此能引导对方注意到有同样意义的不同可能，找出在同一层次的其他选择，使思想和生活更加丰富，这样的技巧叫作“平行”（parallel）。\u003c/p>\u003cp>以上三个方向的语言技巧，统称为“上堆下切”技巧（chunking），这套技巧的功能是从三个方向（上、下、平行）扩展交谈的涵盖面，使谈论的内容更丰富，效果更理想。\u003c/p>","explains":"\u003cp>[What]当我们在与别人沟通时，在谈话内容的设计上，我们可以通过“上堆下切平行”三个手段，使得谈话内容更细化、抽象或者广泛，使得我们的谈话内容依据一定逻辑框架有序跳转，促使整体沟通更加有效。\u003c/p>\u003cp>[Why]\u003c/p>\u003cp>〈不这样么的坏处〉沟通中表示赞同或者反对是很基础的沟通技巧，但一味赞同有点像PMP，一味反对由会被认为是杠精，更重要的是这样没办法应对更复杂的沟通场景。因为更复杂的场景需要深入的讨论，而且要从不同角度，检视双方的相同以及不同观点，最后创造然后达成共识。\u003c/p>\u003cp>[How]&nbsp;所以我们推荐配合使用“先跟后带”+“上堆下切平行”两个方法，具体的做法是：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>跟随-复述关键。\u003c/strong>和上面的步骤相同，我们首先复述对方言语中的关键词，这些关键词通常是表达事实、评价、情绪、需求的词语。复述可以让对方有被倾听和被尊重的感觉，同时对方也可以回顾他的表达是否准确和充分。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>迎合-上堆下切平行。\u003c/strong>基于刚才的关键词，然后选择进行上堆下切平行中的一种路径，进入深度沟通。\u003c/p>\u003cp>2.1下切：最常用的是要求对方提供对关键词的详细信息。通常的句式是：“你刚才提到的XX是指什么吗？”\u003c/p>\u003cp>2.2上堆：也可以挖掘信息背后的，拔升信息的高度使得它更抽象而且概括。这里可以用的工具是“5Why”法，和“NLP逻辑层次”法，可用的句式是：“为什么你觉得这个很重要？”\u003c/p>\u003cp>2.3&nbsp;平行：也可以在当前谈话的层面引入不同的角度，启发不同的可能。可用的句式是：“除此之外……”或者“还有呢？”\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong>\u003cstrong>带引-引领确认。\u003c/strong>当谈话内容经过一次或多次跳转，双方共同参与，共同贡献有质量的信息，我们及时引领确认使得双方都认可共创的内容及结论，共同完成一次高质量的沟通。\u003c/p>\u003cp>&lt;反例&gt;举个例子，记得有一次我经理突然走到我身边，怒气冲冲地对我说：“小程，项目进度严重落后啊，这样我们根本达不到老板的工期要求，你们工作太不用心了吧！”\u003c/p>\u003cp>当时我已经忙得焦头烂额，再听到经理指责说“太不用心了!”而我昨晚加班到12点多才回家，我一下子就爆了，我就回他说：“这个项目本来工期就不合理，我们已经累成狗了，你要还不满意，那爱怎么办就怎么办吧！”然后一甩手走开了。经理也被我怼得哑口无言，后面几天说话都别扭了。\u003c/p>\u003cp>&lt;正例&gt; 那我如果更成熟一些，使用“先跟后带”+“上堆下切平行”的方法，那我可能会这样来设计沟通路径：\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>跟随-复述关键。\u003c/strong>\u003cstrong>\u003c/strong>我会先留意经理的关键词，比如：事实（项目进度落后、满足不了老板工期要求）、评价（不用心）、情绪（推测是着急？失望？）、需要（他想赶上进度）。\u003c/p>\u003cp>\u003cstrong>2.\u003c/strong>\u003cstrong>迎合-上堆下切平行。\u003c/strong>\u003cstrong>\u003c/strong>假设我选择的谈话大纲切入点是“项目进度落后”，用不同的方向去迎合则会有不同的回应：\u003c/p>\u003cp>2.1下切：“进度落后啊？经理，我对比了计划确实我们落后了1天”\u003c/p>\u003cp>2.2上堆：“经理，进度确实落后了，除了老板看的紧之外，项目满足工期还有什么考虑吗?”\u003c/p>\u003cp>2.3&nbsp;平行：“经理，进度确实落后了，另外老板也提到过，项目质量、使用界面也是他非常关注的。”\u003c/p>\u003cp>\u003cstrong>3.\u003c/strong>\u003cstrong>带引-引领确认。\u003c/strong>\u003cstrong>\u003c/strong>由第二步的讨论我们可能带引到不同的讨论路径和结果。比如1）在下切路径上：经过细致的任务安排，落后的1天后期可以追回；2）在上堆路径上：老板很关心，那我们可以删减一部分功能，满足老板看重工期的要求；3）在平行路径上：通过调整经理的评价标准，由1个增加到3个，改变经理的评价。\u003c/p>\u003cp>这样解释后，大家会不会觉得原来这么复杂的沟通，背后都可以非常逻辑化去组织，这样是不是可以有效改善我们的沟通能力呢？\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>有的伙伴可能会说，这个方法非常结构化但是太复杂啦，但沟通现场没办法那么快地反应啊？\u003c/p>\u003cp>确实，这种沟通方法对于小伙伴们的倾听能力，察觉到对方的关键词，以及相应的设计沟通路径，对逻辑和表达能力的要求是比较高的，仅靠当场即时反应很有难度。但这也正是“先跟后带”方法本身很有威力的原因，所以最好我们对于常见场景，做好事前话术准备，这些都可以帮助我们快速提升这方面的能力。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>不同于漫无边际的闲聊，“先跟后带”+“上堆下切平行”更适用于有目的的沟通说服场景，比如一次销售会谈，一次工作谈话等，所以我们一方面提前准备，另外也随时注意现场互动，是一种非常有威力的沟通技巧。\u003cbr>\u003c/p>","interaction":"\u003cp>&nbsp; 为了能够让大家在现场就能够掌握“先跟后带”+“上堆下切平行”的沟通技巧，现在请大家阅读一段对话，请思考小贩的沟通路径和技巧，填充并和同组小伙伴分享，时间6分钟。\u003c/p>\u003cp>有这么一个老太太，她去菜场买水果，她来到一个小贩的水果摊前，问“这李子怎么样？”\u003c/p>\u003cp>“老太太您好，来买李子啊，您想买哪一种李子呢？”小贩没有急着回答问题，而是问起了问题。（小贩这里使用了什么技巧： &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;）\u003c/p>\u003cp>“我要酸一点儿的。”老太太说。\u003c/p>\u003cp>“其他人买李子都要又大又甜的，您为什么要买酸李子呢？”小贩接着问。（小贩这里使用了什么技巧： &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;）\u003c/p>\u003cp>“我儿媳妇要生孩子了，想吃点儿酸的。”老太太回答道。\u003c/p>\u003cp>“哎呀，恭喜您马上要当奶奶了！”小贩连连道喜，“您对媳妇儿真体贴啊，她想吃酸的，肯定能给您生个大胖孙子。您要买多少？”（小贩这里使用了什么技巧： &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;）\u003c/p>\u003cp>“我再来一斤吧。”老太太被小贩说得很高兴，又买了一斤李子。\u003c/p>\u003cp>小贩一边称李子，一边继续和老太太聊：“孕妇怀孕很辛苦，最需要营养了，平时要多补充点维生素，多吃水果。您知道什么水果维生素最丰富吗？”（小贩这里使用了什么技巧： &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;）\u003c/p>\u003cp>“不清楚。”\u003c/p>\u003cp>“猕猴桃富含很多种维生素，特别适合孕妇，您看要不要也来点儿？”小贩接着问。（小贩这里使用了什么技巧： &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;）\u003c/p>\u003cp>“是吗？那我就再来一斤猕猴桃吧。”\u003c/p>\u003cp>“您可真是一位好婆婆，您媳妇儿真是有福气。”小贩一边称猕猴桃，嘴里也不闲着，“我天天都在这摆摊，水果都是当天从批发市场精挑细选的，又新鲜，营养又丰富。今天进货的香蕉也很好，对胎儿的神经发育有好处，要不也买点尝尝吧？”（小贩这里使用了什么技巧： &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;）\u003c/p>\u003cp>“行！就这扎吧”老太太被小贩夸得很高兴，一边掏钱，一边满口答应着。\u003c/p>\u003cp>现在有请一位小组为我们分享，他们对小贩每句话的拆解，共5分钟（含点评）。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>“老太太您好，来买李子啊，您想买哪一种李子呢？”小贩没有急着回答问题，而是问起了问题。（小贩这里使用了什么技巧：学习者1:先跟-下切）\u003c/p>\u003cp>“我要酸一点儿的。”老太太说。\u003c/p>\u003cp>“其他人买李子都要又大又甜的，您为什么要买酸李子呢？”小贩接着问。（小贩这里使用了什么技巧：学习者2 ：上堆，了解动机的部分，夸奖学习者掌握精准）\u003c/p>\u003cp>“我儿媳妇要生孩子了，想吃点儿酸的。”老太太回答道。\u003c/p>\u003cp>“哎呀，恭喜您马上要当奶奶了！”小贩连连道喜，“您对媳妇儿真体贴啊，她想吃酸的，肯定能给您生个大胖孙子。您要买多少？”（小贩这里使用了什么技巧：学习者3:跟随。点评和讨论）\u003c/p>\u003cp>“我再来一斤吧。”老太太被小贩说得很高兴，又买了一斤李子。\u003c/p>\u003cp>小贩一边称李子，一边继续和老太太聊：“孕妇怀孕很辛苦，最需要营养了，平时要多补充点维生素，多吃水果。您知道什么水果维生素最丰富吗？”（小贩这里使用了什么技巧：学习者4:下切。点评其实也用了一个逻辑跳转，首先是平行+下切）\u003c/p>\u003cp>“不清楚。”\u003c/p>\u003cp>“猕猴桃富含很多种维生素，特别适合孕妇，您看要不要也来点儿？”小贩接着问。（小贩这里使用了什么技巧：学习者1:从含维生素丰富的水果下切到猕猴桃）\u003c/p>\u003cp>“是吗？那我就再来一斤猕猴桃吧。”\u003c/p>\u003cp>“您可真是一位好婆婆，您媳妇儿真是有福气。”小贩一边称猕猴桃，嘴里也不闲着，“我天天都在这摆摊，水果都是当天从批发市场精挑细选的，又新鲜，营养又丰富。今天进货的香蕉也很好，对胎儿的神经发育有好处，要不也买点尝尝吧？”（小贩这里使用了什么技巧：学习者2:平行）\u003c/p>\u003cp>“行！就这扎吧”老太太被小贩夸得很高兴，一边掏钱，一边满口答应着。\u003c/p>\u003cp>（问题交流，学习者提出了刚才猕猴桃的下切的逻辑分析，做了确认。另外一个学习者对“跟随”作了表述上的区分，一种是完全的重有字眼，另外一种是用相同的意思再重新表达。号召大家给自己鼓掌~~）\u003cbr>\u003c/p>\u003cp>【分步催化1，5分钟】那接下来我请大家和我一起想象一个对你很常见的场景，而且很有可能它会在未来两周再次发生。这个场景可能是：孩子刚考了一个很差的成绩，现在放学回来请你在成绩单上签字；同事向你抱怨领导最近给他的工作太多，压力山大；爱人双11剁手买了一样你不赞成买的东西，现在收到货了，你看到就心塞，准备和爱人认真地谈一谈。\u003c/p>\u003cp>请你认真想想那是什么场景，你这次沟通的目标是什么？然后花2分钟在小组内分享。然后我将请小伙伴来做分享。强调一下，只需分享你可能遇到的场景，不需要涉及如何沟通。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者2:我现在带班的有一个班长，其他班委就给我反映他的情况说，班长参加了很多社团，所以没有时间关注班里，导致班里的活动没有人组织，计划做一次沟通。因为班长想做的事情太多，导致班里的向心力受到影响，希望通过谈话尝试说服班长，一方面不伤害他的自尊心，一方面说出问题，希望能够讨论出解决方案。\u003c/p>\u003cp>【分步催化2，7分钟】好的，刚刚大家已经想好了那个未来场景，我们大家一起根据刚才设定的场景，应用“先跟后带”+“上堆下切平行”的方法来作一次模拟对话，提醒大家注意的是，我们主要还是演练技巧，不强求一定要达成圆满的解决方案和沟通结果。\u003c/p>\u003cp>学习者案例记录\u003c/p>\u003cp>第一次沟通模拟：\u003c/p>\u003cp>学习者2（老师）：刘班长，你最近是不是很忙啊？\u003c/p>\u003cp>学习者1（班长）:还好。\u003c/p>\u003cp>学习者2（老师）：但是我发现有些同学给我反映说，最近班上的活动比较少，你能不能告诉老师你最近在忙些什么呢？\u003c/p>\u003cp>学习者1（班长）:最近参加了一些社团的活动。\u003c/p>\u003cp>学习者2（老师）：就是你觉得社团的活动和班上的活动能不能整合一下？就是放在一起？\u003c/p>\u003cp>学习者1（班长）:时间地点都不大一样，估计不大好放在一起。\u003c/p>\u003cp>（拆书家点评：请注意先跟后带，否则谈话路径会越来越远）\u003c/p>\u003cp>学习者2（老师）：哦，可能比较确实难配合得上，但是目前班上的凝聚力低，也是一个实际的问题，作为班长和我作为老师，都想去解决这个问题，你觉得有什么更好的办法来改变这个状况呢？\u003c/p>\u003cp>学习者1（班长）:嗯，现阶段还好啊，我觉得这边参加了活动，班里的还是有兼顾的，还是可以处理好的。\u003c/p>\u003cp>学习者2（老师）：…嗯，很难啊，我谈不下去了（面向大家）\u003c/p>\u003cp>暂停，拆书家点评要点：谈话还是比较“各说各话”，老师觉得有问题，但同学并不这么认为，所以需要留意使用“先跟后带”的方法，另外使用下切来具体落实行动，用上堆来统一目标，用平行来加入更广泛的话题，这样可以更加同频，更加亲和。\u003c/p>\u003cp>第二次沟通模拟：\u003c/p>\u003cp>学习者2（老师）：班长你好，因为前段时间开了一个班会，了解到一些情况，问一下你目前觉得我们班里的怎么样的？\u003c/p>\u003cp>学习者1（班长）:班里的学习情况还可以，积极度还有待提高一些。\u003c/p>\u003cp>学习者2（老师）：那你最近有没有一些想法可以提高班级成员的积极性？\u003c/p>\u003cp>学习者1（班长）:有啊，在后边我们可以再组织一些活动？\u003c/p>\u003cp>学习者2（老师）：活动有具体的时间吗？\u003c/p>\u003cp>学习者1（班长）:这个等我们手头上的事情忙完了，可以再计划。\u003c/p>\u003cp>学习者2（老师）：嗯，你手头上目前有很多事情，是吧？\u003c/p>\u003cp>学习者1（班长）:现在主要参加了一些社团活动，所以会忙一些。\u003c/p>\u003cp>学习者2（老师）：对对，现在学校的社团活动也很丰富，而且也可以锻炼自己的成长。那你觉得在这方面，有没有可能把你在社团的一些经验，变成我们班级的活动，带动我们班级同学一起去参与到有意义的活动中去呢？\u003c/p>\u003cp>学习者1（班长）:后边肯定有一些可以结合的，现在先学习一些经验嘛\u003c/p>\u003cp>学习者2（老师）：对对，你在社团的经验与班的结合起来，也可以锻炼到你的能力，对吧？\u003c/p>\u003cp>学习者1（班长）:对的，对的。\u003c/p>\u003cp>学习者2（老师）：那目前我们想要具体的把时间落实下来，让我们的行动更有步骤一些，是不是？我们经常在这方面锻炼时候，我们也可以考虑到自己的能力和效率，我们能不能再进一步再细化一些？\u003c/p>\u003cp>学习者1（班长）:现在确实忙一些，过一段时间可以计划一下。\u003c/p>\u003cp>学习者2（老师）：嗯，估计多长时间呢？\u003c/p>\u003cp>学习者1（班长）:我估计…再过两个月左右\u003c/p>\u003cp>学习者2（老师）：可以，可以。\u003c/p>\u003cp>拆书家点评：这段谈话来看，前面几句老师还有有些“步步紧逼”，但从第五句开始，老师开始用“跟”，重复班长的一些关键词，相应的氛围真的有很多扭转，后边在时间等方面还是“部分”达成了共识，这一点来说还是非常棒的。当然技巧还有比较复杂，学生也比较坚持，所以还希望大家多练习。\u003c/p>\u003cp>【有力的总结语】\u003c/p>\u003cp>时间过得好快，感谢伙伴们的全情投入和积极分享。我们最后总结一下，今天我们主要学习了“先跟后带”的方法，是一个组合的方法，先跟后带，加上“上堆下切平行”的方法，让我们可以有目的，有逻辑，有计划地组织一个复杂的沟通。当我们使用比较灵活的时候，谈话的内容可上天，可入地，可平推，谈话的路径和范围非常灵活，手段也更加的有效。所以希望大家都能够掌握这个方法，象李中莹老师说的，可以让生活更加的成功快乐，谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1576223697000,"updated_at":1576223697000,"ria":true},{"id":8085,"topic":"意义换框法来处理负面经验","learn_goal":"使用意义换框法来在负面事件中发现积极意义","remark":"本次分享拆页来自于《重塑心灵》，作者李中莹先生华人世界研究NLP（身心语言程序学）的大师，书中的“意义换框法”通过“反果转因”的方法强迫我们探索事件的多种意义，让我们尝试从不同的“框”解读我们周围的世界，是很实用的一个方法。","level":"TF1-2","duration":15,"status":29,"type":0,"chaishujia":{"username":"乘风","city":"广州市"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; \u003cstrong>&nbsp;[分组及自我介绍]&nbsp;\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;大家好，我是老程，首先请大家分成4个小组，为保证各小组的背景均衡，请各位已经了解NLP，或者读过《重塑心灵》这本书的朋友配合一下，分散在各小组，谢谢。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;然后我用三个标签法介绍自己：\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;1）2020年的三级拆书家，这是我的个人目标；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;2）中层管理者职业精进探索者，我比较关注如何促进中层管理者全面成长的理论及落地方法；\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;3）价值链接者，做一个在链接中传递价值的人。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\u003cstrong>[图书介绍]&nbsp;\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;今天我们的片断来自于《重塑心灵》，作者李中莹先生是华人世界研究NLP（身心语言程序学）的大师，这本书浅显易懂，全面讲解了NLP的基础概念，被大家称为NLP世界的入门书。就象书的封面所讲“每个人都拥有让自己成功快乐的能力”，精读这本书可以改变我们的思维、格局和认知高度，所以强烈向大家推荐。本次分享的意义换框法是书中的一个实用小方法。\u003c/p>","ratings_count":2,"texts":[{"id":11678,"quote":"\u003cp>现在请大家阅读手中的拆页，读完后举手示意一下，谢谢！\u003c/p>\u003cp>《重塑心灵》李中莹 P49-50\u003c/p>\u003cp>意义换框法\u003c/p>\u003cp>“意义换框法”是NLP技巧“换框法”中最常用和最好用的技巧。它完全只凭言语和思想模式而产生效果，是NLP的改变信念技巧中最快速最容易的一个。“意义换框法”是找出一个负面经验中的正面意义。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都只是人加诸的。既然是人加上去的意义，则一件事情——\u003c/p>\u003cp>◇可以有其他的意义，也可以有更多的意义；\u003c/p>\u003cp>◇可以有不好的意义，也可以有好的意义。\u003c/p>\u003cp>……\u003c/p>\u003cp>同一件事情里面总有不止一个意义包含其中。找出最能帮助自己的意义，便可以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。\u003c/p>\u003cp>意义换框法对一些因果式的信念最为有效。例如：“因为上级挑剔，所以我工作不开心。”\u003c/p>\u003cp>方法是把句中的“果”（工作不开心）改为它的反义词，再把句首的“因为”二字放到最后，成为：“上级挑剔，所以我工作积极，因为……”然后反复地思考如何能把句子写完，要求至少有六个不同的版本，再找出其中最能够接受的一句。以下是一些学员的杰作：“上级挑剔……”\u003c/p>\u003cp>◇使他无从挑剔\u003c/p>\u003cp>◇使我提升得更快\u003c/p>\u003cp>◇使他改变对我的态度\u003c/p>\u003cp>◇使我超越他的标准\u003c/p>\u003cp>◇使我变得更能干\u003c/p>\u003cp>◇使我更快升级，脱离他的管治\u003c/p>\u003cp>◇使我更有能力去另找新工作\u003c/p>","explains":"\u003cp>[why]有时难免我们走入了思维的盲角，百思不得其解，轻者只是短期影响到工作、生活和家庭，严重的话甚至会产生后悔一生的遗憾和伤害，但如果我们有一个好的方法来处理这些负面经验，则会很快走出困境。\u003c/p>\u003cp>[what]这段拆页介绍的“意义换框三步法”让我们从不同角度，察觉事件的不同意义，从而跳出思维的限制“框”\u003c/p>\u003cp>[where &amp; when]这个方法对于困果式负面思维，比如原文的“因为上级挑剔，所以我工作不开心”是最见效的。\u003c/p>\u003cp>[how]具体来说：\u003c/p>\u003cp>\u003cstrong>第一步，倒结果。\u003c/strong>接受原来的原因部分如“上司挑剔”，同时彻底颠倒转换原来的结果部分，如把“我不开心”替换为“我积极工作”\u003c/p>\u003cp>\u003cstrong>第二步，找新意。\u003c/strong>重新探索这个事件可以带来的不同意义，个人建议找出至少3个。比如上文中的“使我更有能力去另找新工作，使他改变对我的态度，使我变得更能干”等\u003c/p>\u003cp>\u003cstrong>第三步，定新框\u003c/strong>。比较选择其中最能打动内心的一个，组合整句即为新“框”。在上例中即为“上级挑剔，所以我工作积极，因为我更有能力去另找新工作”。\u003c/p>\u003cp>这里再举两个例子。\u003c/p>\u003cp>一个是最近美国打压中国高科技企业的例子，联想公司的解读“框”是：“美国可能会针对联想，所以联想很麻烦”而华为公司的则有很大不同：“美国可能会针对华为，所以华为要主动，因为正好有动力开始研发自主产权的芯片和操作系统以备万一”\u003c/p>\u003cp>&nbsp;&nbsp;另外一个是我本人的例子。我原来就觉得“因为老婆要求我提前报备是不是回去吃晚饭，所以每次约饭我在朋友前特别没面子”，后来用“意义换框法”再想想，就变成了“老婆要求我提前报备是不是回去吃晚饭，所以每次约饭我在朋友前特有面子，因为表示家里老婆很关心我/因为我很晚回去，孩子作业的事也都安排好了/因为有紧急的事，老婆还可以找到我或者同行的人”\u003c/p>","interaction":"\u003cp>\u003cstrong>【A1】\u003c/strong>\u003c/p>\u003cp>好，下面我们以小组形式，先请大家自己联想过去经历的某个“想不开”时刻，在便笺纸上用“因为…所以…”格式写下最初的想法，然后继续尝试用“倒结果、找新意、定新框”三步法扭转思路。写完后请读一下，并感受一下你的心情。\u003c/p>\u003cp>总时间控制为5分钟，建议花1分钟左右自己尝试，然后每人1分钟在组内分享,互相反馈。\u003c/p>\u003cp>\u003cem>学习者记录：\u003c/em>\u003c/p>\u003cp>学习者1记录:&nbsp;\u003c/p>\u003cp>原：因为老板要求很过分，所以我把他炒了。换：因为老板要求很过分，所以我要继续跟他干，因为我可以提高能力；\u003c/p>\u003cp>学习者2记录:&nbsp;\u003c/p>\u003cp>原：因为工作比较忙，所以没时间看书。换：因为工作比较忙，所以要用更多的时间看书，这样就会提升能力，让自己的工作不再那么忙。\u003c/p>\u003cp>\u003cstrong>【A2】\u003c/strong>\u003cbr>\u003c/p>\u003cp>&nbsp;&nbsp;好的方法更值得我们多加练习。现在请大家计划在将来两周内某事件中应用。想一下你会怎么设计“倒结果、找新意、定新框”三步走？请把要点写在发给你的拆页或便签上。&nbsp;\u003c/p>\u003cp>&nbsp; \u003cem>学习者3记录\u003c/em>：\u003c/p>\u003cp>l&nbsp;&nbsp;事件（原框）：因为（工作很闲）\u003c/p>\u003cp>所以（我很焦虑）\u003c/p>\u003cp>l&nbsp;&nbsp;新框：\u003c/p>\u003cp>n&nbsp;&nbsp;倒结果：（工作很闲），所以（我很开心）\u003c/p>\u003cp>n&nbsp;&nbsp;找新意：1）我有更多时间做一下总结：2）有时间学习新的技能；3）有时间享受一下生活；\u003c/p>\u003cp>n定新框：（工作很闲），所以（我很开心），因为我有时间学习新的技能\u003c/p>\u003cp>[结束语]\u003c/p>\u003cp>让我们回顾一下，今天我们一起学习了“意义换框法”，通过“倒结果、找新意、定新框”三步走，换个角度解读一个负面的经验或事件，找到它正面和成长的部分。山重水复疑无路，柳暗花明又一村，愿各位都用这个方法，少点皱纹，多些欢笑！谢谢大家！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1559656402000,"updated_at":1571213144000,"ria":true},{"id":7902,"topic":"如何提升沟通力","learn_goal":"让大家知道沟通的定义能够解决沟通出现的分歧","remark":"通过学习沟通的定义和回应的技巧，能够提升沟通的意愿。","level":"TF3-3","duration":60,"status":30,"type":0,"chaishujia":{"username":"CoCo陶可可","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"大家好，我是今天的拆书家陶可可。\r\n我是一名沟通爱好者，现在在华南理工大学进修管理沟通相关专业。从事的工作涉及商务谈判、客户沟通等等。\r\n我曾经因为有效的沟通帮自己赢得了人生的第一桶金，5000元。\r\n跟着我一起学习关于沟通的内容，大家可以学到我的实际经历与理论相结合的超值内容。\r\n再次欢迎大家的到来。\r\n【分组】\r\n首先，非常感谢大家今天来参加拆书活动，j今天现场有15个人，那么请大家三人为一小组，自由组合。 \r\n好的，大家都找到自己小组了吗？\r\n图书介绍（2分钟）\r\n【图书介绍-学习者场景法】\r\n事件：\r\n不知道大家有没有遇到这样的经历，你内心深处一直很喜欢一个男生，你会经常去看他的微博，去看他的朋友圈。但是，你从来没有告诉过他。你也不知道他喜不喜欢你。就这样到了某一天，你刷朋友圈时看到他发了一张结婚的朋友圈，你才得知：他有女朋友了。\r\n提问： \r\n请问各位，你们在从小到大的人生中，有遇到过像这样或许不自信、或许因为胆小而不敢开口的情况吗？ 你们当时是什么感受呢？ \r\n（学习者互动反馈：扎心，遗憾）\r\n通常情况下，我们遇到喜欢的人的应对方式可能是“咱也不敢问，咱也不敢说”，然后数年以后回忆起来，可能会后悔。\r\n影响：\r\n所以，大家看，无论是在工作中，还是生活里，我们如果不善于沟通，或者不及时沟通，那么随之而来的有可能是错过了一段美好的爱情，也有可能导致一场误会、带来一段冷战，让人际关系走下坡路。\r\n解决：\r\n这本《重塑心灵》认为，通过改善沟通方式，可以提升沟通能力，让人际关系更和谐。书中的关于沟通的定义以及如何在遇到分歧时进行回应的步骤，经过我的实践运用，我认为，可以解决我们沟通的大部分难题，甚至比我们想象的更好，非常有价值。\r\n学习目标（总）\r\n我们今天的学习目标是，通过2个片段的学习，希望大家可以辨认什么是有效的沟通，以及使用“沟通前奏三部曲”提升沟通意愿。并且在沟通中遇到误会时可以采用“回应三步骤”的技巧，降低沟通发生误会的概率，从而帮助我们达到沟通的目的，为自己赢得友好的人际关系。","ratings_count":1,"texts":[{"id":11450,"quote":"\u003ch3>R1学习目标（0.5分钟）\u003c/h3>\u003cp>今天第一个拆页是关于沟通的，学习目标是希望大家在跟随我完成RIA现场学习后，可以辨认什么是沟通，以及可以使用“沟通前奏三部曲”提升自己沟通的意愿，让自己和对方有话说。\u003c/p>\u003ch3>【R】阅读原书拆页（2分钟）\u003c/h3>\u003cp>\u003cstrong>《重塑心灵》P172\u003c/strong>\u003c/p>\u003cp>“沟”者渠也，“通”者连也，“沟通”本身的意思是借助某种渠道使双方能够通连。\u003c/p>\u003cp>&nbsp;&nbsp; 在小说中常常可以读到这样的故事：一男一女，于风华正茂时一见倾心，情愫暗生。但因着矜持与羞涩，或者世俗的牵扯阻碍，犹疑着，酝酿着，那纯真而隐晦的爱意，终只是在眉梢眼角轻轻流露，\u003cstrong>并没有开口说出\u003c/strong>。然后阴错阳差间，大家已各奔东西，听任流年似水时光逝去，多年后在异地他乡两人不期而遇时，已是鬓丝如霜，各有各的曲折，各有各的悲哀——于是把盏话沧桑。酒过三巡，醉意稍甚的一方突然涩涩开口：当年，其实深爱过你。另一方也只是眼神凄柔地沉默以对。其实这么多年过去，世事早已尘埃落定，说不说出，都是云淡风轻了。但当年的一句话，也许可以重写两个人的生命。\u003c/p>\u003cp>&nbsp;&nbsp; 爱要说出口，任何一种沟通其实都是如此。对方是否是这个意思或者已否明白你的心意，只有对方才能决定。不要假设，若不肯定，\u003cstrong>找他谈淡\u003c/strong>。\u003c/p>\u003cp>&nbsp;&nbsp; 人间充满因为猜疑别人的想法和不肯明白表达自己的意思而引起的误会和悲剧，不信的话，你不妨看看《家》《春》《秋》或者任何一部文艺作品，也可以留心你每晚收看的电视剧，还可以注意你的朋友之中曾经出现过的纠纷，看看你可以找出多少个例证。\u003c/p>\u003cp>&nbsp;&nbsp; 在人与人之间的关系中，可以减少的假设便应尽量减少。大部分人都同意夫妻之间可无事不谈，但是，很多夫妻很少分享内心的感受，有什么不满意都只是隐藏在心里，要对方瞎猜。夫妻都是这样，家人、同事、朋友更不用说了。\u003c/p>\u003cp>&nbsp;&nbsp; 中国人的传统思想中讲究修养，做人要含蓄、内敛，往往使人不谈心中不快的事。其实真正上乘的修养，是心中没有不快的事。既然有了，面对它，积极和善意地处理、化解它才是正确的做法。人间已经太多因为小小的误会而引起的困扰、悲剧，甚至一生的折磨。为自己做点好事，不要再猜臆别人内心的看法或感受，去找他谈谈吧。多尊重别人一些，问问他的内心真实的想法吧。\u003c/p>","explains":"\u003ch4>【强化概念讲解（举例与对比）】\u003c/h4>\u003cp>在这个拆页中，我们看到了和“沟通”有关的描述。\u003c/p>\u003cp>那么根据这个拆页，什么才是沟通呢？\u003c/p>\u003cp>e.g.1\u003c/p>\u003cp>我看到安迪听我的拆书时脸色很不好，我就笃定他肯定不喜欢我的拆书。决定再也不理他了，微信拉黑，电话也拉黑。总之，就是不要再让生活里再出现这个人。\u003c/p>\u003cp>大家觉得这做到了沟通吗？\u003c/p>\u003cp>（学习者反馈：没有）\u003c/p>\u003cp>没做到。是的，我们一个人自己自己的“臆想”，不叫沟通。一般来说，沟通是一个双向互动的过程，至少要有一个沟通对象。\u003c/p>\u003cp>e.g.2\u003c/p>\u003cp>我想让领导给我涨工资，于是在周一公司开完例会的时候，我跑到他的办公室，去谈加薪。最后被批评了一顿，搞得我很受伤。\u003c/p>\u003cp>大家觉得这个问题出在哪里呢？\u003c/p>\u003cp>（学习者反馈：时机不对）\u003c/p>\u003cp>是的，没有。场合没选好。其实沟通一般是需要选择适合的场景。周一大家都是开完例会，非常忙碌的时候，你不在好好上班却和领导谈加薪，这个会导致领导觉得你很自私，没有奉献精神。\u003c/p>\u003cp>e.g.3 \u003c/p>\u003cp>狐狸和兔子在一起很久了，但他们经常因为一些小事吵架。比如狐狸不洗澡了，兔子就说，你这个臭人，我要跟你分手。直到有一天狐狸说，“哼，分就分。”，他们就真的分手了。\u003c/p>\u003cp>大家觉得，狐狸和兔子的这个对话是沟通嘛？\u003c/p>\u003cp>（学习者反馈）\u003c/p>\u003cp>不是。沟通一般是需要传递有效的信息。而在这对话中，其实兔子是不想分手的，她只是想狐狸能够改变习惯而已。却因为没有表达出有效的信息，导致两个动物走向分手。就像拆页里说的，“爱就要说出口。”两个人在一起，“爱”就是你们之间可以传递的有效信息。\u003c/p>\u003cp>所以，我们根据拆页总结出，沟通的定义是，两个人或者多人在适合的场景下传递有效的信息。\u003c/p>\u003ch4>【行动建议】\u003c/h4>\u003cp>同时，我们从“沟通”的定义和要点也可以得出，当我们要去开展沟通的时候，有这三个步骤需要做好准备：\u003c/p>\u003cp>第一步，明确沟通对象。\u003c/p>\u003cp>第二步，选择适合场景。\u003c/p>\u003cp>第三步，表达有效信息。\u003c/p>\u003cp>为了便于记忆，我们可以把它称作“沟通前奏三部曲”。\u003c/p>\u003ch4>【自己的例子】\u003c/h4>\u003cp>e.g.4 \u003c/p>\u003cp>这样听起来还是有点抽象，我来举一个自己的例子。\u003c/p>\u003cp>一年一度的普遍调薪时候到了。涨是都会涨，但是涨额是我们每个人可以去争取的。那么对我来说，也肯定不能放过啦！既然我要去沟通加薪，那么我就要进入“沟通前奏三部曲”了。\u003c/p>\u003cp>第一步，明确沟通对象。\u003c/p>\u003cp>谈加薪，在我们公司，加薪是先找领导谈。有的公司是找人力资源部门，当然这个有所不同。总之我先明确了沟通对象是我的领导。\u003c/p>\u003cp>第二步，选择适合场景。\u003c/p>\u003cp>紧接着到了第二步，选择适合的场景。我设想的是在一个悠闲的午后拿着一杯咖啡去找他谈加薪，他喝着我的咖啡，果断的同意了。这个是我的幻想。书面场景还是口头场景？正式场合还是非正式场合？星期一谈还是星期四谈？\u003c/p>\u003cp>经过一系列的考量，我觉得这个要当面说比较好。一来，表示态度诚恳，二来展示自己的表达能力。确定了当面说这个场景，我接下来要去约领导时间了。\u003c/p>\u003cp>我选择了周四的下午不太忙碌的时候去找他谈。一般到了周四大家工作都忙得差不多属于比较悠闲的状态，这样比较好进入加薪的话题。\u003c/p>\u003cp>第三步，表达有效信息。\u003c/p>\u003cp>去谈加薪，需要表达哪些有效的信息呢？\u003c/p>\u003cp>比如，\u003c/p>\u003cp>领导，您看，这是我2018年的工作业绩业绩，\u003c/p>\u003cp>领导，我未来给公司带来的价值会更大，包括我能够培训实习生，快速复制我的能力，帮助公司提升效率。\u003c/p>\u003cp>……\u003c/p>\u003cp>好的，这些有效信息我是肯定要表达的。接下来我就满怀信心地去找领导了，当然最后也是谈成了加薪。领导说，你这么多年在公司真的很认真负责，他还对我说了声谢谢。\u003c/p>\u003cp>这个经历让我更加觉得沟通是一件需要好好准备的事情。\u003c/p>\u003ch4>【预防异议】\u003c/h4>\u003cp>有人会好奇，沟通前一定要遵循这三个步骤吗？其实取决于你当时所处的一个环境。比如，在一些很紧急的时候，比如遇到生命危险的时候，我们可能没有办法一下子明确沟通对象是谁，也顾不上去想场合是否合适，就需要立即找到人。那么这个时候就不用考虑严格遵循这三个步骤，救命要紧。\u003c/p>\u003ch4>【适用边界】\u003c/h4>\u003cp>“沟通前奏三部曲”适用于所有的场景吗？其实也不是。在一些比较正式的场合，我们认为有必要作沟通准备的时候，那么就需要做一下“沟通前奏三部曲”。而在一些比较生活化的场合中，我们往往是你一句我一句的闲聊，那么就没有必要使用“沟通前奏三部曲”。\u003c/p>","interaction":"\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>【编写剧本】\u003c/p>\u003cp>那么我们学习了“沟通前奏三部曲”之后，接下来我们一起做一个编写剧本的练习，帮助我们巩固一下刚刚学习的内容。\u003c/p>\u003cp>请大家想象一下，未来，你自己本人在哪些场景可能运用到“沟通前奏三部曲”的场景？\u003c/p>\u003cp>比如，工作中，你需要去找人力资源部门同事谈一下给组织扩编的事情；想跟行政部门多申请几个办公文具，……\u003c/p>\u003cp>接下来请大家想象一下，未来你自己本人在哪个场景你会用到“沟通前奏三部曲”？\u003c/p>\u003cp>我来具体说一下设计剧本的要求：\u003c/p>\u003cp>1、这是一个对话，对话包括事件、背景和人物，以及起因、经过、结果；\u003c/p>\u003cp>2、解决问题的方法中使用了沟通三个步骤，最后变成一个成功地解决了你自己问题的剧本。\u003c/p>\u003cp>时间3分钟，3分钟后，我们请一个学习者来分享他的剧本。这是待会儿可以用到的道具，一只公仔是你的倾听对象，一只公仔是你，来辅助你演绎你的剧本。\u003c/p>\u003cp>请问，我的表达足够清晰吗？\u003c/p>\u003cp>（发放剧本卡片）\u003c/p>\u003cp>小伙伴已经写完了，哪位愿意分享一下你的对话呢？\u003c/p>\u003ch4>学习者案例记录：\u003c/h4>\u003cp>现场学习者@小玉：\u003c/p>\u003cp>我自己未来在______向喜欢的男生表白的时候______场景会用到“沟通前奏三部曲”。\u003c/p>\u003cp>一、事件背景：_______我暗恋一个男生很久了，一直想告诉他我喜欢他________。\u003c/p>\u003cp>二、人物：我自己本人，那个男生。\u003c/p>\u003cp>三、起因：_我觉得自己年纪也不小了，然后也难得遇到一个喜欢的男生。所以就想表白试试看。\u003c/p>\u003cp>四、经过（使用“沟通前奏三部曲”）：\u003c/p>\u003cp>第一步，明确沟通对象。___是这个男生_______；\u003c/p>\u003cp>第二步，选择适合场合。___一个餐厅里，是午后_________；\u003c/p>\u003cp>第三步，表达有效信息。____我喜欢你，希望我们能够在一起试试________。\u003c/p>\u003cp>五、结果\u003c/p>\u003cp>可以知道他对我的感觉是什么，得到一个反馈。这是我想要的结果，这样去沟通的话，其实要比一直放在心里不敢说要好多了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":11451,"quote":"\u003ch3>【AI】请大家自测（2分钟）\u003c/h3>\u003cp>【拆书家提问设计（逐字稿），发放自测题】\u003c/p>\u003cp>【过渡】\u003c/p>\u003cp>我们前面已经学习了“沟通前奏三部曲”，那么在实际的沟通的过程中，双方往往可能会产生分歧，比如我不认可你，或者他不认可我。这个时候就需要一方有所回应。我们接下来就一起来学习让沟通更加顺畅的回应技巧。\u003c/p>\u003ch3>【R2学习目标】（0.5分钟）\u003c/h3>\u003cp>好的，接下来我们进入第二个片段的学习环节。\u003c/p>\u003cp>在阅读拆页前本环节的学习目标是，希望大家能够在与人沟通中出现分歧的时候，能够使用“回应三步骤法”来进行沟通，降低沟通信息传递的误差度，帮助我们达到沟通的目的，为自己赢得友好的人际关系。\u003c/p>\u003cp>接下来，我给大家发一个测试题，请大家根据自己的实际情况，对照自己平时的做法，然后进行打分。“1分”代表完全不符合，“6分”代表非常符合，打完分以后请大家统计一下自己获得的总分。\u003c/p>\u003ch4>发放自测题\u003c/h4>\u003cp>1. 沟通出现分歧时，我回应别人从不用敌对情绪。（1）（2）（3）（4）（5）（6）\u003c/p>\u003cp>2. 沟通出现分歧时，我回应别人总是能够找到替换方案化解分歧。（1）（2）（3）（4）（5）（6）\u003c/p>\u003cp>3. 沟通出现分歧时，我回应别人都会尊重对方的感受。（1）（2）（3）（4）（5）（6）\u003c/p>\u003cp>4. 沟通出现分歧时，我回应别人都会及时调整方向获取更多信息。（1）（2）（3）（4）（5）（6）\u003c/p>\u003cp>5. 沟通出现分歧时，我回应别人的谈话氛围总是很愉悦。（1）（2）（3）（4）（5）（6）\u003c/p>\u003ch3>【I】解释自测题（2分钟）\u003c/h3>\u003cp>这个自测表主要是测试大家在沟通出现分歧的过程中“回应”的质量，请问大家的合计分数是多少呢？有没有超过20分的小伙伴？\u003c/p>\u003cp>（学习者反馈：5个）\u003c/p>\u003cp>有低于20的小伙伴吗？\u003c/p>\u003cp>（学习者反馈：9个）\u003c/p>\u003cp>分数大于20分的小伙伴，祝贺你们，已经能够在沟通中很好地进行高质量的“回应”了。\u003c/p>\u003cp>少于20分的小伙伴也不要有压力，我们今天就是一起来学习回应的技巧。 \u003c/p>\u003cp>当然这只是一个精简的小测试，仅供大家参考，量表的测试结果无关好坏，只是来帮助我们更好的了解我们的现状，分数低的也不需要灰心，今天我们所拆解的内容就可以帮助大家改进我们回应的质量。\u003c/p>\u003ch4>【过渡到阅读拆页】\u003c/h4>\u003cp>通过自测环节，我们对沟通中的回应有了一些认识。\u003c/p>\u003cp>接下来请大家花2分钟的时间，阅读我发给大家的拆页内容，完成后请抬头示意我一下，谢谢！\u003c/p>\u003ch3>【R】阅读原文拆页（2分钟）\u003c/h3>\u003cp>【阅读拆页】\u003c/p>\u003cp>《重塑心灵》P180\u003c/p>\u003cp>理查德·班德勒曾经说过，当你对别人说话时，你不是给他一些信息便是在改变他。文字的运用，对话时所用的语言，对沟通的效果也有很大的决定作用。同样的意思，不同的人去说，或者同一个人用不同的词语、顺序表达出来，效果会有很大差别。要达成好的沟通效果，就要讲究语言的技巧。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 做保险工作的林小姐被大家公认为“很会讲话”的人，很多朋友愿意同她交谈，把心里话说给她听，也愿意听她的意见，很少见她和什么人发生争执、吵嘴等。工作时经常有人毫不留情面地跟她说：“保险浪费金钱！”有时她这样说：“看来你是同意应该为家庭设立保障的，你现在用的是什么方法？”有时她又这样回应：“浪费金钱是不对的，尤其是在今天经济困难的社会环境中，我看你需要的是不浪费金钱，且物有所值的家庭保障计划！”还有的时候，她说：“我的很多好朋友都是这样说，直到他们听我解释了，才知道原来保险是花这么少钱可以买到这么大的一份保障，可以活得更开心，因为没有后顾之忧嘛。他们现在都买了，而且介绍很多朋友给我！”不管用哪种方式去回应，她总有办法让对方听她说完，并且多数时候都能把保单卖出去。\u003c/p>","explains":"\u003ch3>I】拆书家讲解引导（10分钟）\u003c/h3>\u003cp>回应是我们在沟通过程中经常要用到的一个方式，能够在沟通的过程中及时地回应对方，一来是对对方的尊重表示你在倾听，另外一方面可以帮助我们弄清楚对方话语的意思，探索出对方说话的意义，有助于建立和对方一致的气氛。\u003c/p>\u003cp>如果在沟通过程中不回应的话，容易导致沟通气氛不和谐，会给对方觉得“你不重视我”的印象，会为沟通效果减分。\u003c/p>\u003cp>那么在沟通中应该如何回应呢？\u003c/p>\u003cp>根据拆页的案例信息，我总结提炼出“回应三步骤法”，一起来看一下。\u003c/p>\u003cp>第一步，找认同。\u003c/p>\u003cp>说出双方都认可的信息。我们在与人沟通的时候，会遇到意见不一致的情况。那么这个时候，我们需要有技巧的回应。回应的第一步就是，找到双方都认同的地方，先达成一部分共识。在拆页的案例中，当对方说出“保险浪费金钱”的时候，对方其实认同的是什么呢？这个就要回到保险的本质上，保险的本质是为家庭设立保障计划。但是她不认同的是浪费金钱的保障计划。所以认同的地方是：“您也认为有必要为家庭设立保障计划”。\u003c/p>\u003cp>第二步，替换不认同。\u003c/p>\u003cp>对方不认同的是采取浪费金钱这个方式。它的的对立面是，不浪费钱或者说物超所值，甚至是包括对方在使用的其他我们不知道的方法。当内心有一些替换答案之后，我们来进行第三步。\u003c/p>\u003cp>第三步，询问确认。\u003c/p>\u003cp>整个表达可以是这样的：你认可保险是一种家庭保障的方法，只不过相较于浪费金钱，你更喜欢物超所值的计划对嘛？来让对方回应，直到我们完全理解对方的意思。这样可以让沟通更顺畅，避免误会的发生。如果替换答案都不能达成共识，那么，就可以直接问，你的家庭保障计划方法是什么呢？\u003c/p>\u003cp>我们连起来回忆一下这个”回应”，大家听起来还是有点抽象，我举一个自己的例子哈。\u003c/p>\u003cp>【举例子】\u003c/p>\u003cp>比如，我在上一家公司有一个领导她不认可培训，她总说培训浪费时间，而且效果又不好。但是实际情况又需要安排培训，这样员工才能够有所改进。\u003c/p>\u003cp>在一个汇报会议上，她再一次提出了这个问题。说培训浪费时间。我当时马上想到了沟通的策略：回应三步骤。\u003c/p>\u003cp>第一步，找认同。她说培训浪费时间，那么培训的目的是什么呢？是为员工的成长负责。所以，这个就是共同认可的价值信息。\u003c/p>\u003cp>第二步，替换不认同。那么替换“浪费时间”的是“分秒必用”。接下来就到了第三步。 \u003c/p>\u003cp>第三步，询问确认。\u003c/p>\u003cp>领导，您也认为需要为员工的成长作进一步的规划，相较于浪费时间的培训，您更倾向于一个充分利用时间的培训，对吗？或者您认为可以规划员工成长的方法有哪些呢？\u003c/p>\u003cp>最后我们达成共识，让每个人自己在课外实践去学习，并输出学后感。以此来激励每个员工的自我成长。这就是我们在沟通中遇到分歧，进行回应并有效解决了分歧的一个真实案例。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>有人说是不是做完“回应三步骤法”就行了，其实要看我们是否理解了对方的意思，有时候需要再回应，直到我们能够理解对方清楚意思为止。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003cp>“回应三步骤法”适用于所有的场景吗？并不是的哈，在一些固定场景下，别人说的话不会带来分歧，我们一听就已经完全明白对方的意思，就不要再去回应了。比如，坐上公交车后，售票员说，上车请投币。这样的信息我们能够完全理解的话，那么如果再去回应，就会显得多余。\u003c/p>","interaction":"\u003ch3>【A3】促动参与（15分钟）\u003c/h3>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>这个片段的内容，就先分享到这里。\u003c/p>\u003cp>下面我想请大家思考一下，在今天我们学习的关于沟通的知识点中，大家还有什么问题吗？ 如果有问题，欢迎现场提出来，我们一起来解决它。\u003c/p>\u003cp>（在白板上记录大家的问题）\u003c/p>\u003cp>问题1：怎么快速找到认同？（组③）\u003c/p>\u003cp>问题2：怎么找到合适的替换？（组②）\u003c/p>\u003cp>问题3：如何达到沟通的目的？（组①）\u003c/p>\u003cp>问题4：如何根据沟通对象的风格选择合适的沟通方式？（组④）\u003c/p>\u003cp>1.【明确问题】\u003c/p>\u003cp>好的，感谢大家的反馈。\u003c/p>\u003cp>那么我们今天时间有限，只能选一个进行讨论，我们举手选一个问题，大家同意吗？ \u003c/p>\u003cp>&lt;学习者举手投票&gt;：\u003c/p>\u003cp>问题1：3票\u003c/p>\u003cp>问题2：1票\u003c/p>\u003cp>问题3：5票\u003c/p>\u003cp>问题4：4票\u003c/p>\u003cp>【提问式反馈与回应&amp;确定问题】\u003c/p>\u003cp>好的，根据民主投票，那么现在我们讨论的问题是：来自小组①的问题“如何达到沟通的目的？”\u003c/p>\u003cp>2. 【引导分组讨论问题本质】\u003c/p>\u003cp>接下来，我们一起来思考一下，_____“没有达到沟通目的”________，出现这个问题背后的原因有哪些呢？\u003c/p>\u003cp>原因1：没有营造沟通分为\u003c/p>\u003cp>原因2：双方认为价值不匹配\u003c/p>\u003cp>原因3：自己没有沟通目标\u003c/p>\u003cp>原因4：沟通过程中没有安全感\u003c/p>\u003cp>原因5：双方没有共同的沟通目的\u003c/p>\u003cp>3. 【明确问题本质】\u003c/p>\u003cp>好的，大家给出了非常多的原因，那么我们知道，我们解决问题就要找问题的本质，本质就是最关键的那个原因，解决了最本质问题，我们这个问题也会迎刃而解。所以，请大家一起想一想，这里最接近问题本质的原因可能是是哪个呢？\u003c/p>\u003cp>（现场有8个人认为原因5是本质原因。）\u003c/p>\u003cp>好的，那么这个是我们大家认为的问题的本质，它就是：双方没有共同的沟通目的。\u003c/p>\u003cp>4. 【分组讨论解决方案】\u003c/p>\u003cp>接下来针对发现“双方没有共同沟通目的”这个问题，请问小组①，你们希望解决到什么程度呢？\u003c/p>\u003cp>好的，也就是要能够找到共同目的的一些技巧对吗？\u003c/p>\u003cp>接下来请大家按照之前的分组，一起讨论一下关于“如何找到共同沟通目的”这个问题，解决方案有。\u003c/p>\u003cp>接着请小组推选代表分享你们讨论出来的解决方案。\u003c/p>\u003cp>5. 【呈现方案】：小组派代表讲解自己组的成果\u003c/p>\u003cp>组②：\u003c/p>\u003cp>1. 换位思考\u003c/p>\u003cp>2. 描绘蓝图\u003c/p>\u003cp>3. 询问\u003c/p>\u003cp>组①：\u003c/p>\u003cp>1. 创造共同目的\u003c/p>\u003cp>2. 围绕共同目的进行沟通\u003c/p>\u003cp>好的，现在愿意分享的小组，他们的方案都在这里了。大家看看哪些是可以执行的，是跟我们组①希望解决收集到的沟通技巧相符合的？\u003c/p>\u003cp>简单归纳总结一下，”如何找到共同沟通目的” 有这些沟通技巧：\u003c/p>\u003cp>1. 换位思考\u003c/p>\u003cp>2. 描绘蓝图\u003c/p>\u003cp>3. 询问\u003c/p>\u003cp>那么这样的解决方案， 请问组①，可以在一定程度上解决你的问题了吗？\u003c/p>\u003cp>&lt;组①反馈&gt;： 基本可以\u003c/p>\u003cp>好的，今天我们的微行动学习环节就到这里。\u003c/p>\u003ch4>【学习者案例记录】\u003c/h4>\u003cp>如上。\u003c/p>\u003ch3>【A2】催化应用（2分钟）\u003c/h3>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>学习是为了更好地拆为己用，那在今天的学习中，有没有让你自己本人联想到未来哪一个沟通的情景会运用今天学习的知识点——回应法。\u003c/p>\u003cp>比如，在与同事、领导沟通的时候，他们对一件事情的看法和我们不一致的时候；\u003c/p>\u003cp>再比如，和朋友一起聊天，关于一些对爱情、对婚姻的看法，我们产生分歧的时候。\u003c/p>\u003cp>【布置任务】\u003c/p>\u003cp>我们知道，学以致用才是对知识的最大珍惜。\u003c/p>\u003cp>因此我给大家布置一个小小的任务，帮助大家更加熟悉运用这个技能。\u003c/p>\u003cp>在未来一周，请记录一次你运用回应法的经历。最先填写好任务卡发在今天活动群里的同学，可以获得红包奖励哟。\u003c/p>\u003ch4>【学习者案例记录】\u003c/h4>\u003cp>现场学习者@罗棛祺\u003c/p>\u003cp>请记录你自己本人在未来一周内你运用回应法的经历：\u003c/p>\u003cp>时间：2019年5月20日\u003c/p>\u003cp>地点：家里\u003c/p>\u003cp>经历描述：回应妹妹认为我告诉爸妈她欠很多债是不怀好意，但我其实是好心的沟通分歧。\u003c/p>\u003cp>第一步，找认同。我告诉，姐姐从小到大有没有伤害过你？没有，所以姐姐是爱你的。\u003c/p>\u003cp>第二步，替换不认同。那你认为的心怀好意是什么做法？或者，不告诉爸妈就是好心了吗？\u003c/p>\u003cp>第三步，询问确认。你知道，姐姐其实是爱你的。相比于告诉爸妈，你认为我可以选择更加友善的方式，对吗？\u003c/p>\u003ch2>结语（1分钟）\u003c/h2>\u003cp>今天一共和大家分享了两个片段：\u003c/p>\u003cp>第一个片段是关于沟通的含义以及三个步骤，一起来回忆下是哪三个步骤？\u003c/p>\u003cp>第二个片段是关于在沟通过程中的回应，出现分歧如何回应，可以提升沟通效果，增进人际关系。 \u003c/p>\u003cp>知识或技能并不会学一次就会变成自己的能力，期待大家在以后生活和工作中，多多运用，沟通能力呲呲地上升，都能成为一个优秀的沟通专家。\u003c/p>\u003cp>今天的拆书就到这里，谢谢大家的参与~\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1557941013000,"updated_at":1557941013000,"ria":true},{"id":7493,"topic":"做有心的沟通者","learn_goal":"通过对沟通力的学习掌握沟通的步骤要点，以及懂得回应","remark":"为什么沟通总没有取得理想中的效果？为什么一说话总是引起别人的误会？掌握沟通的这几个技巧，让沟通有方法，让误解消除，一起做沟通达人。","level":"TF3-3","duration":60,"status":29,"type":0,"chaishujia":{"username":"CoCo陶可可","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是今天的拆书家陶可可。 \u003cbr>\u003c/p>\u003cp>【分组】\u003c/p>\u003cp>非常感谢大家今天来参加拆书活动，首先请大家找到自己的学习拍档！\r\n没错，就是坐在你对面的那个伙伴。好的，大家都找好了之后，请与对方握手并真诚地说一句，今天的学习，你是我的老师！（要注意现场性别差异，针对演练有针对性地组合小组。）\u003c/p>\u003cp>【图书介绍-学习者场景法】\u003c/p>\u003cp>事件：\u003cstrong>大家是否有遇到过这样的情况？\u003c/strong>例如，你一直很喜欢一个男生，你会经常去看他的微博，去看他的朋友圈，但是，你从来没有告诉过他。你也不知道他喜不喜欢你。然后隔了很久，你得知他有女朋友了了。\r\n再比如，你和一个同事之间发生了摩擦，其实事情可能也很小，就是别人在领导面前吐槽了你几句，而你知道后真的很生气。 \u003cbr>\u003c/p>\u003cp>提问： 大家在从小到大，在工作或者生活中，有遇到过类似的情况吗？\r\n像暗恋这种情况，有没有想起来会万分后悔呢？\r\n像同事摩擦这种情况，再回想起来，会不会觉得“也不至于吧”？ \r\n（学习者互动反馈） \u003cbr>\u003c/p>\u003cp>影响：大家看，无论是在工作中，还是生活里，我们如果不善于沟通，或者不及时沟通，那么随之而来的有可能是错过了一段美好的爱情，也有可能导致一场误会、带来一段冷战，让原本和睦的关系越走越远。\u003c/p>\u003cp>解决： 这本《重塑心灵》认为，通过改善沟通方式，可以提升沟通能力，让人际关系更和谐。书中的沟通方法论经过我的实践运用，我认为，可以解决我们沟通的大部分难题，甚至比我们 &nbsp; &nbsp; 想象的更好，非常有价值。 \u003cbr>\u003c/p>\u003cp>【学习目标-总述】\r\n今天通过两个片段的学习，希望现场学习者能够掌握沟通的三个步骤，并且在沟通中遇到误会时可以采用回应三步骤的技巧，从而降低人际关系僵化的概率，并帮助我们达到沟通的目的，为自己赢得友好的人际关系，给对方留下好印象。\r\n &nbsp; &nbsp; \u003cbr>\u003c/p>\u003cp>【学习目标-分述（现场其实在各自的拆页前去讲学习目标的，写在这里是为了给各位评审方便查阅）】\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【R1\u003c/strong>\u003cstrong>学习目标】\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>今天第一个拆页是关于\u003cstrong>沟通\u003c/strong>的，学习目标是希望大家在跟随我完成RIA现场学习后，可以掌握沟通的三个步骤，并且在大家遇到问题不知所措的时候，能够第一时间想到沟通这个手段，从而\u003cstrong>降低\u003c/strong>大家因为不懂沟通、不知道如何沟通而使得人际关系出现裂痕的概率。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【R2\u003c/strong>\u003cstrong>学习目标】\u003c/strong>\u003c/p>\u003cp>在阅读拆页前本环节的学习目标是，希望大家能够在与人沟通中出现分歧的时候，能够用\u003cstrong>回应法\u003c/strong>来进行沟通，降低沟通信息传递的误差度，帮助我们达到沟通的目的，为自己赢得友好的人际关系，给对方留下好印象。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","ratings_count":1,"texts":[{"id":10964,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>《重塑心灵》P172\u003c/strong>\u003c/p>\u003cp>“沟”者渠也，“通”者连也，“沟通”本身的意思是借助某种渠道使双方能够通连。\u003c/p>\u003cp>&nbsp;&nbsp; 在小说中常常可以读到这样的故事：一男一女，于风华正茂时一见倾心，情愫暗生。但因着矜持与羞涩，或者世俗的牵扯阻碍，犹疑着，酝酿着，那纯真而隐晦的爱意，终只是在眉梢眼角轻轻流露，\u003cstrong>并没有开口说出\u003c/strong>。然后阴错阳差间，大家已各奔东西，听任流年似水时光逝去，多年后在异地他乡两人不期而遇时，已是鬓丝如霜，各有各的曲折，各有各的悲哀——于是把盏话沧桑。酒过三巡，醉意稍甚的一方突然涩涩开口：当年，其实深爱过你。另一方也只是眼神凄柔地沉默以对。其实这么多年过去，世事早已尘埃落定，说不说出，都是云淡风轻了。但当年的一句话，也许可以重写两个人的生命。\u003c/p>\u003cp>&nbsp;&nbsp; 爱要说出口，任何一种沟通其实都是如此。对方是否是这个意思或者已否明白你的心意，只有对方才能决定。不要假设，若不肯定，\u003cstrong>找他谈淡\u003c/strong>。\u003c/p>\u003cp>&nbsp;&nbsp; 人间充满因为猜疑别人的想法和不肯明白表达自己的意思而引起的误会和悲剧，不信的话，你不妨看看《家》《春》《秋》或者任何一部文艺作品，也可以留心你每晚收看的电视剧，还可以注意你的朋友之中曾经出现过的纠纷，看看你可以找出多少个例证。\u003c/p>\u003cp>&nbsp;&nbsp; 在人与人之间的关系中，可以减少的假设便应尽量减少。大部分人都同意夫妻之间可无事不谈，但是，很多夫妻很少分享内心的感受，有什么不满意都只是隐藏在心里，要对方瞎猜。夫妻都是这样，家人、同事、朋友更不用说了。\u003c/p>\u003cp>&nbsp;&nbsp; 中国人的传统思想中讲究修养，做人要含蓄、内敛，往往使人不谈心中不快的事。其实真正上乘的修养，是心中没有不快的事。既然有了，面对它，积极和善意地处理、化解它才是正确的做法。人间已经太多因为小小的误会而引起的困扰、悲剧，甚至一生的折磨。为自己做点好事，不要再猜臆别人内心的看法或感受，去找他谈谈吧。多尊重别人一些，问问他的内心真实的想法吧。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>\u003cstrong>【R1\u003c/strong>\u003cstrong>学习目标】\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>今天第一个拆页是关于\u003cstrong>沟通\u003c/strong>的，学习目标是希望大家在跟随我完成RIA现场学习后，可以掌握沟通的三个步骤，并且在大家遇到问题不知所措的时候，能够第一时间想到沟通这个手段，从而\u003cstrong>降低\u003c/strong>大家因为不懂沟通、不知道如何沟通而使得人际关系出现裂痕的概率。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>【强化概念讲解（举例与对比）】\u003c/p>\u003cp>在这个拆页中，我们看到了“沟通”的定义和重要性。\u003c/p>\u003cp>\u003cstrong>那么根据这个拆页，什么叫做沟通呢？他和我们日常生活中的“说话”有什么区别呢？\u003c/strong>\u003c/p>\u003cp>\u003cstrong>e.g.1\u003c/strong>\u003c/p>\u003cp>我想和XXX探讨拆书法，然后我一直在说，期间对方想打断我，也被我堵回去了。\u003c/p>\u003cp>大家觉得这是沟通吗？还只是“说话”？\u003c/p>\u003cp>（学习者反馈）\u003c/p>\u003cp>不是。\u003cstrong>不去互动\u003c/strong>，而是我们一个人自己一直“说话”，这个也不叫沟通。沟通是一个双向互动的过程，至少要有两个人。\u003c/p>\u003cp>\u003cstrong>e.g.2\u003c/strong>\u003c/p>\u003cp>我今天看到XX，心情很激动，一聊就是十分钟，聊完就到拆书的时间了。而我刚刚想起来，今天是想问他上次那本书是在哪里买的。\u003c/p>\u003cp>大家觉得这个是沟通嘛？\u003c/p>\u003cp>（学习者反馈）\u003c/p>\u003cp>不是。这个属于“说话”的范畴，因为在这段谈话中，我并没有把自己要说的话说出来。而\u003cstrong>沟通往往是有主题、有目的的沟通\u003c/strong>。\u003c/p>\u003cp>\u003cstrong>e.g.3 &nbsp; \u003c/strong>\u003c/p>\u003cp>我知道不久后就是XXX的生日了，我给他准备了一大段生日祝福的话。然后呢，这些话在一个他被老板批评的上午，我硬拉着他说祝他生日快乐之类的话语。\u003c/p>\u003cp>他好像听了我的祝福并没有很开心，搞得我很受伤。\u003c/p>\u003cp>大家觉得，这个是沟通嘛？\u003c/p>\u003cp>（学习者反馈）\u003c/p>\u003cp>不是。因为\u003cstrong>没有选择有效的表达方式\u003c/strong>。顶多是“说话”的范畴，但是并没有达到沟通的效果。而且，这个时候，不建议口头沟通，比较好的方式有，你写一封信放在他的桌子上。微信留言，提醒他有空看一下。\u003c/p>\u003cp>\u003cstrong>所以，沟通的本质定义是，\u003c/strong>\u003cstrong>两个人\u003c/strong>\u003cstrong>通过某种\u003c/strong>\u003cstrong>渠道\u003c/strong>\u003cstrong>进行\u003c/strong>\u003cstrong>有主题\u003c/strong>\u003cstrong>的互动。\u003c/strong>\u003c/p>\u003cp>【行动建议】\u003c/p>\u003cp>所以，我们从“沟通”的概念和要点，能够归纳出沟通最核心的步骤，\u003c/p>\u003cp>请大家看这个图示： \u003c/p>\u003cp>当我们要去做沟通的时候，沟通需要包括哪些步骤呢？\u003c/p>\u003cp>\u003cstrong>第一步，定主题，列要点。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步，选方式，架桥梁。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步，听反馈，回主题。\u003c/strong>\u003c/p>\u003cp>【自己的例子】\u003c/p>\u003cp>\u003cstrong>e.g.4 &nbsp; \u003c/strong>\u003c/p>\u003cp>这样听起来还是有点抽象，我来举一个自己的例子。\u003c/p>\u003cp>一年一度的普遍调薪时候到了。涨是都会涨，但是涨额是我们每个人可以去争取的。那么对我来说，这是需要去和领导“沟通”的。\u003c/p>\u003cp>\u003cstrong>第一步，定沟通主题，列要点。\u003c/strong>\u003c/p>\u003cp>主题就是希望领导给我加薪。\u003c/p>\u003cp>把我要说的话先列出来，有：\u003c/p>\u003cp>①领导，我希望加薪。\u003c/p>\u003cp>②领导，我来公司快2年了，还没有加过薪。\u003c/p>\u003cp>……\u003c/p>\u003cp>只说自己想说的行不行呢？行，但是领导万一觉得不够说到他心里去，那么我们是不是可以把领导关注的内容也装一些进去啊？比如，\u003c/p>\u003cp>③领导，您看，这是我2018年的工作业绩业绩，\u003c/p>\u003cp>④领导，我未来给公司带来的价值会更大，包括我能够培训实习生，快速复制我的能力，帮助公司提升效率。\u003c/p>\u003cp>……\u003c/p>\u003cp>好的，这里大家可以列在纸上，也可以放在云笔记里。重点是，心中要有数。\u003c/p>\u003cp>\u003cstrong>接下来是第二步， 选择沟通方式，把这个沟通的桥梁架起来。\u003c/strong>\u003c/p>\u003cp>怎么把信息传递给领导呢？\u003c/p>\u003cp>书面形式还是口头形式？正式场合还是非正式场合？星期一谈还是星期四谈？\u003c/p>\u003cp>经过一系列的考量，我觉得这个要当面说比较好。一来，表示态度诚恳，二来展示自己的表达能力。确定了当面说这个工具，我接下来要去约领导时间了。\u003c/p>\u003cp>\u003cstrong>最后一步，就是倾听领导反馈，回到我们一开始设置的主题看看，沟通结果是否达到了我们预期的效果。\u003c/strong>\u003c/p>\u003cp>我们吧啦吧啦说了一大堆，还是希望领导给个反馈，加薪能不能加？什么时候加？不能加的话，有什么其他的安抚措施。\u003c/p>\u003cp>我们可以试探性问一句，\u003c/p>\u003cp>①领导您看，我这个小小的请求，您能帮我跟公司争取一下嘛？\u003c/p>\u003cp>②或者说，领导，我希望自己能够为公司贡献更多的价值，欢迎您对我的工作提出改进的建议，我做好了全力以赴的准备，同时，相应地我也希望能够为自己争取一些薪资调整的福利。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>大家会好奇说，掌握沟通三个步骤是不是就一定能够带来成功的沟通？其实，影响沟通成功与失败的因素有很多，也跟我们自己设定的沟通目的有关系，沟通的步骤和方法只是其中的一个因素。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>【编写剧本】\u003c/p>\u003cp>那么我们学习了沟通的三个步骤之后，接下来我们一起做一个\u003cstrong>编写剧本\u003c/strong>的练习，帮助我们巩固一下刚刚学习的内容。\u003c/p>\u003cp>请大家想象一下，未来，\u003cstrong>你自己本人\u003c/strong>在哪些场景可能运用到\u003cstrong>沟通这三个步骤\u003c/strong>的场景？\u003c/p>\u003cp>比如，工作中，我们要和领导去谈一下给组织扩编的事情；比如，生活中，我们要去和一个男孩子/女生表达自己的喜欢。等等……\u003c/p>\u003cp>接下来请大家想象一下未来\u003cstrong>你自己本人\u003c/strong>在哪个场景你会用到沟通的这三个步骤？\u003c/p>\u003cp>我来具体说一下设计剧本的要求：\u003c/p>\u003cp>1、这是一个对话，对话包括事件背景和人物，以及起因、经过、结果；\u003c/p>\u003cp>2、解决问题的方法中使用了沟通三个步骤，最后变成一个成功地\u003cstrong>解决了你自己问题\u003c/strong>的剧本。\u003c/p>\u003cp>时间3分钟，3分钟后，我们请一个学习者来分享他的剧本。这是待会儿可以用到的道具，一只公仔是你的倾听对象，一只公仔是你，来辅助你演绎你的剧本。\u003c/p>\u003cp>请问，我的表达足够清晰吗？\u003c/p>\u003cp>小伙伴已经写完了，哪位愿意分享一下你的对话呢？\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>学习者案例记录：\u003c/p>\u003cp>\u003cstrong>分享者——刘亲近\u003c/strong>\u003c/p>\u003cp>我自己未来在_____合作伙伴的团队建设______场景会用到沟通的三个步骤。\u003c/p>\u003cp>我们有一个团队，然后感觉没有动力往前走了。其中包括我，社群运营官、客服人员。\u003c/p>\u003cp>起因是，团队运营了三个月，好现了很多情况。因为大家都不在同一个地方，想一起沟通下未来的发展路径。\u003c/p>\u003cp>第一步，定主题，列要点。我确定的主题是，未来团队如何继续发展。要点有，了解大家的时间安排因为有的是兼职；了解大家对竞争比较大的看法等。\u003c/p>\u003cp>第二步，选方式，架桥梁。我们时间选在晚上，语音沟通比较好。因为大家比较远，见面不是很方便。\u003c/p>\u003cp>第三步，听反馈，回主题。最后我还是会回到这主题上，看看自己是否充分了解了这些信息，然后帮助我做下一步的决策。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":10965,"quote":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>【拆书家提问设计（逐字稿），发放自测题】\u003c/p>\u003cp>【过渡】\u003c/p>\u003cp>我们前面已经学会了沟通的三个步骤，那么沟通的过程中，双方对一些信息产生了认知不一致怎么办呢？这个时候就需要一方有所回应。\u003c/p>\u003cp>所以我们接下来学习让沟通更加顺畅的回应技巧。\u003c/p>\u003cp>\u003cstrong>【R2\u003c/strong>\u003cstrong>学习目标】-学习目标（0.5分钟）\u003c/strong>\u003c/p>\u003cp>好的，接下来我们进入第二个片段的学习环节。\u003c/p>\u003cp>在阅读拆页前本环节的学习目标是，希望大家能够在与人沟通中出现分歧的时候，能够用\u003cstrong>回应法\u003c/strong>来进行沟通，降低沟通信息传递的误差度，帮助我们达到沟通的目的，为自己赢得友好的人际关系，给对方留下好印象。\u003c/p>\u003cp>接下来，我给大家发一个测试题，请大家根据自己的实际情况，对照自己平时的做法，然后进行打分。\u003c/p>\u003cp>1分代表完全不符合，6分代表非常符合，打完分以后请大家统计一下自己获得的总分。\u003c/p>\u003cp>\u003cstrong>发放自测题\u003c/strong>\u003c/p>1沟通出现分歧时，我回应别人从不用敌对情绪。（1）（2）（3）（4）（5）（6）2沟通出现分歧时，我回应别人总是能够找到替换方案化解分歧。（1）（2）（3）（4）（5）（6）3沟通出现分歧时，我回应别人都会尊重对方的感受。（1）（2）（3）（4）（5）（6）4沟通出现分歧时，我回应别人都会及时调整方向获取更多信息。（1）（2）（3）（4）（5）（6）5沟通出现分歧时，我回应别人的谈话氛围总是很愉悦。（1）（2）（3）（4）（5）（6）\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>这个自测表主要是测试大家在沟通出现分歧的过程中“回应”的质量，请问大家的合计分数是多少呢？有没有超过20分的小伙伴？\u003c/p>\u003cp>（学习者反馈）\u003c/p>\u003cp>有低于15的小伙伴吗？\u003c/p>\u003cp>（现场有3位分数低于15分的小伙伴）\u003c/p>\u003cp>分数大于20分请举手示意一下。\u003c/p>\u003cp>（现场有3位分数超过20分的小伙伴）\u003c/p>\u003cp>很好，祝贺你们，已经能够在沟通中很好地进行高质量的“回应”了。\u003c/p>\u003cp>少于20分的小伙伴也不要有压力，我们今天就是一起来学习回应的技巧。 \u003c/p>\u003cp>当然这只是一个精简的小测试，仅供大家参考，量表的测试结果无关好坏，只是来帮助我们更好的了解我们的现状，分数低的也不需要灰心，今天我们所拆解的内容就可以帮助大家改进我们回应的质量。\u003c/p>\u003cp>【过渡到阅读拆页】\u003c/p>\u003cp>通过自测环节，我们对沟通中的回应有了一些认识。\u003c/p>\u003cp>接下来请大家花2分钟的时间，阅读我发给大家的拆页内容，完成后请抬头示意我一下，谢谢！\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>【阅读拆页】\u003c/p>\u003cp>\u003cstrong>《重塑心灵》P180\u003c/strong>\u003c/p>\u003cp>理查德·班德勒曾经说过，当你对别人说话时，你不是给他一些信息便是在改变他。文字的运用，对话时所用的语言，对沟通的效果也有很大的决定作用。同样的意思，不同的人去说，或者同一个人用不同的词语、顺序表达出来，效果会有很大差别。要达成好的沟通效果，就要讲究语言的技巧。\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 做保险工作的林小姐被大家公认为“很会讲话”的人，很多朋友愿意同她交谈，把心里话说给她听，也愿意听她的意见，很少见她和什么人发生争执、吵嘴等。工作时经常有人毫不留情面地跟她说：“保险浪费金钱！”有时她这样说：“看来你是同意应该为家庭设立保障的，你现在用的是什么方法？”有时她又这样回应：“浪费金钱是不对的，尤其是在今天经济困难的社会环境中，我看你需要的是不浪费金钱，且物有所值的家庭保障计划！”还有的时候，她说：“我的很多好朋友都是这样说，直到他们听我解释了，才知道原来保险是花这么少钱可以买到这么大的一份保障，可以活得更开心，因为没有后顾之忧嘛。他们现在都买了，而且介绍很多朋友给我！”不管用哪种方式去回应，她总有办法让对方听她说完，并且多数时候都能把保单卖出去。\u003c/p>","explains":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>回应是我们在沟通过程中经常要用到的一个方式，能够在沟通的过程中及时地回应对方，一来是对对方的尊重表示你在倾听，另外一方面可以帮助我们弄清楚对方话语的意思，探索出对方说话的意义，有助于建立和对方一致的气氛。\u003c/p>\u003cp>如果在沟通过程中不回应的话，容易导致沟通气氛不和谐，会给对方觉得“你不重视我”的印象，会为沟通效果减分。\u003c/p>\u003cp>那么在沟通中应该如何回应呢？\u003c/p>\u003cp>根据拆页的案例信息，我总结提炼了三个步骤，一起来看一下。\u003c/p>\u003cp>\u003cstrong>第一步，找双方都认可的地方。\u003c/strong>我们在与人沟通的时候，会遇到意见不一致的情况。那么这个时候，我们需要有技巧的回应。回应的第一步就是，找到共同认同的地方，先达成一部分共识。在拆页的案例中，当对方说出“保险浪费金钱”的时候，我们看到双方共同认可的地方在于，“保险的本质是为家庭设立保障计划”这个就是一个共同意义。\u003c/p>\u003cp>\u003cstrong>第二步，找反向替换。\u003c/strong>浪费金钱的对立面是，不浪费钱或者说物超所值，甚至是包括对方在使用的其他我们不知道的方法。当内心有一些替换答案之后，我们来进行第三步。\u003c/p>\u003cp>\u003cstrong>第三步，请求澄清，询问对方选择哪种替换。\u003c/strong>\u003c/p>\u003cp>整个表达可以是这样的：你认可保险是一种家庭保障的方法，只不过相较于浪费金钱，你更喜欢物超所值的计划对嘛？来让对方澄清，直到我们完全理解对方的意思。这样可以让沟通更顺畅，避免误会的发生。如果替换答案都不能达成共识，那么，就可以直接问，你的家庭保障计划方法是什么？\u003c/p>\u003cp>我们连起来回忆一下这个”回应”，大家听起来还是有点抽象，我举一个自己的例子哈。\u003c/p>\u003cp>\u003cstrong>【举例子】\u003c/strong>\u003c/p>\u003cp>比如，你和朋友在聊天，对方说，知否知否不好看。但其实你觉得还不错。\u003c/p>\u003cp>\u003cstrong>第一步，找双方都认可的地方\u003c/strong>。她说不好看，说明她还是很关注电视剧的，或者看过相关的评论。共同认可的地方在于，双方都比较关注电视剧。\u003c/p>\u003cp>\u003cstrong>第二步，找反向替换。\u003c/strong>那么替换知否知否就是，她觉得好看的电视剧有哪些；或者替换“不好看”，她觉得知否知否应该拍成什么样子。\u003c/p>\u003cp>\u003cstrong>第三步，请求澄清，询问对方选择哪种替换。\u003c/strong>\u003c/p>\u003cp>①看来你也关注电视剧了，那你觉得最近好看的电视剧有哪些呢？\u003c/p>\u003cp>②看来你也关注电视剧了，那你觉得知否知否应该拍成什么样子？\u003c/p>\u003cp>这就是我们在沟通过程遇到有分歧的时候，进行回应的一个例子。\u003c/p>\u003cp>【适用边界】\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>回应法的前提是双方有分歧的时候，可以运用这三个步骤进行回应。但是一些固定场景下，别人说的话不会带来分歧，或者你非常认同，就不要再去回应了。比如，坐上公交车后，售票员说，上车请投币。这样的信息我们能够完全理解的话，那么如果再去回应，就会显得多余。\u003c/p>","interaction":"\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>拆书家提问设计（逐字稿）\u003c/p>\u003cp>这个片段的内容，就先分享到这里。下面我想请大家结合自己的经验，在学习\u003cstrong>回应”法\u003c/strong>的过程中，你们觉得哪一个步骤最难做到？\u003c/p>\u003cp>（学习者反馈：第二步和第一步；）\u003c/p>\u003cp>\u003cstrong>1.\u003c/strong>\u003cstrong>【明确问题】\u003c/strong>\u003c/p>\u003cp>好的，感谢大家的反馈，那么我们今天时间有限，只能选一个进行讨论，我们举手选一个问题，大家同意吗？ &nbsp; \u003c/p>\u003cp>&lt;学习者举手投票&gt;：\u003c/p>\u003cp>第二步，5位同学。\u003c/p>\u003cp>第一步，6位同学。\u003c/p>\u003cp>确定第一步“找不到双方都认可的地方”，作为问题去解决。\u003c/p>\u003cp>\u003cstrong>【提问式反馈与回应&amp;确定问题】\u003c/strong>\u003c/p>\u003cp>好的，那么现在我们讨论的问题是：____找不到双方都认可的地方，应该怎么办？ \u003c/p>\u003cp>\u003cstrong>2. \u003c/strong>\u003cstrong>【引导分组讨论问题本质】\u003c/strong>\u003c/p>\u003cp>按照刚才的分组，现在我们一起来思考一下，_____找不到双方都认可的地方，应该怎么办？这个问题背后的原因有哪些呢？\u003c/p>\u003cp>现场学习者反馈——\u003c/p>\u003cp>原因1：价值观不同\u003c/p>\u003cp>原因2：知识经验不同\u003c/p>\u003cp>原因3：情绪不同\u003c/p>\u003cp>原因4：关系不融洽\u003c/p>\u003cp>原因5：利益之争\u003c/p>\u003cp>原因6：双方各执己见\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>3. \u003c/strong>\u003cstrong>【明确问题本质】\u003c/strong>\u003c/p>\u003cp>好的，大家给出了非常多的原因，那么我们知道，我们解决问题就要找问题的本质，本质就是最关键的那个原因，解决了最本质问题，我们这个问题也会迎刃而解。所以，请大家一起想一想，这里最接近问题本质的原因可能是是哪个呢？\u003c/p>\u003cp>（学习者反馈：价值观不同、知识和经验不同、利益之争不同）\u003c/p>\u003cp>投票表决：\u003c/p>\u003cp>价值观不同，7个学习者\u003c/p>\u003cp>知识和经验的，3个学习者\u003c/p>\u003cp>利益之争，1个学习者\u003c/p>\u003cp>好的，那么我们一直确定：价值观不同是最本质的那个原因。\u003c/p>\u003cp>\u003cstrong>4. \u003c/strong>\u003cstrong>【分组讨论解决方案】\u003c/strong>\u003c/p>\u003cp>针对发现“ _找不到双方都认可的地方，应该怎么办？”这个问题，我们希望解决到什么样子？\u003c/p>\u003cp>学习者1：双方都达成达成一致\u003c/p>\u003cp>好的，大家的目标都很一致，就是双方都达成达成一致，对嘛？大家都同意嘛？\u003c/p>\u003cp>那现在我们按照之前的分组，一起讨论出“如何解决因价值观不同而导致的找不到共识（共同认可的地方）”的解决方案出来。\u003c/p>\u003cp>我们先在组内选择一个小组长，组长责任重大，需要负责记录大家的想法，然后组长做汇报。\u003c/p>\u003cp>\u003cstrong>5. \u003c/strong>\u003cstrong>【呈现方案】：请每组派代表讲解自己组的成果\u003c/strong>\u003c/p>\u003cp>组1： 停止攻击；价值提升；\u003c/p>\u003cp>组2：确定相同的地方；找到平衡点；达成协议；\u003c/p>\u003cp>组3：明确态度；积极倾听；求同存异；\u003c/p>\u003cp>好的，感大家的分享。我们看到有一些步骤是类似的概念，为了帮助大家更好地记忆，我们进行一个排序和归纳。\u003c/p>\u003cp>大家觉得第一个步骤可以是什么？\u003c/p>\u003cp>（学习者反馈：态度。）\u003c/p>\u003cp>第二个呢，确定相同、找到平衡点、求同存异和停止攻击，可以归纳为，找到共同目标。\u003c/p>\u003cp>第三步呢，达成协议。\u003c/p>\u003cp>好的，那么经过我们的讨论，针对如何解决因价值观的问题而导致的没法找到共识，可以有如下的建议：\u003c/p>\u003cp>\u003cstrong>第一步，明确态度；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第二步，找共同目标；\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第三步，达成共识；\u003c/strong>\u003c/p>\u003cp>那么这样的解决方案，大家都满意嘛？\u003c/p>\u003cp>&lt;学习者反馈&gt;： 可以接受。\u003c/p>\u003cp>好的，那么我们的微行动学习环节就到这里。\u003c/p>\u003cp>\u003cstrong>拆书家提问设计（逐字稿）\u003c/strong>\u003cbr>学习是为了更好地拆为己用，那在今天的学习中，有没有让你自己本人联想到未来哪一个沟通的情景会运用今天学习的知识点——回应法。\u003cbr>比如，在与同事、领导沟通的时候，他们对一件事情的看法和我们不一致的时候；\u003cbr>再比如，和朋友一起聊天，关于一些对爱情、对婚姻的看法，我们产生分歧的时候。\u003c/p>\u003cp>【布置任务】\u003cbr>我们知道，学以致用才是对知识的最大珍惜。\u003cbr>因此我给大家布置一个小小的任务，帮助大家更加熟悉运用这个技能。\u003cbr>在未来一周，请记录一次你运用回应法的经历。最先填写好任务卡发在今天活动群里的同学，可以获得红包奖励哟。\u003cbr>\u003cbr>\u003c/p>\u003cp>【学习者案例记录】\u003cbr>分享者——微信昵称@婷婷he文文\u003cbr>\u003cbr>\u003c/p>\u003cp>（逐字稿）\u003cbr>今天一共和大家分享了两个片段：\u003cbr>第一个片段是关于沟通的含义以及三个步骤，大家看着这幅图，一起来回忆下是哪三个步骤？\u003cbr>第二个片段是关于在沟通过程中的回应，出现分歧如何回应，可以提升沟通效果，增进人际关系。 \u003cbr>知识或技能并不会学一次就会变成自己的能力，期待大家在以后生活和工作中，多多运用，沟通能力呲呲地上升，都能成为一个优秀的沟通专家。\u003cbr>\u003cbr>今天的拆书就到这里，谢谢大家的参与~\u003cbr>\u003cbr>\u003cbr>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1554391310000,"updated_at":1554650003000,"ria":true},{"id":6934,"topic":"松动信念的方法","learn_goal":"在面对限制性信念（负面的想法）时运用松动信念的方法让旧信念动","remark":"    ","level":"TF2-2","duration":20,"status":29,"type":0,"chaishujia":{"username":"玲珍","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;大家好，我是玲珍。喜欢阅读，现在正努力成为一名优秀三级拆书家。为了更好地学习，我们现场的伙伴两两分成一个小组。\r\n今天我们拆解的片段来自书本《重塑心灵》\r\n【F】作者是李中莹先生，他最早把NLP（神经语言程序学）完整全面地介绍到国内，被誉为&quot;华人世界的国际级NLP大师 &quot;。这本书自出版以来已经16年了，期间不断修订，先后加印20多次，很受欢迎。\r\n【A】和其他NLP的书籍比较，这本书以通俗的语言讲解，即使是没有NLP基础的读者也能够理解和运用。\r\n【B1】当你遇到不顺利的情境时，也许会不知所措，而这本书有很多灵活的工具，可以帮助你拥有让自己成功快乐的能力。\r\n【B2】今晚我们拆解的是“松动信念的方法”的片段，这可以帮助读者动摇限制性的信念，打开思路解决问题。\r\n【学习目标】\r\n在跟随我完成本次RIA现场学习后，大家能够在面对限制性信念（负面的想法）时运用松动信念的方法让旧信念动摇。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":10304,"quote":"\u003cp>下面请大家用2分钟时间阅读原文片段，阅读完的伙伴请示意我一下。\u003c/p>\u003cp>《重塑心灵》P41\u003c/p>\u003cp>\u003cstrong>改变信念系统的技巧\u003c/strong>\u003c/p>\u003cp>一个人的思想、情绪和行为，都受他内心的信念系统所支配。一些局限性的信念，可以使这个人每当面对某些人事物的时候，不能做到三赢，并感受不到应有的成功快乐。过去积存的选择也就是他头脑里现有的神经元网络，这些选择既然无效，每次遇到同一件事，便都只会重复那不理想的效果。欲想他有更好的表现，必须先让他建立一些更有效的信念，也就是建立新的神经元网络去改进对待同类事情的想法与做法。\u003c/p>\u003cp>\u003cstrong>松动信念的方法\u003c/strong>\u003c/p>\u003cp>以下方法对所持的信念做出审视和界定，因而能够使之松动。所用的例子是一位家庭主妇应否每天都等待丈夫回家一同吃饭。\u003c/p>\u003cp>\u003cstrong>1\u003c/strong>\u003cstrong>．改变标签。\u003c/strong>\u003c/p>\u003cp>例：“不等待他回来便吃东西是不尊重他。”（标签）\u003c/p>\u003cp>“不等待他回来便吃东西是照顾自己。”（新标签）\u003c/p>\u003cp>\u003cstrong>2\u003c/strong>\u003cstrong>．改变标签的定义\u003c/strong>\u003c/p>\u003cp>例：“自己因为太饿而没有气カ，从而产生抱怨情绪，他回来后你不能给他好的照顾，这才是不尊重他呢！\u003c/p>\u003cp>\u003cstrong>3\u003c/strong>\u003cstrong>．审视背后的动机。\u003c/strong>找出事情背后的正面动机，这往往需要找出更高的理解层次，即更大的意义、更广的覆盖面或范畴。可以问：“这样做会让你变得怎么样？会给你一些什么重要的东西？”这样有可能让这个主妇看到改变的好处。\u003c/p>\u003cp>例：“不等待他回来便吃东西，使我有气力做好家务，进而把东西收好，怀着轻松愉快的心情等待他回来。”\u003c/p>\u003cp>\u003cstrong>4\u003c/strong>\u003cstrong>．极度延伸。\u003c/strong>把维持旧信念的终极结果明显化。引导她自问，或者对她说：“你继续这样做，最终会有什么结果？\u003c/p>\u003cp>例：“继续这样做，偶然的胃痛会变成长期的胃病，身体坏了，什么事情都做不好，情绪也会越来越坏，两人的关系会越来越紧张。”\u003c/p>\u003cp>以上的过程，最好是引导对方制造一些有视觉、听觉和感觉元素的未来景象，这会产生支持改变信念的动力。上面的例子，其实真正的突破点可能是教导这个家庭主妇如何与丈夫共同讨论晚饭时间的安排，但是这位女士必须先让内心的旧信念动摇了，才会有动力去思考和开口。\u003c/p>","explains":"\u003cp>(What) 人总会受到信念的驱使做出相应的行为，而如果持有的信念是有局限性的，就会阻碍事情的发展。例如一个人持有“不听父母话就是不孝顺”这个信念，当父母提出不合理要求时，究竟是听父母的话还是拒绝父母不合理要求呢？又比如说“宝宝还这么小，我这时候出来创业是不负责任的”，“我花很时间参加拆书活动少了陪伴家人是不重视家人的表现”等等。\u003c/p>\u003cp>(Why)如果我们能够去动摇这些限制性的信念，可以帮助我们从新的角度去看待同样的事情，从而为解决问题提供更加充足的动力。\u003c/p>\u003cp>【不这么做的坏处】当我们不去动摇限制性的信念时，我们会困在问题里边，很难有新的方向去解决问题。\u003cbr>\u003c/p>\u003cp>(How)以下四种方法可以帮助我们松动限制性信念：\u003c/p>\u003cp>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;转变标签\u003c/p>\u003cp>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;转变标签的含义\u003c/p>\u003cp>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;找到改变信念后的好处\u003c/p>\u003cp>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;找到维持旧信念的坏处\u003c/p>\u003cp>【例子】\u003c/p>\u003cp>我想到我自己的一个例子：\u003c/p>\u003cp>我刚结婚的时候希望在工作方面有更好的发展，不打算这么快要小孩。但 “结婚了还不打算要小孩是对不起公婆”这个信念让我很犹豫。我运用了松动信念的一些方法：\u003c/p>\u003cp>转变标签的含义：如果因为没有做好心理准备，放弃职业发展而怀孕，我的坏情绪会让小孩身体不好，这会让他们费神照顾，这样才是对不起他们。\u003c/p>\u003cp>找到改变信念后的好处：先不着急要小孩，我现在的工作做好了，可以为他们提供更好的条件安享晚年，再过一段时间同样可以满足他们做爷爷奶奶的愿望。\u003c/p>\u003cp>找到维持旧信念的坏处：如果现在怀孕生小孩，会错失很好的职业发展机会，这会让我有一种的不平衡心态，让家庭关系紧张。\u003c/p>\u003cp>动摇了原来的信念后，我开始敢于和先生、公婆讨论生小孩和职业发展的计划，而不是一直抱着“结婚后还不打算要小孩是对不起公婆”这个信念让自己进退两难。\u003c/p>\u003cp>【预防异议】\u003c/p>\u003cp>听完了4个松动信念的方法，可能你会认为，有问题了直接想解决方案就好了，怎么就要浪费时间去松动信念呢？直接跳到解决问题环节看似高效，但如果我们一直抱着负面的信念不放，是很难有动力去做出改变的。所以先松动信念看似浪费时间，其实当你有动力去做出改变后，其实可以加速问题解决。\u003c/p>","interaction":"\u003cp>【A2催化应用】\u003c/p>\u003cp>【分步催化-场景】\u003cbr>\u003c/p>\u003cp>设想一下，未来的周日是难得的休息天，微风吹动了轻柔的窗帘，你慢慢地醒来，打算轻松地过好这一天。这时，脑海中涌现了一些你一直持有的限制性的信念，让你突然不想起来面对了，这时，你想到的限制性的信念是什么呢？\u003c/p>\u003cp>请在小组内分享，每人1分钟时间，组内分享完后会邀请一位小伙伴上来分享。我的指示清晰吗？\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者1：我作为妈妈没有把孩子照顾好，所以孩子容易生病。\u003c/p>\u003cp>【分步催化-规划应用】\u003c/p>\u003cp>这时，你想到了今天学习的松动信念的方法，你马上从床上坐起来运用文中提到的方法松动刚才讨论的一个限制性信念。\u003c/p>\u003cp>请在小组内分享你是如何运用文中提到的方法松动信念的，你可以运用其中一种方法或者几种方法。每人1分钟时间，组内分享完后会邀请一位小伙伴上来分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者2：我孩子2岁前都是我带的，现在我有一份高薪的工作摆在我面前，但觉得“做高薪的工作不能很好照顾好小孩”。我分析后可以运用第三种方法（找到改变信念后的好处），我努力工作可以帮助我实现自我和让家庭更好，更有能力照顾好小孩。\u003c/p>\u003cp>【结束】\u003c/p>\u003cp>谢谢大家的分享。通过刚才的学习，希望大家能够把知识拆为己用，当遇到限制性信念时，可以运用这4种方法松动信念，为自己打开解决问题的思路。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":false}}],"created_at":1546069730000,"updated_at":1546070298000,"ria":true},{"id":6090,"topic":"EQ型处理他人情绪","learn_goal":"适用EQ型处理情绪模式，有效处理他人情绪","remark":"","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"邓燕珊|珍妮","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;Hello，大家好，我是爱视觉爱培训的珍妮，为了让各位更好地进行拆为己用，我们来分组。从我的左手边开始，两两为一组，今天下午一同分享，一起学习！我的指令清晰吗？\r\n【图书介绍法】\r\n事件：各位有没有这样的经历？当你失恋或者面试失败、考试挂科时，你的朋友对你说不要难过，再来就是了或者带你去唱歌喝酒。无论是劝说还是转移情绪，你的负面情绪总是消散不去甚至被放大了。\r\n提问：如果对方有情绪的时候，你会怎么做呢？是对他说一大堆的道理劝说他，还是对他的情绪视而不见。你有想过有什么样的方式可以更好的处理他的情绪，更好地帮助他呢？\r\n影响：如果对方的情绪一直得不到解决，往轻了说他会一直处在情绪的漩涡里，严重的是渐渐对事情反应麻木了，没有感觉。同样地，你们的关系也会影响甚至恶化。\r\n解决：《重塑心灵》这本书帮我们破解了这个难题，他找到了我们常见的他人无效处理情绪的类型，并给出EQ型处理情绪模式，帮助大家实现有效处理他人情绪。\r\n【学习目标】\r\n在跟随我完成本次的ria现场学习后，我们学习者将学会面对他人有不良情绪时，识别无效的做法，用EQ型处理情绪模式接纳、分享、肯定以及策划，从而更有效的引导他人处理情绪并解决问题。\r\n &nbsp; &nbsp; &nbsp; &nbsp;\u003c/p>","ratings_count":1,"texts":[{"id":9338,"quote":"\u003cp>【A1量表自测】\u003c/p>\u003cp>学习有效处理他人情绪之前，我们先做一个小测试。测试的目的是为了自查我们现在处理他人情绪的方式程度如何？\u003c/p>\u003cp>请仔细阅读下面的表格每句话，按自己的实际情况为自己打分（1表示很不符合，6分表示非常符合）\u003c/p>\u003cp>1、如果对方产生情绪，我总是先看到不好的一面，想要远离。\u003c/p>\u003cp>2、在对方产生情绪时，我总是帮助他转移焦点不要困在情绪。\u003c/p>\u003cp>3、在两人沟通中即使对方情绪不好，我也会努力表达我的想法，给出我的建议。\u003c/p>\u003cp>4、看到别人有情绪，我会认为对方应该自己处理好情绪，不应该显露出来。\u003c/p>\u003cp>5、与有情绪的人沟通，我会觉得被传递负能量。\u003c/p>\u003cp>【I解释自测题】\u003c/p>\u003cp>请得分在20分以上（包括20分）的同学，举手示意我一下，几位得分超过20分的小伙伴，或许在处理他人情绪的时候犯了些常见的问题。如何有效处理他人情绪呢，在今天的拆页学习中会有所帮助。\u003c/p>\u003cp>刚才自测中得分低于20分的小伙伴，或许你们能很好地处理他人情绪，相信今天的学习也能对你有所启发。\u003cbr>\u003c/p>\u003cp>【阅读拆页】\u003c/p>\u003cp>处理他人情绪通常会有四种没有效果的类型:\u003c/p>\u003cp>1.交换型,给予一些对方在乎的价值去驱使对方的情绪暂时消失，例如小孩子糖果要他停止哭泣，带对方去唱歌饮酒以驱走情绪。这些都是暂时性的，因为没有对引起情的事情做任何事，只要那些价值消失，同样的情绪会再次出现。\u003c/p>\u003cp>2、惩罚型,把情绪看作恶毒的东西，是不应该出现的，对方应因此而受罚，就像威吓孩子说再哭便会打他。若对方是成年人，惩罚包括拒绝沟通不闻不问、冷言冷语、斥责等。这样孤立了对方，并不能舒缓他的情绪，而只会使他产生更多的情绪\u003c/p>\u003cp>3.冷漠型,认为成年人应该有能力使自己不会产生这样的情绪，或者不应把情绪显露出来，同时又认为情绪是每个人自己的事，应该自己处理。所以，这种类型的行为模式是完全漠视对方的情绪，对对方的情绪视而不见，或者示意对方应自己处理好情绪。\u003c/p>\u003cp>4.说教型,顾名思义这种类型是说大量的道理，而不顾对方的感受，这很容易使对方陷入更大的情绪困扰中。\u003c/p>\u003cp>有效的方式是EQ型的方式，让我们先来看看“EQ”（情绪智能）是什么。“情绪智能”来自英文的 Emotional Intelligence。这个名词是因1995年美国人丹尼尔・戈尔曼（ Daniel Goleman）所写的书《 Emotional Intelligence而受人注意的。这本书主要的意思是指出一个人的成功，1Q（智力）只占小部分（20％），而EQ占80％。该书说EQ包含五个意思:\u003c/p>\u003cp>◇认识自己的情绪\u003c/p>\u003cp>◇管理自己的情绪\u003c/p>\u003cp>◇有效推动自己\u003c/p>\u003cp>◇认识别人的情绪\u003c/p>\u003cp>◇处理好人际关系\u003c/p>\u003cp>我认为只用两点便能充分解释EQ的意思:\u003c/p>\u003cp>◇清楚认识和正确运用情绪去帮助自己\u003c/p>\u003cp>◇了解和分享别人的看法和感受\u003c/p>","explains":"\u003cp>【I简短互动】\u003c/p>\u003cp>我们越来越感觉到情绪的重要性，也越来越关注自我的情绪管理，调节自己的情绪。但我们却忽略了如何有效处理他人的情绪，拆页里提到的无效方式的4种类型，大家还记得是哪4种吗？（交换型、惩罚型、冷模型、说教型）\u003c/p>\u003cp>对于这种处理方式，我想大多数伙伴都经历过。有过相关经验的小伙伴，举手示意我一下。（举手）\u003c/p>\u003cp>看来我们都深受这些方式影响，那每次过后你的情绪能否得到缓解呢？\u003c/p>\u003cp>（并没有，对吧。而且无效的处理方式会人情绪反复出现，甚至更严重。）\u003c/p>\u003cp>避免无效方式的方法就使用EQ处理情绪模式，EQ型是指正确认识和接受情绪，并去了解别人和分享感受。\u003c/p>\u003cp>既然有效处理情绪对我们来说十分重要。那么如何使用EQ型处理情绪模式呢？有4个步骤：\u003c/p>\u003cp>第一步：接纳，接受对方情绪。观察对方的面部表情、肢体状态，直接了当地说出你看到情绪并主动和他沟通，作为处理情绪的第一步，让对方知道你愿意关注和尊重他的感受。\u003c/p>\u003cp>第二步：分享，作为处理情绪的最关键一步：先处理情绪感受，再处理事情。我们在倾诉的时候习惯先出事情的内容，但情绪没有处理，聊事情是不会有效果，反而让情绪放大。所以先引导对方关注自己的情绪，再去处理事情。\u003c/p>\u003cp>第三步：肯定，肯定对方的动机及需要，引导发现不对的行为。&nbsp;\u003c/p>\u003cp>第四步：策划，引导对方找出更好的做法，思考怎么面对这件事情，怎么解决。\u003c/p>\u003cp>【匹配例子】\u003c/p>\u003cp>接下来举个我的例子，上周朋友找我倾诉提到她对公司领导不满意想要换工作，当时我打断她说，你不是想要换工作而是要逃避现状。最后，她也转移了话题。\u003c/p>\u003cp>而如果运用EQ处理情绪模式，我会接纳她的情绪，询问她：“你看起来不开心，是怎么了呢？”让她感受到我在尊重她的感受。\u003c/p>\u003cp>然后在听她提到领导的问题时，我会请她分享情绪，“感觉你对此很愤怒，是吗？”她可能会说出自己真正期待的需求。\u003c/p>\u003cp>等感受到她的情绪得到释放，这时我再肯定她渴望被关注和认可的需要，引导她发现自己现在消极怠工的现状。\u003c/p>\u003cp>最后帮助她一起策划解决问题的方案，什么样的做法可以让她更好地达成自己的需求。\u003c/p>\u003cp>通过EQ处理情绪可以有效帮助对方处理情绪，处理情绪后再解决问题可以让对方更愿意主动面对问题，而通过策划解决同类问题可以避免同样的情绪重复发生。\u003c/p>\u003ch2>【预防异议及适用边界】\u003c/h2>\u003cp>对我们大多数人来说，直接进行EQ处理情绪模型的后2步“肯定”和“策划”更为简便，前面2步接纳和分享是否可以省略呢？\u003c/p>\u003cp>答案是不可以的，要清楚知道当别人向我倾诉时，面对的不仅仅只是他人的事件问题，还有他人的情绪。当人有情绪时，是很难理性解决问题的。我想，这点大家都深有体会。有效处理问题的前提是处理对方情绪。有时候，你只需要做到前2步，接纳和分享对方的情绪，当对方重新感受到关注和认可时他可能就自己找到了解决问题的方法。\u003c/p>\u003cp>EQ处理情绪模型特别适合适用于亲密关系无论是亲人、爱人还是亲子、朋友，只要你愿意帮助对方处理情绪更有效解决问题，其实都可以使用。\u003c/p>","interaction":"\u003cp>【A3场景设计】\u003c/p>\u003cp>接下来进入现场演练的环节，今天的演练任务是角色扮演，我给大家设计了一个场景。场景是拆书活动结束后，小红回到家已经是晚上11点了。拿钥匙开门发现自己家门被反锁了，她只好按门铃吵醒了已休息的父母。小红爸开门时责备她，晚回来也不和家里人打招呼。小红觉得挺委屈，把这件事情告诉了小明，小明根据EQ处理情绪模式进行回应。\u003c/p>\u003cp>【小组讨论】\u003c/p>\u003cp>请大家在小组内讨论一下小红和小明的对话，小明需要使用EQ处理情绪模式进行回应，并加工成对话。\u003c/p>\u003cp>【指令】\u003c/p>\u003cp>请大家花5分钟讨论出可能的对话，并记录下来。5分钟后，我会邀请小伙伴来进行角色扮演。\u003c/p>\u003cp>好了，时间交给大家。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>小红：小明我烦死了，刚被我爸骂了。我回家按门铃吵醒他们被他批了一顿。真的很难受，本来就加班很辛苦还要被批评。\u003c/p>\u003cp>小明：那你这么晚回家又挨了顿骂，是不是感觉特别不舒服，是吗？（接纳及引导分享情绪）\u003c/p>\u003cp>小红：是啊，还挺委屈的。本来以为加班回来晚了，家里会准备夜宵或心疼我一下。结果夜宵没了，还被批一顿。（分享情绪）\u003c/p>\u003cp>小明：我很理解你，我也遇到过类似的事情。因为出去没给家里人打电话，家里人很生气为什么出去呀。这个时候，内心确实不太好受。\u003c/p>\u003cp>小红：是啊，太不好受了。不过和你说完感觉好多了。\u003c/p>\u003cp>小明：嗯嗯，确实你现在工作压力很大，肯定希望家里人能够在背后支持你和关心你的。不过，爸爸批你是不是还有其他的原因呢。（肯定正面动机和引导负面行为）\u003c/p>\u003cp>小红：父母可能也担心我在外面晚呀，最近和爸妈的沟通也不太好。\u003c/p>\u003cp>小明：是啊，我也理解有时候在工作遇到挑战不开心也不想告诉父母怕他们担心。有时候不告诉他们又会不理解我干嘛那么辛苦。那我们来想想如何避免这个问题再重演呢？（共同策划）\u003c/p>\u003cp>小红：我想了想明天早上一早吃早餐的时候，把自己工作情况讲一讲。最近工作上也有一些小成就，我觉得可以分享一下。这段时间加班的情况也可以了解一下，今晚就不打扰他们了。\u003c/p>\u003cp>小明：你这个想法太好了，那你先休息一下好好睡个懒觉吧。祝你好梦！\u003c/p>\u003cp>小红：谢谢晚安。\u003c/p>\u003ch2>【a2应用】\u003c/h2>\u003cp>知识点只有经过大量的刻意练习，才能真正变成自己的能力。给大家布置一个课后作业：在未来一周，想象你可能会遇到的场景，比如客户投诉、同事抱怨、爱人发脾气、孩子与人发生矛盾等等，刻意使用EQ处理情绪模式去帮助对方处理情绪。请大家在今天拆书活动结束后一周内完成它，并写下应用收获。在群里分享，也可以单独发给我。\u003c/p>\u003cp>【学习者案例搜集】\u003c/p>\u003cp>在吃早餐的时候，老公和我说部门新入职的跟单想辞职了。\u003c/p>\u003cp>我下意识地反应，准备脱口而出：那怎么办呢？想直接给他建议和方案，想到这属于说教型对方可能并不想听只是想倾诉一下。\u003c/p>\u003cp>想到了上周学习地EQ情绪处理模型：接纳-分享-肯定-策划。我看到了他的无奈，并想要让他感受到我在关注他。\u003c/p>\u003cp>于是我对他说，再次发生这样的事情，感觉很郁闷是吗？\u003c/p>\u003cp>老公和我分享了他这段时间的辛苦和劳累，最近很多工作主要原因是原来的跟单离职后，新的跟单没有那么快上手。\u003c/p>\u003cp>我给了他一个拥抱并感谢他对家里的照顾还要兼顾繁忙的工作，然后引导他思考每次人员替换都给他带来冲击和影响，有什么更好的方法避免人员替换对他的影响呢？\u003c/p>\u003cp>于是他想出了对现有的人员架构进行职责清晰以及制定完整的sop流程。让任何人到这个岗位都能比较快速的上手基础工作，减少他的工作量。\u003c/p>\u003cp>【结语】\u003c/p>\u003cp>通过今天的分享，大家了解了无效方式的4种类型以及EQ处理情绪模式。大家还记得是哪四种无效方式吗？(交换、冷漠、惩罚、说教)。\u003c/p>\u003cp>EQ处理情绪模式如何使用呢？（接纳、分享、肯定、策划）。\u003c/p>\u003cp>大家都好棒！\u003c/p>\u003cp>总的来说，先解决情绪再解决问题。最后，期望大家可以结合过往学习的各种沟通技巧更好地把EQ情绪处理模型应用到实际当中，谢谢大家！\u003c/p>\u003cp>今天的拆书就到这里，请大家用便签写下对我的反馈，谢谢大家。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1537194587000,"updated_at":1537196207000,"ria":true},{"id":4944,"topic":"意义换框法浅析","learn_goal":"在与他人沟通的时候 我们也要选对表达方式，使用正确的表达方式","remark":"《重塑心灵:一门使人成功快乐的学问》内容为：快乐是一个永恒的话题，也是人类一个谜题。有资料显示我们中的许多人可以说是不快乐的!你是否考虑过我们到底是怎么了？快乐从何而来，怎样寻找快乐，这是一个人们首先想问的问题；每个人的成长道路上，都不可避免地会遇到挫折失败，许多人在为自已的命运哭泣，这使得许多人的不快乐成为了一种习惯，在对待自己的时候，我们也要使用正确的表达方式。使用正面词语则是一种十分有效的方式，正面词语不仅可以用在沟通，也可以用于对己。","level":"TF3-1","duration":20,"status":29,"type":0,"chaishujia":{"username":"瑩雪","city":"青岛"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"大家上午好，我是瑩雪。很开心跟伙伴们一起进行我的3-1拆书。今天我们依然以小组为单位进行，首先我们进行一下分组（两人一组）。今天我要拆的片段出自国际NLP大师李中莹经典著作《重塑心灵》，李中莹先生最早把NLP完整地介绍到国内，因而被誉为“华人世界的国际级NLP大师”，他发展出大量独到而实用的思想和行为技巧，可以有效地帮助一个人培养出良好的心理素质。《重塑心灵》是讲NLP的书，而NLP是很实用的学问，它能够推动一个人快速地提升他的素质，进而享受更大的成功快乐。","ratings_count":3,"texts":[{"id":8028,"quote":"\u003cp>意义换框法\u003c/p>\u003cp>“意义换框法”是NLP技巧“换框法”中最常用和最好用的技巧。它完全只凭言语和思想模式而产生效果，是NLP的改变信念技巧中最快速最容易的一个。“意义换框法”是找出一个负面经验中的正面意义。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都只是人加诸的。既然是人加上去的意义，则一件事情——可以有其他的意义，也可以有更多的意义；可以有不好的意义，也可以有好的意义。试想一下，当你用一块石头去锤打一颗钉子，或者赶走一只老鼠，你赋予这块石头的意义是什么？它本来有这些意义吗？再想一想，一块石头可以有多少用途？\u003c/p>\u003cp>把上面问题引出的意念放在别人的一句话、一个行为，甚至环境出现的一些情况上，会给你什么启示？\u003c/p>\u003cp>下次坐车没有事情做的时候，可以试想一想一只曲别针可以有多少用途。也许这样你会明白一件事情的意义只是取决于我们的主观思想。\u003c/p>\u003cp>同一件事情里面总有不止一个意义包含其中。找出最能帮助自己的意义，便可以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。\u003c/p>","explains":"\u003cp>意义换框法改变思维框架，将认为负面的、无价值的东西转化为正向成长有价值、有帮助的东西，有助于突破我们原有的思维框架，使我们可以从一个全新的角度看问题，从而使问题得到解决，比如：\u003c/p>\u003cp>事件：因为别人的挑剔，导致我的工作展开很不顺利；觉得最近的事情好忙，我都没有时间处理我自己的事；孩子很不听话，觉得特别烦躁等等。\u003c/p>\u003cp>提问：当你遇到这种情况的时候你是怎么想的呢，是想办法解决这些问题还是就让自己的情绪一直这样消极下去呢？\u003c/p>\u003cp>影响：当你想着这些消极情绪时，是不是让你对事情的控制更加脱离掌控呢？有没有想过可能是因为你没有想到好的解决情绪的方法才让你觉得消极，事情才会变得“越来越糟”。\u003c/p>\u003cp>解决：今天我要拆的片段来源于《重塑心灵》这本书，本书让我们从新角度看待问题，避免人生被很多的框架（信念、价值）所框住，无论是哪一种换框法，都是让我们从一个比较狭隘的视角看到更大的空间，从而产生新的选择。有选择就是有能力，就能从中选择对我们最大的利益行为。今天我们将要了解一下“意义换框法”，意义换框法将会教我们如何转换我们对事物赋予的意义，通过对意义的转换解决上面的问题。\u003c/p>\u003cp>学习目标：通过今天的学习，我们将学会通过意义换框法（方法），找出负面经验中的正面意义（行为），把事情的价值改变，使事情由绊脚石变为踏脚石（效果），并熟练的运用到实际生活中的能力。\u003c/p>\u003cp>I·重述知识\u003c/p>\u003cp>先给大家分享几个我们生活中常见的负面转变正面的例子：1、负面：领导找我谈话，我心情不好；&nbsp; 转换成正面：领导找你谈话，你要高兴才对啊，这样你才能有进步的空间啊；2、负面： 这个月收入不高；&nbsp;&nbsp; 转换成正面：这样能让我更懂的合理支配和学习如何计划用钱；3、负面： 你怎么这么无聊呢？&nbsp; 转换成正面：所以我才运用无聊的时间，寻找更有意义的事情；&nbsp;&nbsp;&nbsp;&nbsp; 凡事没有好与坏，只有好与更好，NLP就是将我们从好带到更好。所有一切人、事、物是中立的，当我们所赋予的角度不同，其意义也就不同了。”（换框法”是找出一个负面经验中的正面意义。）我们所理解的事情不同的意义又会给我们带来不同的感受、情绪，这些感受、情绪是推动我们做某些行为、不做某些行为的动力。\u003c/p>\u003cp>为了使大家更熟练的运用意义换框法的语言模式，请大家做到以下步骤：\u003c/p>\u003cp>第一步：把句中的“果”（工作不开心）改成它的反义词。\u003c/p>\u003cp>第二步：把句首的“因为”放到最后。（上级挑剔，所以我努力工作，因为...）\u003c/p>\u003cp>第三步：反复思考怎么能写出完整的句子来，至少要有六种表达，然后选出最能接受的一句话。\u003c/p>\u003cp>第四步：反复的阅读你觉得最好的一句话，并和原来这句话（因为上级挑剔，所以我工作不开心。）作比较，体会一下内心的感受，感觉一下哪句话更好。\u003c/p>\u003cp>例如：上级挑剔，所以我工作积极，因为：让我能够突破；/让他无从挑剔；/让我能力更强；/让我能够跟最能相处的人共事；/让我工作更严谨；/让我更成功；\u003c/p>\u003cp>我们再来看一下换框前的负面案例：有一位很好的医生，他不能拒绝找他出诊的病人，这使他有过多的业务，休息时间不够，家人也抱怨他只醉心于工作，忽略了他们。使这位医院极度陷入焦虑状态，最后医生通过NLP换框法，学会拒绝一些出诊要求如何会使他成为一个更好的医生、能帮助到更多的人。由此可见，通过这种方法来改变原有的意义框架，是十分有效且快速的，它用简单的两三句话就可以解决现有的状况。\u003c/p>\u003cp>&nbsp;&nbsp;【 需要注意的是，这种方法比较适合处理与自身有关的问题，例如工作或是家庭，在使用意义换框法时，需要明白最让你困惑的事情是什么（工作总是做不好的原因是什么？） 这个事情的根本原因是什么（是老板太过严格还是自己跟本就没有努力到位？ ），并经过反复的实践，这样才能彻底的转换成正面的意义（明白了老板挑剔是因为自己不够努力，老板严格是为了让我前进）。】\u003c/p>","interaction":"\u003cp>A2\u003c/p>\u003cp>在将来可能会发生很多问题，我们多数会选择向别人倾诉，现在请小伙伴们想一下，在未来的一个月，你想运用意义框架法与谁进行一次对话，指引它从一个全新的角度看问题。这个人是谁呢？你想就哪件事和他沟通？给大家2分钟时间写一下。\u003c/p>\u003cp>【\u003cstrong>分步催化2\u003c/strong>】\u003c/p>\u003cp>接下来请你运用意义换框法来进行对话，指引你的朋友把问题转换，用一个全新的角度看问题。\u003c/p>\u003cp>请大家用5分钟思考并想出具体的情景，用一个简短的步骤写下来。然后我们邀请两位小伙伴来分享一下他的作品。\u003c/p>\u003cp>【学习者分享】\u003c/p>\u003cp>A：我想和我的一个朋友说，有一个大公司给他发了招聘通知，但专业不对口。我想这样对他说：我听说有个大公司给你发了招聘通知？虽然专业不是很对口，但这样也很好，虽然你原来的工作投入了很多得精力，也投入了很多时间。你做了这么久这个领域，也该换一换口味了是不是。事情要往好了想啊。换了新工作可以认识新的人，学到新的技能，一开始可能会辛苦，但总会有回报啊\u003c/p>\u003cp>刚才伙伴的分享中，运用了意义换框法，可见大家都已经明白换框法的道理。希望大家在生活中多加运用，熟练掌握，你决心改变你对事情的看法，改变你的命运，你的人生亦将会更加美好。\u003c/p>\u003cp>感谢大家的陪伴，下次再见！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1522587316000,"updated_at":1524128033000,"ria":true},{"id":4901,"topic":"倾听是良好沟通的前提 恰当使用正面词语","learn_goal":"改善自己的人际关系网","remark":"《重塑心灵:一门使人成功快乐的学问》内容为：快乐是一个永恒的话题，也是人类一个谜题。有资料显示我们中的许多人可以说是不快乐的!你是否考虑过我们到底是怎么了？我们丢失了什么呢？是人类自我的一种情感发展趋势？还是我们生活的方式在影响着我们的心情呢…… \r\n快乐从何而来，怎样寻找快乐，这是一个人们首先想问的问题，因此，本文开始从“快乐何处寻”来谈起，能力与道德，或者说事业与人品是一个人得到社会认可的两个重要标准，而这两个方面与快乐都有很大的关系；每个人的成长道路上，都不可避免地会遇到挫折失败，许多人在为自已的命运哭泣，这使得许多人的不快乐成为了一种习惯，因此，无论挫折失败，我们都可以很快乐地应对生活中","level":"TF2-4","duration":60,"status":29,"type":0,"chaishujia":{"username":"瑩雪","city":"青岛"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"\u003cp>&nbsp; &nbsp; &nbsp;大家上午好，我是瑩雪。很开心跟伙伴们一起进行我的2-4拆书。今天我们依然以小组为单位进行，首先我们进行一下分组（两人一组）。&nbsp; &nbsp; &nbsp;&nbsp;\u003c/p>","ratings_count":3,"texts":[{"id":7974,"quote":"\u003ch1>F：今天我要拆的片段出自国际NLP大师李中·莹经典著作《重塑心灵》，李中莹先生最早把NLP完整地介绍到国内，因而被誉为“华人世界的国际级NLP大师”，他发展出大量独到而实用的思想和行为技巧，可以有效地帮助一个人培养出良好的心理素质。\u003c/h1>\u003ch1>A：《重塑心灵》一书最大的特色是保持了李中莹老师惯有的务实与落地的态度。《重塑心灵》一书站在大众的角度，以尽量通俗的语言或接近英文原意的中文重新诠释了惯用词汇。NLP在中国尚不明确的时候，李中莹老师已经做了先驱，为我们指引出一条丰富多彩的道路。\u003c/h1>\u003ch1>B：《重塑心灵》是讲NLP的书，而NLP是很实用的学问，它能够推动一个人快速地提升他的素质，进而享受更大的成功快乐。\u003c/h1>\u003cp>&nbsp;&nbsp;&nbsp; \u003cstrong>书中有一部分讲的是个体在生存时面对的问题。\u003c/strong>\u003c/p>\u003ch1>个体在生存时面对的问题很简单，一方面是对待自己，另一方面是对待他人。在与他人沟通的时候 我们也要选对表达方式，使用正确的表达方式会使得沟通变得很简单许多。在对待自己的时候，我们也要使用正确的表达方式。使用正面词语则是一种十分有效的方式，正面词语不仅可以用在沟通，也可以用于对己。\u003c/h1>\u003cp>\u003cstrong>今天的拆书我们来了解一些关于沟通和正面词语方面的知识。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>请阅读第一个拆页：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>R1\u003c/strong>\u003cstrong>阅读原文片段\u003c/strong>\u003c/p>\u003cp>沟通是一方发出信息，另一方接收进去，并且做出回应。当沟通用非语言的方式进行，倾听将需要用眼睛完成；当沟通用语言的方式进行，则倾听将需要同时用眼睛和耳朵进行。更积极的倾听还需要用上嘴巴、心甚至整个人。有了足够的倾听，我们才能清楚准确地了解信息发出方的意思，因而才能够做出最正确的分析、感受，并且做出最符合所需的回应。\u003c/p>\u003cp>卡拉•韩娜馨博士是运动机制学的权威，她研究指出，每个人都有两边脑、两只眼睛和两个耳朵，但在幼时成长的过程中，会发展成主要运用其中的一边。我们都知道左边的脑控制右边身体，而右边的脑控制左边身体。当一个人处于压力下时，非主要运用的一边脑会几乎停顿，而只靠主要运用的一边脑处理事情。\u003c/p>\u003cp>在另一方面，倾听并不是只听到对方的文字及其意思，更重要的倾听是：\u003c/p>\u003cp>①对方语言文字背后的信念、价值观、规条和对方对自己“身份”的定位。若有问题、争吵或冲突，真正的原因总是在这里找到。\u003c/p>\u003cp>②对方说话时的语音语调和身体语言。这些显示出对方的内心状态，尤其是他的情绪感受。嘴巴可以说出很多好听的话，但是语音语调和身体语言真实地显露他内心的真正立场。\u003c/p>","explains":"\u003cp>\u003cstrong>I\u003c/strong>\u003cstrong>重述知识\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习目标：\u003c/strong>\u003cstrong>在跟随我完成本次学习后，学习者能够基本解决在与他人沟通时因不会倾听而导致矛盾的问题。\u003c/strong>\u003c/p>\u003cp>不管是家人，朋友，同事甚至上司，每个人身上都有密码，倾听是打开密码的钥匙。也就是说，只有你会倾听了，就会在倾听中知道他们所要关心和感兴趣的信息，能听到说者话里的心里话了，那么反馈，自然就一击即中。\u003c/p>\u003cp>倾听是对信息进行积极主动的搜寻行为。倾听与一个人的态度、理解、记忆、情感都有一定的联系，倾听是一种行动，一种艺术和一种心智，使我们了解他人和事情真相，不需出声即可达到沟通目的。\u003cstrong>步骤：\u003c/strong>倾听的艺术关键是在于，\u003cstrong>一、听者应该集中自己的注意力；二、听者应该\u003c/strong>\u003cstrong>适时给说话人一个示意\u003c/strong>。\u003c/p>\u003cp>现实生活中每个人都需要有忠实的听众，用心倾听最大的好处就是深得人心，容易使双方心灵沟通、增加信任度，这一点在工作和交友上至关重要，在婚姻与家庭生活中更重要。设身处地地倾听不但可以了解对方的真实情况，还有助于增进彼此的感情。所以，无论你在社会和家庭中扮演什么角色，都要学会倾听别人说话，即使无力解决实际问题，也比不说不听、袖手旁观强百倍。在现实生活中我们要养成良好的倾听习惯，培养自己的耐性，在倾听别人的同时也常倾听自己的内心，学会倾听有利于知己知彼。\u003cstrong>不这么做的坏处：\u003c/strong>不懂倾听的人，不会是一个好的沟通者，在沟通过程中，大多数人习惯着急发言，总在听到他人前半句的表述之后，就急于发表自己的看法。殊不知，我们可能因此就让倾听半途而废，进而曲解了对方的意思。\u003cstrong>案例：\u003c/strong>有这样一则故事，课堂上老师提问一个5岁的小男孩：“你长大后想做什么？”“飞机驾驶员！”男孩气宇轩昂地站起来回答道。“很好。”老师继续问：“如果你驾驶的飞机经过大海时，引擎熄火了，你怎么办？”“我会让大家绑好安全带，然后，我带上降落伞，跳下去。”男孩几乎没有犹豫，答案冲口而出。“坐下！你是个没有责任心的孩子，我很失望。”老师生气了，冷冷地挥了挥手。坐下的男孩满脸通红，周围传来了同学们窃窃的笑语。突然，男孩大声哭着说：“老师，我要回来的，我还要回来的……我是去取燃料！”晶莹的泪滴挂在男孩胖乎乎的脸上，孩子的眼睛明亮有神。老师愣了几秒，脸颊微微发起烧来。倾听，不止是竖起耳朵，它要求心灵同样真诚。有时候，心还要走在耳朵的前面。\u003cstrong>案例：\u003c/strong>我的一个朋友，跑保险的，他总是能够拿下别人办不到的单子，别人问他他是怎么做到的，他却只笑笑：没什么好方法，我会集中注意力倾听客户的话，并适时给予回应。\u003cstrong>预防异议：\u003c/strong>你可能会感觉耐心倾听哪有那么简单啊，很多时候我们根本不可能听下去。但其实，只要听者全身心投入，适当给予回应，对于说话者而言就是很大的鼓励。而当你能够做到这些，你就基本做到了耐心倾听。接下来你要做的就是在不断的实践中养成耐心倾听的习惯。\u003c/p>","interaction":"\u003cp>\u003cstrong>A1\u003c/strong>\u003c/p>\u003cp>既然我们已经弄明白了沟通的关键是倾听，那我们就将上面的方法应用到实际中。\u003c/p>\u003cp>在一位愿意接纳的倾听者之前，我们可以厘清自己的想法，发现自己内心的感受。当我们倾听别人有不同见解时，可以继续倾听，揣摩说者的意图，前后连贯，有时会增进我们的理解，因此，在将自己的经历告诉一个肯倾听我们说话的人的同时，我们也更能聆听自己的声音。\u003c/p>\u003cp>\u003cstrong>在你的过去的生活和工作中，是不是也有沟通倾听问题？如果让你回到过去，你会怎样利用我们讲的两个步骤？请大家思考并写下来。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>\u003cstrong>：\u003c/strong>过去小学生没话找话时我一般会不理他，而他会觉得很失落。现在看来，我需要照顾他的感受，沟通的关键是倾听。现在我会集中注意力倾听他的讲话并适时给予回应。当我们与孩子沟通时，尤为重要的是倾听，孩子不需要我们给到建议或者指令，只想表达并寻求我们的关注，从而认真的倾听给到孩子想要的需求就好。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>倾听是需要学习的。现实生活中喜欢抢发言权的人有很多，因为我们通常都只在意和关心自己的需要和兴趣：高兴的事情，不吐不快，对于烦闷和痛苦也同样需要宣泄。但在大多数交流中，我们用于应答和倾听的时间，大概和讲话的时间一样多。只是我们自己常常无法意识到这点，而且善于听取他人谈话的人也并不多。由于不善于倾听，很多商家也因此失去了客户；过于热衷的畅谈自己而忽略了他人的感受，其结果就是谈而不畅，因为别人对于倾听你的谈话已经失去了兴趣。\u003c/p>\u003cp>看到的不一定是真实的，在一本书上我曾看到这样一则故事：教堂里丢失了圣子塑像，神父心急如焚，到处寻找。一日，神父看见一个家里很穷的五六岁男孩拉着一辆颜色鲜红的四轮儿童玩具车，追上去本想对他说句“圣诞快乐”，并赞美一下他的玩具马车，可是神父走近时发现马车里坐着他苦苦寻觅多时的圣子塑像。神父生气了，厉声呵斥住了孩子，并严厉地盘问他。孩子对自己的行为供认不讳。由于年龄太小，他显然还不知道偷窃是一中罪过，更不知道偷窃教堂里的圣像是一种更为严重的罪过。于是神父用清晰而响亮的话语阐明了利害。而孩子却回答：我没有偷那个绳子塑像，事情根本不是您说的那样。我一直都希望得到一辆红色的四轮马车作为圣诞礼物，但是我们家太穷了，买不起，我一直都没有得到。今年圣诞节前，我向圣子塑像祈祷，并向他许下诺言说，今年我要是能得到一辆红色的四轮马车，就第一个带着他坐车出来兜风。\u003c/p>\u003cp>有时眼睛看到未必是真实的，如果我们肯倾听一下，会有助于我们弄清事情的真相。\u003c/p>\u003cp>在以后的一段时间，你想倾听谁的话呢。请大家思考3-5分钟，并分享自己的故事。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>\u003cstrong>：\u003c/strong>接下来的一段时间，我最想倾听我的闺蜜。闺蜜最近发生了很多事，现在我明白了，她最需要的是一个能倾诉的人，今后我想试着倾听她，她需要一个人倾听，并不是需要一个方法。\u003c/p>\u003cp>\u003cstrong>B\u003c/strong>\u003cstrong>：\u003c/strong>接下来的一段时间，我最想倾听我的客户。过去跟客户沟通，谈不拢的时候，我总会打断了对方的话，双方都在表达自己的观点。原本这通电话是想要双方意见达成一致的，结果双方都带有情绪，开始区分责任、扯皮。双方都意识到带着情绪去表达或者一方愿意倾听，就会走向不可控制的方向。我等对方说完，对方也等我说完，双方明白了彼此的意思都是想要尽快的完善减少伤害，后面的沟通比较顺畅，通过这件事让我明白，表达者一方不要带情绪，倾听者要倾听完表达者的话，从底层含义去理解表达者的意思，耐心倾听才能达到很好的沟通效果。\u003c/p>\u003cp>\u003cstrong>总结：\u003c/strong>当我们使用这样的倾听方式去与他人沟通时，就会发现我们很容易的就和对方达成共识，你也能更好理解他说的话，也就很少出现你不懂他说的是什么的尴尬场面了。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":7975,"quote":"\u003cp>沟通还需要正确使用正面词语，下面请大家阅读第二个拆页：\u003c/p>\u003cp>\u003cstrong>R·阅读原文片段\u003c/strong>\u003c/p>\u003cp>恰当使用正面词语\u003c/p>\u003cp>语言显露一个人心态和思想的深层内涵，同时我们可以运用语言去改善自己及别人的心态和思想，因而改变行为和结果。”良言一句三冬暖，恶语伤人六月寒“说的正是这个道理。事实上，对自己及身边的人，我们也经常用语言操纵着自己和他们的心理状态。\u003c/p>\u003cp>在我们的意识和潜意识之中，所有的情感、思想、欲念、感受，都似一团模糊不清的星云。目前的科学还没有准确把握语言究竟是怎样编码、生成的，哪怕是最先进的口语或写作教材，也无法教会人们按照特定的流程、特定的方式出口成章或妙笔生花。尽管如此，我们经过大量研究，发现大脑和语言之前，还是有些规律可循的。规律之一就是——人类的大脑有一个奇怪的特点，就是不能接受含有”不“字的指令。\u003c/p>\u003cp>想象你是餐厅的经理，正在招待我这个顾客，我点菜说”我不吃牛肉，不吃螃蟹、不吃辣椒的东西、不要油炸的东西。“你会问我：”那你想吃什么？“假如我只重复前面的话语，最终你会说：”先生，我没有办法为你做什么，因为你还没有告诉我你想吃什么。”\u003c/p>\u003cp>现在，看看以下的指示：“你不可以想老虎，绝对不可以想老虎，大老虎不可以想，小老虎也不可以想，就算是白色的老虎也不可以想。总而言之，你不可以想老虎，不可以想老虎！”现在，检查一下你自己：你正在想什么？对了，你在想老虎！\u003c/p>","explains":"\u003cp>\u003cstrong>I\u003c/strong>\u003cstrong>重述知识\u003c/strong>\u003c/p>\u003cp>\u003cstrong>目标：\u003c/strong> 通过学习，学习者能够将负面词语替换成正面词语，不再提及你不想要的东西，而关注你想要的东西。\u003c/p>\u003cp>正面词语帮助我们运用词语去改变思想而使自己在人生里有更积极和进取的态度遇事时更快找出解决跳出困境，在我们身边不难听到一些这类的说话显出说话的人陷于困境中：&nbsp;&nbsp; 我不要再被人欺负\u003c/p>\u003cp>我没有办法\u003c/p>\u003cp>这没有可能\u003c/p>\u003cp>困境里的“困”是因为事情里有一些自己无法控制的因素，使我们感到无可奈何，即是无能为力在困境中的人容易把思想放在那些无法控制或不想要的因素上。当能够改为注意一些本人可以控制的因素，自己便有办法对事情作出改善，即是说可以再来一次和越做越好的心态使事情有了新的转机，便肯再多试一份成功的机会，每一次都比上一次好。慢慢的累积下来有所成就的人便会比怨天尤人的人多多了。\u003c/p>\u003cp>常说我办不到的人，是一个失败者。而说我要找出一个解决办法的人，是一个乐观者亦是一个成功者，其实都是同一个情况。心态不同便出现反差大不相同的结果，\u003cstrong>方法：\u003c/strong>进而改变语言，\u003cstrong>一、\u003c/strong>可以把句子中的“不”没有等”负”性的字替换成正面的词语代替；\u003cstrong>二、\u003c/strong>可以使心态向积极的方向改变，例如:\u003c/p>\u003cp>1、我不要再被人欺负 \u003cstrong>改为 \u003c/strong>我要别人尊重我；\u003c/p>\u003cp>2、我没有办法 \u003cstrong>改为 \u003c/strong>我要试从一个新的角度去看这个问题；\u003c/p>\u003cp>3、这没有可能 \u003cstrong>改为\u003c/strong> 我要找出一个突破的方法；\u003c/p>\u003cp>看看这些例子你会发觉左边(负面)的例子，就像困在一个圈中，文字的意思完全是静态的而右边(正面)的语言，则是有动感是灵活的，则是可以有所行动的意思。我们的大脑跟随着思想去操纵我们的身体，而大脑只能接受正面的指令，给它负面的指令它便会做出与我们意愿相反的结果。例如：一些人不断叫自己不要惊慌，结果是不久之后自己惊慌到发抖甚至哭出来便是这个原因。同理可得，当你和别人说话的时候说“不可以或不行…”，他对方是完全无法接收到的。例如：多数的时候你不想让对方做的事情，对方偏偏做了，而你想让对方做的事情是因为你没有告诉他该做什么，你只告诉他不该做什么，导致对方无法达到你想要的。\u003cstrong>预防异议：\u003c/strong>你可能会感觉这哪有这么简单，但其实，你这种想法本身就是错误的，你应该将心态向积极的方向转变，试着从一个全新的角度看问题。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3\u003c/strong>\u003c/p>\u003cp>心态不同便会出现不同的语言，而改变语言便可以使心态改变。即把句子中的“不”、“没有”等负面的词删除，改用正面的词语代替。下面我们想象一下日常工作中常见的语言：不要迟到→请准时在8点前到岗；不要做与工作无关的事情→上班做与工作有关的事情；不要出事→注意按遵章守纪，按操作规程操作，安全在心中；不要急→心情要放松点，有节奏地工作； \u003c/p>\u003cp>下面我们来现场演练一下，以帮助我们更好地熟悉正面词汇的使用技巧。现在假设这样一个场景，小李因为总迟到被扣钱了，作为他的同事，你会怎样劝他。接下来就请大家两个人一组，运用上面所学的知识点，恰当使用正面词语来自行设计对白并进行角色扮演，时间为25分钟；最后我们会邀请一个组来分享他们的感受。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>a： 我最近发现一个方法可以让自己的工作越来越有动力。\u003c/p>\u003cp>b ：是什么？说来听听。\u003c/p>\u003cp>a ：我先举个例子，你最近是不是因为总迟到被扣钱了？\u003c/p>\u003cp>b ：嗯，虽然迟到是我的错，但也不能扣钱啊。\u003c/p>\u003cp>a ：那你再听一下这个：“听经理秘书说每个月迟到次数不多于两次的给发额外奖金。”\u003c/p>\u003cp>b ：哇 有这种好事吗？那我以后再也不迟到了。\u003c/p>\u003cp>a ：有没有发现有什么不同？\u003c/p>\u003cp>b ：第一个例子听起来就很不舒服，有想反抗的心理。第二个就不会，还会有积极向上的感觉。\u003c/p>\u003cp>a ：这个就是正面词语的影响啦，可以提高员工的积极性，使员工变得积极向上。\u003c/p>\u003cp>从二位伙伴的分享中我们不难看出，正面词语不仅能改变思想，还能使人在职场中改变负面情绪，从而调动更多的积极性。\u003c/p>\u003cp>\u003cstrong>A2\u003c/strong>\u003c/p>\u003cp>你最近的事情很多很杂，忙的焦头烂额，事情却没有得到很好地解决。这时的你就会有很多负面想法，这时就需要我们用正面词语改变负面想法：“虽然现在事情很多，但是我很有头绪，我能够按时间完成这些事，老板将这些事情安排给我是看重我，这说明我在领导的眼里还是很有能力的”。当你这样想时，你就会感觉活力又回来了。\u003c/p>\u003cp>你过去是否遇到过类似的问题？如果让你回到过去你该怎么做？请你根据这次拆书的内容，说出你的故事。大家思考5分钟，稍后请两位伙伴来具体分享。\u003c/p>\u003cp>\u003cstrong>【学习者分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>\u003cstrong>：\u003c/strong>最近在做总结的时候才发现还有一部分事情没做完，看着不多却很麻烦，我内心就很烦躁，十分想放弃。越这样想越不想做，经常在座位上盯着电脑什么都不做的过一上午，到了下午又开始后悔为什么上午什么都没做。第二天又开始这样重复。现在我会转换这些负面情绪：事情理清了再开始做，一件一件事情慢慢来，想着做完一件事的成就感，带着这种成就感接着往下做。事情是不可能做不完的，而事情做完是有成就感的。为了这种成就感我也要努力\u003c/p>\u003cp>\u003cstrong>B\u003c/strong>\u003cstrong>：\u003c/strong>负面语言有负面语言的使用场景，负面语言比较容易激发我们爬行动物脑的反应和力量，非常直接和有效，我们本能的就会使用否定性语言，因为它非常有力量。从理性的角度来讲，我们不希望矛盾激化，我们希望解决问题，而不是把谁激怒，解决具体问题，就要使用正面语言，正面语言有个大的问题，就是正面语言如果踩不到那个点上，正面语言很弱、无力，对方麻木，平常状态，负面语言好用是因为大量接受了相关的正面语言，正面语言没有全面的建立起来，所以你再给他说正面语言的时候就要丰富，除了声音、表情、动作、肢体语言，都是我们要表达的，认知失调。比如：习惯班有个孩子，第一周所有的孩子都在习惯养成的第一阶段，新鲜期，表现的都很优秀。第二周本性就暴露出来了，不听指挥，积分效应失效了。有一个孩子爱招事的特点、话多、总是通过伤害别人骂别人来凸显自己的与众不同。我们很快与家长沟通，找到原生家庭的痛点，更大的问题来自家庭，妈妈很痛苦，自己处于失控状态，孩子就用这种方式来表达情绪。如果我们用，不要动、不要说、别打他，这样的词语他会没有反映。会告诉他怎么做给到指令，现在光用语言已经不管用了。当他再要去伤害别人的时候，我会抱住他问，今天有什么不开心的事要跟老师说一说吗，然后他会说没有不开心，跟谁谁打了一架，人家没打过我，这样做并没有解决真正的问题，只是把他抽离出来。暂时缓解了矛盾，使用正面肢体语言，因为对于这个孩子光用语言已经不起作用了。从这个孩子身上让我体会到正面语言和负面语言，我们学到的多用正面语言，实际操作过程中，负面语言有他短期有效的价值。如果大量使用负面语言只会让伤害越来越深，正面语言不单是词汇问题，还有很多其他高级应用。\u003c/p>\u003cp>\u003cstrong>总结：\u003c/strong>今天的两段拆页，大家都有所感悟，我相信伙伴们与人沟通时会注重倾听的方式，倾听的能力是一种技巧，也是一种艺术。学会倾听，把说话的权利让给别人，才能获得自己想要的沟通成果。同时也要关注自己语言中的词语，多使用正面词语，恰当的使用正面词语能够让我们想通很多事情，也可以使事情变得简单容易。多用正面词语鼓励自己、激发自己，从而改变负面状态，变得更加积极向上，可以使我们更好的享受生活。感谢大家的陪伴，我们下次再见！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1522072866000,"updated_at":1527823706000,"ria":true},{"id":4786,"topic":"意义换框法的妙用","learn_goal":"学会使用意义换框法找到负面经验中的正面意义","remark":"","level":"TF1-2","duration":15,"status":30,"type":0,"chaishujia":{"username":"林俏宏","city":"南宁"},"club":{"name":"南宁老友分舵","city":"南宁"},"prologue":"各位小伙伴，大家好，我是小林，非常开心能在拆书帮认识这么多爱好读书的朋友。首先，请允许我用三个标签来介绍我自己。第一个标签：搬书虫。由于工作的关系，“沉迷”书堆之中不能自拔。第二个标签：闷罐子。不熟悉的环境会紧张，熟悉了以后会话不停～第三个标签：想改变。想通过拆书，从搬书变成用书，从闷罐子，变成有料的罐子！\r\n 我今天带来的拆页来自国际NLP大师李中莹经典著作《重塑心灵》，这本书是NLP领域最重要的中文著作，也是NLP学习者的必读书籍之一。NLP是指神经语言程序学，被解释为研究我们的大脑如何工作的学问。NLP的技巧配合大脑运作的模式去选择思想、语言和行为，它对人生的多个方面都能带来正面的影响，能够帮助我们摆脱困境，使我们能够获得轻松满足，成功快乐的人生。","ratings_count":2,"texts":[{"id":7843,"quote":"\u003cp>【R】“意义换框法”是NLP技巧“换框法”中最常用和最好用的技巧。它完全只凭言语和思想模式而产生效果，是NLP的改变信念技巧中最快速最容易的一个。“意义换框法”是找出一个负面经验中的正面意义。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都是人加诸的。既然是人加上去的意义，则一件事情—\u003c/p>\u003cp>&nbsp; &nbsp;可以有其他的意义，也可以有更多的意义；\u003c/p>\u003cp>&nbsp; &nbsp;可以有不好的意义，也可以有好的意义。\u003c/p>\u003cp>&nbsp; &nbsp;试想一下，当你用一块石头去锤打一颗钉子，或者赶走一只老鼠，你赋予这块石头的意义是什么？ 它本来有这些意义吗？再想一想，一块石头可以有多少用途？\u003c/p>\u003cp>&nbsp; &nbsp;把上面问题引出的意念放在别人的一句话、一个行为，甚至环境出现的一些情况上，会给你什么启示?\u003c/p>\u003cp>&nbsp; &nbsp;下次坐车没有事情做的时候，可以试想一想一只曲别针可以有多少用途。也许这样你就会明白一件事情的意义只是取决于我们的主观思想。\u003c/p>\u003cp>&nbsp; &nbsp;同一件事情里面总有不止一个意义包含其中。找出最能帮助自己的意义，便可以把事情的价值改变，使事情由畔脚石变为踏脚石，自己因而有所提升，这就是意义换框法。\u003c/p>\u003cp>&nbsp; &nbsp;意义换框法对一些因果式的信念最为有效。例如：“因为上级挑剔，所以我工作不开心。”\u003c/p>\u003cp>&nbsp; &nbsp;方法是把句中的“果”（工作不开心）改为它的反义词，再把句首的“因为”二字放到最后，成为：“上级挑剔，所以我工作积极，因为……”然后反复地思考如何能把句子写完，要求至少有六个不同版本，再找出其中最能够接受的一句。\u003c/p>","explains":"\u003cp>【I】现在看到，大多数小伙伴已经阅读完毕。这个片段选自李中莹老师的《重塑心灵》：一件事情具有怎样的意义，其实是人们主观加上去的，事实上，一件事情可以有很多不同的意义，这些意义有利有弊。通过“意义换框法”能够帮助我们从负面的经验中找到正面的意义，让这个正面的意义改变事情的价值从而为我们所用。\u003c/p>\u003cp>&nbsp; &nbsp;针对一些常见的因果式的经验如：“因为A，所以B”，我们可以用三个步骤找出其有用的意义，这个步骤是：第一步：取结果的反义，即B→非B；第二步：将“因为”二字后移至非B之后，形成“A，所以非B，因为…”句式；第三步.反复思考找出6个以上方法将句子补充完整并找出最能接受的一句。\u003c/p>\u003cp>&nbsp; &nbsp;下面我举个例子吧~，当然这个人不是我哈（笑）：消极句式：“因为她很凶，所以我不与她交流”。让我尝试采用意义换框法调整句式。首先，第一步：保持A也就是“她很凶”不变，B修改为非B就是“我不与她交流”修改为“我积极与她交流”；第二步：将“因为”后移，得到新的句子：“她很凶，所以我积极与她交流，因为……”\u003c/p>\u003cp>第三步，也就是最重要的一步，认真思考，将句子补充完整。在这里，我经过反复思考得到了6个新的意义：\u003c/p>\u003cp>1.我想锻炼自己的沟通能力；\u003c/p>\u003cp>2.我想了解她凶的原因；\u003c/p>\u003cp>3.我想让她改变对我的态度；\u003c/p>\u003cp>4.我想拓展自己的人脉；\u003c/p>\u003cp>5.我想用行动表达友善；\u003c/p>\u003cp>6.我要提升自己处理冲突的能力。\u003c/p>\u003cp>经过自己的筛选，我觉得“她很凶，所以我积极与她交流，因为我要提升自己处理冲突的能力。”这句话让我获得了积极与她交流的正面意义，改变了我“因为她很凶，所以我不与她交流”的消极看法，从而我开始尝试寻找与她积极沟通的方法。\u003c/p>\u003cp>这是我自己采用“意义换框法”变更常见因果式经验，从而找到消极经验的正面意义，从而推动自己积极行动的例子。\u003c/p>","interaction":"\u003cp>【A1】接下来，请小伙伴们回想一下自己的工作和生活中有没有类似“因为A，所以B”的消极经验？我们把我大家讨论一下，然后小组票选出最丧的一句，待会我会请这位丧王小伙伴来分享一下自己的经验。比丧时间4分钟，我来分一下组，我右手边的三位小伙伴就是第一组，左手边的是另一组，好~现在开始。\u003c/p>\u003cp>学习者讨论结果：\u003c/p>\u003cp>（小齐）我有两个孩子嘛，经常会有这样的情况出现。像上周六在家，两个孩子太淘气了，为了争一个玩具大吵大闹的，当时我又在忙家务，本来就很累，虽然知道淘气是孩子的天性，但是当时手上干着活，两个孩子又打闹，我当时太生气了。\u003c/p>\u003cp>我说“妈妈在打扫卫生。你们安静一下，看看书不要打闹。”可是两个孩子根本不听，还是继续闹，我实在忍不住就打了孩子屁股。\u003c/p>\u003cp>所以我的句式是“因为小孩太淘气，所以我想打他。”\u003c/p>\u003cp>【A2】接下来，我想请小组的每一位小伙伴尝试用“意义换框法”修改刚才票选的丧王句式，得到“A，所以非B，因为…”的句子，每人找寻3个正面意义将句子补充完整。请小伙伴用一分钟的时间在便签纸上写一写。待会我也会请一位小伙伴来分享他的新句子。\u003c/p>\u003cp>学习者讨论结果：\u003c/p>\u003cp>（小齐）因为越淘气的小孩越需要爱，所以你越打他其实他会越淘气。\u003c/p>\u003cp>&nbsp; &nbsp; 我要在遇到孩子淘气的时候，主动运用这个新句式“孩子越淘气，我越不能打他，因为我想努力践行新的育儿方法。”\u003c/p>\u003cp>&nbsp; &nbsp; 我的目标是：在接下来的一周中，孩子淘气的时候，我不再动手打他，而是尝试新的方法，平和的教育和引导孩子安静下来。\u003c/p>\u003cp>&nbsp; &nbsp; 首先我要转变自己“因为小孩太淘气，所以我想打他。”这样的想法，改用“孩子越淘气，我越不能打他，因为我想努力践行新的育儿方法。”来赋予教育淘气孩子的新意义。\u003c/p>\u003cp>&nbsp; &nbsp;在对话上我不会再用命令式的语气，而是尝试理解孩子，从孩子的角度出发，而不是直接动手打他。我会用努力践行新的育儿方法这样的想法来转变我的态度，更好的处理遇到孩子淘气的问题。\u003c/p>\u003cp>&nbsp; &nbsp;好的，感谢小齐的分享。今天，我们一起学习了“意义换框法”并掌握了使用新句式来找寻消极经验里新的正面意义的方法，非常好，希望小伙伴们都能通过学习将知识拆为己用。今天我的拆书就到这里，感谢各位小伙伴的参与。谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1520906403000,"updated_at":1520906403000,"ria":true},{"id":4542,"topic":"心理学","learn_goal":"身份、角色与自我价值","remark":"你是一枚热爱学习的小伙伴吗？\r\n你喜欢主动出击、掌控人生吗？\r\n你渴望幸福和快乐，对吗？\r\n关注拆书的你，不论你是处在自我成长的第1年，是第3年，还是第8年，都会有很多困惑，也会有更高的追求。那今天推荐的《重塑心灵》就可以成为你的枕边宝典，你可以跟随本书的架构，去全方位梳理、或者重点打造自己的思维，提升自己心理能量，帮助自己在变幻莫测的世界里创造自己的成功和快乐。\r\n今天为大家挑选的片段叫“身份、角色与自我价值”。通过今天的学习使大家能够理解身份、角色与自我价值的概念，写出至少5-10个角色并进行自我价值评分，挑出最想改变的角色、列出具体行为帮助提升其价值感。\r\n不用怀疑，你值得参与！","level":"TF2-3","duration":30,"status":0,"type":0,"chaishujia":{"username":"田华*善美","city":"武汉"},"club":{"name":"武汉古琴台分舵","city":"武汉"},"prologue":"大家好！我是心理咨询师善美。今天我们仍然是分两个小组进行，我的左手边到对面**为一组，我的右手边到对面**为一组。【F】今天我拆解的片段来自于《重塑心灵——每个人都拥有让自己成功快乐的能力》这本书，作者是李中莹老师。【A】他是最早把NLP这门学问完整的介绍到国内的引路人，这本《重塑心灵》非常通俗易懂、并且又系统性很强。【B】对于今天来到拆书帮的小伙伴，我相信都是热爱学习、主动出击、力求掌控自己人生、渴望幸福和快乐的伙伴，对吗？那么，不论你是处在自我成长的第1年，是第3年，还是第8年，都可以跟随本书的架构，去全方位梳理、或者重点打造自己的思维，提升自己心理能量，帮助自己在变幻莫测的世界里创造自己的成功和快乐。今天为大家挑选的片段叫“身份、角色与自我价值”。【学习目标】通过今天的学习，你写出至少5-10个角色并进行自我价值提升，在一定程度上改善你的自我价值感。","ratings_count":0,"texts":[{"id":7563,"quote":"\u003cp>身份是一个人心理活动的最核心部分，管理的是这个人关于“我是谁”和“我的人生是怎样的”的事情。这个人做或不做些什么、有什么计划、内心在隐藏或者逃避什么，全部都是为了满足这个人的“身份”需要。\u003c/p>\u003cp>一个人在他的人生里只有一个身份，却可以有很多个角色。身份照顾的是在所处的任何环境里的整个人，而角色照顾的则是这个人针对某些人事物的他。可以说，一个人的所有角色加起来，便是这个人的身份。这个人在他的生活里必然与很多人事物拉上关系。针对这些人事物，这个人会有很多不同的角色。例如和妈妈在一起时，就是儿子的角色，在写书的时候是作者的角色，站在台上讲课的时候是讲师的角色，在酒楼吃饭时是顾客的角色……所有这些角色合起来便是这个人的身份了。一个人活在这个世界里，有千千万万的角色，当我们把焦点只放在某一个情况里，例如我们跟妈妈在一起，我们也会把我们的角色当做我们的身份。也许最恰当的比喻就是钻石，一个人是整颗钻石，钻石上每一个切面代表了一个角色。\u003c/p>\u003cp>身份是心理活动的核心部分，支持这些活动的，也就是身份的能量，称作自我价值。身份管的是“我是谁”和“我的人生是怎样的”，自我价值的作用便是为了做出这两类事情而提供的推动力，这份推动力使“我”在人生里产生和增加“价值”，是每一个人建立成功快乐的人生的本钱。没有足够的自我价值，建立成功快乐人生便只是梦想，难以实现。已经成年但自我价值不足的人，可以运用以下的三个方法加以改善：1、言出必行，言出必准 &nbsp;&nbsp;2、有所不为，有所必为 3接受自己，肯定自己。\u003c/p>","explains":"\u003cp>好的，大家都看完了。我先跟大家确认一下这个拆页最核心的内容：\u003c/p>\u003cp>第一：身份是一个人心理活动的最核心部分，是回答“我是谁”和“我的人生是怎样的”。\u003c/p>\u003cp>第二：角色是在具体的环境和关系中的身份，把所有的角色合起来就是一个人的身份。比如我既是女儿，又是老婆，又是妈妈，还是儿媳妇，还是心理咨询师和新手拆书家等等，所有这些面都像是钻石的切面，合起来才是一个完整的我。\u003c/p>\u003cp>第三：自我价值是心理活动的推动力，有足够的自我价值，是每个人建立成功快乐人生的本钱。自我价值指的是角色的能量状态，是指钻石的色泽度，透明度等等。【细化的行动步骤】为了使“自我价值“这个模糊的概念有更直观的感受，我们第一步可以采用打分的方式。根据你的主管感受，你觉得没有价值为0分，非常有价值为10分。你可以给每个角色的价值进行大致评分。假如某些角色打分比较低，只有2分，我们首先要接纳自己这个2分，起码不是0分对不对？第二步再考虑是不是目前需要紧急提升、第三步再采用文中提到的三个方法进行提升。\u003c/p>","interaction":"\u003cp>那么接下来我们系统的认识并提升一下自己的身份、角色和自我价值。 \u003c/p>\u003cp>【具体确定的场景】我知道大家都有一个角色和身份，叫做“大学生“。我们需要进一步探讨的是，你认为自己是一个“满怀憧憬的大学生”，打7分，还是一个“迷茫的大学生”，打2分。这两个“大学生“的现状和未来都不一样，对不对？所以，你需要给自己一个更清晰认知。\u003c/p>\u003cp>好，如果咱们两个都是“满怀憧憬的大学生”，你还是一个“行动力很强的女生”，给自己打8分，而我是一个“看心情，随心所欲的女生”，给自己打5分，那么我们未来三五年在学业和职业方面很可能会拉开差距对吗？所以，你还需要给自己一个更完整认知。\u003c/p>\u003cp>现在每个伙伴面前有一张白纸。\u003c/p>\u003cp>【行动指令】首先请你用短句的方式，写出自己5-10角色，并进行价值打分。\u003c/p>\u003cp>接下来挑出自己最想改变的角色。\u003c/p>\u003cp>最后写下来针对该角色，你要做什么、以及不能做什么事情，来调整自己的角色行为和价值感。\u003c/p>\u003cp>&nbsp; 每人大概用3-5分钟独自写完以上内容，然后用5-8分钟在小组内讨论，给彼此一些反馈和建议。最后我们邀请1位小伙伴来展示一下自己，让我们大家充分的认识一下她，好吗？\u003c/p>\u003cp>我是一名大学生。 &nbsp;我给自己打7分。\u003c/p>\u003cp>我是一名志愿者。 &nbsp;我给自己打7分。\u003c/p>\u003cp>我是父母的女儿。 &nbsp;我给自己打8分。\u003c/p>\u003cp>我是两个姐姐的妹妹。 &nbsp;我给自己打8分。\u003c/p>\u003cp>我是他们的学姐。 &nbsp;&nbsp;我给自己打7分。\u003c/p>\u003cp>这名伙伴的自我价值感整体比较高。而且现场她给自己打7分的比如作为学姐和志愿者，别人给她的评价还更高，所以自己最想改变的角色没有做深入探讨。（另一伙伴写的是：我是个不孝的儿子，给自己打2分。结束后单独进行交流调整）。\u003c/p>\u003cp>我是一名有上进心的大学生，我给自己打7分，我接纳自己，认可自己，作为大学生，我希望我竭尽所能去做到成绩优异，办事能力强。\u003c/p>\u003cp>我不要有拖延（的习惯）。\u003c/p>\u003cp>谢谢大家的积极参与，掌握得都挺好的。因为身份是所有心理活动的核心内容，所以今天我们对身份，角色和自我价值的探讨，希望能从根本上帮助大家更完整、清晰的看待自己，使大家在自我成长的路上能事半功倍。\u003c/p>\u003cp>我是心理咨询师善美，专注于个人成长已经十年。如果大家有想进一步了解的，可以加我微信，有缘的话我们下次拆书再见喔！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1516582947000,"updated_at":1516583051000,"ria":true},{"id":4487,"topic":"如何选择实现目标的方法","learn_goal":"学会用三步法来判断实现目标的方法是否值得去尝试","remark":"","level":"TF1-1","duration":15,"status":30,"type":0,"chaishujia":{"username":"林俏宏","city":"南宁"},"club":{"name":"南宁老友分舵","city":"南宁"},"prologue":"各位小伙伴，大家好，我是小林，非常开心能在拆书帮认识这么多爱好读书的朋友。首先，请允许我用三个标签来介绍我自己。第一个标签：搬书虫。由于工作的关系，“沉迷”书堆之中不能自拔。第二个标签：闷罐子。不熟悉的环境会紧张，熟悉了以后会话不停～第三个标签：想改变。想通过拆书，从搬书变成用书，从闷罐子，变成有料的罐子！\r\n 我今天带来的拆页来自国际NLP大师李中莹经典著作《重塑心灵》，这本书是NLP领域最重要的中文著作，也是NLP学习者的必读书籍之一。NLP是指神经语言程序学，被解释为研究我们的大脑如何工作的学问。NLP的技巧配合大脑运作的模式去选择思想、语言和行为，它对人生的多个方面都能带来正面的影响，能够帮助我们摆脱困境，使我们能够获得轻松满足，成功快乐的人生。","ratings_count":1,"texts":[{"id":7499,"quote":"\u003cp>&nbsp;某个目标是否值得你去努力，只有你本人能够决定。但是某个方法是否值得你去尝试，却只需要问三个问题，如答案都是“Yes”，请不要踌躇，马上去做吧！这三个问题是：\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; 1.\u003c/strong>结果对我有好处吗?\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; 2.\u003c/strong>我想在短期内得到这份好处吗？\u003c/p>\u003cp>\u003cstrong>&nbsp;&nbsp;&nbsp; 3.\u003c/strong>这些好处，能否符合“我好、你好、世界好”的要求？\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp; 旧的做法既然无效，重复旧的做法就等于坐在路边等街道重开；抱怨环境条件不足，只不过是放弃返家念头的借口而已。任何新的方法都比旧方法有多一分成功的可能，何况多尝试便会使自己想出更多的方法。为什么你不能成为第一个找出解决方法的人？\u003c/p>\u003cp>&nbsp;--片段节选自李中莹《重塑心灵》（2015年版）P48-49\u003c/p>","explains":"\u003cp>&nbsp; &nbsp;现在看到，大多数小伙伴已经阅读完毕。这个片段选自李中莹老师的《重塑心灵》：当你有了明确的目标，需要在多种方法中找出值得尝试的方法时，可以询问自己三个问题：1.结果是否对我有好处？2.我是否短期内就需要这些好处？3.这些好处是否符合“我好”、“你好”、“世界好”的“三好”原则？如果三个答案都是肯定的，那么这个方法值得马上尝试。\u003c/p>","interaction":"\u003cp>&nbsp; &nbsp;我今天带来的拆页来自国际NLP大师李中莹经典著作《重塑心灵》，这本书是NLP领域最重要的中文著作，也是NLP学习者的必读书籍之一。NLP是指神经语言程序学，被解释为研究我们的大脑如何工作的学问。NLP的技巧配合大脑运作的模式去选择思想、语言和行为，它对人生的多个方面都能带来正面的影响，能够帮助我们摆脱困境，使我们能够获得轻松满足，成功快乐的人生。\u003c/p>\u003cp>接下来，我就简单介绍一下拆书和拆书帮。\u003cbr>\u003c/p>\u003cp>所谓“拆书”其实是一种方法论，是一种读书方法。通过这种方法，可以让学习者做到学以致用。“拆书”取意于“将书中知识拆为己用”，提倡通过学习改变行为，践行“把图书的知识转化为自己的能力”，强调以学习者为中心而不是以知识为中心，把知识关联学习者的经验，规划出具体的运用。拆书法有两大方式：“自我学习”和“现场学习”。“自我学习”即个人使用便签读书法（就是我们说的RIA拆书法）进行学习，这个方法包括RIA三个环节，R指阅读原文片段，I拆书家对原文片段的理解，A学习者拆为己用。现场学习法就是像我们今天现在的一种学习形式，有一位拆书家进行现场引导带领大家一起学习。拆书帮是赵周老师基于拆书法创立的，在全国各地已经有许多个分舵，截止2018年1月1日，拆书帮正式分舵和筹备分舵覆盖全国27个省份和47座城市，会员总数达到1584人。拆书帮是一个公益组织，也是一个正能量高发地。它的使命是帮助更多的学习爱好者成长为拆书家，同样截止1月1日，拆书帮1级拆书家达到了593人，二级拆书家有283人，三级拆书家161人，这个数据依然在强有力的增长中。 接下来让我现场演示什么是拆书这个过程。请小伙伴用1分钟时间一起来阅读今天的拆页，阅读完的小伙伴可以举手示意我一下。\u003c/p>\u003cp>【A1】\u003c/p>\u003cp>接下来我想分享一个我的例子。作为一只常年呆在书堆里的书虫，我喜欢阅读，喜欢学习，但是由于工作后真正空闲下来的时间不多，没有办法腾出大块的时间来阅读和消化，所以每次读到的知识过一段时间就会被遗忘。2017年6月至8月，我尝试了几种方法，比如：1.报网络学习课程，多腾出睡前的1个小时对知识进行系统学习，但是这涉及到费用和时间问题，每天工作结束后很疲惫，专门使用睡前一小时学习难以坚持下来；2.工作空闲时间对知识点进行摘抄，定期复习，但工作空闲时间的摘抄复习不利于端正工作态度，甚至在同事间形成不好的影响；3.参与读书会等组织分享阅读心得，巩固知识，但经过参与我发现大多读书会往往针对整本书籍进行阅读分享，需要全本阅读才能参与，耗时过长。最后我选择了参加拆书帮，并于7月进入了老友分舵RIA训练营，实践证明，这个才是最适合我的方法。针对这个问题，我进行了反思，用三个问题检验选择拆书帮这一方法：1.结果对我是否有好处？（有！便签拆书法让我灵活的使用了碎片化时间完成了知识点的学习、记忆和运用）2.我是短期内就需要这些好处？（当然！因为我需要不断增加自己的知识储备解决随时可能遇到的问题。）3.是否符合“三好”原则？（是的，拆书法对我自己的成长、提高我的工作效率减轻同事工作压力、甚至对我周围的朋友、家人和一起拆书的小伙伴都是一个很好的进步。）\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>接下来的我想运用这个知识点来解决我2018年工作计划遇到的问题。我先说一下背景：\u003c/p>\u003cp>&nbsp; &nbsp; 我现在负责的是汽车图书馆方面的工作，其中有一项就是和司机一起将汽图车开到指定的服务点开展现场借阅图书活动，这些服务点有的是社区，有的是政府机关，服务需求不同。\u003c/p>\u003cp>&nbsp; &nbsp; 好，那么问题来了。我1月20日前需要完成2018年的工作计划，想优化汽车图书馆的服务、提升工作效率，基于这个目标，我重新梳理了工作内容，得到了几个方案：1.调整工作优先级，将不必要立马完成的工作内容调整到下半年；2.将原本6个服务点5天才能完成的现场服务工作安排调整为3天完成；3.整理汽车图书馆内2000册图书，重新规划图书选送方案。\u003c/p>\u003cp>&nbsp; &nbsp; 我将使用三个问题来对方案进行筛选：首先：选出的方案需要给我带来优化服务、提升工作效率的好处；接着，这个方案必须让我在一个月的时间内就能够获得工作效率的提升；最后，方案必须符合“三好”原则，不仅要实现我的目标，还要有益于减轻同事工作负担、有利于读者的需求，实现三方都获益。通过询问自己这三个问题，我将选出最好的方案或者优化出一个更适合的方案。\u003c/p>\u003cp>&nbsp; &nbsp; 以上，是我今天对《重塑心灵》中“使用三个问题判断方法是否值得尝试”这一知识点的学习，希望通过今天的分享，小伙伴们都能够有所收获，今天我的拆书就到这里，感谢小伙伴的参与，谢谢！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}},{"id":7644,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1515986720000,"updated_at":1515986720000,"ria":true},{"id":4423,"topic":"如何看到事情的积极意义","learn_goal":"在任何不开心的事情时，能够找到负面经验的正面意义，走出情绪困","remark":"","level":"TF3-2","duration":25,"status":30,"type":0,"chaishujia":{"username":"黎娟","city":"长沙"},"club":{"name":"长沙麓山分舵","city":"长沙"},"prologue":"【自我介绍】大家好，我叫黎娟，黎明的黎。是一个高中AP心理学老师和心理咨询师，也是一名二级拆书家，现在正在努力冲三级。下面我将开始我的拆书。\r\n【场景法介绍】 \r\n【事件】在生活中，我们经常会遇到一些不顺心如意的事情。例如被上司批评、感情遭受创伤、完成任务时遇到困难等。\r\n【提问】大家想想，当我们遇到这样的问题时，通常我们把它们归为好事还是坏事呢？\r\n【影响】大家可能会说有好也有坏呀，对，同样一件事情，有的人理解为可以接受的、快乐、高兴的，有的人理解为不可接受、郁闷甚至痛苦的。所以，给事情赋予不同的意义，我们的情绪状态和处理方式就会不一样。假设给事情赋予负面的意义，不仅会让我们产生负面的情绪，也会让我们带着负面的信念生活，长久这样下去，我们就会形成负面的问题应对方式，导致生活越来越恶化，最终很难走出困境。\r\n【解决】所以我们知道，给事情赋予积极正面的意义对于我们走出情绪和生活困境很重要，那怎么做到呢？今天我介绍的李中莹《重塑心灵》就可以帮到大家，这是一本关于NLP的书籍，NLP就是研究大脑如何工作的，它通过一些语言模式、思维模式的转变来改变我们的信念、价值系统，让我们能够多看到事情积极","ratings_count":1,"texts":[{"id":7432,"quote":"\u003cp>\u003cstrong>首先我们来做一个自测题。\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【自测量表】\u003c/strong>请大家仔细阅读以下每句话，根据自己实际情况给自己打分，1代表完全不符合，6代表非常符合 &nbsp;&nbsp;\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、当一件事情的结果是失败时，我会尝试从中寻找其带给我的好处。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、朋友遇到不顺心的事情时，我会安慰她要看到事情积极的一面\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、别人误会我时，我总是会用积极的语言来安慰自己。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、我相信生活中每件事情都有积极的一面\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、工作中遇到困难时，我也会通过想事情积极的一面来缓解情绪。\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cstrong>【自测表-量表解释】\u003c/strong>25分以上的小伙伴请举手，25分以上的，说明你有一种天生乐天派的特质，遇事总能很快想到积极的一面，自我调整能力非常强；15到25分之间的请举手，这个分数阶段的小伙伴说明平时遇到事情有时候会积极，有时候会消极，自我调整能力较强，但是还可以继续提高一下；15分以下的小伙伴，说明平时负面情绪困扰可能持续时间长一些，还需要多学习一些自我调整情绪的技巧。不过没关系，我们今天学习的技巧正好可以帮到大家。请大家阅读以下片段：\u003c/p>\u003cp>\u003cstrong>R： \u003c/strong>\u003c/p>\u003cp>【原文why/原文what/原文案例】选自《重塑心灵》P49\u003c/p>\u003cp>“意义换框法”是NLP技巧“换框法”中最常用和最好用的技巧。它完全只凭言语和思想模式而产生效果，是NLP的改变信念技巧中最快速最容易的一个。“意义换框法”是找出一个负面经验中的正面意义。它的概念基础是：世界上所有的事情本身是没有意义的，所有的意义都只是人加诸的。既然是人加上去的意义，则一件事情--\u003c/p>\u003cp>可以有其他的意义，也可以有更多的意义；\u003c/p>\u003cp>可以有不好的意义，也可以有好的意义。\u003c/p>","explains":"\u003cp>【学习目标】通过本次的拆解，学习者能够在有负面情绪时，【具体内容】利用意义换框法的三个步骤，【可观察到的动作】找到负面事件的正面意义，【完成程度】从而实现从负面思维框架到转换到正面思维框架的目标。\u003c/p>\u003cp>\u003cstrong>【互动\u003c/strong>\u003cstrong>】\u003c/strong>大家在片段中读到了什么关键词呢？恩，对了，意义换框法。\u003cstrong>【互动\u003c/strong>\u003cstrong>】\u003c/strong>原文中解释意义换框法的是哪句话呢？对，找出负面经验中的正面意义。负面经验也就是不如意的事情，任何事情都有好的意义，也有不好的意义。意义换框法就是，对于本来我们赋予了不好意义的事情，找出最能帮助自己的正面意义，把这件事情的价值改变一下，我们的情绪和处理问题的方式也就跟着变得正面了。那为什么要学习和使用意义换框法呢？利用意义换框法找事情积极的意义，就可以拥有更多积极的情绪，减少内疚、无奈、伤心、后悔、遗憾等负面情绪引起的精神内耗，我们就可以有更多精力去做一些更有价值的事情；另外，事情积极的意义往往是我们内心最想追求的价值，换框之后帮助我们找到了做事真正的价值，所以即使事情不如意我们也更有动力克服。\u003c/p>\u003cp>【行动步骤】那我们要怎么使用意义换框法呢？有以下三个步骤：\u003c/p>\u003cp>\u003cstrong>第一步：\u003c/strong>\u003cstrong>找因果句式，\u003c/strong>就是找出让自己有负面情绪的具体事件，将所面临的问题用“\u003cstrong>因为某某事情，所以我感觉怎么样\u003c/strong>”的句式表达出来,感觉出来负面情绪其实就是给事情赋予了负面意义。之所以要转化成因果语句，是为后面的加工做准备的。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>举例\u003c/strong>】比如前段时间，我家人接连生病，先是妈妈高血压去医院，然后是男朋友阑尾炎，我忙着照顾他们，应对乏力的状态下自己也感冒生病了，在医院钱包还被小偷偷了。我觉得很无奈、无力、焦虑，觉得自己太倒霉。\u003cstrong>【互动\u003c/strong>\u003cstrong>】\u003c/strong>我想请问下大家，这个情景我们用因果句式可以怎么表示呢？对，我们可以表示成：因为家人接连生病我钱包又被偷，所以我特别焦虑、无奈。\u003c/p>\u003cp>\u003cstrong>第\u003c/strong>\u003cstrong>二\u003c/strong>\u003cstrong>步：\u003c/strong>\u003cstrong>换\u003c/strong>\u003cstrong>正面意义，\u003c/strong>接着上面的第二步，我们来反复思考“如果这件事情对我来说是有正面价值的，会是什么呢？”所以上面的因果句式可以换成：\u003cstrong>某某事情也有积极的一面，因为......\u003c/strong>注意：这些价值一定要是积极乐观、接近现实的，要起到立马鼓舞士气的作用。另外，这里的积极点要求越多越好（一般\u003cstrong>至少六个\u003c/strong>，但是如果实在想不出六个，想到不能想出来为止）。积极的价值观是我们做事保持好状态的最大动力，如果找到了一件事情越多的正面价值，即使这是一件不顺心的事情，我们也会因为心中有目标和方向而克服万难。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>举例\u003c/strong>】还是上面那个例子，我可以这样来想：\u003c/p>\u003cp>家人接连生病我钱包又被偷了，这件事情也有积极的一面，因为.....\u003c/p>\u003cp>1、这件事情让我成长了不少，我学会了更加独立冷静谨慎地面对和处理问题\u003c/p>\u003cp>2、使我意识到平时自己忽略了家人和自己的身体，所以在我后面的每月计划中，家人和身体锻炼这两块我一定会做好平衡。\u003c/p>\u003cp>3、这可以督促我培养饮食清淡、每天多动一动锻炼身体的好习惯......\u003c/p>\u003cp>其实还有其他的点，当我这么去想这件事情积极的一面的时候，我发现自己文思泉涌，很多很多积极的地方是我以前从来不会去想到的。\u003c/p>\u003cp>\u003cstrong>第三步：选最佳意义，\u003c/strong>找出最能接受的一句并将这一句\u003cstrong>反复念几遍\u003c/strong>并记住。这一句最好是让你读完心情非常舒服，精神振奋的，心中充满力量，有种“恩，对了，就是这样”的感觉。这个话术就是：\u003cstrong>某某事情，它也有积极的一面，因为......\u003c/strong>这个步骤和第二步是难点也是起关键作用的步骤，需要大家练习的时候静心，最好写下来分析。\u003cstrong>【\u003c/strong>\u003cstrong>举例\u003c/strong>】例如上面那个例子，我觉得让我心情马上好转的积极点是：让我成长了不少。所以我这样来换框：家人接连生病我钱包又被偷了，这件事情也有积极的一面，让我成长了不少，我学会了更加独立冷静谨慎地面对和处理问题。\u003c/p>\u003cp>\u003cstrong>【适用边界】\u003c/strong>意义换框法是一种非阿Q式的情绪梳理方法，可以应用在工作、生活、情感沟通等多个方面。这个方法仅用于帮助有情绪困扰的个人暂时走出情绪困境，不能作为解决问题的最终方法。另外，使用该方法的前提是：使用该方法的人一定要有比较强的自知力和改变欲望且情绪问题没有构成严重心理问题，如果情绪问题严重，需要及时找心理咨询师疏导。\u003c/p>","interaction":"\u003cp>\u003cstrong>A3：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【给出具体场景】\u003c/strong>小李刚大学毕业一年，是一家知名互联网公司的行政人员。小李最近非常苦恼，找闺蜜小何哭诉，最近换了一个上级领导，这个领导交代工作任务时总是没有明确的要求，导致小李很茫然，也很郁闷，都不想做了，但是这个公司又是小李所在城市非常不错的公司，小李刚进公司的时候就想一直在这个公司好好发展，其他公司暂时又不想考虑。\u003c/p>\u003cp>\u003cstrong>【给出清晰指令\u003c/strong>\u003cstrong>】\u003c/strong>现在两两一组，一人做小李，一人做小李的朋友小何。小何需要利用意义换框法的三个步骤帮助小李找到这个事情的正面意义，帮小李走出情绪困境。请大家在小组内花5分钟讨论一下，请大家参考我刚刚的步骤和话术来进行讨论，扮演小李的可以边讨论边写事情的意义，讨论五分钟后我会请小伙伴来分享下你们的讨论过程和结果。请大家注意我们训练的真正目标不是解决场景中的问题，因为解决的办法有很多，今天我们只借用这个场景来演练意义换框法的三个步骤就可以了。\u003c/p>\u003cp>\u003cstrong>【\u003c/strong>\u003cstrong>伙伴分享\u003c/strong>\u003cstrong>】\u003c/strong>\u003c/p>\u003cp>学习者刘婷（扮演小李）：我最近特别郁闷，最近换了一个上级领导，领导跟我交代工作任务的时候总是没有明确要求，搞得我特别茫然，都不想做了。\u003c/p>\u003cp>学习者杨山（扮演小何）：你先不要急，我们慢慢来分析下这个事情。\u003c/p>\u003cp>学习者刘婷（扮演小李）：但是我又觉得这个公司是这里很不错的公司，我找其他的公司又找不到这么合适的了。\u003c/p>\u003cp>学习者杨山（扮演小何）：那也就是说你其实还是想呆着公司，那你现在就需要调整下情绪和心理状态来应对这个事情了。这个事情除了让你郁闷之外，如果让你想点正面意义，你觉得可以有什么呢？\u003cstrong>（找正面意义）\u003c/strong>\u003c/p>\u003cp>学习者刘婷（扮演小李）：如果一定要说正面意义的话，那也有，比如说我可以慢慢学会去读懂领导需要的是什么结果，能读懂领导其实也是一种很不错的能力；又比如说这可以提高我分析问题的能力等等。\u003c/p>\u003cp>学习者杨山（扮演小何）：除了这个还有吗？\u003c/p>\u003cp>学习者刘婷（扮演小李）：这件事情还能使我办事更加独立，提升得更快，以后真有其他公司合适的岗位我也更能胜任了......\u003c/p>\u003cp>学习者杨山（扮演小何）：太棒了！那你觉得，刚刚你说的那些正面意义中，那个让你一想到就精神振奋，马上觉得动力满满呢？\u003cstrong>（找最佳意义）\u003c/strong>\u003c/p>\u003cp>学习者刘婷（扮演小李）：这件事情能使我办事更加独立，提升得更快，以后真有其他公司合适的岗位我也更能胜任了。\u003c/p>\u003cp>学习者杨山（扮演小何）：特别棒，那你现在在心里默念这句话三遍，默念完后再谈谈你的感受。\u003c/p>\u003cp>学习者刘婷（扮演小李）：默念三遍。恩，我现在感觉舒服多了，觉得这其实也是件好事，所以领导交代任务不明确，我觉得也是在锻炼自己的能力，以后让自己更有竞争力。\u003c/p>\u003cp>学习者杨山（扮演小何）：非常棒！\u003c/p>\u003cp>\u003cstrong>【拆书家反馈】\u003c/strong>感谢2位的演练。我们再次把掌声送给他们。刚刚两位的分享中小何先用引导小李去想领导交代任务不明确这件事情，如果有正面意义，会是什么，就是使用意义换框法的第二步，接下来小李就说了很多意义，最后再找出一个最好的意义默念三遍。这个方法使用的很好，大家发现第一步使用因果句式他们是没有说的，他们采用先让小李说事情小何听的步骤，其实只要情绪困扰能说清楚，在生活中也是允许的，我们的第一步找因果句式是帮助大家说事情的可参考模式。\u003c/p>\u003cp>\u003cstrong>&nbsp;A2：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【布置作业——\u003c/strong>\u003cstrong>特定任务\u003c/strong>\u003cstrong>】\u003c/strong>现在来布置一个作业。虽然我们刚刚在现场演练了一下，但是生活中这样的场景非常多需要我们不断把所学进行实践。请大家在本次活动结束后未来一周内，找朋友或家人甚至自己进行一次练习，在自己或朋友或家人碰到不顺心的事情时，利用意义换框法三步骤来引导找到负面经验的正面意义，帮助自己或他人走出情绪困境。大家实践完后可以自己总结哪里做的好，需要改善什么，困难点在哪里，也可以和聊天的家人朋友一起沟通总结，一周内完成并且反馈给我哟。希望大家通过练习收获更多，再次感谢各位参与！\u003c/p>\u003cp>&nbsp;\u003cstrong>【伙伴分享】\u003c/strong>\u003c/p>\u003cp>1、找因果句式：因为我开车没注意超速提示，被交警罚款，所以我感觉到郁闷。\u003c/p>\u003cp>2、换正面意义：超速被罚这件事情也有积极的一面，因为可以让自己有教训/避免了交通事故/以后会更加注意交通安全/自己还活着/没伤害到别人/可以随时提醒自己。\u003c/p>\u003cp>3、选最佳意义：我超速被罚，这件事情也有积极的一面，因为它避免了交通事故。最后我将这一句反复念了几遍，感觉心里舒服多了。\u003c/p>\u003cp>\u003cstrong>【结语】\u003c/strong>今天我们学习的意义换框法其实就是帮助我们遇到事情时快速处理好情绪问题的方法。碰到不开心的事情时，想想如果这件事情对我来说是有正面价值的，会是什么呢？多想想事情正面的意义，远离情绪烦恼就不难了。知道这个方法不是关键，关键是练习和真正去实践。今天我们一起知道了这个方法，也希望我们可以一起去练习和实践。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1515396289000,"updated_at":1515396289000,"ria":true},{"id":4415,"topic":"事情在脑里的位置——时间线","learn_goal":"做情绪的主人，充分享受、完全拥有正面情绪，恰当处理负面情绪；","remark":"《重塑心灵:一门使人成功快乐的学问》内容为：快乐是一个永恒的话题，也是人类一个谜题。有资料显示我们中的许多人可以说是不快乐的!你是否考虑过我们到底是怎么了？我们丢失了什么呢？是人类自我的一种情感发展趋势？还是我们生活的方式在影响着我们的心情呢…… \r\n快乐从何而来，怎样寻找快乐，这是一个人们首先想问的问题，因此，本文开始从“快乐何处寻”来谈起，能力与道德，或者说事业与人品是一个人得到社会认可的两个重要标准，而这两个方面与快乐都有很大的关系；接下来从成功及其道德品行来说快乐。智者乐水，仁者乐山，自然的美可以愉悦心灵，而健康是保持快乐的真理。 \r\n每个人的成长道路上，都不可避免地会遇到挫折失败，许多人","level":"TF2-1","duration":18,"status":29,"type":0,"chaishujia":{"username":"瑩雪","city":"青岛"},"club":{"name":"筹备分舵","city":"北京市"},"prologue":"拆书帮的伙伴们大家上午好，我是莹雪。很开心跟伙伴们一起进行我的2-1拆书。今天我们依然以小组为单位进行，首先我们进行一下分组（两人一组）。 F：今天我要拆的片段出自国际NLP大师李中莹经典著作《重塑心灵》，李中莹先生最早把NLP完整地介绍到国内，因而被誉为“华人世界的国际级NLP大师”，他发展出大量独到而实用的思想和行为技巧，可以有效地帮助一个人培养出良好的心理素质。 A：《重塑心灵》一书最大的特色是保持李中莹老师惯有的务实与落地的态度。《重塑心灵》一书站在大众的角度，以尽量通俗的语言或接近英文原意的中文重新诠释了惯用词汇。NLP在中国尚不明确的时候，李中莹老师已经做了先驱，为我们指引出一条丰富多彩的道路。 B：《重塑心灵》是讲NLP的书，而NLP是很实用的学问，它能够推动一个人快速地提升他的素质，进而享受更大的成功快乐。 我们可以尝试拆解《重塑心灵》一书，有效的资源，帮助我们过的更加开心和快乐。今天我所选的片段是：事情在脑里的位置——时间线，希望通过学习大家能实践时间线的目标法，打破状态达到一个良好的目标感受。请阅读原文如下。","ratings_count":3,"texts":[{"id":7424,"quote":"\u003cp>时间线实践目标法是运用时间线去体验达到一个良好目标感受。\u003c/p>\u003cp>1、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 如果你是惯用右手的人，你的时间线是：过去在左边，未来在右边。因此，当你回想一件往事的时候，它应该是在你的左边的。你可以试着闭上眼睛回想去年某一个特别的日子（例如，新年、生日等）早上刷牙时的情景，用手指出情景的中心点所在，然后睁开眼睛，看看你手指的位置。然后再闭上眼睛，想象你三年后同一个特别的日子早上刷牙的情景，用手指出情景的中心点所在，然后睁开眼睛，看看这次你手指的位置。一般人第一次手指的位置会在鼻子的左前方，第二次则在鼻子的右前方。\u003c/p>\u003cp>2、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 如果你平时生活比较紧张，觉得事情总是排山倒海般到来，而且总是急着想快点把事情做好，当你闭上眼睛想那些未完成的事情时，那些情景会在你的右方，而且在较高的位置，例如：视线的上半部，具有一种压迫感，且颜色较鲜明，光亮度高。\u003c/p>\u003cp>3、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 如果你平时生活比较轻松，觉得事情的来临自有它们的节奏，无须心急，当你闭上眼睛想那些未完成的事情的时候，那些景象也会在你的右方，但是没有那么接近你，与2比较，位置可能稍低一点，颜色会淡一点，亮度也没有那么高。\u003c/p>","explains":"\u003cp>学习目标：实践时间线的目标法，打破状态达到一个良好的目标感受。\u003c/p>\u003cp>What：时间线可用来探索人是如何架构他的时间观、时间趋向。在一个人的脑里对时空概念的处理模式。Why：当我们脑里混乱时，按照这个来做，把脑里事情依时间来排序整齐，可以使我们能够安定下来。如果我们习惯使用右手，则未来会出现在右边，而过去在左边。可以闭上眼思考过去、现在和未来的事情，用笔画出一条直线，用手指指出脑里景象的中心点。当我们站立在现在的一点，脑里会配合时间线决定了过去与未来的方向，时间是有弹性的，比如：就考试临近来说，当我们要考试的时候 需要复习的东西有很多，这时候我们就需要时间线来帮我们梳理一下-看过的部分、熟悉的部分和没看过的、陌生的部分在感知中的地位是不一样的，梳理后我们可以按照时间的长短来复习。Where：我们通过时间线来实现时间线的目标法，梳理我们大脑储存的景象，按时间排列，以便我们大脑的思路更加清晰，并将脑里的目标付诸实行，有一个良好的时间目标感受。不这样做的坏处：如果我们没有时限来集中注意力的话，很难检查出自己在不同时间段，到底做到什么程度了，或偏离目标，浪费不必要的时间，达不到我们所要的效果。\u003c/p>\u003cp>技巧步骤：how：\u003c/p>\u003cp>1、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 在纸上画一条时间线，在时间线上画一个点代表“现在”的位置，在时间线上未来的方向上选择一个点，代表达到目标的时间，用颜色笔把这个时间点清楚的标示出来。\u003c/p>\u003cp>2、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 由“现在”到”目标“中间一段，想一想可能出现的困难、障碍、挑战和解决的方法依次打分，例如：轻微的困难我们可以打到3分以下，比较难的障碍可以打到6、7分……直到达到”目标“为止。\u003c/p>\u003cp>3、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 当我们在脑里走完到达”目标“这一段，可以想象一下能出现的环境或人、事、物，比如：可能出现什么人或事的问题？ &nbsp;会出现哪些意想不到的障碍？ &nbsp;某些人的妒忌、不合作将会引起哪些困难？&nbsp;&nbsp; 如出现困境我们须要什么资源？ 当出现这些困难时我们要标注出来离目标还有多长时间。\u003c/p>\u003cp>4、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 我们到达”目标“点时，深呼吸把这份良好的感觉加强，储存到身体内。带着成功的经验与喜悦，可能看到过程中哪里可以更省力，更高效。从时间线里走出来，返回到”现在“的点上。\u003c/p>\u003cp>5、&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 站到”现在“的点上，再看一次目标的路途，再举步向”目标”走一趟，再次感受那份达到目标的良好感觉。并把目标放到脑里右上方处，给自己鼓励。打破状态，做未来测试。\u003c/p>\u003cp>第一步：画下代表时间的线，分清现在到目标的距离，在脑海中演示从现在走到目标会遇到多少困难，花费多少时间。达到终点后，记下曾经遇到的困难，并把成功时的喜悦记在脑海里。\u003c/p>\u003cp>第二步：回到现实中，再走一遍这个过程。\u003c/p>","interaction":"\u003cp>A1\u003c/p>\u003cp>显像提问的A1：请认真的考虑这样的问题，当你手边有一堆事情的时候，你是怎么解决的呢？是有特定的顺序，还是先想到哪个就做哪个呢？特定情境：为了能对这个技巧更加熟练，我们在大脑里构想一个情景，比如：到年末时，我们需要整理这一年来的成功和失败，在整理的时候，先在脑海里想一下从整理开始时到整理完毕需要做的事情，想想会遇到什么样的困难，将这些困难进行排列，选择优先解决的困难，直到完成目标。当我们在时间线中完成目标后，带着这份喜悦从时间线中出来，回到现在这个点。然后站在这个点上，再来一次走上成功的路，并把目标放在未来的某一点上，为自己打气，打到打破现在不理想的状态，以便达成最终目的。\u003c/p>\u003cp>\u003cstrong>伙伴分享：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>A\u003c/strong>\u003cstrong>：\u003c/strong>我设定的目标是要完成拆书2-4，我需要经历的是1-1到2-4，现有的问题有时间安排部分，拆页部分，拆书稿被驳回不通过，没有吃透拆书手册。我对这四个问题进行了分级，最高的是没有吃透拆书手册（7分），拆书稿不通过和时间（2分)，因为这两个是可以通过某些努力改变的；找不到拆页部分（4分）。我需要做的努力有：要看仔细手册，使我的拆书稿达到要求；我需要在网站上找出前辈们成功的案例，参考他们的文章。最重要的是我需要规划好自己的时间，能够确保每次参加活动。\u003c/p>\u003cp>A1+\u003c/p>\u003cp>反思加工指令：再请你考虑一下，如果你用了这次拆书的技巧，是不是事情就会变得更有条理了呢？我们是不是就有更多的时间去处理别的事情了呢？请大家在纸上画出自己的时间线并的找到现在和目标点。然后，请每位伙伴用1-2分钟在小组内分享。请每个小组选一个代表，为我们大家做分享。\u003c/p>\u003cp>在完成本次RIA现场学习后，学习者能够有效的使用时间目表法，并用这个方法带给大家最有价值的时间目标体验，是大家能够明确自己的时间目标，更好的掌握自己的时间。\u003c/p>\u003cp>\u003cstrong>伙伴分享：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>B\u003c/strong>\u003cstrong>：\u003c/strong>个人学习和成长方面，时间线比较短，生活跟工作没有太多目标。时间短的原因是拆书和考试，拆书要跟上线下活动的节奏，考试在6月份，拆书和考试中间划的比较长，在这中间还有一个作业，计算机网络作业目标离的比较远。\u003c/p>\u003cp>\u003cstrong>C\u003c/strong>\u003cstrong>：\u003c/strong>工作时间线，4月完成新团队搭建，办公室座满8个人；6月完成新产品升级，拿出厚厚教案；9月份要完成全年80%销售额的目标，暑假结束新开班的销售额要完成全年的80%； 11月策划年底冲刺的活动，脑海呈现活动热烈的场景和排队交费的场面；12月底完成2019年度的工作计划，有一张非常大的稿纸，画满曲线2019年会比2018年有100%以上的涨幅。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1515329180000,"updated_at":1523168862000,"ria":true},{"id":4222,"topic":"自我情绪管理","learn_goal":"如何用四招（理解接纳，运用，改变，提升）来学会自我情绪管理","remark":"","level":"TF3-2","duration":22,"status":0,"type":0,"chaishujia":{"username":"guoguo","city":"福州"},"club":{"name":"福州闽江分舵","city":"福州"},"prologue":"哈罗，大家好，我是郭艳霞，欢迎来到我的拆书现场，今天我要完成的是TF3-2。拆书的片段是一本应用类书籍，书名《NLP重塑心灵》，作者是李中莹，下面我用一种新的方法—场景法来介绍下\r\n【事件场景】：已接近年终了，各部门都开启了年终的工作，领导要求我在半个月之内做好明年的培训计划，领导对此项目高度关注，时间没到就开始催催催，加上年底工作又多，因此打乱了原本的计划，导致自己内心很着急，心情烦躁，压力很大，有时候还精力不集中，就想发泄下，可苦于没有办法。\r\n【提问】：不知道你有没有和我类似的经历？感觉到负面情绪你是否也手足无措呢，或者你一般是怎么处理的呢？\r\n【影响】：也许偶尔的负面情绪没有太大的影响，但是长期类似压力导致的负面情绪将会严重影响到自己的工作和生活。\r\n 【解决】：李中莹最早把NLP完整地介绍到国内，发展出大量独到而实用的思想和行为技巧，通过今天的学习，可以有效的帮助一个人学会自我情绪管理，培养出良好的心理素质。","ratings_count":0,"texts":[{"id":7205,"quote":"\u003cp>\u003cstrong>场景法介绍图书：\u003c/strong>\u003c/p>\u003cp>【事件场景】：已接近年终了，各部门都开启了年终的工作，领导要求我在半个月之内做好明年的培训计划，领导对此项目高度关注，时间没到就开始催催催，加上年底工作又多，因此打乱了原本的计划，导致自己内心很着急，心情烦躁，压力很大，有时候还精力不集中，就想发泄下，可苦于没有办法。&nbsp;\u003c/p>\u003cp>【提问】：不知道你有没有和我类似的经历？感觉到负面情绪你是否也手足无措呢，或者你一般是怎么处理的呢？&nbsp;\u003c/p>\u003cp>【影响】：也许偶尔的负面情绪没有太大的影响，但是长期类似压力导致的负面情绪将会严重影响到自己的工作和生活。&nbsp;\u003c/p>\u003cp>【解决】：李中莹最早把NLP完整地介绍到国内，发展出大量独到而实用的思想和行为技巧，通过今天的学习，可以有效的帮助一个人学会自我情绪管理，培养出良好的心理素质。\u003c/p>\u003cp>\u003cstrong>原文片断：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>情绪是本人的信念系统与外界的人事物共同作用的产物\u003c/p>\u003cp>世上所有的情绪可以被分为两类：“开心”与“不开心”。这种现象让我们更加明了人们过去很少注意自己的情绪感受，而且也更加清楚人们对自己内心究竟是怎么回事所知很少。\u003cbr>&nbsp;&nbsp;&nbsp;引导人们更准确地体会和说出内心的情绪感受，我惯用的说法是：\u003cbr>&nbsp;&nbsp;&nbsp;◇&nbsp;“不开心的背后，是一些什么情绪？”\u003cbr>&nbsp;&nbsp;&nbsp;◇&nbsp;“不开心一般不会单独存在，与它在一起的是些什么情绪？\u003c/p>\u003cp>◇&nbsp;“你还可以用什么其他文字去描述这份情绪？”\u003c/p>\u003cp>如果对方对情绪认识很少，这方面的词汇很贫乏，我常会加上一些建议让他选择（但从不假设或武断判定）：“不开心的背后，是愤怒还是恐惧？焦虑还是无力感？”\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;了解了情绪的真正来源，我们就可以在情绪管理方面有所作为。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;通常因为人们对情绪所知甚少，对于一些所谓“负面”情绪觉得无能为力，经常感到被它们牵着鼻子走，所以最常与“情绪”二字用在一起的动词是“控制”：“我如何能够控制自己的情绪？”其实当需要用到“控制”二字时，情绪往往便已经是失控了。如果有人对你说“请控制一下你的狗”，肯定你的狗已经制造出了一些麻烦！更深入地想一想：“控制情绪”这几个字完全是治标性的说法：情绪出现便把它消除。这里没有考虑怎样做情绪才不会出现。若那些情绪根本不会出现，又有何“控制”的必要？\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;现在，我们明白了情绪根本不是单纯地因为外界的人事物产生，而是本人的信念系统与外界的人事物共同作用的产物，我们便可重新建立对自己情绪的管治权。\u003c/p>\u003cp>通常人们处理自己的情绪只有三种途径\u003c/p>\u003cp>忍：隐藏在心里；\u003c/p>\u003cp>发：发泄出来；\u003c/p>\u003cp>逃：使自已忙碌不去想起有关的事情。\u003c/p>\u003cp>三种途径都没有效果。隐藏在心里造成本人的心情不稳定，形成很多心理症结，现在的科学研究已经证实这会引起严重的健康问题。发泄出来的方式包括发牌气（这影响了人际关系和别人对你的看法）、暴饮暴食或疯狂购物等行为，每次发泄过后还是觉得不成，经常要重复发泄，造成很大的后遗症。使自己忙碌不去想有关的事情，当时有点效果，但是每当夜深人静、独自一人时，那些引起困扰的事情和情绪便会“才下眉头，却上心头”，往往造成失眠问题。\u003c/p>\u003cp>“NLP简快心理疗法”有很多处理个人情绪的技巧，可分为两个部分治标和治本。这些技巧都很有效，使人重新成为自己情绪的主人，掌控自己的人生，在情绪面前有所提升和突破，而不是无奈和无力。其实，所有心理困扰都造成情绪问题。处理了问题，情绪便消失；处理了情绪，能力便走出来。能够面对和处理问题，问题也更快更易消失！\u003c/p>\u003cp>治标的技巧，可分为四类:\u003c/p>\u003cp>1.消除——把事情引起的情绪消除掉，再回忆那件事情，内心感到平静。\u003c/p>\u003cp>2.淡化——把内心的大部分情绪感受化解，只剩余轻微的感觉。\u003c/p>\u003cp>3.运用——几平所有的负面情绪都有其正面的意义和价值，不是给我们力量便是指引我们行动方向。\u003c/p>\u003cp>4.配合——接受内心的情绪，做最能配合它的事。\u003c/p>\u003cp>治本的技巧也可以分为三类:\u003c/p>\u003cp>1.改变本人的信念、价值观和规条——因为情绪的真正来源是一个人的信念，价值观和规条，当它们改变了，同样的事情出现时，这个人的情绪状态便有不同。\u003c/p>\u003cp>2.处理涉及本人身份层次的问题——这可以是一些关于身份的局限性信念，或者与家族系统有关的身份问题。\u003c/p>\u003cp>3.提升本人的思维处理能力——这类技巧，在于增加一个人的智慧，不能寄望某一两个专题技巧便能达到完满的境界，而需要不断地修炼。NLP的十二条前提假设便是属于这个范畴，若能在每一件事中都充分地实现这些前提假设，人生里绝大部分的困扰都不会出现。\u003c/p>","explains":"\u003cp>学习目标：\u003c/p>\u003cp>希望大家在跟随我用RIA拆解完这个片段后，【被观察到的行为】 能用“理解接纳、运用、改变、提升”这四招【具体内容】学会【完成程度】\u003cstrong>自我情绪管理\u003c/strong>\u003c/p>\u003cp>测试题：\u003c/p>\u003cp>在阅读原文之前，我们先做一个小测试题，测试题有7个题目，请按照1-6分的标准为自己打分，1&nbsp;表示完全不符合，6表示非常符合，测试题不同于考试题，没有标准答案，大家只需通过回想自己相关的经历和以往的表现，根据自己的实际情况选择符合项，无需有任何的顾虑，请仔细阅读下面表格中的每句话：\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>1、我总是喜欢把心事藏在心里\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>2、当他人让我不爽的时候我就对他大发脾气\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>3、当我心情不好的时候，我会去逛街买很多东西\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>4、当我不开心的时候，我喜欢不停地吃东西\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>5、我让自己处于忙碌的状态使自己忘记那些不愉快的事情\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>6、我心情郁闷喜欢和朋友唠叨，倒到苦水\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>7、最近一段时间，老是失眠\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003ctd>\u003cp>6\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>解析测试题：\u003c/p>\u003cp>测试之后请大家给自己算出总分，得分21-36区间的分表示你平时处理情绪经常都是负面的途径，15-21分表明你的情绪管理的还比较好。0—14分的说明你平常能够很好的管理自己情绪。\u003c/p>\u003cp>其实这些做法都是比较消极的，就像片段上说的，埋藏在心里、发泄、通过其他的事情自我麻痹都不是处理情绪的好方法，相信大家都还记得自己刚刚自测的分数，如果在21分以上就表明我有那么一丢丢情绪问题，那么我们如何应该怎么样更好的管理自己的情绪呢？\u003c/p>\u003cp>原文片段告诉我们4种治标和3种治本的方法，我总结为以下四点：\u003c/p>\u003cp>第一，理解并接纳自己的情绪，运用消除、淡化、配合的方式降低情绪对我们的负面影响；\u003c/p>\u003cp>第二，运用情绪，寻找负面情绪的正面价值；\u003c/p>\u003cp>第三，改变，换个角度想想，改变自己固有的信念，信念改变，情绪状态变不同。\u003c/p>\u003cp>第四，积极思考，提升思维能力。\u003c/p>\u003cp>举例说明：\u003c/p>\u003cp>上上周领导要求我在半个月之内做好明年的绩效考核方案，可是时间还没有到，她就一直催催催，每天都问进度，可我就一直卡在一点上无法突破，始终找不到平衡的点，就这样心里很是着急，心情相当的郁闷，压力很大，晚上老是睡不好，内心还大骂领导，布置的什么破任务，还不听的催，跟催命似的。\u003c/p>\u003cp>但是当我看到这个片段的时候，后面我就做出了调整，调整后，我顺利了的完成了任务。\u003c/p>\u003cp>首先：接纳我现在很着急、愤怒的情绪，慢慢的化解郁闷的情绪；\u003c/p>\u003cp>第二：找到情绪的正面价值，其实我压力很大，是因为自己太过追求完美，总想着一定要做出一个很完美的方案才能交给领导，有压力才会有动力\u003c/p>\u003cp>第三：改变对领导的看法，其实领导将这么大的事情较给自己去办，是因为信任，而不是想给自己找麻烦，是想让自己更快的成长\u003c/p>\u003cp>第四：正因为如此，我应该多和领导沟通，了解领导的想法，通过参看相关资料做出一份方案。\u003c/p>","interaction":"\u003cp>A3：小组讨论\u003c/p>\u003cp>场景：周末小李约女朋友小林12点在爱情海宴遇吃午饭，小林开心的打扮的美美的准时在宴遇赴约，可是到了男朋友小李还没到，这时候她就找了个地方先坐下来等，12点20分男朋友还没有到，小李有点生气，打电话却是无法接通，心里有点不安，小李耐着性子继续等了20分钟，可是男朋友小林还是没有出现，这时候不安的情绪已经变得愤怒，心里想着：竟然让我等了40分，以前都是你等的我份，这分明是不够爱我的吗，不行，要和这样的男人分手。\u003c/p>\u003cp>现在假设这样的场景下，请大家分组讨论下解决方案，可以运用片段中哪些处理情绪的技巧帮小林冷静下来，杜绝分手的想法。\u003c/p>\u003cp>解决方案：\u003c/p>\u003cp>学习者1：首先让自己先冷静下来，先不要胡思乱想，想想是不是出什么事情了，或者因为什么原因耽搁了；\u003c/p>\u003cp>（消除、淡化负面情绪）\u003c/p>\u003cp>第二：换位思考下，以前老让男朋友等那么久，他肯定也很着急，也会很不安，也担心自己会出什么事情\u003c/p>\u003cp>第三：可以找找正面价值，我居然可以等一个人近一个小时，以前十分钟都不行，想想都觉得自己挺棒的。\u003c/p>\u003cp>第四：不能因为男朋友一次的迟到就断定他不爱自己，这太武断了，而且也不能因为这点小事就提分手，学会理解和包容。\u003c/p>\u003cp>布置任务：\u003c/p>\u003cp>A2：找人分享：\u003c/p>\u003cp>请在一两天内找个机会跟身边的同事或者朋友聊聊处理情绪常犯的错误有哪些，并给出怎么做会更好的建议。想想有哪些要点可以分享，分享的要点越多，你的处理自我情绪的能力就会越高。\u003c/p>\u003cp>\u003cstrong>学习者的分享：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>这周朋友找我吐槽工作上遇到的不顺心的事，我会结合拆书家讲解的NLP简快心理疗法给她建议。\u003c/p>\u003cp>1.先接受当下的情绪，这事情的确让她很难过，很伤心。\u003c/p>\u003cp>2.寻找这事情背后的积极意义。发生了这事的确很不开心，但这次的经验可以避免下次出现类似的情况，是个宝贵的经验财富。\u003c/p>\u003cp>3.换位思考，站在对方的角度来想这件事。\u003c/p>\u003cp>4.提升自己的思维方式，分析背后的原因，找到问题的根结，提升自己正视情绪，冷静处理的能力。\u003c/p>\u003cp>\u003cstrong>总结：\u003c/strong>\u003c/p>\u003cp>今天的拆书到此结束，望今后你们在今后的生活工作中都能很好的处理自己的情绪，做情绪的达人。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1513000118000,"updated_at":1513000118000,"ria":true},{"id":3360,"topic":"重复旧的做法，只会得到旧的结果","learn_goal":"只有做法不同，结果才会不同","remark":"","level":"TF1-1","duration":30,"status":0,"type":0,"chaishujia":{"username":"玲Lynn","city":"南昌"},"club":{"name":"南昌滕王阁分舵","city":"南昌"},"prologue":null,"ratings_count":0,"texts":[{"id":6222,"quote":"\u003cp>\u003cp>自我介绍:\u003c/p>\u003cp>大家好，我叫胡水珍。我是一名家庭教育工作者。\u003c/p>\u003cp>我的三个兴趣是:喜欢美食，喜欢分享，喜欢音乐。一次偶然的机会，我听说有拆书帮这个群体，我带着好奇心和学习心态走进了这个圈子，认识了许多优秀爱学习的朋友。我很喜欢这种学习的氛围，所以，我会一直和大家坚持学习下去，希望和大家在这个友爱的大家庭里共同的成长，共同进步。\u003c/p>\u003cp>拆书帮介绍:\u003c/p>\u003cp>“拆书”是一种学习方法，适用于以提升能力、解决问题为目标的成人学习，强调以学习者为中心，而不是以知识为中心。要把知识关联学习者的经验、规划具体的运用。&nbsp;\u003c/p>\u003cp>拆书分为：个人学习的拆书法和组织学习的拆书法。\u003c/p>\u003cp>个人学习的应用就是便签法；组织学习的应用就是一位拆书家拿一本书加工出一场现场学习，引导和促进一群人把知识拆为己用。&nbsp;\u003c/p>\u003cp>在拆书学习活动中，拆书家扮演的是引导者、促动师、催化师的角色，启发、引导学习者进行更深入的思考，促进学习者把知识转化为行动，践行“知行合一”。\u003c/p>\u003cp>在拆书帮内部有一本人人必读的书——《这样读书就够了》，目前已经被韩国引进出版了韩文版，相信不久的将来，还会出英文版，名扬全世界。\u003c/p>\u003cp>&nbsp;“拆书帮”是一个全国性的成人学习社群， 目前在北京、上海、广州、深圳等全国30多个城市都建有拆书帮的学习者俱乐部（也叫拆书帮分舵）。拆书帮分舵是一种公益性的组织，它的使命是帮助更多的学习爱好者成长为拆书家。 欢迎大家加入我们拆书帮，和一群信仰学习、热爱自我成长的小伙伴一起来把知识拆为己用，帮助身边我们爱的人和爱我们的人一起学习、成长！&nbsp;\u003c/p>\u003c/p>\u003cp>原文片段:\u003cbr>\u003c/p>\u003cp>重复旧的做法，只会得到旧的结果\u003cbr>\u003c/p>\u003cp>做法不同，结果才会不同。如果你做的事没有效果，那么请你改变你的做法。任何具有创新思维的做法都会比你旧有的多一份成功机会，希望明天比昨天更好，必须用昨天不同的做法改变自己，别人才有可能改变。世界上每样事情本来都在不停的改变，不肯改变，便是感到压力越来越大，终于面临淘汰或失败的威胁。因此，只有不断地改变做法，才能与其它事物保持理想的关系。&quot;做法&quot;是规条，目的是取得效果，把焦点放在取得效果之上，就要灵活不断的修正做法，改变是所有进步的起点。有些时候必须把全部旧的想法放下，才能看到突破的可能性，过分专注于问题本身便会看不到周边的众多机会。\u003c/p>","explains":"\u003cp>【I】\u003c/p>\u003cp>分享便签\u003c/p>\u003cp>我深刻体会到，重复旧的做法，只会得到旧的结果。只有做法不同，结果才会不同。改变对每个人来说都是非常重要的，也是非常需要自我提醒的。从知道到做到做到重点关注的是：我们处理各类问题时，把焦点放在取得效果之上，需要灵活地修正做法，改变才是进步的起点。\u003c/p>","interaction":"\u003cp>【A1】\u003c/p>\u003cp>分享A1便签\u003c/p>\u003cp>1998年的夏天，在南昌的一所大学里，我认识一位很会弹吉的朋友，看着他手指在琴弦上如鱼得水般灵活，我特别羡慕。心想：我要学也能弹这么好。跟着他学了好几次，我始终云里雾里，越来越迷糊，最后还是没有学会，就连简单的音阶也不会弹。我感到特别沮丧。\u003c/p>\u003cp>2016年的春天，我去了一趟郑州参加小吉他（尤克里里）培训， 令人没想到是是，我用了半天就学会弹奏十多首曲子。满满的成就感。和十几年前比起来，问题都出在方法上，我终于找到了原因所在。朋友采用的是老套说教的方法，而培训里老师用的是多种有趣的创新玩法。结合奥尔夫和身体律动等。所以，我学得特别快。深刻体会到，方法不同，做法不同，效果乃天壤之别。\u003cbr>\u003c/p>\u003cp>【A2】\u003c/p>\u003cp>分享A2便签\u003c/p>\u003cp>现在起，我计划：在今年8-12月份的家长课中，根据不同家长们的情况，改变我以往习惯性的授课模式，帮助大家轻松育儿，快乐学习的效果。8月份底，我将开展一场快乐奥尔夫音乐教师培训，采用多种视角和发挥集体想像力的开放式，达成合作共赢的效果。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":false}}],"created_at":1501830751000,"updated_at":1501830751000,"ria":true},{"id":3114,"topic":"重塑心灵-换框法","learn_goal":"能够接受：我们具备从负面体验中找到正面意义，感受到成功快乐","remark":"","level":"TF2-4","duration":60,"status":0,"type":0,"chaishujia":{"username":"房明","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"大家好，我是今天的拆书家房明。为了便于今天有更好的互动体验，我们首先来分一下组。\r\n 【图书介绍】【F】今天我们一起拆解的书是《重塑心灵》。这本书的作者是国际NLP大师李中莹，本书一经出版就成为国内最权威的NLP入门书。NLP可译为“身心语法程序学”，是一门研究我们的大脑如何工作的学问。本书不仅提供了既安全又容易产生实效的NLP技巧，还提出了更多与时代同步发展的新观点与新案例。【A】这本书与其他介绍NLP的书籍相比，没有过多艰涩的专业辞藻，而是站在一般大众角度，以尽量通俗的中文重新诠释英文原意，比如将英文的系统性、整体平衡翻译为“三赢”（我好！你好！世界好！）就是神来之笔。【B1】这本书可以帮助我们拥有让自己成功快乐的能力，尤其是对我自己来说，《重塑心灵》就是一本可以反复阅读的书，在这里不仅可以找到让人生更有效率的方法，还可以摆脱负面情绪的羁绊，甚至可以找到如何能够做一个成功的父母以及如何让孩子过的更开心、学东西更快的方法。【B2】今天我们就来学习改变我们信念系统的技巧中最快速最容易的一个——意义换框法，这个方法可以帮助我们找到负面体验中的正面意义。","ratings_count":0,"texts":[{"id":5925,"quote":"\u003cp>\u003cstrong>拆页1：《重塑心灵》 第一章 什么是NLP&nbsp; P15-16\u003c/strong>\u003c/p>\u003cp>\u003cstrong>每个人都已经具备使自己成功快乐的资源\u003c/strong>\u003c/p>\u003cp>每一个人都有过成功快乐的经验，也即是说有使自己成功快乐的能力。人类只用了大脑能力的极少部分，增加对大脑的运用，很多新的突破便会出现。现在已有大量的技巧发展出来，人类比以前更容易提升大脑效率。每一个人都可以通过改变思想而改变自己的情绪和行为，因而改变自己的人生。每天中遇到的事情，都可能含有给我们带来成功快乐的因素，取舍全由个人决定。所有事情或经验中，正面和负面的意义同时存在，把事情或经验变为绊脚石还是踏脚石，须由自己决定。成功快乐的人所拥有的思想和行为能力，都是经过一个过程而培养出来的。在开始的时候，他们与其他人所具备的条件一样，有能力替自己制造出困扰，也有能力替自己消除困扰。情绪、压力、困扰都不是源自外界的事物，而是由自己内在的信念、价值观和规条产生出来的。不相信自己有能力或有可能，是自己得不到成功快乐的最大障碍。\u003c/p>","explains":"\u003cp>&nbsp;【学习目标1】在跟随我完成本次RIA现场学习后，学习者在经历负面体验时，能够接受——我们具备从负面体验中找到正面意义，从而感受到成功快乐的能力，相信自己能够走出负面感受的泥潭。\u003c/p>\u003cp>【伙伴发言】请大家说说看在片段1中看到了那些关键词/句呢？\u003c/p>\u003cp>就像原文片段中说的，我们每个人在成长过程中，都曾有过成功快乐的时候，因此我们早已具备可以让自己成功快乐的能力。可为什么就像一句歌词里唱的那样“越长大，越孤单”，似乎长大从某种程度意味着孤单、烦恼、压力、困惑和迷茫。是因为我们遇到的烦心事越来越多吗？我们看看原文片段是怎么说的？原文片段告诉我们，\u003cstrong>我们每天遇到的各种事情，无论好坏都有两面意义。\u003c/strong>【伙伴发言】\u003cstrong>有哪两面意义呢？请大家说说看。没错，既有正面意义也有负面意义。\u003c/strong>\u003c/p>\u003cp>【不那么做的坏处】举个例子，相信大家从学生时代开始直到工作以后都会经历很多考试，也许某一次考试虽然自己认真准备了但却没能通过，我们一般会怎么想呢？“我真倒霉！复习的重点都没考”，【伙伴发言】请大家一起来判断下这是正面意义还是负面意义呢？没错，这是这件事的负面意义。如果我们只看到负面意义，会怎么样呢？我们就会掉进沮丧、失望，甚至不想再继续备考的负面感受里，对吗？但是如果我们能够转念一想“考试没过，使我知道了自己还有很多知识需要掌握，证明我还有很大的提升空间”。【伙伴发言】请大家再来判断下这是正面意义还是负面意义呢？ 是的，这是正面意义，当我们能够看到正面意义，我们内心的能量值就会有所提升，而不是一味地任由自己陷入负面感受不能自拔。所以说，\u003cstrong>我们能否看到事情的正面意义，从而感受到成功快乐，完全由我们自己决定，并不取决于外界事物。\u003c/strong>\u003c/p>","interaction":"\u003cp>【A1】显像提问\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>回忆一下过往的1个月，大家在工作中是否有过这样的负面体验：连续一周天天加班，熬夜熬出黑眼圈，但交出的方案却得不到认可，被领导无情地“打回来”；或者在生活中是否有过这样的负面体验：尽力做一个好父母，哪怕工作“累成狗”也要空出时间陪伴孩子，但孩子却总是跟自己“对着干”，或者感情上努力付出不计回报，但从“另一半”的嘴里说出的话却总是抱怨；又或者在学习上，挑灯夜读努力备考却没有通过。你有过这样的类似经历吗？当时发生了什么事？这件事的负面意义是什么？你的感受是怎么样的？给大家3分钟的时间回忆一下，填写在我发给大家的A4纸上，并在小组内分享。我们3分钟后请小伙伴们来分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者1：\u003c/p>\u003cp>我也遇到了你刚才提到的交出的方案得不到认可，被打回来的事情。这周一，辛辛苦苦赶报告，连续加班，周四交给领导，被领导批的一塌糊涂。整个下午都陷入沮丧的负面情绪里，甚至没办法继续工作。\u003c/p>\u003cp>【A1+】反思加工\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>根据刚才拆页的内容，我们知道能否看到事情的正面意义，从而感受到成功快乐，完全由我们自己决定，并不取决于外界事物。\u003c/p>\u003cp>如果时光能倒流，再面对同样的情况，想想看这件事中的正面意义是什么？\u003c/p>\u003cp>给大家1分钟的时间思考答案，我们1分钟后请小伙伴们来分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者2：我上周拆书过级2-4时，开场开的很不成功，当天晚上一度非常沮丧。如果时光可以倒流，我会找到的正面意义是：使我能够知道自己的不足，让自己有更大的进步空间。\u003c/p>\u003cp>【递进】\u003cbr>\u003c/p>\u003cp>知易行难，道理虽然我们都懂了，但是我们还是会感到遇到事情，特别是在经历一些负面体验时，比如（\u003cstrong>小伙伴A1中提到的亲身经历\u003c/strong>）、考试没过、晋升无望、失恋等等，我们往往只是看到其中的负面意义，然后任由负面感受泛滥，就像绊脚石一样牵绊着我们前进的脚步。这是为什么呢？是我们能力达不到吗？原文片段在最后告诉我们：\u003cstrong>并不是我们不具备这样的能力，而是因为我们不相信我们自己能够做到。\u003c/strong>那我们应该如何做到呢？带着这个问题我们一起来看一下拆页2。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":false,"a3":false}},{"id":5926,"quote":"\u003cp>\u003cstrong>拆页\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>：《重塑心灵》\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>第二章\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>信念系统\u003c/strong>\u003cstrong>&nbsp; P50-51\u003c/strong>\u003c/p>\u003cp>\u003cstrong>换框法之一：意义换框法\u003c/strong>\u003cstrong>&nbsp; \u003c/strong>\u003c/p>\u003cp>所有的事本身是没有意义的，所有的意义都是人加上去的。既然是人加上去的意义，则一件事情：\u003c/p>\u003cp>第一，可以有其他的意义，也可以有更多的意义。&nbsp; \u003c/p>\u003cp>第二，可以有不好的意义，也可以有好的意义。&nbsp; \u003c/p>\u003cp>试想一下当你用一块石头去锤打一颗钉子或者赶走一只老鼠你加到这块石头上的意义是什么？它本来有这些意义吗？再想一想，一块石头可以有多少用途？\u003c/p>\u003cp>把上面问题引出的意念放在别人所说的一句话、一个行为、甚至环境出现的一些情况上，你会得到什么启示？下次坐车没事做的时候，试想一想万字夹可以有多少用途。也许这样你会明白一件事情的意义，只是决定于我们的主观思想。&nbsp; \u003c/p>\u003cp>同一件事情里面总有不只一个意义包含其中。找出其中最能给自己帮助的意义，便可以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。&nbsp; \u003c/p>\u003cp>意义换框法对一些因果式的信念最为有效。例如：&nbsp; \u003c/p>\u003cp>“因为上司挑剔，所以我工作不开心。” \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 方法是把句中的&quot;果&quot;改为它的相反词再把句首的&quot;因为&quot;二字放到最后，成为：&nbsp; \u003c/p>\u003cp>“上司挑剔，所以我工作积极，因为……”&nbsp; \u003c/p>\u003cp>然后反复地思考如何能把句子写完,要求至少有6个不同的版本,再找出其中最能够接受的句子。&nbsp; \u003c/p>\u003cp>以下是课程里一些学员的杰作：&nbsp; \u003c/p>\u003cp>使我变得更能干&nbsp; \u003c/p>\u003cp>使我更快升级，脱离他的管治&nbsp; \u003c/p>\u003cp>使我更有能力去另找新工作&nbsp; \u003c/p>\u003cp>使我在同事之中受到最少的挑剔，因而更有安全感&nbsp; \u003c/p>\u003cp>使我能更早创业&nbsp; \u003c/p>\u003cp>我要证明他不能控制我的情绪&nbsp; \u003c/p>\u003cp>我要证明我可以做到&nbsp; \u003c/p>\u003cp>使我能清静愉快地工作&nbsp; \u003c/p>\u003cp>能证明在这种上司之下我仍能胜任&nbsp; \u003c/p>\u003cp>能证明我能超越任何压力&nbsp; \u003c/p>\u003cp>使其他老板注意我，因而创出转工的机会&nbsp; \u003c/p>\u003cp>使我有更优良的表现&nbsp; \u003c/p>\u003cp>试着挑选一条你觉得最好的，然后把整句话反复地念数遍。现在，你再念念本来的一句：“因为上司挑剔，所以我工作不开心。”你内心的感觉有怎样的不同？本来的一句和后来的一句，哪句你觉得更舒服一点？\u003c/p>\u003cp>假若我是你的一位多年好友，3个月前转了工作，今天走到你面前说，因为上司挑剔，所以我工作不开心。”你会觉得很自然地接受我的话，给我安慰、鼓励，你接受我的话的信念平台是：“上司挑剔，当然会不开心。” 现在，你把内容转了180度，刚好是相反的：“上司挑剔，所以我工作积极，因为……”而你的内心感觉比上一句更好。这是因为你内心的信念已经改变了。信念是在潜意识里，所以感觉是最好的测试标准。&nbsp;&nbsp;\u003c/p>","explains":"\u003cp>【学习目标2】在跟随我完成本次RIA现场学习后，学习者在经历负面感受时，能够利用意义换框法，找到负面感受中的正面意义，从而实现从原有的负面思维框架转换到正面思维框架的目标。\u003c/p>\u003cp>正如上一个片段告诉我们：同一件事情，既可以有正面意义，也可以有负面意义。所以，才会有古人云“塞翁失马，焉知非福”。既然得失总在一念之间，那有没有什么方法能够帮助我们具备遇事学会转念一想，多想一点正面意义，少想一点负面意义的能力呢？\u003c/p>\u003cp>意义换框法，恰好可以帮助我们借助语言模式的改变，找到一件事情负面体验中的正面意义。\u003c/p>\u003cp>【细化行动步骤】那么意义换框法有哪些步骤呢？\u003c/p>\u003cp>【伙伴发言】请大家说说看，原文片段是怎么说的呢？\u003c/p>\u003cp>大家说的特别好，把关键步骤都找出来了。\u003c/p>\u003cp>\u003cstrong>（动作：白板展示）\u003c/strong>我现在用一组更易记住的转换公式来总结一下意义换框法的所有步骤：\u003c/p>\u003cp>因为A，所以B&nbsp;\u003c/p>\u003cp>转换为：\u003c/p>\u003cp>因为A，所以非B。\u003c/p>\u003cp>其中，A：负面体验；B：负面感受。\u003c/p>\u003cp>我来解释一下，这一组公式如何来用：\u003c/p>\u003cp>（1）因为A，所以B：公式中，A是负面体验，B是由A得到的负面感受。这一步的关键是觉察并记录负面感受。【适用边界】请大家注意，意义换框法特别适合改变因果式的负面想法和感受，可以应用在工作、生活、情感沟通、教育子女等多个方面，但是意义换框法不适合给自己找借口，比如刚才我们提到的考试的例子“因为没有认真努力备考，所以考试没通过”。这样的因为和所以就是在找借口啦。\u003c/p>\u003cp>（2）因为A，所以非B：将B转换为非B，也就是将负面感受转换为正面感受。然后，借助头脑风暴，反复思考将句子补全。最好能想出3个以上的不同版本，目的是从中选出感觉最好的那一句，并反复多念几遍，体会最开始的那句话与这句话带给你心情的变化，哪句话更舒服。\u003c/p>\u003cp>【更贴近实际的例子】我来说一个我自己的例子，去年我报考了一级注册建筑师执业资格考试，考试是在9月份，当时下定决心想一次性通过，所以整个暑假我几乎把所有能利用的时间都拿来备考，甚至晚上经常看书看到夜里1、2点，我还曾经在我的朋友圈晒过自己挑灯夜读的照片，我的学生们看了纷纷点赞留言。可是最终还是有一门没过。看着成绩单，我心里想这门实操性的专业课对我这个工程经验不足的老师来说太难了，就算我努力复习也很难考过，干脆放弃得了，想到此心情很沮丧。但是后来我尝试利用了意义换框法：\u003c/p>\u003cp>\u003cstrong>因为\u003c/strong>我没有通过执业资格考试，\u003cstrong>所以\u003c/strong>我感到沮丧。\u003c/p>\u003cp>\u003cstrong>因为\u003c/strong>我没有通过执业资格考试，\u003cstrong>所以\u003c/strong>我更加积极备考。\u003c/p>\u003cp>\u003cstrong>因为\u003c/strong>：\u003c/p>\u003cp>①使我知道自己可以设定分难度的考试目标，先通过更容易过的二级，再来过一级，这样考试通过会更容易。\u003c/p>\u003cp>②使我对知识点理解和工程应用更深刻，掌握得更扎实。\u003c/p>\u003cp>③使我不急于为了考试而考试，而是享受学习备考的过程。\u003c/p>\u003cp>以上3个版本中，通过反复读，我感觉最好的句子是：使我对知识点理解和工程应用更深刻，掌握得更扎实。最后，通过和最开始句子的比较，我发现我的心情明显好转，不再感到沮丧，而是心中充满了力量。而且通过思考正面意义，让我接下来的备考行动方向也更明确了：在今年5月份我参加了二级考试，并计划今年暑假在复习书本知识的基础上，联系1-2个工地到现场参观，并在网上学习工程实例视频。\u003c/p>\u003cp>【预防异议】说到这里，可能有小伙伴有疑问，“因为”后面是不是一定要有3个或者6个以上的版本，我想不出这么多怎么办？我在应用该方法时有一个很重要的体会是每当我思考出一个版本，都是给出事情的一个正面价值，你未必每句都能接受，但是总有一两句会给你一种合情合理，或者“啊，对了！”的感觉。所以我觉得不必拘泥于3或6这个数字，但是尽力思考给出多个答案是很有必要的。\u003c/p>\u003cp>意义换框法，不仅能够帮助我们自己走出负面感受的泥潭，还可以帮助他人摆脱负面感受的羁绊。比如，我的学生也曾经因为工作面试没通过，找我诉苦。如果我按照“因为工作面试没过，所以心情沮丧”的思路安慰、鼓励她，虽然没啥问题，但是并不能让她看到这件事情的正面意义，因而这样的安慰，也不能帮助她建立正向信念。如果把内容反转“因为工作面试没通过，所以我更要开心并积极准备”，并帮她找到感觉最好的正面意义，就会让她改变信念，从内心中感到充满能量。这样的安慰和鼓励效果是不是更好呢？\u003c/p>\u003cp>总结来说，利用意义换框法，可以从负面体验中找到正面意义，从而帮助我们跳出原有的负面思维框架，转换到正面思维框架。最后，我们再来复习一下，具体的公式：\u003c/p>\u003cp>因为A，所以B&nbsp;\u003c/p>\u003cp>转换为：\u003c/p>\u003cp>因为A，所以非B。\u003c/p>","interaction":"\u003cp>【A3】促动参与\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>\u003cstrong>（动作：发放附\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>小明参加工作三年了，虽然年纪轻轻，但工作积极努力，业绩突出。最近，小明被公司列入了提拔考核对象，但最后却没能成功晋升职位。小明感到很沮丧，他把心中的不快向他的朋友小S倾诉，小S给予他安慰和鼓励。\u003c/p>\u003cp>【小组讨论】\u003c/p>\u003cp>现在，请每两人一组进行演练。一人扮演小明，一人扮演小明的朋友小S。 请大家在小组中花五分钟讨论一下小明的朋友小S如何安慰和鼓励小明，从而帮助他找到这件事情的正面意义，心情获得好转。双方讨论需要用上原文拆解中意义换框法的公式。大家先在组内讨论，并将讨论结果填写在我发给大家的A4纸上。\u003c/p>\u003cp>请参考下面的表格，写下你们的讨论结果。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>意义换框法公式\u003c/p>\u003c/td>\u003ctd>\u003cp>例如：未通过执业资格考试\u003c/p>\u003c/td>\u003ctd>\u003cp>事件：未成功晋升职位\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>因为A，所以B。\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>因为\u003c/strong>我没有通过执业资格考试，\u003cstrong>所以\u003c/strong>我感到沮丧，不想继续备考。\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>因为\u003c/strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ，\u003c/p>\u003cp>\u003cstrong>所以\u003c/strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>因为A，所以非B，因为：\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>因为\u003c/strong>我没有通过执业资格考试，\u003cstrong>所以\u003c/strong>我积极备考，\u003c/p>\u003cp>\u003cstrong>因为\u003c/strong>：\u003c/p>\u003cp>①使我知道自己可以设定分难度的考试目标，先通过更容易过的二级，再来过一级，这样考试通过会更容易。\u003c/p>\u003cp>②使我对知识点理解和工程应用更深刻，掌握得更扎实。\u003c/p>\u003cp>③使我不急于为了考试而考试，而是享受学习备考的过程。\u003c/p>\u003cp>\u003cstrong>我感觉最好的句子是\u003c/strong>：\u003c/p>\u003cp>使我对知识点理解和工程应用更深刻，掌握得更扎实。\u003c/p>\u003cp>\u003cstrong>此时，我的心情\u003c/strong>：\u003c/p>\u003cp>明显好转，不再感到沮丧，而是心中充满了力量。并明确了下一步行动方向。\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>因为\u003c/strong>&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;，\u003c/p>\u003cp>\u003cstrong>所以\u003c/strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 。\u003c/p>\u003cp>\u003cstrong>因为\u003c/strong>：\u003c/p>\u003cp>①\u003c/p>\u003cp>②\u003c/p>\u003cp>③\u003c/p>\u003cp>\u003cstrong>小明感觉最好的句子是\u003c/strong>：\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>此时，小明的心情：\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cbr>&nbsp; &nbsp; 请问我的指令是否清晰？给大家5分钟的时间，开始。\u003c/p>\u003cp>【小组演练】\u003c/p>\u003cp>好的，时间到。接下来，请在小组内将刚刚讨论的结果进行3分钟的角色扮演演练。要求运用到刚才讨论得到的意义换框法公式。\u003c/p>\u003cp>我的表述是否清晰？好，3分钟小组演练开始。\u003c/p>\u003cp>【困惑回应】\u003c/p>\u003cp>在这个过程中，有什么问题都可以直接提出来。\u003c/p>\u003cp>【角色扮演】\u003c/p>\u003cp>&nbsp; &nbsp; 好的，时间到。接下来，哪一组的小伙伴愿意上来演练一次你们刚才的对话。温馨提示，要体现意义换框法公式哦。好的，接下来3分钟的时间交给大家。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者小组1：\u003c/p>\u003cp>小明：小S，我最近因为工作上的事情好烦啊。\u003c/p>\u003cp>小s：怎么了，我也发现你一直闷闷不乐的，好像有心事。\u003c/p>\u003cp>小明：我最近不是被选为提拔对象了吗？结果最后没能晋升，我之前工作都很拼的，现在心里难受的很，都不想以后继续积极表现了。\u003c/p>\u003cp>小s：原来是因为工作晋升没成功，所以很沮丧，是吗？\u003c/p>\u003cp>小明：是啊，换谁都会这样的。\u003c/p>\u003cp>小s：你可以换个角度想想，工作晋升不成功，要怎么想才能让自己觉得，更要开心积极地工作？\u003c/p>\u003cp>小明：嗯，我觉得虽然这次晋升不成功，但是我也因此更加能够认清自己身上的亮点，我的组织协调能力很强，以后我会继续发挥长处。当然，我也更清楚了我自己的短板，以后也会继续提升自己的能力。\u003c/p>\u003cp>小s：这样想会不会感觉好多了？\u003c/p>\u003cp>小明：是啊，明显感觉舒服多了。\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>我们拆书法的很重要的理念是拆为己用，接下来让我们一起来规划一下今后我们自己如何应用意义换框法。\u003c/p>\u003cp>【分步催化1】\u003c/p>\u003cp>学习应考，工作面试、晋升，上司刁难，教育子女，情感沟通……想一想你现在或者近期在工作和生活中会涉及哪个情境，是可以运用到意义换框法呢？请大家在A4纸上写下在该情境中可能会遇到的一个负面事件，我给大家2分钟的时间，写1件事即可。\u003c/p>\u003cp>【分步催化2】\u003c/p>\u003cp>请大家思考一下，通过今天的所学，大家对于这件现在或近期会遇到的负面事件如何采用意义换框法来应对呢？请大家花3分钟的时间写出你的行动计划，3分钟后请小伙伴来分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者1：\u003c/p>\u003cp>事件：准备下星期考驾照，在练车的过程中，担心教练太严格，会刁难自己，自己会有难过，想放弃学车的情绪。\u003c/p>\u003cp>行动计划：我在学车时，当遇到教练太过严格，刁难自己，我就会利用意义换框法。我会想教练太过严格，我更要高兴并积极学车，因为这样能够让自己不会成为马路杀手。\u003c/p>\u003cp>学习者2：\u003c/p>\u003cp>事件：我的三级拆书过级在总舵评审时，被打回。\u003c/p>\u003cp>行动计划：若我收到过级被打回的通知，我会用意义换框法找到事件的正面意义：过级被打回，所以我会开心，因为能够让我知道自身的不足，给多一次自己成长进步的机会。接下来我会认真准备预备表，在周四或者周日的练武场重新过级。\u003c/p>\u003cp>结语：\u003c/p>\u003cp>我们都曾经历过陷入负面思维而无法自拔的时刻，这样的时刻就像是我们生活中的“绊脚石”不断牵绊着我们前进的脚步，而今天所拆的知识就如同积极心理疗法，能够帮助我们找到负面体验中的正面意义。请大家记住今天我们拆解的意义换框法的公式：\u003c/p>\u003cp>因为A，所以B&nbsp;\u003c/p>\u003cp>转换为：\u003c/p>\u003cp>因为A，所以非B。\u003c/p>\u003cp>只要我们不断的应用和练习，相信大家很快就能够拥有将一个个“绊脚石”变为“踏脚石”的能力！\u003c/p>\u003cp>最后请大家用便签写下这次拆书活动的反馈建议，可以采用苹果（好的方面）和洋葱（可更好的方面）来写，帮助我提升和改进，最后谢谢大家今天的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}},{"id":5927,"quote":"\u003cp>\u003cstrong>拆页\u003c/strong>\u003cstrong>2\u003c/strong>\u003cstrong>：《重塑心灵》\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>第二章\u003c/strong>\u003cstrong> \u003c/strong>\u003cstrong>信念系统\u003c/strong>\u003cstrong>&nbsp; P50-51\u003c/strong>\u003c/p>\u003cp>\u003cstrong>换框法之一：意义换框法\u003c/strong>\u003cstrong>&nbsp; \u003c/strong>\u003c/p>\u003cp>所有的事本身是没有意义的，所有的意义都是人加上去的。既然是人加上去的意义，则一件事情：\u003c/p>\u003cp>第一，可以有其他的意义，也可以有更多的意义。&nbsp; \u003c/p>\u003cp>第二，可以有不好的意义，也可以有好的意义。&nbsp; \u003c/p>\u003cp>试想一下当你用一块石头去锤打一颗钉子或者赶走一只老鼠你加到这块石头上的意义是什么？它本来有这些意义吗？再想一想，一块石头可以有多少用途？\u003c/p>\u003cp>把上面问题引出的意念放在别人所说的一句话、一个行为、甚至环境出现的一些情况上，你会得到什么启示？下次坐车没事做的时候，试想一想万字夹可以有多少用途。也许这样你会明白一件事情的意义，只是决定于我们的主观思想。&nbsp; \u003c/p>\u003cp>同一件事情里面总有不只一个意义包含其中。找出其中最能给自己帮助的意义，便可以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。&nbsp; \u003c/p>\u003cp>意义换框法对一些因果式的信念最为有效。例如：&nbsp; \u003c/p>\u003cp>“因为上司挑剔，所以我工作不开心。” \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 方法是把句中的&quot;果&quot;改为它的相反词再把句首的&quot;因为&quot;二字放到最后，成为：&nbsp; \u003c/p>\u003cp>“上司挑剔，所以我工作积极，因为……”&nbsp; \u003c/p>\u003cp>然后反复地思考如何能把句子写完,要求至少有6个不同的版本,再找出其中最能够接受的句子。&nbsp; \u003c/p>\u003cp>以下是课程里一些学员的杰作：&nbsp; \u003c/p>\u003cp>使我变得更能干&nbsp; \u003c/p>\u003cp>使我更快升级，脱离他的管治&nbsp; \u003c/p>\u003cp>使我更有能力去另找新工作&nbsp; \u003c/p>\u003cp>使我在同事之中受到最少的挑剔，因而更有安全感&nbsp; \u003c/p>\u003cp>使我能更早创业&nbsp; \u003c/p>\u003cp>我要证明他不能控制我的情绪&nbsp; \u003c/p>\u003cp>我要证明我可以做到&nbsp; \u003c/p>\u003cp>使我能清静愉快地工作&nbsp; \u003c/p>\u003cp>能证明在这种上司之下我仍能胜任&nbsp; \u003c/p>\u003cp>能证明我能超越任何压力&nbsp; \u003c/p>\u003cp>使其他老板注意我，因而创出转工的机会&nbsp; \u003c/p>\u003cp>使我有更优良的表现&nbsp; \u003c/p>\u003cp>试着挑选一条你觉得最好的，然后把整句话反复地念数遍。现在，你再念念本来的一句：“因为上司挑剔，所以我工作不开心。”你内心的感觉有怎样的不同？本来的一句和后来的一句，哪句你觉得更舒服一点？\u003c/p>\u003cp>假若我是你的一位多年好友，3个月前转了工作，今天走到你面前说，因为上司挑剔，所以我工作不开心。”你会觉得很自然地接受我的话，给我安慰、鼓励，你接受我的话的信念平台是：“上司挑剔，当然会不开心。” 现在，你把内容转了180度，刚好是相反的：“上司挑剔，所以我工作积极，因为……”而你的内心感觉比上一句更好。这是因为你内心的信念已经改变了。信念是在潜意识里，所以感觉是最好的测试标准。&nbsp;&nbsp;\u003c/p>","explains":"\u003cp>正如上一个片段告诉我们：同一件事情，既可以有正面意义，也可以有负面意义。所以，才会有古人云“塞翁失马，焉知非福”。既然得失总在一念之间，那有没有什么方法能够帮助我们具备遇事学会转念一想，多想一点正面意义，少想一点负面意义的能力呢？\u003c/p>\u003cp>意义换框法，恰好可以帮助我们借助语言模式的改变，找到一件事情负面体验中的正面意义。\u003c/p>\u003cp>【细化行动步骤】那么意义换框法有哪些步骤呢？\u003c/p>\u003cp>【伙伴发言】请大家说说看，原文片段是怎么说的呢？\u003c/p>\u003cp>大家说的特别好，把关键步骤都找出来了。\u003c/p>\u003cp>\u003cstrong>（动作：白板展示）\u003c/strong>我现在用一组更易记住的转换公式来总结一下意义换框法的所有步骤：\u003c/p>\u003cp>因为A，所以B&nbsp;\u003c/p>\u003cp>转换为：\u003c/p>\u003cp>因为A，所以非B。\u003c/p>\u003cp>其中，A：负面体验；B：负面感受。\u003c/p>\u003cp>我来解释一下，这一组公式如何来用：\u003c/p>\u003cp>（1）因为A，所以B：公式中，A是负面体验，B是由A得到的负面感受。这一步的关键是觉察并记录负面感受。【适用边界】请大家注意，意义换框法特别适合改变因果式的负面想法和感受，可以应用在工作、生活、情感沟通、教育子女等多个方面，但是意义换框法不适合给自己找借口，比如刚才我们提到的考试的例子“因为没有认真努力备考，所以考试没通过”。这样的因为和所以就是在找借口啦。\u003c/p>\u003cp>（2）因为A，所以非B：将B转换为非B，也就是将负面感受转换为正面感受。然后，借助头脑风暴，反复思考将句子补全。最好能想出3个以上的不同版本，目的是从中选出感觉最好的那一句，并反复多念几遍，体会最开始的那句话与这句话带给你心情的变化，哪句话更舒服。\u003c/p>\u003cp>【更贴近实际的例子】我来说一个我自己的例子，去年我报考了一级注册建筑师执业资格考试，考试是在9月份，当时下定决心想一次性通过，所以整个暑假我几乎把所有能利用的时间都拿来备考，甚至晚上经常看书看到夜里1、2点，我还曾经在我的朋友圈晒过自己挑灯夜读的照片，我的学生们看了纷纷点赞留言。可是最终还是有一门没过。看着成绩单，我心里想这门实操性的专业课对我这个工程经验不足的老师来说太难了，就算我努力复习也很难考过，干脆放弃得了，想到此心情很沮丧。但是后来我尝试利用了意义换框法：\u003c/p>\u003cp>\u003cstrong>因为\u003c/strong>我没有通过执业资格考试，\u003cstrong>所以\u003c/strong>我感到沮丧。\u003c/p>\u003cp>\u003cstrong>因为\u003c/strong>我没有通过执业资格考试，\u003cstrong>所以\u003c/strong>我更加积极备考。\u003c/p>\u003cp>\u003cstrong>因为\u003c/strong>：\u003c/p>\u003cp>①使我知道自己可以设定分难度的考试目标，先通过更容易过的二级，再来过一级，这样考试通过会更容易。\u003c/p>\u003cp>②使我对知识点理解和工程应用更深刻，掌握得更扎实。\u003c/p>\u003cp>③使我不急于为了考试而考试，而是享受学习备考的过程。\u003c/p>\u003cp>以上3个版本中，通过反复读，我感觉最好的句子是：使我对知识点理解和工程应用更深刻，掌握得更扎实。最后，通过和最开始句子的比较，我发现我的心情明显好转，不再感到沮丧，而是心中充满了力量。而且通过思考正面意义，让我接下来的备考行动方向也更明确了：在今年5月份我参加了二级考试，并计划今年暑假在复习书本知识的基础上，联系1-2个工地到现场参观，并在网上学习工程实例视频。\u003c/p>\u003cp>【预防异议】说到这里，可能有小伙伴有疑问，“因为”后面是不是一定要有3个或者6个以上的版本，我想不出这么多怎么办？我在应用该方法时有一个很重要的体会是每当我思考出一个版本，都是给出事情的一个正面价值，你未必每句都能接受，但是总有一两句会给你一种合情合理，或者“啊，对了！”的感觉。所以我觉得不必拘泥于3或6这个数字，但是尽力思考给出多个答案是很有必要的。\u003c/p>\u003cp>意义换框法，不仅能够帮助我们自己走出负面感受的泥潭，还可以帮助他人摆脱负面感受的羁绊。比如，我的学生也曾经因为工作面试没通过，找我诉苦。如果我按照“因为工作面试没过，所以心情沮丧”的思路安慰、鼓励她，虽然没啥问题，但是并不能让她看到这件事情的正面意义，因而这样的安慰，也不能帮助她建立正向信念。如果把内容反转“因为工作面试没通过，所以我更要开心并积极准备”，并帮她找到感觉最好的正面意义，就会让她改变信念，从内心中感到充满能量。这样的安慰和鼓励效果是不是更好呢？\u003c/p>\u003cp>总结来说，利用意义换框法，可以从负面体验中找到正面意义，从而帮助我们跳出原有的负面思维框架，转换到正面思维框架。最后，我们再来复习一下，具体的公式：\u003c/p>\u003cp>因为A，所以B&nbsp;\u003c/p>\u003cp>转换为：\u003c/p>\u003cp>因为A，所以非B。\u003c/p>","interaction":"\u003cp>【A3】促动参与\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>\u003cstrong>（动作：发放附\u003c/strong>\u003cstrong>1\u003c/strong>\u003cstrong>）\u003c/strong>\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>小明参加工作三年了，虽然年纪轻轻，但工作积极努力，业绩突出。最近，小明被公司列入了提拔考核对象，但最后却没能成功晋升职位。小明感到很沮丧，他把心中的不快向他的朋友小S倾诉，小S给予他安慰和鼓励。\u003c/p>\u003cp>【小组讨论】\u003c/p>\u003cp>现在，请每两人一组进行演练。一人扮演小明，一人扮演小明的朋友小S。 请大家在小组中花五分钟讨论一下小明的朋友小S如何安慰和鼓励小明，从而帮助他找到这件事情的正面意义，心情获得好转。双方讨论需要用上原文拆解中意义换框法的公式。大家先在组内讨论，并将讨论结果填写在我发给大家的A4纸上。\u003c/p>\u003cp>请参考下面的表格，写下你们的讨论结果。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>意义换框法公式\u003c/p>\u003c/td>\u003ctd>\u003cp>例如：未通过执业资格考试\u003c/p>\u003c/td>\u003ctd>\u003cp>事件：未成功晋升职位\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>因为A，所以B。\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>因为\u003c/strong>我没有通过执业资格考试，\u003cstrong>所以\u003c/strong>我感到沮丧，不想继续备考。\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>因为\u003c/strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ，\u003c/p>\u003cp>\u003cstrong>所以\u003c/strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 。\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>因为A，所以非B，因为：\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>因为\u003c/strong>我没有通过执业资格考试，\u003cstrong>所以\u003c/strong>我积极备考，\u003c/p>\u003cp>\u003cstrong>因为\u003c/strong>：\u003c/p>\u003cp>①使我知道自己可以设定分难度的考试目标，先通过更容易过的二级，再来过一级，这样考试通过会更容易。\u003c/p>\u003cp>②使我对知识点理解和工程应用更深刻，掌握得更扎实。\u003c/p>\u003cp>③使我不急于为了考试而考试，而是享受学习备考的过程。\u003c/p>\u003cp>\u003cstrong>我感觉最好的句子是\u003c/strong>：\u003c/p>\u003cp>使我对知识点理解和工程应用更深刻，掌握得更扎实。\u003c/p>\u003cp>\u003cstrong>此时，我的心情\u003c/strong>：\u003c/p>\u003cp>明显好转，不再感到沮丧，而是心中充满了力量。并明确了下一步行动方向。\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>因为\u003c/strong>&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;，\u003c/p>\u003cp>\u003cstrong>所以\u003c/strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 。\u003c/p>\u003cp>\u003cstrong>因为\u003c/strong>：\u003c/p>\u003cp>①\u003c/p>\u003cp>②\u003c/p>\u003cp>③\u003c/p>\u003cp>\u003cstrong>小明感觉最好的句子是\u003c/strong>：\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>此时，小明的心情：\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>\u003cbr>&nbsp; &nbsp; 请问我的指令是否清晰？给大家5分钟的时间，开始。\u003c/p>\u003cp>【小组演练】\u003c/p>\u003cp>好的，时间到。接下来，请在小组内将刚刚讨论的结果进行3分钟的角色扮演演练。要求运用到刚才讨论得到的意义换框法公式。\u003c/p>\u003cp>我的表述是否清晰？好，3分钟小组演练开始。\u003c/p>\u003cp>【困惑回应】\u003c/p>\u003cp>在这个过程中，有什么问题都可以直接提出来。\u003c/p>\u003cp>【角色扮演】\u003c/p>\u003cp>&nbsp; &nbsp; 好的，时间到。接下来，哪一组的小伙伴愿意上来演练一次你们刚才的对话。温馨提示，要体现意义换框法公式哦。好的，接下来3分钟的时间交给大家。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者小组1：\u003c/p>\u003cp>小明：小S，我最近因为工作上的事情好烦啊。\u003c/p>\u003cp>小s：怎么了，我也发现你一直闷闷不乐的，好像有心事。\u003c/p>\u003cp>小明：我最近不是被选为提拔对象了吗？结果最后没能晋升，我之前工作都很拼的，现在心里难受的很，都不想以后继续积极表现了。\u003c/p>\u003cp>小s：原来是因为工作晋升没成功，所以很沮丧，是吗？\u003c/p>\u003cp>小明：是啊，换谁都会这样的。\u003c/p>\u003cp>小s：你可以换个角度想想，工作晋升不成功，要怎么想才能让自己觉得，更要开心积极地工作？\u003c/p>\u003cp>小明：嗯，我觉得虽然这次晋升不成功，但是我也因此更加能够认清自己身上的亮点，我的组织协调能力很强，以后我会继续发挥长处。当然，我也更清楚了我自己的短板，以后也会继续提升自己的能力。\u003c/p>\u003cp>小s：这样想会不会感觉好多了？\u003c/p>\u003cp>小明：是啊，明显感觉舒服多了。\u003c/p>\u003cp>【A2】催化应用\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>我们拆书法的很重要的理念是拆为己用，接下来让我们一起来规划一下今后我们自己如何应用意义换框法。\u003c/p>\u003cp>【分步催化1】\u003c/p>\u003cp>学习应考，工作面试、晋升，上司刁难，教育子女，情感沟通……想一想你现在或者近期在工作和生活中会涉及哪个情境，是可以运用到意义换框法呢？请大家在A4纸上写下在该情境中可能会遇到的一个负面事件，我给大家2分钟的时间，写1件事即可。\u003c/p>\u003cp>【分步催化2】\u003c/p>\u003cp>请大家思考一下，通过今天的所学，大家对于这件现在或近期会遇到的负面事件如何采用意义换框法来应对呢？请大家花3分钟的时间写出你的行动计划，3分钟后请小伙伴来分享。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者1：\u003c/p>\u003cp>事件：准备下星期考驾照，在练车的过程中，担心教练太严格，会刁难自己，自己会有难过，想放弃学车的情绪。\u003c/p>\u003cp>行动计划：我在学车时，当遇到教练太过严格，刁难自己，我就会利用意义换框法。我会想教练太过严格，我更要高兴并积极学车，因为这样能够让自己不会成为马路杀手。\u003c/p>\u003cp>学习者2：\u003c/p>\u003cp>事件：我的三级拆书过级在总舵评审时，被打回。\u003c/p>\u003cp>行动计划：若我收到过级被打回的通知，我会用意义换框法找到事件的正面意义：过级被打回，所以我会开心，因为能够让我知道自身的不足，给多一次自己成长进步的机会。接下来我会认真准备预备表，在周四或者周日的练武场重新过级。\u003c/p>\u003cp>结语：\u003c/p>\u003cp>我们都曾经历过陷入负面思维而无法自拔的时刻，这样的时刻就像是我们生活中的“绊脚石”不断牵绊着我们前进的脚步，而今天所拆的知识就如同积极心理疗法，能够帮助我们找到负面体验中的正面意义。请大家记住今天我们拆解的意义换框法的公式：\u003c/p>\u003cp>因为A，所以B&nbsp;\u003c/p>\u003cp>转换为：\u003c/p>\u003cp>因为A，所以非B。\u003c/p>\u003cp>只要我们不断的应用和练习，相信大家很快就能够拥有将一个个“绊脚石”变为“踏脚石”的能力！\u003c/p>\u003cp>最后请大家用便签写下这次拆书活动的反馈建议，可以采用苹果（好的方面）和洋葱（可更好的方面）来写，帮助我提升和改进，最后谢谢大家今天的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":true,"a3":true}}],"created_at":1499092481000,"updated_at":1499096575000,"ria":true},{"id":3113,"topic":"重塑心灵——意义换框法","learn_goal":"学习者利用意义换框法的三个步骤，能够找到负面感受中的正面意义","remark":"","level":"TF2-3","duration":30,"status":0,"type":0,"chaishujia":{"username":"房明","city":"广州"},"club":{"name":"广州小蛮腰分舵","city":"广州"},"prologue":"大家好，我是今天的拆书家房明。我们首先来分一下组。\r\n 【图书介绍】【F】今天我们一起拆解的书是《重塑心灵》。这本书的作者是国际NLP大师李中莹，本书一经出版就成为国内最权威的NLP入门书。NLP可译为“身心语法程序学”，是一门研究我们的大脑如何工作的学问。本书较全面地介绍了NLP的历史、理论框架、基本概念等基础理论，同时提供了既安全又容易产生实效的NLP技巧技巧，以及更多与时代同步发展的新观点与新案例。【A】这本书与其他介绍NLP的书籍相比，没有过多艰涩的专业辞藻，而是站在一般大众角度，以尽量通俗的中文重新诠释英文原意，比如将英文的系统性、整体平衡翻译为“三赢”（我好！你好！世界好！）就是神来之笔。【B1】这本书可以帮助我们拥有让自己成功快乐的能力，尤其是对我自己来说，《重塑心灵》就是一本可以反复阅读的书，在这里不仅可以找到让人生更有效率的方法，还可以摆脱负面情绪的羁绊，甚至可以找到如何能够做一个成功的父母以及如何让孩子过的更开心、学东西更快的方法。【B2】今天我们就来学习改变我们信念系统的技巧中最快速最容易的一个——意义换框法，可以帮助我们找到负面感受中的正面意义。","ratings_count":0,"texts":[{"id":5924,"quote":"\u003cp>\u003cstrong>换框法之一：意义换框法\u003c/strong>\u003cstrong>&nbsp; \u003c/strong>\u003c/p>\u003cp>所有的事本身是没有意义的所有的意义都是人加上去的。既然是人加上去的意义，则一件事情：&nbsp; \u003c/p>\u003cp>第一，可以有其他的意义，也可以有更多的意义。&nbsp; \u003c/p>\u003cp>第二，可以有不好的意义，也可以有好的意义。&nbsp; \u003c/p>\u003cp>试想一下当你用一块石头去锤打一颗钉子或者赶走一只老鼠你加到这块石头上的意义是什么？它本来有这些意义吗?？再想一想，一块石头可以有多少用途？\u003c/p>\u003cp>把上面问题引出的意念放在别人所说的一句话、一个行为甚至环境出现的一些情况上，你会得到什么启示？下次坐车没事做的时候，试想一想万字夹可以有多少用途。也许这样你会明白一件事情的意义，只是决定于我们的主观思想。&nbsp; \u003c/p>\u003cp>同一件事情里面总有不只一个意义包含其中。找出其中最能给自己帮助的意义，便可以把事情的价值改变，使事情由绊脚石变为踏脚石，自己因而有所提升。这便是意义换框法。&nbsp; \u003c/p>\u003cp>意义换框法对一些因果式的信念最为有效。例如：&nbsp; \u003c/p>\u003cp>“因为上司挑剔所以我工作不开心。” \u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 方法是把句中的&quot;果&quot;改为它的相反词再把句首的&quot;因为&quot;二字放到最后，成为：&nbsp; \u003c/p>\u003cp>“上司挑剔，所以我工作积极，因为……”&nbsp; \u003c/p>\u003cp>然后反复地思考如何能把句子写完,要求至少有6个不同的版本,再找出其中最能够接受的句子。&nbsp; \u003c/p>\u003cp>以下是课程里一些学员的杰作：&nbsp; \u003c/p>\u003cp>使我变得更能干&nbsp; \u003c/p>\u003cp>使我更快升级脱离他的管治&nbsp; \u003c/p>\u003cp>使我更有能力去另找新工作&nbsp; \u003c/p>\u003cp>使我在同事之中受到最少的挑剔因而更有安全感&nbsp; \u003c/p>\u003cp>使我能更早创业&nbsp; \u003c/p>\u003cp>我要证明他不能控制我的情绪&nbsp; \u003c/p>\u003cp>我要证明我可以做到&nbsp; \u003c/p>\u003cp>使我能清静愉快地工作&nbsp; \u003c/p>\u003cp>能证明在这种上司之下我仍能胜任&nbsp; \u003c/p>\u003cp>能证明我能超越任何压力&nbsp; \u003c/p>\u003cp>使其他老板注意我因而创出转工的机会&nbsp; \u003c/p>\u003cp>使我有更优良的表现&nbsp; \u003c/p>\u003cp>试着挑选一条你觉得最好的，然后把整句话反复地念数遍。现在，你再念念本来的一句：“因为上司挑剔，所以我工作不开心。”你内心的感觉有怎样的不同？本来的一句和后来的一句，哪句你觉得更舒服一点？\u003c/p>\u003cp>假若我是你的一位多年好友，3个月前转了工作，今天走到你面前说，因为上司挑剔，所以我工作不开心。”你会觉得很自然地接受我的话，给我安慰、鼓励，你接受我的话的信念平台是：“上司挑剔，当然会不开心。” 现在，你把内容转了180度，刚好是相反的：“上司挑剔，所以我工作积极，因为……”而你的内心感觉比上一句更好。这是因为你内心的信念已经改变了。信念是在潜意识里，所以感觉是最好的测试标准。&nbsp;&nbsp;\u003c/p>","explains":"\u003cp>【学习目标】在跟随我完成本次RIA现场学习后，学习者在经历负面感受时，利用意义换框法的三个步骤，能够找到负面感受中的正面意义，从而实现从原有的负面思维框架转换到正面思维框架的目标。\u003c/p>\u003cp>【why】我先来给大家分享个有趣的故事：有个卖鞋公司派两个人去非洲考查市场，第一个人回来说那里的市场很糟糕没一个人穿鞋，第二个人说老总那里市场太好了！到现在那里的人还没鞋子穿。（伙伴发言1）大家从这个故事里得到了什么启发？没错，同一件事情，既可以有正面意义，也可以有负面意义。所以，才会有古人云“塞翁失马，焉知非福”。既然得失总在一念之间，那有没有什么方法能够帮助我们遇事学会转念一想，多想一点正面意义，少想一点负面意义呢？\u003c/p>\u003cp>【what】意义换框法，恰好可以帮助我们借助语言模式的改变，找到一件事情负面感受中的正面意义。\u003c/p>\u003cp>【how】【细化行动步骤】（展示图1）那么我们应该如何使用意义换框法呢？我们可以按照三个具体的步骤来完成：\u003c/p>\u003cp>（1）觉察并记录负面感受。意义换框法特别适合改变因果式的负面感受。具体格式为：\u003c/p>\u003cp>因为A（原因），所以B（负面感受）。\u003c/p>\u003cp>（2）将负面感受转换为正面感受。首先，将B （负面感受）转换为C（正面感受）；然后，将句首的“因为”两个字放到最后。具体格式为：\u003c/p>\u003cp>A（原因），所以C（正面感受），因为&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 。\u003c/p>\u003cp>（3）选出最好的正面感受。借助头脑风暴，反复思考将“因为”后面的句子补全。最好能想出六个以上的不同版本，目的是从中选出感觉最好的那一句，并反复多念几遍，体会最开始的那句话与这句话带给你心情的变化，哪句话更舒服。\u003c/p>\u003cp>【例子】举个例子，每次我都很努力地准备拆书过级，有一次没通过，当时心情很沮丧，甚至想要放弃继续过级。后来我按照意义换框法的三个步骤，成功跳出了负面思维框架的羁绊。具体过程是这样的：\u003c/p>\u003cp>（1）觉察并记录负面感受。\u003cstrong>因为\u003c/strong>我没有通过拆书过级，\u003cstrong>所以\u003c/strong>我感到沮丧。\u003c/p>\u003cp>（2）将负面感受转换为正面感受。我没有通过拆书过级，\u003cstrong>所以\u003c/strong>我更加积极过级，\u003cstrong>因为\u003c/strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; 。\u003c/p>\u003cp>（3）选出最好的正面感受。经过头脑风暴，我想到了“因为”后面可以有以下六个不同版本：\u003c/p>\u003cp>①使我知道自己的不足。\u003c/p>\u003cp>②使我反复推敲技能点，因而对技能点的掌握更扎实。\u003c/p>\u003cp>③使我能够学会遇到失败快速调整自己的状态。\u003c/p>\u003cp>④使我学会了在过级结束后及时总结复盘。\u003c/p>\u003cp>⑤使我不急于往前冲，而是享受过级的过程。\u003c/p>\u003cp>⑥使我对知识点理解和应用更深刻，进而可形成自己特色拆书课。\u003c/p>\u003cp>以上六个版本中，通过反复诵读，我感觉最好的句子是：使我反复推敲技能点，让我对该级别技能点的掌握更加扎实。\u003c/p>\u003cp>最后，通过和最开始句子的比较，我发现我的心情明显好转，不再感到沮丧，而是心中充满了力量。\u003c/p>\u003cp>说到这里，可能有小伙伴有疑问，“因为”后面是不是一定要有6个以上的版本，我想不出这么多版本怎么办呢？我在应用该方法时一个很重要的体会是每当我思考出一个版本，都是给出事情的一个正面意义，你未必每句都能接受，但是总有一两句会给你一种合情合理，或者“啊，对了！”的感觉。所以我觉得不必拘泥于6这个数字，但是尽力思考给出多个答案是很有必要的。\u003c/p>\u003cp>&nbsp; &nbsp; 总结来说，利用意义换框法，可以从负面感受中找到正面意义，从而帮助我们跳出原有的负面思维框架，转换到正面思维框架。最后，我们再来复习一下，具体的三个步骤：（1）觉察并记录负面感受；（2）将负面感受转换为正面感受；（3）选出最好的正面感受。\u003c/p>","interaction":"\u003cp>【A3】促动参与\u003c/p>\u003cp>拆书家提问设计（逐字稿）：\u003c/p>\u003cp>【场景设计】\u003c/p>\u003cp>小明参加工作三年了，虽然年纪轻轻，但工作积极努力，业绩突出。最近，小明被公司列入了提拔考核对象，但最后却没能成功晋升职位。小明感到很沮丧，他把心中的不快向他的朋友倾诉，小明的朋友给予他安慰和鼓励。\u003c/p>\u003cp>【小组讨论】（分发现场演练表格）\u003c/p>\u003cp>现在，请每两人一组进行演练。一人扮演小明，一人扮演小明的朋友。 请大家在小组中花五分钟讨论一下小明的朋友如何安慰和鼓励小明，从而帮助他找到这件事情的正面意义，心情获得好转。双方讨论需要用上原文拆解中意义换框法的三个步骤。\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>意义换框法步骤\u003c/p>\u003c/td>\u003ctd>\u003cp>事件：未通过拆书过级 \u003c/p>\u003c/td>\u003ctd>\u003cp>事件：未成功晋升职位\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>（1）觉察并记录负面感受。\u003c/p>\u003c/td>\u003ctd>\u003cp>\u003cstrong>因为\u003c/strong>我没有通过拆书过级，\u003c/p>\u003cp>\u003cstrong>所以\u003c/strong>我感到很沮丧。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>（2）将负面感受转换为正面感受。\u003c/p>\u003c/td>\u003ctd>\u003cp>我没有通过拆书过级，\u003c/p>\u003cp>\u003cstrong>所以\u003c/strong>我更加积极过级，\u003c/p>\u003cp>\u003cstrong>因为\u003c/strong>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;。\u003c/p>\u003c/td>\u003ctd>\u003cbr>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>（3）选出最好的正面感受。\u003c/p>\u003c/td>\u003ctd>\u003cp>①使我知道自己的不足。\u003c/p>\u003cp>②使我反复推敲技能点，让我对该级别技能点的掌握更加扎实。\u003c/p>\u003cp>……\u003c/p>\u003cp>\u003cstrong>我感觉最好的句子是\u003c/strong>：\u003c/p>\u003cp>使我反复推敲技能点，让我对该级别技能点的掌握更加扎实。\u003c/p>\u003cp>\u003cstrong>此时，我的心情\u003c/strong>：\u003c/p>\u003cp>明显好转，不再感到沮丧，而是心中充满了力量。\u003c/p>\u003c/td>\u003ctd>\u003cp>①\u003c/p>\u003cp>②\u003c/p>\u003cp>③\u003c/p>\u003cp>④\u003c/p>\u003cp>⑤\u003c/p>\u003cp>⑥\u003c/p>\u003cp>\u003cstrong>小明感觉最好的句子是\u003c/strong>：\u003c/p>\u003cp>\u003cstrong>此时，小明的心情：\u003c/strong>\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者1：\u003c/p>\u003cp>步骤（1）：因为我没有成功晋升职位，所以我感到很难过。\u003c/p>\u003cp>步骤（2）：我没有成功晋升职位，我更应该积极工作。\u003c/p>\u003cp>步骤（3）：\u003c/p>\u003cp>①使我能够发现自己的不足\u003c/p>\u003cp>②使我能够发现工作改善重点\u003c/p>\u003cp>③使我能够把基础技能做扎实，打牢靠\u003c/p>\u003cp>④使我有更多在基层可以磨练的机会\u003c/p>\u003cp>⑤使我能够培养自己的抗压的能力，抱着平常心态。\u003c/p>\u003cp>⑥使我积累工作经验，可以自己创业\u003c/p>\u003cp>【角色扮演】\u003c/p>\u003cp>请大家花五分钟讨论，并在我发给大家的表格上，记录下讨论结果。然后，我会邀请大家通过角色扮演对话的方式分享你们的讨论结果。好了，时间交给大家。\u003c/p>\u003cp>学习者案例记录：\u003c/p>\u003cp>学习者1：\u003c/p>\u003cp>小明：琼姐，我好难过呀，因为这一次我工作那么努力，但是仍然得不到晋升的机会，所以我感到很沮丧。\u003c/p>\u003cp>小明的朋友：你没有得到晋升，所以很沮丧。那你能不能换一种说法：你没有得到晋升，所以今后你要更加努力的工作。你没有晋身的原因，你有没有总结一下：\u003c/p>\u003cp>比如可能是自己的能力不足，或者是你工作的重点并不是领导想要的，或者是在基层有更多可以锻炼和磨练的机会，你以后可能遇到的打击会更大，刚好这次可以培养自己的抗压能力，还有啊，实在大不了可以积累了经验出来单干呀。\u003c/p>\u003cp>小明：您这样说我觉得好多了，是啊，我应该在工作中沉下心来更多的关注我的工作重点是不是符合领导的要求。\u003c/p>\u003cp>小明的朋友：你现在心情是不是好多了？\u003c/p>\u003cp>小明：是啊，现在心情好多了，我会继续努力工作。谢谢勍姐开导！\u003c/p>\u003cp>总结：我们都曾经历过陷入负面思维而无法自拔的时刻，这样的时刻就像是我们生活中的“绊脚石”不断牵绊着我们前进的脚步，而今天所拆的知识就如同积极心理疗法，能够帮助我们找到负面感受中的正面意义。请大家记住今天我们拆解的意义换框法的三个步骤，只要我们不断的应用和练习，相信大家很快就能够拥有将一个个“绊脚石”变为“踏脚石”的能力！\u003c/p>\u003cp>最后请大家用便签写下想对我说的话，谢谢大家今天的参与！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":true}}],"created_at":1499091380000,"updated_at":1499097208000,"ria":true},{"id":2462,"topic":"沟通方式决定沟通效果","learn_goal":"教你在人际交往中如何做到有效沟通","remark":"重塑心灵(升级版)NLP——每个人都拥有让自己成功快乐的能力》全面地介绍了NLP的历史、理论框架、基本概念等基础理论；共分为10章，每章都有其独立的主题。书中提供了少量NLP技巧，既安全又容易产生实效的技巧，以及更多与时代同步发展的新观点与新案例；同时本书的概念与技巧也可为所有人在面对人生时提供启迪。","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"简·单","city":"兰州"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"各位小伙伴，大家好！我是拆书家简单，非常高兴又和你们见面了。今天我将进行3-1晋级训练，感谢大家的参与。事件:小伙伴，你们有没有过这些体验:夫妻之间因意见不统一，争论过后不欢而散或进入冷战；父母亲对孩子的引导和要求，孩子不听。提问:当你你遇到这些情况你是如何应对？最后效果如何？影响：也许生气，也许抓狂，最终两者之间的关系僵化，或矛盾升级。解决：今天我分享的主题是良好的沟通效果取决于沟通方式，源自于李中莹的《重塑心灵》。在这本书中有许多nlp的理论，它是研究我们的大脑如何工作的学问，可以帮助我们改善工作或生活中的某些部分。","ratings_count":0,"texts":[{"id":5164,"quote":"\u003cp>沟通的效果决定于对方的回应。强调说得对不对没有意义，说得有好效果才重要。因为良好沟通效果是你的目标，所以绝对不能停下来，一味地强调自己说得对，而要不断地改变你的沟通方式，直至你所期望的回应出现。然后，你应继续这个沟通方式，保持良好的沟通效果。如果有一天所期望的回应消失了，你便需要不断地改变你的沟通方式，直到理想的回应重新出现。\u003cbr>\u003c/p>","explains":"\u003cp>与人之间沟通，就是一方表达自己的信息，另一方对这个信息做出回应，达成共识，最终获得良好的沟通效果。但是在传递的过程中，由于表达方式的不同，沟通效果会受到很大的影响。\u003c/p>\u003cp>案例一:孩子高兴地对妈妈说:妈妈，我的作业全都写完了，可以玩一会吧！妈妈严肃地说:你总惦记着玩，再去复习复习。孩子嘟嘟嘴不想再说什么了。\u003c/p>\u003cp>这个案例效果如何？得到期望的回应了吗？显然没有\u003c/p>\u003cp>案例二:过节夫妻回婆家，\u003c/p>\u003cp>丈夫对妻子说:时间差不多了，你麻利些。\u003c/p>\u003cp>妻子说:马上就好。时间又过了十分钟，\u003c/p>\u003cp>丈夫不耐烦的说:你就不能快点吗？每次出门都磨磨叽叽，我看你就是不想去我家。\u003c/p>\u003cp>妻子也不高兴地说:你怎么说话的，我这不是快好了嘛！。\u003c/p>\u003cp>又过片刻，\u003c/p>\u003cp>丈夫看到妻子慢慢腾腾的样子，气呼呼地说:还嫌我说的不对，我看你就是不想去，故意磨磨叽叽！算了算了，今天哪也不去了，你看看都几点了……\u003c/p>\u003cp>此案例沟通效果如何？显然无效\u003c/p>\u003cp>我们沟通的目标是对方做出我们期望的回应，可是，现实生活中没有达到期望的回应，怎么办？我们可以通过以下四步来达到有效沟通目的。\u003c/p>\u003cp>步骤一，明确期望对方的回应，态度真诚且尊重对方。\u003c/p>\u003cp>步骤二，身体放松，面带微笑，手心自然打开。\u003c/p>\u003cp>步骤三，说话时，语速缓慢，语气柔和。\u003c/p>\u003cp>步骤四，交流时，先重复对方话语里的关键词，再表达自己与对方不同的看法、观点。\u003c/p>\u003cp>案例:\u003cbr>\u003c/p>\u003cp>儿子:妈妈，我作业写完了，我想玩会。\u003c/p>\u003cp>妈妈微笑着轻声地对儿子说:哦！这么快就全部写完了，真棒!如果认真检查后全部正确，那就是高效率啊！\u003c/p>\u003cp>儿子:好！我现在就检查。\u003c/p>\u003cp>片刻\u003c/p>\u003cp>儿子:我检查完了，错了一道题\u003c/p>\u003cp>妈妈轻声细语:儿子，你非常认真，找出了错题，想想问题出自哪里呢？\u003c/p>\u003cp>儿子:我粗心了，没注意。\u003c/p>\u003cp>妈妈和气地说:儿子，这样的错误下次是不是要注意啊！\u003c/p>\u003cp>儿子:我记住了。\u003c/p>\u003cp>妈妈愉快的说:那去玩吧！\u003c/p>","interaction":"\u003cp>A2.请小伙伴自己编一个故事，有关有效沟通的应用情景，要求有人物对话 ，情景变化（起因，经过，结果）。五分钟后请讲剧本。\u003c/p>\u003cp>干事向领导请示工作。\u003c/p>\u003cp>干事:最近，基层单位配了许多书，我发现阅读量不大，原因是:一，成人不爱看书。二，没时间看书。三，记不住。针对这些问题，我最近接触的拆书帮就可以解决这些书闲置的问题。\u003c/p>\u003cp>领导:所以，我们的目标是促进员工多阅读，对吗？\u003c/p>\u003cp>干事:我们想办法帮助员工高高兴兴接受阅读，养成习惯，我想尝试引入“拆书帮”的阅读法，不知道，您的意见是？\u003c/p>\u003cp>领导:你想通过阅读提升员工素质，想法非常好，可是平时大家都太忙，你打算选择什么时间呢？\u003c/p>\u003cp>干事:拆书可以先做试点，选择一个有愿意的班组，平时没时间可以安排拆书家单独指导，不会占用太多时间的。\u003c/p>\u003cp>领导:嗯！分小组，以小组为单位，也好安排。最好让员工主动参与。\u003c/p>\u003cp>干事:是的，自己报名，不强迫\u003c/p>\u003cp>领导:这样，挺好！\u003c/p>\u003cp>通过这个情景，我们都能感受到，双方的表现都是以真诚的态度且尊重对方的。在轻松的状态下语速缓慢，语气柔和，最终获得了良好的沟通效果。\u003c/p>\u003cp>结束语:通过原文片段结合讲解，总结提炼出有效沟通的四个步骤，沟通无效时可以不断调整沟通方式，直到获得良好的沟通效果。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1492959496000,"updated_at":1492959496000,"ria":true},{"id":1641,"topic":"如何管理情绪","learn_goal":"如何管理情绪","remark":"","level":"TF3-3","duration":55,"status":0,"type":0,"chaishujia":{"username":"guoguo","city":"福州"},"club":{"name":"福州闽江分舵","city":"福州"},"prologue":"哈罗，大家好，我是郭艳霞，欢迎来到我的拆书现场，今天我要完成的是TF3-3。拆书的片段是一本应用类书籍，书名《NLP重塑心灵》，作者是李中莹，下面我用客户场景法介绍\r\n事件场景：在当今这社会，情绪能够影响人的一生，如何管理情绪成为当今的热门话题，情绪管理是一种能力，管理不好情绪的人一生必定过得艰辛，成功人士能够很好的管理情绪，他们不仅能够处理自己的情绪，还可以恰到好处的处理他人的情绪，能够帮助他人处理他们的情绪。\r\n提问：那么生活中当你面对各种各样情绪的时候你是怎么处理的？当你伤心、难过、愤怒时，你是选择忍、还是选择发泄，又或者选择逃避；当你面对他人的愤怒、悲伤、生气的时候，你是束手无策还是哑口无言呢？\r\n影响：纵观古今，有多少故事因主人公肆意放纵情绪而以悲剧告终，换目四顾，多少人生因情绪的困扰而黯淡无光，如果管理不好情绪，家庭、生活、学习、工作都受到不良的影响。 \r\n解决：通过今天的学习，不仅让你能够学习好如何管理自己的情绪，还将学习如何管理他人的情绪，让你成为情绪的主导者，使自己成为情绪的主人，掌控自己的人生。好，那就让我们进入学习阶段吧。","ratings_count":0,"texts":[{"id":4197,"quote":"\u003cp>情绪是本人的信念系统与外界的人事物共同作用的产物\u003c/p>\u003cp>世上所有的情绪可以被分为两类：“开心”与“不开心”。这种现象让我们更加明了人们过去很少注意自己的情绪感受，而且也更加清楚人们对自己内心究竟是怎么回事所知很少。\u003cbr> &nbsp;&nbsp; 引导人们更准确地体会和说出内心的情绪感受，我惯用的说法是：\u003cbr> &nbsp;&nbsp; ◇ “不开心的背后，是一些什么情绪？”\u003cbr> &nbsp;&nbsp; ◇ “不开心一般不会单独存在，与它在一起的是些什么情绪？\u003c/p>\u003cp>◇ “你还可以用什么其他文字去描述这份情绪？”\u003c/p>\u003cp>如果对方对情绪认识很少，这方面的词汇很贫乏，我常会加上一些建议让他选择（但从不假设或武断判定）：“不开心的背后，是愤怒还是恐惧？焦虑还是无力感？”\u003cbr> &nbsp;&nbsp;&nbsp; 了解了情绪的真正来源，我们就可以在情绪管理方面有所作为。\u003cbr> &nbsp;&nbsp;&nbsp; 通常因为人们对情绪所知甚少，对于一些所谓“负面”情绪觉得无能为力，经常感到被它们牵着鼻子走，所以最常与“情绪”二字用在一起的动词是“控制”：“我如何能够控制自己的情绪？”其实当需要用到“控制”二字时，情绪往往便已经是失控了。如果有人对你说“请控制一下你的狗”，肯定你的狗已经制造出了一些麻烦！更深入地想一想：“控制情绪”这几个字完全是治标性的说法：情绪出现便把它消除。这里没有考虑怎样做情绪才不会出现。若那些情绪根本不会出现，又有何“控制”的必要？\u003cbr> &nbsp;&nbsp;&nbsp; 现在，我们明白了情绪根本不是单纯地因为外界的人事物产生，而是本人的信念系统与外界的人事物共同作用的产物，我们便可重新建立对自己情绪的管治权。\u003c/p>\u003cp>处理本人情绪的方式，通常人们处理自己的情绪只有三种途径：\u003c/p>\u003cp>忍：隐藏在心里；\u003c/p>\u003cp>发：发泄出来；\u003c/p>\u003cp>逃：使自己忙碌不去想起有关的事情。\u003c/p>\u003cp>三种途径都没有效果。隐藏在心里造成本人的心情不稳定，形成很多心理症结，现在的科学研究已经证实这会引起严重的健康问题。发泄出来的方式包括发脾气（这影响了人际关系和别人对你的看法）、暴饮暴食或疯狂购物等行为，每次发泄过后还是觉得不成，经常要重复发泄，造成很大的后遗症。使自己忙碌不去想有关的事情，当时有点效果，但是每当夜深人静、独自一人时，那些引起困扰的事情和情绪便会“才下眉头，却上心头”，往往造成失眠问题。\u003c/p>","explains":"\u003cp>\u003cstrong>【与学习者互动】\u003c/strong>\u003c/p>\u003cp>你处理情绪的时候你是怎么样的呢？\u003c/p>\u003cp>学习者李女士：当我自己很愤怒的时候，我会大喊大叫，摔东西；\u003c/p>\u003cp>学习者黄先生：当我很伤心难过的时候，我会叫上朋友去喝酒；\u003c/p>\u003cp>学习者刘女士；我遇到很痛苦的时候，我选择投入到工作中，让你自己忙碌起来。\u003c/p>\u003cp>\u003cstrong>讲解：\u003c/strong>当你面对自己的情绪的时候，你是否也是像通常人们处理自己的情绪三种方式那样呢。\u003cbr>\u003c/p>\u003cp>第一种：\u003cstrong>忍\u003c/strong>，将所有的情绪隐藏在心里，自己内心受煎熬；\u003c/p>\u003cp>第二种：\u003cstrong>发\u003c/strong>，发泄出来，例如：发脾气、暴饮暴食、酗酒、k歌、疯狂购物等行为，利用行为麻痹自己。\u003c/p>\u003cp>第三种：\u003cstrong>逃\u003c/strong>，是自己忙碌起来不去想跟这有关的事情，然后当自己忙完以后，那些困扰自己的事情依旧存在，没有得到根本性的解决。当你有情绪的时候，你是否也是这样的方式呢来解决呢，其实无论其中的哪一种方式方法都是无效的，隐藏在心里造成心情的不稳定，容易形成心理症结，很多抑郁症患者就是这样；\u003c/p>\u003cp>以某种方式发泄出来呢，发泄出来是挺爽的，但是发泄过后还是不行，经常需要重复发泄，造成很大的后遗症，而逃避自己的情绪，不正视他的时候情绪依旧存在。\u003c/p>\u003cp>\u003cstrong>个人经历分享：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 其实对于我自身来说，我以前也是基本上用第一种和第三种途径企图控制自己的情绪，而其实当自己在用控制二字的时候，自己已经被情绪控制了。每当别人莫名其妙对自己发脾气的时候，我基本都是用隐忍的状态回应，其实当时自己的是很相当委屈的，可是我选择忍，导致自己很不开心，快乐不起来。\u003c/p>\u003cp>\u003cstrong>【加工自己的案例】\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;当我后来在面对自己有情绪的时候呢，我的处理方式是先让自己冷静下来，然后想想是什么事情引起我的负面情绪，并从负面情绪中找出其正面的价值，然后把这个当做动力，促使自己前进。\u003c/p>","interaction":"\u003cp>\u003cstrong>引导微行动学习：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 那么既然这三种方式都是无效的方式，那么现在请几个人一组，做个小组讨论，用怎么样的途径提升自己管理自己情绪的能力，大家需要明确的是，通过隐忍、发泄、逃避这些途径是没有办法消除情绪的，不是一种有效的方式，那么有哪些可能的方式方法或者思路，请大家思考，并将讨论出的可行的做法记录在白纸上，5分钟后，我请代表分享你们的讨论的成果。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>行动方案：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>第一种方案：\u003c/strong>\u003cstrong>改变，改变自己的观念、信念和价值观\u003c/strong>，其实情绪的真正来源是我们自己内心的一套信念系统，外来的事物只不过是诱因而已，内在的信念才是决定因素，情绪从来不是问题，有问题的是我们处理的方式。比如说如果你感到不适去看医生，医生说你的额头很烫，需要做手术切除，你肯定会觉得这个医生精神不正常，人人都知道额头很烫是身体有问题的病症，可能是感冒发烧了，可能是肠胃出问题了，但99.9%不会是额头本身的问题，症状让我们知道健康有问题，但他本身不是问题，情绪也是一样的，它只是症状而已，可是我们绝大部分的人都把情绪看作是问题的本身。所以这就需要我们改变自己的信念，观念和想法，正视情绪的来源，随时随地清楚的知道自己处于怎么样的情绪状态，把引起情绪的事情消除掉，情绪自然而然就消失了。\u003c/p>\u003cp>\u003cstrong>第二种方案：理解并接受情绪\u003c/strong>，接受自己内心的情绪，做最能配合情绪的事情，例如：疲惫时停下手中的工作，离开座位出去走走，放松放松；心情烦躁的时候避免做重要的决定；愤怒和有压力的时候去运动而不要谈判；担忧和伤感的时候把需要处理的事情减少到最少；\u003c/p>\u003cp>\u003cstrong>第三种方案：\u003c/strong>\u003cstrong>运用情绪情绪，\u003c/strong>几乎所有的负面情绪都有其正面的意义和价值，它不是给我们力量就是指引我们行动的方向，所以，凭着内心的情绪，我们可以做很多使得自己提升的事情。举例说明：\u003cstrong>愤怒\u003c/strong>：其实容易愤怒的人是内心力量不足的人，他们往往需要生活在愤怒里，以维持更大的力量去面对人生，世人最大的错误就是企图利用愤怒带来的力量去改变外面的人和事情，当然这肯定不会成功，反而会激发更大的愤怒。\u003cstrong>其正面意义在于：\u003c/strong>给我们力量去改变一个不能接受的情况。\u003c/p>\u003cp>\u003cstrong>【与学习者互动】\u003c/strong>\u003c/p>\u003cp>那么请大家思考下痛苦、紧张、焦虑、恐惧、失望、悲伤、惭愧、内疚、遗憾等这些负面情绪有哪些正面意义，思考后请学习者分享。\u003c/p>\u003cp>\u003cstrong>学习者刘女士--痛苦：\u003c/strong>\u003cbr>\u003c/p>\u003cp>痛苦可分为生理和心理的痛苦，但意义一样——\u003cstrong>指引我们去找寻一个摆脱的方向\u003c/strong>。把手放在火上感觉痛苦，手会缩开一点，若仍感到痛苦便会继续缩开，直到痛苦消失为止。心理治疗大师罗伯特·麦克唐纳（Robert McDonald）在教授处理感情关系问题的技巧时说：在有痛苦的两人关系中，感到痛苦的人就是该做出改变的人！\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>学习者黄先生--焦虑、紧张\u003c/strong>\u003cbr>\u003c/p>\u003cp>焦虑紧张是\u003cstrong>指引我们找寻解决的方向\u003c/strong>——事情很重要，需要额外的专注和照顾；往往也指出已拥有的资料和能力不足够，需添加一些能力。焦虑/紧张常常跟本人对自己的身份和本人与系统的关系不清晰或者误解有关。\u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者郭女士--恐惧\u003c/strong>\u003cbr>\u003cbr>恐惧的意思是，不愿付出以为需要付出的代价。恐惧指引我们去找出：\u003cstrong>认为需要付出的代价是什么，以及思考可以做些什么使自己无须付出这些代价\u003c/strong>。与困难一样，处理这种情绪的目的并不是使人一定去做某一件事，而是使他多了“可以做这件事”的选择。恐惧是维持动物生存下去的第一重要工具，人活着不能也不应完全没有恐惧。有勇气并不是没有恐惧。真正的勇气是：虽然有恐惧，还能继续走下去。\u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者李先生——失望\u003c/strong>\u003c/p>\u003cp>\u003cbr>失望其实可分为两种——对人事物的失望和对自己的失望。对人事物的失望必然来自想控制它们的企图：无法如愿便失望了。对自己的失望来自不接受自己，“接受自己法”这个技巧最好用。所以，失望也是指引方向的情绪。\u003cbr>\u003cbr>\u003cstrong>学习者林女士——悲伤\u003c/strong>\u003cbr>\u003cbr>悲伤的意义是，从失去里取得力量，使我们更珍惜自己仍然拥有的包括记忆。“珍惜”的意思是妥善运用。所以，悲伤既指引方向，亦给予力量。\u003cbr>\u003c/p>\u003cp>\u003cstrong>学习者苏先生——惭愧、内疚、遗憾\u003c/strong>\u003cbr>\u003cbr>\u003c/p>\u003cp>它们的意思是，以为已经完结的事里尚有未完结的部分。这些情绪是指引方向的，若明白了它们的意思，它们能转化成为力量去推动拥有者把未完结的部分完成。关于这点，家庭系统排列的学问里有关付出与收取的平衡概念很有帮助。\u003c/p>\u003cp>非常感谢大家的分享，大家都能够将以上所有情绪找到其正面意义，其实只要找到了负面情绪的正面价值，将正面意义为我所用，就可以能够很好的处理还自己的情绪了。\u003c/p>\u003cp>\u003cstrong>激发应用：\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp; 学习如何处理好自己的情绪，那么请你根据之前已存在的情绪，之前你是如何处理的，通过今天的分享你又将如何做，思考几分钟和我们分享。\u003c/p>\u003cp>\u003cstrong>学习者分享经历\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp; 以前面对愤怒的时候，我总是对人大吼大叫，任性的发脾气，摔东西等这类的方式来处理。经过今天的学习，认识到，其实自己的愤怒的原因是因为自己内心力量不足，企图通过表达愤怒让自己维持更大的力量去控制别人。其实当自己内心愤怒的时候首先让自己学会冷静一下，改变自己的内心的想法，然后找出让自己愤怒事情的源头，其实就是自己对世界的看法，真正认识到愤怒这个负面情绪的正面价值，改变自己，突破自我。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;感谢学习者的分享，在面对自己愤怒的时候，让自己冷静下来，然后找到负面情绪的正面意义，为我所用，非常棒，谢谢。\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":4198,"quote":"\u003cp>有效的方式是EQ型的方式，让我们先来看看“EQ”（情绪智能）是什么\u003c/p>\u003cp>情绪智能”来自英文的Emotional Intelligence。这个名词是因1995年美国人丹尼尔·戈尔曼（Daniel Goleman）所写的书《Emotional Intelligence》而受人注意的。这本书主要的意思是指出一个人的成功，IQ（智力）只占小部分（20%），而EQ占80%。该书说EQ包含五个意思：\u003cbr> &nbsp;&nbsp; ◇ 认识自己的情绪\u003cbr> &nbsp;&nbsp; ◇ 管理自己的情绪\u003cbr> &nbsp;&nbsp; ◇ 有效推动自己\u003cbr> &nbsp;&nbsp; ◇ 认识别人的情绪\u003cbr> &nbsp;&nbsp; ◇ 处理好人际关系\u003cbr> &nbsp;&nbsp; 我认为只用两点便能充分解释EQ的意思：\u003cbr> &nbsp;&nbsp; ◇ 清楚认识和正确运用情绪去帮助自己\u003cbr> &nbsp;&nbsp; ◇ 了解和分享别人的看法和感受\u003cbr> &nbsp;&nbsp; 整个世界都忽略了一项对人类的成长及延续十分重要的工作：培养健康的心理。这需要在孩子的年龄还是很小的时候就开始做，最好成年之前便充分完成。而教导孩子认识和正确地对待情绪是最基本的部分。这是说，当孩子还是婴儿的时候，就应该开展情绪智能的教育工作了。\u003cbr> &nbsp;&nbsp; 正确处理他人情绪的方法共有四个步骤：接受、分享、肯定和策划\u003c/p>\u003cp>1．接受——接受是注意到受导者者有情绪、接受有这份情绪的他并如实告诉他。例如：“你看来有点情绪，愿意与我谈谈吗？”或者：“我看到你有点怒气，什么事使你生气呀？”\u003cbr> &nbsp;&nbsp; 2．分享——永远先分享情绪感受，后分享事情的内容。就算受导者反复或坚持先说事情内容，你也需要巧妙地把话题先带到情绪感受的分享。情绪感受未曾处理，谈事情细节不会有效果，往往只会使对方的情绪更大。\u003cbr> &nbsp;&nbsp; 先分享情绪，应该做的是帮助受导者去捕捉内心的情绪。一般人们对情绪认识不多，他们不懂得用足够和适当的文字描述情绪，因此正确表达内心的感受时会有困难。可以提供一些相关的词汇帮助受导者把内心的情绪感觉转换成一些可以被下定义、有界限的情绪类别。例如：“我敢说，那使你觉得尴尬，对吗？”或者：“你感到被人拖累了，是吗？”\u003cbr> 如果受导者总是想说出事情的内容、始末、谁人对错等，可以用语言把他带回到正确的方向（即先处理情绪），例如：“原来是这些使你这样不开心。来，先告诉我你现在内心的感觉怎样。”或者：“哦，怪不得你\u003c/p>\u003cp>这样反应啦！现在你心里觉得怎样？”\u003c/p>\u003cp>3．肯定——应该对不适当的行为设立规范，就是说，勾画出一个明确的框架，里面是可以理解或接受的部分，并就这些可以接受的部分给受导者以肯定。框架外面则是不能接受或者没有效果的东西，应当明确指出并质疑。给予肯定之后，会更容易引导受导者注意到和愿意针对不能接受或者没有效果的东西而有所改变。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp;4．策划——有负面情绪的人现在会想：“我有这样的情绪原来不是错误，但是应该怎样去处理问题呢？”要帮助他解决问题就要询问他想得到些什么，然后与他一起讨论解决问题的一些方法。引导他去发展自己的想法，帮助他做出最好的选择，鼓励他自己解决问题。你可以引导他说：“凡事都有至少三个解决办法嘛，让我们一起想想，如果重新来过，怎样做可能会更有效果？”或者：“下次同样情况出现，怎样才是更好的做法，使效果更理想？”或者：“避免同样的不如意的情况出现，你可以采取哪些预防措施？”\u003c/p>","explains":"\u003cp>自测题\u003c/p>\u003cp>一下有6个题目，请按照1-5分的标准为自己打分，1&nbsp;表示完全不符合，5表示非常符合，请仔细阅读下面表格中的每句话，根据自己的实际情况打分。\u003c/p>\u003cp>当他人表达情绪（悲伤、愤怒、难过）的时候\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>总是束手无策\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>让他自己静静,\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>带他去玩、去疯，让他忘记\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>不闻不问、拒绝沟通\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>斥责、打骂\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>理解并有效帮助他\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>让他摆脱情绪\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>解释自测题：测试题不同于考试题，没有标准答案，考试是以知识为中心的，测试是以学习者为中心的，测试完成后，学习者可以更好的了解自己的情况，而且在做测试题的过程，大家通过不断的回想自己相关的经历和以往的表现，这个过程让大家回忆，也是一个激活经验的方式和方法。通过上诉测试题，你生活中在他人表达情绪的时候是否也像测试题中所提到的那样呢，如果是，那么今天的分享相信对你来说会有所帮助。当你面对他人的悲伤、愤怒、难过的时候你是不是也是像上述的方式那样呢，如果是，那么我们就很有必要学习今天的内容。\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>讲解：\u003c/strong>通过片段的阅读，我们知道了正确处理他人情绪的方法，然而现实生活中多种总是存在着这种或那种无效果的沟通，下面我先介绍下以下四种类型，然后让大家更深入的更的理解片段交给我们的正确处理他人情绪的方法。\u003cbr>\u003c/p>\u003cp>\u003cstrong>第一种\u003c/strong>无效的类型是有时候我们会给予一些对方在乎的价值去驱使对方的情绪暂时消失，这类型叫\u003cstrong>交换型\u003c/strong>比如为了让小孩停止哭泣妈妈给糖吃，带朋友去唱歌喝酒以驱走悲伤情绪，等等，这些其实都是暂时性的，我们没有对引起情绪的事情做什么事情，而是用另外一件事驱走情绪，然后等到那些价值消失后，同样的情绪再次出现；\u003c/p>\u003cp>\u003cstrong>第二种\u003c/strong>\u003cstrong>—\u003c/strong>\u003cstrong>惩罚型，\u003c/strong>人们会把情绪看作是恶毒的东西，是不应该出现的，因此对方应该受到惩罚，比如面对小孩哭泣，很多人会用恐吓的方式说如果再哭就要打他，面对成人，当对方有情绪的时候，我们会拒绝沟通、不闻不问、冷言冷语，有时候更是斥责对方，其实用这样方式，只会让我们孤立对方，并不能舒缓他的情绪，而只会让他产生更加更多的情绪。\u003c/p>\u003cp>\u003cstrong>第三种\u003c/strong>\u003cstrong>-\u003c/strong>\u003cstrong>冷漠型\u003c/strong>，这个主要是对成年人的，他们认为成年人应该有能力处理自己的情绪，或者不应该把这样的情绪显露处理，同时呢又认为情绪是每个人自己的事情，应该自己处理。这类型的行为模式是完全漠视对方的情绪，对对方的情绪视而不见，或示意对方应该自己处理好情绪。\u003c/p>\u003cp>\u003cstrong>第四种\u003c/strong>\u003cstrong>-\u003c/strong>\u003cstrong>说教型，\u003c/strong>说教型，顾名思义，就是对对方说大量的道理，而不顾对方的感受，这样很非常容易让对方陷入更大的情绪困扰中。\u003c/p>\u003cp>那么让我们来看下片段中提到正确处理他人情绪的四个步骤：\u003cstrong>接受、分享、肯定、策划\u003c/strong>，就八个字。\u003c/p>\u003cp>第一、\u003cstrong>接受，\u003c/strong>接受是注意到此人有情绪，接受这份情绪，并且如实的告诉他，注意接受\u003cstrong>不是批判\u003c/strong>—你怎么可以又发怒呢？\u003cstrong>不是否定\u003c/strong>—你不应该在这里发怒，\u003cstrong>不是表示不耐烦—\u003c/strong>哎，你又发脾气啦，\u003cstrong>不是忽视—\u003c/strong>好像完全没有事一样平常闲谈，而是无条件的接受—你这个样子我是接受的，我很愿意和你沟通的意思。\u003c/p>\u003cp>第二、\u003cstrong>分享\u003c/strong>，永远先分享情绪感受，后分享事情的内容，帮助情绪者捕捉内心的情绪，帮助情绪者描述他的情绪。一般情绪者总是会想说出事情的内容、始末，谁对谁错。比如她怎么可以这样，都是他的错…..\u003c/p>\u003cp>这个时候你就可以说：哦，原来是这些让你不开心，那么你现在感觉心里感觉是怎么样的？一定先引导情绪者说出内心的感受，帮助情绪者找到一些能够表达情绪的词汇。其实如果当他们充分表达出情绪后，你会惊奇的发现，他们的面部表情、身体语言、说话的速度、音调、音量及语气都已经有了舒缓的迹象。\u003c/p>\u003cp>记住，先分享情绪，后分享事情，这样能够使得情绪者心情已经平静一些了，这样就好做进一步的引导了。\u003c/p>\u003cp>第三、\u003cstrong>肯定\u003c/strong>，应该对不恰当的行为作出规范，给出一个明确的界限，里面是可以理解或者接受的部分，并对这些可接受的部分表示自己的肯定，对不恰当或者没效果的东西，应当明确指出并质疑。因为表示肯定，使得情绪者感觉到他们是被尊重和理解的，保留了他们的尊严和自信，他们会更加愿意听从你的引导，而且更加关键的是让情绪者明白他的情绪感觉不是问题所在，而不良的言行才是问题的关键，所有的感觉及所有的期望都是可以被接受的，但并非所有的行为都能被接受。\u003c/p>\u003cp>\u003cstrong>【对比概念】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>“\u003cstrong>肯定\u003c/strong>”不等于“完全接受”\u003c/strong>\u003c/p>\u003cp>\u003cstrong>&nbsp; \u003c/strong>记住肯定是对于不恰当的行为中可以理解或者接受的部分给与肯定，绝对不是完全接受。\u003c/p>\u003cp>举个例子：孩子之间争抢玩具，小强要夺走小明的玩偶，小明一开始说：我的玩具，我玩一会再给你好不好！小强依旧继续抢夺，结果小明打了小强，小强也打了小明，他们之间就开始互打了。这个时候，小明和小强商量这样的行为是值得肯定的，但是打人却是不对，对于小明好的行为给予肯定，打人行为应该及时指出，这样的行为是不对的。所以\u003cstrong>“\u003cstrong>肯定\u003c/strong>”不等于“完全接受”。\u003c/strong>\u003c/p>\u003cp>第四、\u003cstrong>策划\u003c/strong>，这个就是引导他去发展自己的想法，帮助他做出最好的选择，鼓励他自己解决问题。你可以说：“凡事都有至少三个解决办法嘛，让我们一起想想，如果重新来过，怎样做可能会更有效果？”或者：“下次同样情况出现，怎样才是更好的做法，使效果更理想？”或者：“避免同样的不如意的情况出现，你可以采取哪些预防措施？”\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>案例分享：\u003c/strong>\u003c/p>\u003cp>有一次，我的小侄女不小心摔倒了大哭，然后很生气的把所有玩具都摔地板上，一直哭闹。当你遇到这种情况的时候，你会怎么做呢？\u003c/p>\u003cp>当时我走到她面前，蹲了下来，给她一个拥抱，和她说:宝贝，摔倒了是不是很难过呀，我知道你现在很难受，给你一个爱的抱抱，然后等她情绪平稳之后不哭后，我和她说：宝宝刚才摔倒了，是什么原因啊，以后自己走路要小心一点，宝宝刚才摔了很多玩具是不对的，不是因为玩具宝宝摔倒的，是宝宝自己不小心滑倒，所以不可以摔玩具，玩具摔了它们也很疼的，所以宝宝下一次走路要小心一点，慢慢走，不要快跑，好不好。\u003c/p>","interaction":"\u003cp>\u003cstrong>促动参与：\u003c/strong>\u003c/p>\u003cp>听了这个故事，是不是觉得在现实生活中也经常发生类似的事情呢？那么面对他人的情绪你是怎么样处理？通过今天分享的关于如何处理他人情绪的四步骤以后在面对这样的问题时候你又会怎么处理呢？请学习者和我们分享下。\u003c/p>\u003cp>\u003cstrong>学习者分享案例\u003c/strong>\u003c/p>\u003cp>同事怒气冲冲跑来向我抱怨，说李同事每次都是不经过她的同意就把文件资料拿走，或者在她的桌子上乱翻东西，她表示很生气并且愤怒，而自己又没有向她说明这是重要文件不能随便乱翻阅。之前我的做法总是安慰她下，没有实质上的东西，有时候还会表现出很不耐烦，通过今天学习了化解他人情绪的四步骤，我会这么做：首先接受她的情绪，对她的情绪感动深受，表示理解，然后对她的这个事情进行一个分析，鼓励她自己寻找解决的方案，让她主动友好幽默的形式提醒李同事，不能这样做，如果要翻阅、借阅需经过她的同意。\u003c/p>\u003cp>\u003cstrong>小组讨论：\u003c/strong>\u003c/p>\u003cp>请大家小组内编一个小故事，设计出有人物、有情节、有场景，有双方对话，在解决问题的过程中，包括了使用今天拆书片段用4步骤来处理他人的情绪，时间五分钟，五分钟以后，我们请一两位小组代表和大家分享一下剧本。\u003c/p>\u003cp>\u003cstrong>学习者分享剧本并角色扮演\u003c/strong>\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>剧本\u003c/strong>：一对小情侣李先生和黄女士因为做家务的原因发生争吵，李先生和黄女士相互约定好，一个做饭一个人洗完，那天李先生做饭后而黄女士却因为看自己很喜欢的连续剧而忘记洗碗，李先生看了很生气，两个人因为一点小事而展开激烈的争吵，黄女士觉得很愤怒，摔门而出，给闺蜜打电话哭诉。\u003c/p>\u003cp>黄女士：他是不是有病啊，不就因为一个碗没洗至于发那么大的火气吗？我就看了一会电视剧，他就在那里大发牢骚，真是气死我，这样下去分手算了\u003c/p>\u003cp>闺蜜：黄呀，你现在很伤心、很难过甚至有点愤怒对吧，你觉得你男朋友就你没洗碗这件事和你吵架是不对的，是这样吗？\u003c/p>\u003cp>黄女士：是呀，他真是不可理喻\u003c/p>\u003cp>闺蜜：我很能够理解你现在的心情，你觉得他没有必要为了这点小事而和你吵架，但是你摔门就是你的不对了，我想Mr李是因为他觉得应该先把碗洗了在去看电视剧，遵守你们之间的约定，他看到你没有洗碗觉得是你们之间的约定没有兑现，所以他生气，其实他很在意你们的约定，所以他内心是很在意你的。你觉得我说的有道理吗？\u003c/p>\u003cp>黄女士：好像是哦\u003c/p>\u003cp>闺蜜：那么你现在该怎么做比较好呢？\u003c/p>\u003cp>黄女士：我回去向他道歉，和他说明情况，讲和。\u003c/p>\u003cp>\u003cstrong>布置任务：\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>请在下周，挑选一个身边已经发生的冲突，运用事后复盘的方式来帮助他化解情绪，试着用今天的四个步骤帮助他人。然后在我们的微信群上发出来，大家一起讨论一起分享。\u003cstrong>&nbsp;\u003c/strong>\u003c/p>\u003cp>\u003cstrong>结语：\u003c/strong>通过今天的分享，相信今后不管你是处理自己的情绪还是处理别人的情绪，只要我们认识到位、方法对路，每个人都会成为情绪管理高手，让我们好好修炼吧。感恩大家的陪伴。\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1482154187000,"updated_at":1482154187000,"ria":true},{"id":1640,"topic":"如何正确处理他人情绪的方式","learn_goal":"学习如何正确处理他人情绪的方式","remark":"","level":"TF3-2","duration":30,"status":0,"type":0,"chaishujia":{"username":"guoguo","city":"福州"},"club":{"name":"福州闽江分舵","city":"福州"},"prologue":"哈罗，大家好，我是郭艳霞，欢迎来到我的拆书现场，今天我要完成的是TF3-2。拆书的片段是一本应用类书籍，书名《NLP重塑心灵》，作者是李中莹，下面我用一种新的方法—客户场景法来介绍下本书\r\n事件场景：在当今这社会，情绪能够影响人的一生，如何管理情绪成为当今的热门话题，情绪管理是一种能力，管理不好情绪的人一生必定过得艰辛，成功人士能够很好的管理情绪，他们不仅能够处理自己的情绪，还可以恰到好处的处理他人的情绪，能够帮助他人处理他们的情绪\r\n提问：那么生活中当你面对各种各样情绪的时候你是怎么处理的？当你面对他人的愤怒、悲伤、生气的时候，你是束手无策还是哑口无言呢？\r\n影响：如果我们处理不好他人的情绪，人际关系会变得紧张，如果处理不好他人的情绪，就当不好领导，如果处理不了他人的情绪，成就不了大事。\r\n解决：通过今天的介绍能帮正确处理他人的情绪，当面对他人愤怒、悲伤、焦虑的时候你再不会素手无策，让你变成沟通的达人。","ratings_count":0,"texts":[{"id":4195,"quote":"\u003cp>有效的方式是EQ型的方式，让我们先来看看“EQ”（情绪智能）是什么\u003c/p>\u003cp>情绪智能”来自英文的Emotional Intelligence。这个名词是因1995年美国人丹尼尔·戈尔曼（Daniel Goleman）所写的书《Emotional Intelligence》而受人注意的。这本书主要的意思是指出一个人的成功，IQ（智力）只占小部分（20%），而EQ占80%。该书说EQ包含五个意思：\u003cbr> &nbsp;&nbsp; ◇ 认识自己的情绪\u003cbr> &nbsp;&nbsp; ◇ 管理自己的情绪\u003cbr> &nbsp;&nbsp; ◇ 有效推动自己\u003cbr> &nbsp;&nbsp; ◇ 认识别人的情绪\u003cbr> &nbsp;&nbsp; ◇ 处理好人际关系\u003cbr> &nbsp;&nbsp; 我认为只用两点便能充分解释EQ的意思：\u003cbr> &nbsp;&nbsp; ◇ 清楚认识和正确运用情绪去帮助自己\u003cbr> &nbsp;&nbsp; ◇ 了解和分享别人的看法和感受\u003cbr> &nbsp;&nbsp; 整个世界都忽略了一项对人类的成长及延续十分重要的工作：培养健康的心理。这需要在孩子的年龄还是很小的时候就开始做，最好成年之前便充分完成。而教导孩子认识和正确地对待情绪是最基本的部分。这是说，当孩子还是婴儿的时候，就应该开展情绪智能的教育工作了。\u003cbr> &nbsp;&nbsp; 正确处理他人情绪的方法共有四个步骤：接受、分享、肯定和策划\u003c/p>\u003cp>1．接受——接受是注意到受导者者有情绪、接受有这份情绪的他并如实告诉他。例如：“你看来有点情绪，愿意与我谈谈吗？”或者：“我看到你有点怒气，什么事使你生气呀？”\u003cbr> &nbsp;&nbsp; 2．分享——永远先分享情绪感受，后分享事情的内容。就算受导者反复或坚持先说事情内容，你也需要巧妙地把话题先带到情绪感受的分享。情绪感受未曾处理，谈事情细节不会有效果，往往只会使对方的情绪更大。\u003cbr> &nbsp;&nbsp; 先分享情绪，应该做的是帮助受导者去捕捉内心的情绪。一般人们对情绪认识不多，他们不懂得用足够和适当的文字描述情绪，因此正确表达内心的感受时会有困难。可以提供一些相关的词汇帮助受导者把内心的情绪感觉转换成一些可以被下定义、有界限的情绪类别。例如：“我敢说，那使你觉得尴尬，对吗？”或者：“你感到被人拖累了，是吗？”\u003cbr> 如果受导者总是想说出事情的内容、始末、谁人对错等，可以用语言把他带回到正确的方向（即先处理情绪），例如：“原来是这些使你这样不开心。来，先告诉我你现在内心的感觉怎样。”或者：“哦，怪不得你\u003c/p>\u003cp>这样反应啦！现在你心里觉得怎样？”\u003c/p>\u003cp>3．肯定——应该对不适当的行为设立规范，就是说，勾画出一个明确的框架，里面是可以理解或接受的部分，并就这些可以接受的部分给受导者以肯定。框架外面则是不能接受或者没有效果的东西，应当明确指出并质疑。给予肯定之后，会更容易引导受导者注意到和愿意针对不能接受或者没有效果的东西而有所改变。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 4．策划——有负面情绪的人现在会想：“我有这样的情绪原来不是错误，但是应该怎样去处理问题呢？”要帮助他解决问题就要询问他想得到些什么，然后与他一起讨论解决问题的一些方法。引导他去发展自己的想法，帮助他做出最好的选择，鼓励他自己解决问题。你可以引导他说：“凡事都有至少三个解决办法嘛，让我们一起想想，如果重新来过，怎样做可能会更有效果？”或者：“下次同样情况出现，怎样才是更好的做法，使效果更理想？”或者：“避免同样的不如意的情况出现，你可以采取哪些预防措施？”\u003c/p>","explains":"\u003cp>自测题\u003c/p>\u003cp>一下有6个题目，请按照1-5分的标准为自己打分，1 表示完全不符合，5表示非常符合，请仔细阅读下面表格中的每句话，根据自己的实际情况打分。\u003c/p>\u003cp>当他人表达情绪（悲伤、愤怒、难过...）的时候\u003c/p>\u003ctable>\u003ctbody>\u003ctr>\u003ctd>\u003cp>总是束手无策\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>让他自己静静,\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>带他去玩、去疯，让他忘记这个不好情绪\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>不闻不问、拒绝沟通\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>斥责、打骂\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>理解并有效帮助他\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003ctr>\u003ctd>\u003cp>让他摆脱情绪\u003c/p>\u003c/td>\u003ctd>\u003cp>1\u003c/p>\u003c/td>\u003ctd>\u003cp>2\u003c/p>\u003c/td>\u003ctd>\u003cp>3\u003c/p>\u003c/td>\u003ctd>\u003cp>4\u003c/p>\u003c/td>\u003ctd>\u003cp>5\u003c/p>\u003c/td>\u003c/tr>\u003c/tbody>\u003c/table>\u003cp>解释自测题：测试题不同于考试题，没有标准答案，考试是以知识为中心的，测试是以学习者为中心的，测试完成后，学习者可以更好的了解自己的情况，而且在做测试题的过程，大家通过不断的回想自己相关的经历和以往的表现，这个过程让大家回忆，也是一个激活经验的方式和方法。通过上诉测试题，你生活中在他人表达情绪的时候是否也像测试题中所提到的那样呢，如果是，那么今天的分享相信对你来说会有所帮助。\u003c/p>\u003cp>\u003cstrong>【与学习者互动】\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp;首先问大家一个问题，当你的家人、朋友、同事他们出现情绪（愤怒、悲伤、难过）的时候你们是怎么处理的\u003c/p>\u003cp>\u003cstrong>\u003c/strong>\u003c/p>\u003cp>学习者A：一般我儿子哭闹的时候，我就拿着饼干或者其他吃的东西给他，让他停止哭泣。\u003cbr>\u003c/p>\u003cp>学习者B：面对我老婆发脾气的时候，我对她总是不闻不问，用冷处理的态度让她自己消化，可有时候我老婆就更加生气，觉得我不够关心，不在乎她。\u003c/p>\u003cp>学习者C：当我朋友他们不开心的时候，我们就去ktv唱歌喝酒，去发泄。\u003c/p>\u003cp>\u003cstrong>&nbsp;\u003cbr>\u003c/strong>&nbsp; &nbsp; 很感谢大家的分享，正如大家所说的那样，我们总是用这样或那样的方式消除情绪，但是感觉没有什么用对不对，现实生活中多种总是存在着这种或那种无效果的沟通，下面我先介绍下以下四种类型，然后让大家更深入的更的理解片段交给我们的正确处理他人情绪的方法。\u003c/p>\u003cp>\u003cstrong>&nbsp; &nbsp;第一种\u003c/strong>无效的类型是有时候我们会给予一些对方在乎的价值去驱使对方的情绪暂时消失，这类型叫\u003cstrong>交换型\u003c/strong>比如为了让小孩停止哭泣妈妈给糖吃，带朋友去唱歌喝酒以驱走悲伤情绪，等等，这些其实都是暂时性的，我们没有对引起情绪的事情做什么事情，而是用另外一件事驱走情绪，然后等到那些价值消失后，同样的情绪再次出现；\u003c/p>\u003cp>\u003cstrong>&nbsp; 第二种\u003c/strong>\u003cstrong>—\u003c/strong>\u003cstrong>惩罚型，\u003c/strong>人们会把情绪看作是恶毒的东西，是不应该出现的，因此对方应该受到惩罚，比如面对小孩哭泣，很多人会用恐吓的方式说如果再哭就要打他，面对成人，当对方有情绪的时候，我们会拒绝沟通、不闻不问、冷言冷语，有时候更是斥责对方，其实用这样方式，只会让我们孤立对方，并不能舒缓他的情绪，而只会让他产生更加更多的情绪。\u003c/p>\u003cp>\u003cstrong>&nbsp; 第三种\u003c/strong>\u003cstrong>-\u003c/strong>\u003cstrong>冷漠型\u003c/strong>，这个主要是对成年人的，他们认为成年人应该有能力处理自己的情绪，或者不应该把这样的情绪显露处理，同时呢又认为情绪是每个人自己的事情，应该自己处理。这类型的行为模式是完全漠视对方的情绪，对对方的情绪视而不见，或示意对方应该自己处理好情绪。\u003c/p>\u003cp>\u003cstrong>&nbsp; 第四种\u003c/strong>\u003cstrong>-\u003c/strong>\u003cstrong>说教型，\u003c/strong>说教型，顾名思义，就是对对方说大量的道理，而不顾对方的感受，这样很非常容易让对方陷入更大的情绪困扰中。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;那么让我们来看下片段中提到正确处理他人情绪的四个步骤：\u003cstrong>接受、分享、肯定、策划\u003c/strong>，就八个字。\u003c/p>\u003cp>&nbsp; &nbsp;第一、\u003cstrong>接受，\u003c/strong>接受是注意到此人有情绪，接受这份情绪，并且如实的告诉他，注意接受\u003cstrong>不是批判\u003c/strong>—你怎么可以又发怒呢？\u003cstrong>不是否定\u003c/strong>—你不应该在这里发怒，\u003cstrong>不是表示不耐烦—\u003c/strong>哎，你又发脾气啦，\u003cstrong>不是忽视—\u003c/strong>好像完全没有事一样平常闲谈，而是无条件的接受—你这个样子我是接受的，我很愿意和你沟通的意思。\u003c/p>\u003cp>&nbsp; &nbsp;第二、\u003cstrong>分享\u003c/strong>，永远先分享情绪感受，后分享事情的内容，帮助情绪者捕捉内心的情绪，帮助情绪者描述他的情绪。一般情绪者总是会想说出事情的内容、始末，谁对谁错。比如她怎么可以这样，都是他的错…..\u003c/p>\u003cp>这个时候你就可以说：哦，原来是这些让你不开心，那么你现在感觉心里感觉是怎么样的？一定先引导情绪者说出内心的感受，帮助情绪者找到一些能够表达情绪的词汇。其实如果当他们充分表达出情绪后，你会惊奇的发现，他们的面部表情、身体语言、说话的速度、音调、音量及语气都已经有了舒缓的迹象。\u003c/p>\u003cp>记住，先分享情绪，后分享事情，这样能够使得情绪者心情已经平静一些了，这样就好做进一步的引导了。\u003c/p>\u003cp>&nbsp; &nbsp;第三、\u003cstrong>肯定\u003c/strong>，应该对不恰当的行为作出规范，给出一个明确的界限，里面是可以理解或者接受的部分，并对这些可接受的部分表示自己的肯定，对不恰当或者没效果的东西，应当明确指出并质疑。因为表示肯定，使得情绪者感觉到他们是被尊重和理解的，保留了他们的尊严和自信，他们会更加愿意听从你的引导，而且更加关键的是让情绪者明白他的情绪感觉不是问题所在，而不良的言行才是问题的关键，所有的感觉及所有的期望都是可以被接受的，但并非所有的行为都能被接受。\u003c/p>\u003cp>&nbsp; &nbsp;第四、\u003cstrong>策划\u003c/strong>，这个就是引导他去发展自己的想法，帮助他做出最好的选择，鼓励他自己解决问题。你可以说：“凡事都有至少三个解决办法嘛，让我们一起想想，如果重新来过，怎样做可能会更有效果？”或者：“下次同样情况出现，怎样才是更好的做法，使效果更理想？”或者：“避免同样的不如意的情况出现，你可以采取哪些预防措施？”\u003c/p>\u003cp>\u003cstrong>（案例分享）\u003c/strong>\u003c/p>\u003cp>孩子之间争抢玩具，小强要夺走小明的，小明一开始说：我的玩具，我玩一会再给你好不好！小强依旧继续抢夺，结果小明打了小强，小强也打了小明，他们之间就开始互打了，小明哭了。这时候小明的妈妈走了过来，如果你是小明妈妈你会怎么做呢？\u003c/p>\u003cp>如果我是小明的妈妈，我会这样做：首先接受和分享他现在的情绪，他哭表示他很伤心，我会说：你哭了，是不是现在很伤心啊，对小明好的地方做出肯定，“你和小强说这个是我的玩具，我玩一会再给你，你这是在和小强商量对不对，我觉得这样做的很好，但是我又会说：打人是不对的，不管是谁先动的手，打人这样的行为就是不可以的，然后等他情绪慢慢稳定下来后，引导他“既然打人不不对的，那么接来下你该怎么做呢”\u003c/p>","interaction":"\u003cstrong>【小组讨论】\u003cbr>【案例背景】\u003cbr>\u003c/strong>在部门的会议室，领导日常会议完后，公布了在候选为主管Lily和Lucy两名成员中，Lily当选，其他与会成员都恭喜和祝福了Lily，而只有Lucy表示很气愤，并且拐弯抹角、指桑骂槐的指责Lily，领导也在现场，场面很尴尬，事后Lucy还向你抱怨Lily的种种不是，听到后你会怎么处理？请大家分成3组，五分钟时间讨论，然后请一组学习者将你们讨论的结果进行分享。\u003cstrong>\u003cbr>【案例解决方案】\u003c/strong>\u003cbr>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>学习者运用四步骤分享：\u003c/p>\u003cp>&nbsp; 学习者： Lucy，对于Lily比你先升职，你感到失落、悲伤，甚至有点妒忌我觉得是很正常的，我也完全可以理解，毕竟你也经过这么长时间的努力，大家对于你的努力也是有目共睹的，但是你在会上用那样的语气，我觉得有点不妥呢，因为大家都恭喜了她，我们是不是应该对她的升职感到高兴，然后找出自己的不足之处，好让我们以后的职业走的更快更远。\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;Lucy：是的，我刚刚的话确实有点过分了，表达方式错了。\u003c/p>\u003cp>&nbsp; &nbsp;学习者：那么既然是这样，你觉得你现在应该怎么样做更合适呢？\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【提问设计+布置作业】\u003c/strong>\u003c/p>\u003cp>今天学习了处理他人情绪的四步骤，大家记得在生活中应用起来，为了让大家更好的理解，我布置一个作业，大家回去好好想想，要是你是场景中的主人公，你该怎么做？\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>\u003cstrong>【案例场景】\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;&nbsp;产品负责人Mr&nbsp;李，做事有自己的计划和风格，属于不紧不慢全面思考型的，营销负责人MS林是个典型的急躁型人员，做事风风火火，他们两要一起做一个项目，一次会上，两个各自带着团队开会，MS林一如既往、自顾自的提出自己各种建议，有时候甚至带着命令的口吻，弄得整个会议被MS林主导，这时候MS林又开始说了：Mr&nbsp;李你下周争取给我一个产品设计图稿。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;这个时候Mr&nbsp;李拍案而起，嚷嚷道：两个团队你全带吧，产品你也设计和推进，都自己干吧，简直太多分了，然后摔门而去。如果你是MS林你这个时候会怎么做？\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;期待学习者在下周二之前把这个场景的思考答案发到我们的微信群里，我们相互讨论，相互学习，共同成长。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;\u003cbr>\u003c/p>\u003cp>结尾：感恩大家的到来，今天的分享到此结束，希望大家在处理他人情绪的时候能够有所收获，能够将今天分享的知识应用到实际，成为情绪管理达人。\u003c/p>\u003cp>\u003cstrong>回访：\u003c/strong>\u003c/p>\u003cp>&nbsp; &nbsp;\u003cstrong>【学习者周一在微信群的分享】\u003c/strong>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003c/p>\u003cp>&nbsp;&nbsp;&nbsp;Ms林找到Mr李，对他说：Mr李，我能感受到你现在很愤怒，不然也不会摔门而去，一定是我哪里做的不脱产或者说得不到位的地方，实在不好意思，能不能请你坐下来，先消消气我们再好好讨论讨论，好不好？（Mr李坐了下来，但还是很生气）\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;Ms林：Mr李，实在很抱歉，我想是不是我催的太着急了，让你有压力所以你生气了。我不知道是不是这样，但是，我真的希望知道你生气的原因，这样我以后会注意，所以我很诚心的希望听到你坦诚不公的回答。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;Mr李情绪有所缓和，说：其实我也很着急，我也知道时间节点，但是我也是有计划的，另外，你经常直接指挥或者用命令的口吻，这样让我觉得很不舒服。\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;Ms林：哦，我知道了，实在对不起，我确实一着急容易如此，这是我的问题，但是希望你能够理解，我只是为了工作，没有其他的意思，实在对不起\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;\u003cbr>&nbsp;&nbsp;&nbsp;&nbsp;Mr李：嗯，没事，大家也都是为了工作，最近我压力也比较大，情绪有所失控，不好意思。\u003cbr>\u003c/p>\u003cp>\u003cstrong>\u003cbr>\u003c/strong>\u003cbr>\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}}],"created_at":1482153026000,"updated_at":1482153026000,"ria":true},{"id":733,"topic":"情绪教导我们在事情中该有所学习，有所收获。","learn_goal":"晋级3-2","remark":" nlp是研究和运用一个人头脑中的思想运作模式，使其更有效的运作以便让人的自身能力发挥得更好。书中提供了许多nlp的理论和nlp的技巧，都是简单易做、很安全又容易产生时效的技巧，这些技巧可以运用到人生的很多方面。可以在短时间里使一个人发生巨大的改变。","level":"TF3-2","duration":22,"status":0,"type":0,"chaishujia":{"username":"简·单","city":"兰州"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"各位小伙伴，大家好！我是二级拆书家简单，很高兴又和你们见面了，今天我将进行3～2晋级训练.欢迎大家的参与。\r\n1、事件场景 ： 前段时间八达岭野生动物园“老虎吃人”的事件引起了不小的轰动，“7月23日下午，一女子在猛兽区下车，被老虎咬伤。”有传言道：妻子嫌丈夫开车肉，夫妻两发生口角，女士情绪失控下车，酿成惨剧。纷纷议论女人的情绪真可怕！\r\n2、提问：我想请问，当女子对丈夫的行为产生不满，她是否需要做出相应的行动？如果需要，一定要采取不顾一切的，忘我的行动吗？\r\n3、影响：这个事件的最终结果：导致女士的生命岌岌可危，女士的母亲当场死亡。愉快的游园变成了亲人离去的悲伤。\r\n4、解决：今天和大家分享的主题源自于李中莹的著作《重塑心灵》，这本书中结合了nlp的理论，能够推动一个人快速的提升素质，享受更大的快乐。今天的主题是：情绪教导我们在事情中该有所学习，有所收获。","ratings_count":0,"texts":[{"id":2348,"quote":"\u003cp>&nbsp; 情绪教导了我们在事情中该有所学习、有所收获\u003c/p>\u003cp>&nbsp; 人生中出现的每一件事都是让我们学习怎样使人生变得更好的机会。情绪的出现，正是保证我们有所学习的动力。每份情绪都有其意义和价值，不是指引我们一个方向，便是给我们一份力量，甚至两者兼有。如果我们没有不甘心被别人小看的感觉，我们便不会发奋。正如如果我们没有痛的感觉，便不会把手从火炉上抽回。试想，如果我们没有恐惧，生命会变得多么脆弱！\u003c/p>","explains":"\u003cp>谈古论今，多少故事 因主人公恣意放纵情绪而以悲剧告终？环顾四周，多少人生因受到情绪的困扰而黯淡无光？\u003c/p>\u003cp>那我想请问小伙伴们，情绪是贬义的，对吗？不是吧！情绪包括负面情绪，但不全是。\u003c/p>\u003cp>情绪控制我们的人生，对吗？当然不是，情绪出现后我们可以管理情绪，我们可以自己掌控我们的人生。\u003c/p>\u003cp>在情绪的影响下，事情都会变得更糟糕，对吗？当然不是，如果你能管理和处理好情绪，事态可以向积极方向发展。\u003c/p>\u003cp>人生中出现的每一件事都会让我们产生情绪，这份情绪的出现是有意义和价值的，这份情绪会给我们指引一个方向或给我们一份力量，甚至两者兼有。如何在情绪中有所收获呢？首先，我们要知道\u003c/p>\u003cp>情绪是内心的感受经由身体表现出来的状态；而它真正来源于人们内心的信念系统包括信念，价值观，规条。外来的事物只不过是诱因而已，内在的信念系统才是决定因素。例如：在开始的事件中“老公开车肉”这是外部事件，女士的内在信念系统是“换自己来开车”。在这样的特殊环境下，不加思索，不顾一切的“下车”是情绪指引下做出的的反映，当然后果很严重。但是，当情绪出现时，女士内在的信念系统里如果蕴蓄一份积极与宽容，抱着积极学习和向着更好的方向努力的信念，也许此时正是我们学习提升的契机。例如：女士对丈夫的“肉”行为理解为，我们可以看到更多的动物，在这个案例中女士的信念系统影响到情绪继而引发惨痛的教训，它的价值在于对我们起到了教育意义。就像片段中提到的“如果我们没有恐惧，生命会变得多么脆弱！”女士的无畏无惧，让亲人和自己付出了惨痛的代价。只要你想拥有美好的未来，调整自己状态，让我们变得更好更强大。\u003c/p>","interaction":"\u003cp>【A1】请大家自测（1分钟）&nbsp;\u003c/p>\u003cp>当你的情绪出现时，请问你是如何解决的？请根据自己的实际情况为自己打分（1分表示很不符合，2分表示符合，3分表示非常符合）\u003c/p>\u003cp>1.当情绪出现时，我是一定有反映的。\u003c/p>\u003cp>2.当爱人夸赞我的厨艺有进步时，我非常开心，决定继续保持。\u003c/p>\u003cp>3.当我的工作任务没有按原计划完成时，我非常懊悔，决定戒了拖延症。\u003c/p>\u003cp>4.当领导批评我业务不过关时，我很委屈，决定今后提高自己的业务能力，避免领导批评！\u003c/p>\u003cp>5.当我路过一口滚烫的大油锅时，深怕油会烫着我，我会刻意的远离它。\u003c/p>\u003cp>身处于繁杂多变的社会，我们会面对很多事情，这些事情会使我们坚强，自信，轻松，冷静，或者也会让我们纠结，焦虑，害怕，恐惧。如果你的总分超过10分，恭喜你，说明当你在情绪出现时会有所收获，而且会向积极的方向努力。如果你的总分在10分以下，那就请你认真的跟随我们的拆书之旅吧！遇见更好的自己。测试结果：尼尼14分，追风12分，七月上14分，在这个充满正能量的社群里，我们的小伙伴 得分都在10分以上，说明你们在情绪出现时都能有所收获，从而让自己变得越来越好。\u003c/p>\u003cp>&nbsp;【A2】催化应用（1分钟）\u003c/p>\u003cp>拆书家布置任务： 根据今天的学习主题，请小伙伴们在一周内保持每天记录一件体现情绪带来价值的事例。例如：今天xxx事情，让我有xxx感受 ，从中学习了xxx或收获了xxx或这份情绪的价值体现在哪里？今后我如何成长？给8.13日活动的小伙伴布置的作业提醒组长追风，每天督促尼尼、七月上完成。\u003c/p>\u003cp>8月14日作业：\u003c/p>\u003cp>【尼赫尼2016.8.14】\u003c/p>\u003cp>事件记录:今天从兰州坐班车回家，我的前座让我比较郁闷。因为车上人少，不到一半，所以基本上是一人两座，我上车比较早，所以只知道前后座有人，具体前座什么样，我也不知道。车开了快一个小时的时候，我的前座突然把座位往后狠狠一放，直接快躺到我怀里了，把我都吓醒了。当时挺生气，就请他把座位往前拉，结果他说你也可以像我一样往后躺，可是我的后面有人，我可不想做这样的事。我说不行，结果那人看我坚持，就把我后面的人硬是使唤到另外一个座位上了，看样子，他们是同乡，然后很鄙视的看了我一眼，把我气的。我只好躺着了，不过真难受。我不喜欢车上躺着。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 慢慢的，我也快睡着了，突然，闻到一股怪异的味道，睁眼一看，再次无语，他又把鞋子脱了，我是怎么发现的呢？因为他的一只鞋子被车颠到我的脚下了，我想起朋友说车上有人拖鞋，他直接把鞋子从窗户扔出去的事，考虑了一下要不要这么干，后来还是给他踢回去了，可是我对他的讨厌和恶心，让我都快晕车了。\u003c/p>\u003cp>&nbsp; &nbsp; &nbsp; 到了合作站下车时，他穿上鞋子，背起来前面的老爷爷，说，阿达，走佬！顿觉自己幸亏没有和他大声冲突。&nbsp;\u003c/p>\u003cp>价值:1遇到事情不能轻易下结论，用自己的眼睛和心灵去看去想。2能在一定时间内自发解决的矛盾，就不要去引爆它。比如这次坐车，下了车就分开了，没必要起冲突，忍一时风平浪静。3理性告诉我们不能以貌取人，但是事实是我们肯定会以貌取人。4虽然他看起来很孝顺，但我还是对他喜欢不起来，因为没有公德心。\u003c/p>\u003cp>【追风20140814情绪小记】周末，平淡的一天。酷热难忍，情绪有点小闷。做什么事情都提不起精神。发呆，发呆，发呆……这样愈发心里感觉失落。于是再次聆听我的神奇治愈钢琴曲《哥德堡变奏曲》，平静，舒缓，我从中感受到了一种温暖，让我很舒服。我很享受这样的温暖，我的情绪不再低迷。于是，我将今天要做的事情简单罗列了一下，然后泡了茶，一边听音乐，一也品茗读书。心情一下好很多……\u003c/p>\u003cp>从中收获的价值是：学会用适时的方式，调整心情。让自己从低迷的情绪中走出来，培养积极健康的生活态度。\u003c/p>\u003cp>【七月上20160814心情小记】我早晨的情绪因为没有在自己定的时间内起来，很懊恼，但很快我就做了调整，争取明天一定早起[微笑]\u003c/p>\u003cp>【尼赫尼2016.8.15情绪记录】\u003c/p>\u003cp>事情经过:这两天王宝强的事情闹得沸沸扬扬的，手机上全在讨论这样的事。作为一个比较传统的人，我还是理解不了马蓉的行为。没想到这样的事竟然今天就在我身边上演。我早就听说老公的一个有些小钱的朋友找了个小三，没想到今天竟然带着跟我们聚餐。我很震惊，也很生气。结果过了一会，他老婆也来了，三个人相处的很自然，我仔细观察了一下，小三很时髦很精致，老婆很邋遢，一身肥肉，说话还有些口臭，对于小三的挑衅老婆也不以为然，我惊呆了。\u003c/p>\u003cp>处理:本来我还想给小三上几句话，可见他老婆的态度，我就忍了。装作没看见。吃完饭，大家散步，他老婆对我说，我就看他们能蹦哒到什么时候，我牢牢抓住老公的钱包，让他们穷开心去吧！听完我一阵冷汗。这三个人，服了。\u003c/p>\u003cp>价值:1在不了解某件事情的前因后果之前，不能妄加评论，静观其变。2有些家庭出问题，责任不仅仅在男人身上，女人也是难辞其咎。3还是觉得嫁给爱情要比嫁给经济更实在一些。4我自己也是邋遢至极，赶紧做一些努力，比如减肥、美白、学会穿衣打扮。\u003c/p>\u003cp>【七月上20160815情绪小纪】今天的情绪很平和，一整天都在微笑，感觉很开心。\u003c/p>\u003cp>【追风20160815情绪小记】今天，与朋友相约狗不理吃饭，落座点餐时，感受到服务员的热情招待，当时心情特别好！稍后，有一领班服务员拿来一个笑脸牌，说让我们买单后送给我们认为服务最好的服务员。我感觉这还真好。随即我对朋友说，这个笑脸要给那个倒茶女孩的。可是在用餐中，我们喊服务员又点了一份饭。因为好长时间没送来，这先后叫了三位服务员，包括那个我要给笑脸牌子的，她们都是点头一应，就走了。我有点小小的抱怨了。 觉得服务不够真诚，不够好！没有可以让我给笑脸牌的。 这时朋友宽慰说，不急，她们很忙，有时很难照顾周全。也许下单后，是厨房没有送上来，怪不得他们的。 咱们观察一下，将笑脸牌送出去，做为鼓励他们能更好的服务。听了这话，我觉有道理。心情平和了。吃过饭，我们将笑脸牌送给了一个小伙子服务员，送给他时我们还当面夸奖他说，他不但勤快，做事也很认真。他是在我们催餐时，很负责任地拿着我们的餐单去询问的。\u003c/p>\u003cp>收获价值：1.遇事要平和，多做换位思考，相互体谅。2.对待服务我们的人，要给予尊重。对于值得肯定的服务，要当面表示感谢！这也是对他人价值的认可，会促使他人今后更好的表现。\u003c/p>\u003cp>【A3】促动参与（8-12分钟）\u003c/p>\u003cp>拆书家提问设计：小关与周围同事不同，她是一个好学上进的年轻人，平时喜欢看书习作。近期单位开展“我爱我家”征文比赛。她信心满满的将自己的作品投稿，参加比赛。时隔数日，比赛结果公布了，小关榜上无名，获奖名单上一等奖获得者却是自己万万没想到的小唐。这种情况下，小关的情绪如何？怎样做能够体现事件引发的情绪给当事人带来的价值？ 小关是如何面对的？ 请小伙伴们进行角色扮演。\u003c/p>\u003cp>A:尼尼（小关）：先是奇怪、想不明白，是不是领导偏心；与小唐交流，认识自己的不足，认识到人际交往的能力欠缺。\u003c/p>\u003cp>B：七月上（小关）：先质问，再对比，也许会“疯掉”。学会内化 自我调整。\u003c/p>\u003cp>小结：参与者都是充满正能量的，都可以做好情绪管理，每个人都会有情绪出现的时候，这份情绪会给我们一个方向或一份力量，帮助我们变得更好，希望通过今天的学习，小伙伴们都有所收获！\u003c/p>","flags":{"r":true,"i":true,"a":true,"a1":true,"a2":true,"a3":true}}],"created_at":1471178170000,"updated_at":1471178170000,"ria":true},{"id":318,"topic":"什么决定了沟通效果","learn_goal":"用场景法介绍书籍，选择没有具体步骤的拆页","remark":"本书中有许多nlp的理论，都用了浅而易懂的生活或工作的例子、故事来诠释。不同的技巧用了不同的说明方式，每个技巧都有清晰的步骤。可以帮助我们改善工作或生活中的某些部分。","level":"TF3-1","duration":20,"status":0,"type":0,"chaishujia":{"username":"简·单","city":"兰州"},"club":{"name":"兰州金城关分舵","city":"兰州"},"prologue":"各位小伙伴，大家好！我是二级拆书家简单，今天我将进行3--1的晋级训练，感谢大家的参与。事件场景：小长假开始的那天（4.29下午）儿子一进门高兴地对我说：“妈妈放假了，我想玩会游戏”。我说：“行，玩一会吧，但是注意保眼睛”时间过了半小时，我说：“该休息了吧！”儿子聚精会神的玩着，只“嗯”了一声，又过了十分钟，我有点没耐心了，开始找话跟他说，转移他的注意力，他却依然投入游戏中，没有停下来的意思，最后我恼火了，对儿子说：“我说了几遍了，这么长时间盯着电脑，会伤了眼睛的，我这都是为你好，你怎么就是不听呢…………”提问:通过儿子玩游戏的事，我想咱们不论是工作中还是生活中与人交往都少不了沟通，那您遇到过这样的情况吗？比如：你说的对方不听，结果如何呢？影响：最终两者之间的关系僵化，或矛盾升级。解决：今天我给大家分享的主题源自于李中莹的《重塑心灵》。在这本书中有许多nlp的理论，可以帮助我们改善工作或生活中的某些部分。今天的主题就是帮助我们调整沟通方式获得良好的沟通效果。","ratings_count":0,"texts":[{"id":844,"quote":"沟通方式没有对与错之分，而沟通效果则有好与坏之别。沟通的效果决定于对方的回应。强调说得对不对没有意义，说得有好效果才重要。因为良好沟通效果是你的目标，所以绝对不能停下来，一味地强调自己说得对，而要不断地改变你的沟通方式，直至你所期望的回应出现。然后，你应继续这个沟通方式，保持良好的沟通效果。如果有一天所期望的回应消失了，你便需要不断地改变你的沟通方式，直到理想的回应重新出现。","explains":"生活中我们每天都少不了沟通。就像刚才我跟儿子的沟通，我在说“该休息了吧”，可是他没有做出我期望的回应，他没有停下来，在这种情况下一再强调“是对他好”是没用的，也不能停下来，这时，您就需要改变自己的沟通方式了。一位美国心理学家研究得出沟通效果来源于：1.文字意义：同意思的表达可以换位思考，调整角度。比如：“你怎么就是不听话呢”可以调整为“现在可以停下来吗？”（7%说话用字的内容）；2.从语音语调（38%说话声音的高低、强弱、粗细、快慢及这种语气） 比如：用不同的语音语调说“我都是为你好”，用轻而柔的语调让对方感受到关爱；而不是用气乎乎的语调3.身体语言（55%面部表情、头与身躯的姿势、手势等）。比如：“电脑对眼睛伤害是很大的，”。请想象他说了两次。语言语调一样，文字一样。第一次他面部有笑容，双手伸出，掌心向上，手指张开。第二次他的面部有点紧张，双手也伸出，但紧握拳头。文字表达很重要，语言语调影响对方的听觉接受效果，能够引起情绪共鸣；身体语言影响视觉接受效果，能够引起意思共鸣。当三方面不配合时，对方会选择语音和身体语言而不是文字的意思。所以对方的回应就出现了你所不期望的。","interaction":"母亲节到啦！你请母亲和家人来到很火的饭馆过节，家人们高高兴兴的相聚在一起边聊天边等待美味佳肴上桌，等了许久也没见饭菜， 你们怎样跟服务员沟通呢？比如：母亲，你，弟弟，服务员各自是怎么说的？结果如何？\r\nalice.zuo(服务员）：由于今天过节再加上我店推出优惠，客人比较多，麻烦请耐心等待。\r\n朱应涛（弟弟）：可是我们已经等了很久了，我妈妈都饿了。愤怒的说\r\nalice.zuo(服务员）：不如我先为你们放点音乐，你们先聊聊天，我再去催一催。\r\n朱应涛（弟弟）：我们是来吃饭的，又不是来听音乐的。\r\nlian(妈妈）：儿子，别气，咱们好好说。\r\n红彤彤（姐姐）:确实等了很久了，比较饿；我弟弟情绪比较急躁，不如你给我\r\n们先上杯茶，再把凉菜抓紧上。\r\n经过征求妈妈和弟弟的意见后\r\n红彤彤（姐姐）;我们要两杯玫瑰茶，一杯菊花茶。\r\nalice.zuo （服务员）：好的，茶水给您马上送过来，凉菜也会很快送来。我再给大厨师说一声，给你们做好一点。\r\n红彤彤（姐姐）：好的，你辛苦了！\r\nalic.zuo(服务员）：给你们带来的不便请多多包涵。\r\n通过情景演练，我们能 直观的看到弟弟情绪波动，妈妈沉着稳重，姐姐语气轻柔，这里有母子沟通，弟弟和服务员的沟通，还有姐姐和服务员的沟通，建议弟弟向姐姐学习与人沟通。","flags":{"r":true,"i":true,"a":true,"a1":false,"a2":false,"a3":false}},{"id":845,"quote":null,"explains":null,"interaction":null,"flags":{"r":false,"i":false,"a":false,"a1":false,"a2":false,"a3":false}}],"created_at":1462802196000,"updated_at":1462804355000,"ria":true}]};